// Content for Real Relationships (node g46, ages 18-22, Chapter 6): NEW v2 build to GDD 46 (mechanic-embodying),
// the relationship heart of College (Thread D · Relationships). Reworks the old ModesEngine build onto the shared
// v2 engine. "Good relationships are built, not found." 84 researched, India-grounded, abuse-aware, non-graphic
// scenarios across what-healthy-looks-like → fight-right → red-flags-grown-up → leaving-safely → breakups →
// tools-and-help, each encoded as one of the shared v2 play actions (branch / sort / strike-rewrite / reflect /
// role-play / spot / match): no binary "tap the right card". Lead: branch (your move), sort, strike-rewrite
// (bust the myth). Five themes: what healthy looks like (daily markers), fight right (the Four Horsemen and
// repair), red flags grown up (coercive control, jealousy-as-love, isolation, gaslighting; UN&RE), leaving
// safely & breakups, tools/help. ABUSE-AWARE: coercive control named clearly; leaving framed as valid, brave and
// NEVER the target's fault; exit-safety handled with care (abuse can escalate at leaving). Breakup content is
// wellbeing-safe (healthy coping, no-contact, rebuilding; links g39 Bounce and g49 Mind & Belonging); non-graphic.
// Even-handed across genders; routes disclosures to help. India: relationships under family scrutiny, 'caring vs
// controlling' romanticised in culture; helplines 181, 1091, 112. Builds on g24 (GLRL), g31 (Mutual), g09
// (Friend or Frenemy); between g45 and g47; on-ramp to Chapter 7. gameId "real-relationships".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"rr-001","type":"sort","hook":"Sort: a marker of a healthy relationship, or not?","items":[{"id":"a","text":"You can be honest without fear"},{"id":"b","text":"You walk on eggshells"},{"id":"c","text":"You each keep your own friends"},{"id":"d","text":"One person calls all the shots"},{"id":"e","text":"You repair after a fight"},{"id":"f","text":"You're punished for saying no"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"},"relearn":"Honesty, your own friends and repairing after a fight are healthy; eggshells, one-sided control and punishment aren't.","source":"healthy markers","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-002","cat":"what-healthy-looks-like","type":"reflect","hook":"Lensy: good relationships are built, with skills, not just found by luck. Sit right with you?","prompt":"What do you think?","options":["Yes","Built, not found","Skills"],"affirm":"Seeing love as something you build, with real skills, is what makes lasting ones possible.","relearn":"Healthy relationships are built with skills, not found by luck.","persona":"any","source":"built not found"},
  {"id":"rr-003","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"independence","hook":"Your partner Sameer wants you to quit your college band so you two can spend evenings together.","steps":[{"prompt":"Practice is tonight, and he's asked again. What do you do?","options":[{"text":"Go to practice and plan a free evening with him","then":"Sameer sighs but agrees to Thursday. You play well tonight.","best":true},{"text":"Say you'll quit soon, to show him how much you love him","then":"Sameer is delighted. That evening, your guitar stays in its case."},{"text":"Skip tonight and decide about the band later","then":"He's happy tonight. Next week, the same ask comes back."},{"text":"Tell him he's clingy and needs his own hobbies","then":"Sameer goes quiet and hurt. You play badly, thinking about it."}],"why":"Healthy love has room for your own life, and planning time together meets his need too."},{"prompt":"A week later, Sameer says your band matters more to you than he does. What do you say?","options":[{"text":"Both matter. The band is part of me, and so are you","then":"Sameer is quiet, then asks when your next gig is.","best":true},{"text":"That's not true. I'll cut practice down to once a month","then":"He relaxes. Your bandmates start rehearsing without you."},{"text":"Maybe he's right, and I'm being selfish","then":"You start feeling guilty every time you pick up your guitar."},{"text":"Then maybe you should find someone less busy","then":"Sameer looks shocked. The evening ends in a cold silence."}],"why":"You don't have to shrink your life to prove your love."},{"prompt":"Your band gets its first gig, on Saturday night. What do you do?","options":[{"text":"Invite Sameer to come, and play either way","then":"Sameer comes, a little awkward, and claps loudest at the end.","best":true},{"text":"Turn it down in case he feels left out","then":"The band finds someone else for the night. You feel a pang."},{"text":"Play it without mentioning it to him","then":"He sees the photos online the next day and feels lied to."},{"text":"Tell him he has to come, to prove he supports me","then":"He comes, sulking, and leaves before your last song."}],"why":"Sharing your world openly, without giving it up, is what healthy looks like."}],"debrief":"Your own friends, hobbies and identity are a marker of a healthy relationship, not a betrayal.","relearn":"Healthy love keeps your own friends, hobbies and identity."},
  {"id":"rr-004","type":"sort","hook":"Sort: builds trust, or erodes it?","items":[{"id":"a","text":"Keeping your word"},{"id":"b","text":"Snooping through their phone"},{"id":"c","text":"Being reliable in small things"},{"id":"d","text":"Testing them with lies"},{"id":"e","text":"Owning it when you mess up"},{"id":"f","text":"Demanding their passwords"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"erodes","label":"Erodes it","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Keeping your word, reliability and owning mistakes build trust; snooping, testing and demanding passwords erode it.","source":"trust","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-005","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"equality","hook":"Farhan wants to spend the Diwali break with his family. You'd hoped to go to yours in Pune.","steps":[{"prompt":"He brings it up again tonight. What do you do?","options":[{"text":"Talk it through as equals and look for a middle","then":"Farhan explains his grandmother is unwell. You share why Pune matters too.","best":true},{"text":"Just give in. Arguing with him isn't worth it","then":"He's pleased. You end the call with your mother feeling small."},{"text":"Hold firm and go quiet until he gives up","then":"The silence lasts two days, and the question is still open."},{"text":"Agree to his plan now and ask for yours next year","then":"Farhan agrees easily. A small part of you already feels unheard."}],"why":"Deciding as equals means both of you are heard before anything is settled."},{"prompt":"Farhan suggests splitting the break between both families, which costs more. What do you say?","options":[{"text":"Work out the costs together and see if it fits","then":"You sit with the numbers. It's tight, but doable if you take the train.","best":true},{"text":"Yes, whatever you think. You're better with money","then":"Farhan decides it all alone. It works, but you don't know how."},{"text":"Only if you pay the extra, since it was your idea","then":"Farhan's face falls. \"I thought we were a team,\" he says."},{"text":"No. Let's just do Pune this year. It's simpler","then":"Farhan goes quiet. The question comes back at dinner."}],"why":"Shared decisions include the money, not just the plan."},{"prompt":"A friend jokes that in every couple, the louder one wins. How do you answer?","options":[{"text":"It shouldn't. We should both get a say","then":"Your friend raises an eyebrow, then asks how you'd make that work.","best":true},{"text":"True. Farhan's louder, so he usually wins","then":"Saying it out loud, it sounds lonelier than you meant."},{"text":"True. I just sulk until I get my way","then":"Everyone laughs. Later, it doesn't feel that funny."},{"text":"Whoever cares more should win, honestly","then":"Your friend nods. Nobody asks who decides who cares more."}],"why":"Healthy couples decide as equals, not by who is loudest or sulks longest."}],"debrief":"Equality means deciding together, not one person dominating.","relearn":"Healthy couples decide as equals, not by who dominates."},
  {"id":"rr-006","type":"sort","hook":"Sort: healthy support, or smothering?","items":[{"id":"a","text":"Cheering on their goals"},{"id":"b","text":"Needing to know their every move"},{"id":"c","text":"Being there in a hard week"},{"id":"d","text":"Resenting their other relationships"},{"id":"e","text":"Giving them space when asked"},{"id":"f","text":"Sulking when they see friends"}],"bins":[{"id":"support","label":"Support","valence":"pos"},{"id":"smother","label":"Smothering","valence":"neg"}],"key":{"a":"support","b":"smother","c":"support","d":"smother","e":"support","f":"smother"},"relearn":"Cheering goals, being there and giving space is support; tracking, resenting others and sulking is smothering.","source":"support","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-007","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"appreciation","hook":"Pranav's been juggling classes and his family's shop, and you want him to feel valued.","setup":"He flops onto the sofa after a long day.","steps":[{"prompt":"Pranav says: \"Sorry, I'm useless company tonight.\"","options":[{"text":"\"You're not. I really appreciate how hard you're working.\"","then":"He looks up. \"Really? I feel like I'm dropping everything.\"","best":true},{"text":"\"A bit, yeah. You're always tired lately.\"","then":"His face falls. \"Great. Thanks.\""},{"text":"\"It's fine. I'm used to it by now.\"","then":"He winces. \"That sounds worse than you think.\""},{"text":"\"Want me to make chai? Then we can watch something.\"","then":"\"Sure,\" he says, smiling, but the tired look stays."}],"why":"Naming what you appreciate out loud is the antidote to contempt."},{"prompt":"Pranav says: \"I keep forgetting things. Like your friend's party.\"","options":[{"text":"\"It stung a bit. I still see how much you're carrying.\"","then":"He exhales. \"Thanks for being honest and kind about it.\"","best":true},{"text":"\"You always forget. Honestly, it's kind of your thing now.\"","then":"He goes quiet. \"Right. Noted.\""},{"text":"\"Don't worry about it at all.\"","then":"\"Okay,\" he says, but he still looks guilty."},{"text":"\"You'd remember if you actually cared.\"","then":"His jaw tightens. \"That's not fair.\""}],"why":"Honesty about the hurt, with respect, keeps you close."},{"prompt":"Pranav asks: \"What do you even like about me these days?\"","options":[{"text":"\"How you show up for your family. And your jokes.\"","then":"He laughs for the first time all day. \"My jokes are great.\"","best":true},{"text":"\"Come on, don't go fishing for compliments now.\"","then":"He shrugs. \"Forget it.\""},{"text":"\"You know I like you. Why ask?\"","then":"\"Sometimes I need to hear it,\" he says quietly."},{"text":"\"Well, I'll tell you once exams are over.\"","then":"\"Right,\" he says. \"After exams.\""}],"why":"Specific appreciation, said out loud, reminds him why you're together."}],"relearn":"Showing genuine appreciation keeps a relationship healthy."},
  {"id":"rr-008","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"maintenance","hook":"Six months in, things with Zubin are easy and good, and you want to keep them that way.","steps":[{"prompt":"It's a busy exam week for both of you. What do you do?","options":[{"text":"Keep small check-ins going, even if it's just a text","then":"Zubin sends back a silly photo of his notes. You both smile.","best":true},{"text":"Go quiet till exams end. The relationship will keep","then":"By Friday, Zubin's texts have shrunk to one word."},{"text":"Skip studying to see him every single night","then":"The evenings are sweet. Your first paper goes badly."},{"text":"Plan a big date after exams to make up for it","then":"Zubin agrees. The week passes with barely a word between you."}],"why":"Small, steady contact keeps a good thing good, even in busy weeks."},{"prompt":"A few weeks later, Zubin says he wishes you'd ask about his day more. What do you do?","options":[{"text":"Thank him for saying it, and ask what would help","then":"He smiles. \"Just ask me at dinner. That's all.\"","best":true},{"text":"Say it's nothing, since things are fine overall","then":"Zubin shrugs, but brings it up again a week later."},{"text":"List the things he's been forgetting too","then":"It turns into a tally. You both go to bed annoyed."},{"text":"Apologise quickly and change the subject","then":"He nods. The small thing stays small, and unspoken."}],"why":"Repairing small things early keeps a good relationship from drifting."},{"prompt":"A month later, Zubin tells you he got the internship he wanted. What do you do?","options":[{"text":"Tell him exactly what you admire in how he did it","then":"Zubin grins. \"You noticed the late nights?\" He looks ten feet tall.","best":true},{"text":"Say \"nice!\" and go back to your phone","then":"He waits for more, then goes back to his own phone."},{"text":"Tell him to celebrate with his friends, since you're busy","then":"He goes out with friends and doesn't mention you."},{"text":"Plan a surprise party without asking what he'd like","then":"He's touched, but tired, and had wanted a quiet dinner."}],"why":"Naming what you appreciate out loud keeps the warmth flowing."}],"debrief":"Even good relationships stay healthy through ongoing communication and appreciation.","relearn":"Keep a good relationship healthy with ongoing care, not coasting."},
  {"id":"rr-009","type":"spot","hook":"Spot the two unhealthy signs.","scene":[{"id":"a","text":"You feel free to be yourself","trick":false},{"id":"b","text":"You hide parts of your life to keep peace","trick":true},{"id":"c","text":"You both own your mistakes","trick":false},{"id":"d","text":"You watch your words so they don't blow up","trick":true},{"id":"e","text":"You can disagree and stay close","trick":false}],"why":"Hiding your life and watching your words to avoid a blow-up are the unhealthy signs; the rest are healthy.","relearn":"Feeling free, owning mistakes and disagreeing safely are healthy; hiding and self-censoring to keep peace aren't.","source":"healthy signs","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-010","type":"sort","hook":"Sort: a green sign, or a red one?","items":[{"id":"a","text":"They respect your no"},{"id":"b","text":"They guilt you out of plans"},{"id":"c","text":"They're happy for your wins"},{"id":"d","text":"They compete with your success"},{"id":"e","text":"They apologise and mean it"},{"id":"f","text":"They keep score of your slips"}],"bins":[{"id":"green","label":"Green","valence":"pos"},{"id":"red","label":"Red","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Respecting your no, celebrating wins and real apologies are green; guilt, competing and score-keeping are red.","source":"green vs red","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-011","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"keeping your world","hook":"Since you started dating Dev four months ago, you've slowly stopped seeing your hostel friends.","steps":[{"prompt":"Your friend Pallavi texts that the gang misses you at Sunday breakfast. What do you do?","options":[{"text":"Go this Sunday, and tell Dev you'll see him after","then":"The gang cheers when you walk in. Dev texts a thumbs up.","best":true},{"text":"Reply with a heart and stay in. You have Dev now","then":"Pallavi sends a sad face. The group chat moves on without you."},{"text":"Say you'll come once things with Dev settle down","then":"Pallavi says okay. The next invite takes a while to come."},{"text":"Ask Dev first whether he'd mind you going","then":"Dev says \"if you must.\" You go, but it feels like you needed a pass."}],"why":"A healthy relationship leaves room for your friends. You don't need to wait or ask."},{"prompt":"Later that week, Pallavi asks why you've been missing for months. What do you say?","options":[{"text":"Honestly, I let my world shrink. I want to fix that","then":"Pallavi hugs you. \"We're right here. Just show up.\"","best":true},{"text":"Dev and I just like our own company. That's all","then":"Pallavi nods, but she doesn't look convinced."},{"text":"You wouldn't understand. You're single","then":"Pallavi's face drops. The conversation ends there."},{"text":"I've just been so busy lately, sorry","then":"\"Busy with Dev,\" Pallavi says with a small smile."}],"why":"Naming what happened honestly lets your friends help you reconnect."},{"prompt":"Dev plans a surprise for the same evening as a friend's birthday dinner. What do you do?","options":[{"text":"Tell Dev about the dinner and suggest another evening","then":"Dev moves his plan to Saturday. You're at dinner with everyone.","best":true},{"text":"Go with Dev. Your friends will get over it","then":"Your friend's birthday photos show everyone except you."},{"text":"Go to the birthday, and don't tell Dev why","then":"Dev finds out later and wonders why you didn't just say."},{"text":"Skip the dinner, and send a really big gift","then":"Your friend loves the gift, but asks why you never come anymore."}],"why":"Saying it openly lets both parts of your life fit, without hiding or giving one up."},{"prompt":"A month later, Dev says he misses having you all to himself. What do you say?","options":[{"text":"I love our time too. My friends are part of me","then":"Dev smiles. \"Fair. Maybe I'll call my own friends this Sunday.\"","best":true},{"text":"Okay, I'll cut back on seeing them again","then":"Dev is pleased. Pallavi's next invite goes unanswered."},{"text":"Wow, clingy much?","then":"Dev's face falls. \"Forget I said anything.\""},{"text":"Then you should go and get your own friends","then":"Dev bristles. \"I was trying to say I love you.\""}],"why":"You can welcome his closeness and still keep the friends who make you who you are."}],"debrief":"Keeping your friendships alive is healthy, and a quiet safeguard too.","relearn":"Keep your friendships; a healthy relationship leaves room for them."},
  {"id":"rr-012","cat":"what-healthy-looks-like","type":"strike-rewrite","hook":"\"You should settle for less to keep someone.\"","relearn":"You deserve respect, trust, equality, honesty and space; don't settle below that.","persona":"any","source":"the recipe","myth":{"un":"You should settle for less to keep someone.","re":"You deserve respect, trust, equality, honesty and space; don't settle below that.","why":"Settling for less invites being treated as less."}},
  {"id":"rr-013","type":"sort","hook":"Sort: equality, or a power imbalance?","persona":"Aarti","items":[{"id":"a","text":"Both opinions carry weight"},{"id":"b","text":"One controls all the money"},{"id":"c","text":"Chores and decisions shared"},{"id":"d","text":"One person's needs always win"},{"id":"e","text":"Big choices made together"},{"id":"f","text":"One decides where you both live"}],"bins":[{"id":"equal","label":"Equality","valence":"pos"},{"id":"imbalance","label":"Imbalance","valence":"neg"}],"key":{"a":"equal","b":"imbalance","c":"equal","d":"imbalance","e":"equal","f":"imbalance"},"relearn":"Both opinions counting, sharing and deciding together is equality; one controlling money, needs or choices is imbalance.","source":"equality","cat":"what-healthy-looks-like"},
  {"id":"rr-014","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"getting a read","hook":"A year in with Neha, you often feel a little on edge. You can't tell if what you have is healthy.","steps":[{"prompt":"You finally sit down to think it through. What do you measure it by?","options":[{"text":"Respect, trust, equality, and whether I stay myself","then":"Trust and equality feel solid. Your own plans, less so.","best":true},{"text":"Whether the good days outnumber the bad ones overall","then":"The count comes out ahead. The on-edge feeling stays unexplained."},{"text":"How much I'd miss her if things ever ended","then":"The answer is \"a lot,\" which tells you little about the rest."},{"text":"Whether other couples seem worse","then":"Your cousins fight more, so you feel better and learn nothing."}],"why":"The healthy markers give a clearer read than mood or comparison."},{"prompt":"Your closest friend Aditi offers to give you her honest view. What do you do?","options":[{"text":"Ask her, and really listen to what she says","then":"Aditi says you seem quieter lately. It stings, and it rings true.","best":true},{"text":"Decline. Outsiders don't get our relationship","then":"Aditi respects it. You're left guessing on your own."},{"text":"Ask her, but only share the good parts first","then":"Aditi says it all sounds lovely. You feel oddly unheard."},{"text":"Say yes, then argue with every point she makes","then":"Aditi stops trying halfway through. You win and learn nothing."}],"why":"People who know you well often see changes you can't see from inside."},{"prompt":"You notice you've stopped raising things with Neha, to avoid a mood. What do you do?","options":[{"text":"Raise one small thing, and see how she responds","then":"Neha listens, a little surprised, and thanks you. You breathe easier.","best":true},{"text":"Tell yourself every couple has its moods","then":"The silence grows. So does the on-edge feeling."},{"text":"Decide the on-edge feeling is all in your head","then":"You push it down, but it's back the next time her mood shifts."},{"text":"Wait and see if it gets better on its own","then":"A month passes. You're still tiptoeing, and still unsure."}],"why":"How someone responds to an honest concern is one of the clearest markers there is."}],"debrief":"Clear markers and people who know you beat guessing. Tiptoeing around a partner's moods is worth taking seriously, and never your fault.","relearn":"Check a relationship against the markers and trusted friends."},
  {"id":"rr-015","type":"match","hook":"Match the healthy ingredient to what it looks like.","pairs":[{"left":"Respect","right":"Your no is honoured"},{"left":"Trust","right":"No snooping needed"},{"left":"Independence","right":"You keep your own life"},{"left":"Equality","right":"Big choices made together"},{"left":"Repair","right":"You make up after a fight"}],"relearn":"Respect, trust, independence, equality and repair each show up in concrete, daily ways.","source":"ingredients","cat":"what-healthy-looks-like","persona":"any"},
  {"id":"rr-016","cat":"fight-right","type":"strike-rewrite","hook":"\"A good relationship has no conflict.\"","myth":{"un":"A good relationship has no conflict.","re":"Conflict is normal; how you handle and repair it is what matters.","why":"Every close pair disagrees sometimes."},"relearn":"Conflict is normal; how you handle and repair it is what matters.","persona":"any","source":"conflict is normal"},
  {"id":"rr-017","cat":"fight-right","type":"strike-rewrite","hook":"\"If we fight, we're doomed.\"","myth":{"un":"If we fight, we're doomed.","re":"Fighting fair and repairing is healthy; it's contempt, not conflict, that predicts breakdown.","why":"How you fight matters more than whether you fight."},"relearn":"Fighting fair and repairing is healthy; contempt, not conflict, predicts breakdown.","persona":"any","source":"how you fight"},
  {"id":"rr-018","cat":"fight-right","type":"sort","hook":"Sort: fair fighting, or a relationship-wrecker?","items":[{"id":"a","text":"Sticking to the actual issue"},{"id":"b","text":"Contempt and name-calling"},{"id":"c","text":"Using 'I felt...' statements"},{"id":"d","text":"Stonewalling and shutting down"},{"id":"e","text":"Owning your part of it"},{"id":"f","text":"\"You always, you never\" attacks"}],"bins":[{"id":"fair","label":"Fair fighting","valence":"pos"},{"id":"wrecker","label":"Wrecker","valence":"neg"}],"key":{"a":"fair","b":"wrecker","c":"fair","d":"wrecker","e":"fair","f":"wrecker"},"relearn":"Sticking to the issue, 'I' statements and owning your part are fair; contempt, stonewalling and 'always/never' wreck.","persona":"any","source":"four horsemen"},
  {"id":"rr-019","cat":"fight-right","type":"strike-rewrite","hook":"\"Winning the argument is the point.\"","myth":{"un":"Winning the argument is the point.","re":"The point is understanding each other and repairing, not scoring a win.","why":"A 'win' that hurts your partner loses the relationship."},"relearn":"The point of a disagreement is understanding and repair, not winning.","persona":"any","source":"repair over winning"},
  {"id":"rr-020","cat":"fight-right","type":"role-play","persona":"any","source":"I statements","hook":"Your partner Mira joked about your family in front of her friends, and it hurt.","setup":"Later, at her flat, she flops onto the sofa.","steps":[{"prompt":"Mira asks: \"You've been quiet since dinner. What's up?\"","options":[{"text":"\"I felt hurt by the joke about my family. Can we talk?\"","then":"She sits up. \"Oh. I didn't think. Tell me.\"","best":true},{"text":"\"You always embarrass me in front of people.\"","then":"Mira stiffens. \"Always? That's not fair.\""},{"text":"\"Nothing. Just tired.\"","then":"She reaches for the remote, then stops. \"Is this about my joke?\""},{"text":"\"It's fine. Just maybe don't joke about my family.\"","then":"Mira shrugs. \"Sure.\" Then she pauses. \"Did it really bother you?\""}],"why":"Starting with how you felt names the hurt without attacking, so she can listen."},{"prompt":"Mira says: \"It was only a joke. Everyone was laughing.\"","options":[{"text":"\"I know you didn't mean harm. It still stung.\"","then":"Mira pauses. \"Okay. I hear that.\"","best":true},{"text":"\"Then your friends are as rude as you are.\"","then":"Her voice hardens. \"Now you're insulting my friends?\""},{"text":"\"Forget it. I'm being too sensitive.\"","then":"Mira looks at you. \"You're clearly still hurt, though.\""},{"text":"\"You'd be furious if I joked about your parents.\"","then":"\"That's different,\" she says, and folds her arms."}],"why":"Holding your feeling without attacking her keeps the talk on the hurt, not on who's right."},{"prompt":"Mira asks: \"Okay. What would you want me to do differently?\"","options":[{"text":"\"Just keep my family out of the jokes, please.\"","then":"\"Fair enough,\" she says. \"I can do that.\"","best":true},{"text":"\"Apologise to me in front of your friends.\"","then":"She blinks. \"That feels like a punishment.\""},{"text":"\"Nothing. You should already know.\"","then":"She throws up her hands. \"How can I fix it, then?\""},{"text":"\"Promise you'll never joke about anything of mine.\"","then":"\"Anything?\" she says. \"That's a big ask.\""}],"why":"A clear, small request is easy to agree to and easy to keep."}],"relearn":"Raise a hurt with an 'I felt...' opener, not a 'you always' attack."},
  {"id":"rr-021","cat":"fight-right","type":"spot","hook":"Spot the two most corrosive lines to catch.","scene":[{"id":"a","text":"Eye-rolling and sarcasm (contempt)","trick":true},{"id":"b","text":"Naming a specific upset calmly","trick":false},{"id":"c","text":"Mocking and name-calling (contempt)","trick":true},{"id":"d","text":"\"Help me understand your side\"","trick":false},{"id":"e","text":"\"I felt hurt, can we talk?\"","trick":false}],"why":"Contempt, sarcasm, mockery, eye-rolling, is the single most damaging pattern; calm, specific complaints aren't.","relearn":"Contempt is the single most corrosive pattern in conflict.","persona":"any","source":"contempt"},
  {"id":"rr-022","cat":"fight-right","type":"branch","persona":"any","source":"self-soothing","hook":"Your argument with Simran about weekend plans is heating up fast.","steps":[{"prompt":"Your heart is pounding and you can't think straight. What do you do?","options":[{"text":"Push on and say whatever comes out","then":"You say something about her family that you regret at once."},{"text":"Walk out without a word","then":"The door shuts. Simran is left in the room, stunned and hurt."},{"text":"Ask for twenty minutes to calm down, then return","then":"Simran hesitates, then nods. \"Twenty minutes. Then we finish this.\"","best":true},{"text":"Go quiet and let her talk until she's done","then":"You nod along, hearing nothing. She can tell you've checked out."}],"why":"A short break with a promise to return stops you saying something cruel."},{"prompt":"Later, alone, you're still replaying her words. What do you do?","options":[{"text":"Write a list of everything she's done wrong","then":"The list grows to fifteen points, and you get angrier with each one."},{"text":"Take slow breaths and go for a short walk","then":"By the corner shop, your shoulders drop and you can think again.","best":true},{"text":"Vent to a friend who always takes your side","then":"Your friend agrees she's impossible, and you feel more fired up."},{"text":"Scroll your phone to forget the fight","then":"Half an hour vanishes. You feel numb, not calm, and the fight is still there."}],"why":"Calming your body first is what lets you come back able to listen."},{"prompt":"Once you've both cooled off, you and Simran are in the same room again. What do you do?","options":[{"text":"Act like nothing happened and suggest dinner","then":"Dinner is quiet. The weekend plans are still undecided."},{"text":"Wait for her to apologise first","then":"She waits too. The silence stretches through the evening."},{"text":"Restart the argument from where it stopped","then":"Within a minute, you're both flooded again."},{"text":"Say you're ready to talk, and ask her side first","then":"Simran's face softens. \"Okay. I'm ready too.\"","best":true}],"why":"Coming back and listening first is what turns a break into repair."}],"debrief":"A brief, agreed break to calm down, then returning, is healthy. It's the antidote to flooding and stonewalling.","relearn":"When flooded, take a short break and return; don't explode or vanish."},
  {"id":"rr-023","cat":"fight-right","type":"role-play","persona":"Rohan","source":"repair / apology","hook":"You shouted at Aisha for not replying, then saw she'd told you she was in a lab.","setup":"Now she's on the phone, waiting.","steps":[{"prompt":"Aisha asks: \"Do you have something to say to me?\"","options":[{"text":"\"I was wrong to shout at you. I'm sorry.\"","then":"\"Thank you,\" she says. \"That really upset me.\"","best":true},{"text":"\"Sorry you feel that way.\"","then":"\"That's not an apology,\" she says flatly."},{"text":"\"Sorry, but you could have reminded me.\"","then":"\"I did remind you,\" Aisha says. \"Twice.\""},{"text":"\"Can we just forget it happened?\"","then":"\"No,\" she says quietly. \"I can't just forget it.\""}],"why":"A real apology owns what you did, with no \"but\" and no blame."},{"prompt":"Aisha says: \"You always get like this when you're stressed.\"","options":[{"text":"\"You're right. I take it out on you. That's not okay.\"","then":"Aisha's voice softens. \"Thank you for saying that.\"","best":true},{"text":"\"Always? That's a bit unfair.\"","then":"\"Maybe not always,\" she says. \"Often enough.\""},{"text":"\"I know. That's just how I am.\"","then":"Aisha sighs. \"So I should just accept it?\""},{"text":"\"I've had a brutal week. Cut me some slack, please.\"","then":"\"I have been,\" she says. \"For a while now.\""}],"why":"Owning the pattern, not just the moment, shows her you see what she sees."},{"prompt":"Aisha asks: \"So what happens next time you're stressed?\"","options":[{"text":"\"I'll tell you I'm stressed before it spills over.\"","then":"\"That would help,\" she says. \"I'd rather know.\"","best":true},{"text":"\"It won't happen again. I promise.\"","then":"\"You said that last time,\" she says."},{"text":"\"I don't know. I'll try harder, I guess.\"","then":"She's quiet. \"Trying how, though?\""},{"text":"\"You could just give me space when I'm like that.\"","then":"\"So it's on me again?\" she asks."}],"why":"Naming a specific change makes an apology believable, not just sweet."},{"prompt":"Aisha says: \"I'm still a bit shaken by all this, honestly.\"","options":[{"text":"\"That makes sense. Take the time you need.\"","then":"\"Thanks,\" she says. \"I'll call you tomorrow.\"","best":true},{"text":"\"But I said sorry. What more do you want?\"","then":"Aisha goes quiet. \"Nothing, I guess.\""},{"text":"\"Let me come over now and make it up to you.\"","then":"\"Not tonight,\" she says. \"I need a bit of space.\""},{"text":"\"Okay. I'll leave you alone for a few days, then.\"","then":"\"I didn't say that,\" she says, surprised."}],"why":"An apology doesn't erase hurt on the spot. Giving her time respects that."}],"relearn":"A real apology owns your part and names what you'll change."},
  {"id":"rr-024","cat":"fight-right","type":"sort","hook":"Sort: an antidote to a wrecker, or the wrecker itself?","items":[{"id":"a","text":"Taking responsibility for your part"},{"id":"b","text":"Getting defensive and blaming back"},{"id":"c","text":"Appreciation and respect"},{"id":"d","text":"Criticising their character"},{"id":"e","text":"A self-soothing break, then return"},{"id":"f","text":"Going cold and shutting down"}],"bins":[{"id":"antidote","label":"Antidote","valence":"pos"},{"id":"wrecker","label":"Wrecker","valence":"neg"}],"key":{"a":"antidote","b":"wrecker","c":"antidote","d":"wrecker","e":"antidote","f":"wrecker"},"relearn":"Responsibility, appreciation and a break-then-return are antidotes; defensiveness, character attacks and shutting down wreck.","persona":"any","source":"antidotes"},
  {"id":"rr-025","cat":"fight-right","type":"branch","persona":"any","source":"defensiveness","hook":"Your partner Tara says you always leave her to plan everything when you meet.","steps":[{"prompt":"Your first instinct is to defend yourself. What do you do?","options":[{"text":"List the times she forgot things too","then":"Tara folds her arms. \"This isn't about me.\""},{"text":"Say sorry fast so the topic ends","then":"Tara nods, unconvinced. \"You're just saying that.\""},{"text":"Say that's just how you are, and she knew it","then":"Tara looks tired. \"So nothing changes, then.\""},{"text":"Listen fully, then own the part that's fair","then":"Tara's shoulders drop. \"Thank you. That's all I wanted.\"","best":true}],"why":"Listening and owning your part breaks the defensiveness loop."},{"prompt":"Tara adds that it makes her feel she cares more than you do. What do you say?","options":[{"text":"Ask what would help it feel shared","then":"Tara thinks. \"Maybe you plan every other date?\"","best":true},{"text":"Say that's not true, and you care just as much","then":"\"Then show it,\" she says, and the room goes quiet."},{"text":"Tell her she's being dramatic","then":"Tara's face hardens. The talk is over."},{"text":"Promise to plan everything from now on","then":"Tara smiles, but you both know it won't last."}],"why":"Asking what would help turns a complaint into a shared plan."},{"prompt":"A few days later, you forget to book tickets for your Saturday plan. What do you do?","options":[{"text":"Blame the booking app for crashing","then":"Tara checks the app. It works fine. Now it's about trust too."},{"text":"Tell Tara straight away and book another show","then":"Tara laughs. \"Okay. At least you told me.\"","best":true},{"text":"Hope she doesn't notice","then":"She notices at the cinema door, and the evening sours."},{"text":"Apologise at length and call yourself useless","then":"Tara ends up comforting you, and the plan is still unbooked."}],"why":"Owning a slip quickly and fixing it keeps small mistakes small."},{"prompt":"Later that month, Tara raises something small that annoyed her. What do you do?","options":[{"text":"Say \"here we go again\"","then":"Tara's face falls. \"Forget I said anything.\""},{"text":"Agree to everything so it's over quickly","then":"It ends fast. Tara can tell you weren't really listening."},{"text":"Hear it out, and say what you'll change","then":"Tara relaxes. \"That was easier than I expected.\"","best":true},{"text":"Bring up something she did, to even it out","then":"It turns into a scoreboard, and neither of you wins."}],"why":"Hearing small complaints without defending yourself keeps big ones from building."}],"debrief":"Defensiveness escalates. Listening and taking responsibility de-escalates and repairs.","relearn":"Listen and own your part instead of getting defensive."},
  {"id":"rr-026","cat":"fight-right","type":"strike-rewrite","hook":"\"Bringing up every past grievance helps you win.\"","myth":{"un":"Bringing up every past grievance helps you win.","re":"Fair fighting stays on one issue; kitchen-sinking everything just wounds.","why":"Piling on the past buries the actual problem."},"relearn":"Fight fair by staying on one issue, not dredging up everything.","persona":"any","source":"fair fighting"},
  {"id":"rr-027","cat":"fight-right","type":"branch","persona":"any","source":"repair","hook":"After last night's fight with Farhan, his texts today are short and cold.","steps":[{"prompt":"It's lunchtime, and neither of you has mentioned it. What do you do?","options":[{"text":"Stay cold until he apologises","then":"His replies get shorter. By evening you're barely speaking."},{"text":"Send a warm message: \"I hate how we left it.\"","then":"Farhan replies after a minute. \"Me too. Talk tonight?\"","best":true},{"text":"Send a long message about what he did wrong","then":"He reads it and doesn't reply for hours."},{"text":"Send a meme and act like nothing happened","then":"He sends a laugh back. The fight is still sitting between you."}],"why":"A small repair attempt reopens the door that a fight closed."},{"prompt":"That evening, Farhan says he was harsh last night. What do you do?","options":[{"text":"Thank him, and own the part you got wrong too","then":"Farhan exhales. \"Thanks. I think we were both tired.\"","best":true},{"text":"Say \"finally\" and list the other times he was harsh","then":"His face closes. \"Forget I said anything.\""},{"text":"Say it's fine and move on quickly","then":"He looks relieved. Neither of you talks about what caused it."},{"text":"Accept it, but stay distant for a few days","then":"He keeps trying. By the third day, he stops."}],"why":"Meeting an apology with your own part closes the rupture for both of you."},{"prompt":"A week later, the thing you fought about comes up again. What do you do?","options":[{"text":"Bring up last week's fight as proof","then":"Farhan sighs. \"So we're doing this again.\""},{"text":"Drop it to avoid another fight","then":"The evening stays calm. The topic waits for next time."},{"text":"Tell him he never listens","then":"He goes quiet and turns back to his laptop."},{"text":"Start gently, with how you feel","then":"Farhan nods. \"Okay. What would work for you?\"","best":true}],"why":"A gentle start makes the next talk a repair, not a rerun."}],"debrief":"Repair attempts after conflict are what keep healthy couples close.","relearn":"Make a repair attempt after a fight; don't let it fester."},
  {"id":"rr-028","cat":"fight-right","type":"role-play","persona":"any","source":"repair","hook":"You and Dev snapped at each other over the dishes, and now the flat feels cold.","setup":"An hour later, you both reach for the kettle.","steps":[{"prompt":"Dev asks, without looking up: \"Are you done with this?\"","options":[{"text":"\"Yes. I didn't like how we spoke. Can we try again?\"","then":"He looks up. \"Yeah. I didn't like it either.\"","best":true},{"text":"\"Whatever. It's all yours.\"","then":"He shrugs. \"Fine.\" At the door, he stops and turns back."},{"text":"\"Only if you've finally learnt how to wash it.\"","then":"\"Seriously?\" he says. \"You're still on that?\""},{"text":"\"Sorry about earlier. Let's just forget it, okay?\"","then":"\"Sure,\" he says. The dishes question is still unsolved."}],"why":"A small repair attempt reconnects you before the cold sets in."},{"prompt":"Dev says: \"I'm just tired of being the one who always cleans up.\"","options":[{"text":"\"That's tiring. Can we split it fairly?\"","then":"\"Yes,\" he says. \"A rota, maybe?\"","best":true},{"text":"\"Always? I cleaned on Sunday.\"","then":"\"Once,\" he says. \"You cleaned once.\""},{"text":"\"Fine. I'll do everything from now on.\"","then":"He rolls his eyes. \"That's not what I asked.\""},{"text":"\"Let's not start all this again tonight.\"","then":"He sighs. \"Then when?\""}],"why":"Hearing his point and turning it into a shared fix keeps you on the same side."},{"prompt":"Dev asks: \"Chai? And can we not do the cold thing next time?\"","options":[{"text":"\"Yes to both. Next time I'll reach out sooner.\"","then":"He smiles and reaches for two cups.","best":true},{"text":"\"You started the cold thing, not me.\"","then":"His smile fades. \"Here we go.\""},{"text":"\"Chai, yes. The rest, we'll see.\"","then":"He nods slowly, not quite sure where you stand."},{"text":"\"Sure. Let's just agree to never fight again.\"","then":"He laughs. \"We will, though. That's okay.\""}],"why":"Agreeing on how to repair next time makes the next fight shorter."}],"relearn":"Initiating repair kindly reconnects after a fight."},
  {"id":"rr-029","cat":"fight-right","type":"role-play","persona":"any","source":"stonewalling","hook":"Mid-argument, Karan has gone silent, arms crossed, eyes on the floor.","setup":"You've tried to get an answer twice.","steps":[{"prompt":"Karan mutters: \"I don't want to talk right now.\"","options":[{"text":"\"Okay. Let's take a breather and talk in an hour?\"","then":"His shoulders ease. \"Yeah. An hour.\"","best":true},{"text":"\"Answer me right now or we're done.\"","then":"Karan stands and walks out. The door bangs behind him."},{"text":"\"Take all the time you need.\"","then":"He nods. Neither of you knows when, or if, you'll talk."},{"text":"\"You can't shut down every time. Talk to me.\"","then":"He shakes his head and stares harder at the floor."}],"why":"A break with a return time lets him calm down without the fight being dropped."},{"prompt":"Later that evening, Karan says: \"I just freeze when voices get loud.\"","options":[{"text":"\"Thanks for telling me. What helps when that happens?\"","then":"\"A few minutes,\" he says. \"And quieter voices. Then I can talk.\"","best":true},{"text":"\"My voice wasn't even that loud. You're exaggerating.\"","then":"He looks away. \"It felt loud to me.\""},{"text":"\"You need to toughen up a bit.\"","then":"Karan's face closes again."},{"text":"\"Okay. I'll just drop it whenever you go quiet.\"","then":"He frowns. \"Then nothing ever gets sorted.\""}],"why":"Asking what helps him turns his shutdown into something you can plan around."},{"prompt":"A little later, Karan asks: \"Can we go back to what we were fighting about?\"","options":[{"text":"\"Yes. Can I start with how I felt, not what you did?\"","then":"\"Please,\" he says, and sits down.","best":true},{"text":"\"Honestly, I've forgotten what it was. Let's leave it.\"","then":"\"Okay,\" he says. He doesn't look like it's settled."},{"text":"\"Only if you promise not to freeze again.\"","then":"\"I can't promise that,\" he says quietly."},{"text":"\"Sure. So, as I was saying, you were wrong.\"","then":"His jaw tightens. \"Here we go again.\""}],"why":"Coming back to it gently is what makes the break a break, not a way to bury it."},{"prompt":"Before bed, Karan asks: \"Next time I freeze, what should I do?\"","options":[{"text":"\"Say you need a break, and when you'll be back.\"","then":"\"I can do that,\" he says, and squeezes your hand.","best":true},{"text":"\"Just try not to freeze.\"","then":"\"I'll try,\" he says, not sounding sure."},{"text":"\"Walk away. I'll figure out the rest.\"","then":"\"Okay,\" he says. You both know that won't settle anything."},{"text":"\"Text me instead. It's easier than talking.\"","then":"\"Maybe,\" he says. \"But we'd still need to talk after.\""}],"why":"A shared signal for breaks means neither of you is left hanging mid-fight."}],"relearn":"Offer a calm break and a time to return rather than pressuring a shut-down partner."},
  {"id":"rr-030","cat":"fight-right","type":"sort","hook":"Sort: helps a relationship recover from conflict, or harms it?","items":[{"id":"a","text":"Apologising and meaning it"},{"id":"b","text":"Silent treatment for days"},{"id":"c","text":"Naming feelings calmly"},{"id":"d","text":"Threatening to leave to win"},{"id":"e","text":"A kind check-in afterwards"},{"id":"f","text":"Dragging up every old fight"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Apology, naming feelings and a check-in help recovery; silent treatment, leave-threats and dredging the past harm.","persona":"any","source":"recovery"},
  {"id":"rr-031","cat":"fight-right","type":"reflect","hook":"Lensy: handling conflict well might be the single most useful relationship skill there is. Worth building?","prompt":"What do you think?","options":["Yes","Most useful","Build it"],"affirm":"Couples who repair well last; this is a skill worth building for life.","relearn":"Handling conflict and repairing well is the key relationship skill.","persona":"any","source":"skill"},
  {"id":"rr-032","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Jealousy means they really love you.\"","myth":{"un":"Jealousy means they really love you.","re":"Jealousy and possessiveness are about control, not love.","why":"Real love trusts; control polices."},"relearn":"Jealousy and possessiveness are about control, not love.","persona":"any","source":"jealousy-as-love"},
  {"id":"rr-033","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They check my phone and location because they care.\"","myth":{"un":"They check my phone and location because they care.","re":"Monitoring 'for transparency' is control; healthy transparency is voluntary, not demanded.","why":"Care doesn't surveil."},"relearn":"Monitoring your phone or location 'for transparency' is control, not care.","persona":"any","source":"coercive control"},
  {"id":"rr-034","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They're just protective; that's why they don't like my friends.\"","myth":{"un":"They're just protective about my friends.","re":"Cutting you off from friends and family is isolation, a control tactic, not protection.","why":"Isolation makes you easier to control."},"relearn":"Cutting you off from friends and family is isolation, not protection.","persona":"any","source":"isolation"},
  {"id":"rr-035","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two gaslighting lines (the red flags).","scene":[{"id":"a","text":"\"That never happened, you're imagining it\"","trick":true},{"id":"b","text":"\"I see why that upset you\"","trick":false},{"id":"c","text":"\"You're too sensitive, as always\"","trick":true},{"id":"d","text":"\"You're right, let's sort it out\"","trick":false},{"id":"e","text":"\"I hear what you're saying\"","trick":false}],"why":"Denying your reality and calling you 'too sensitive' is gaslighting; acknowledging your feelings isn't.","relearn":"Denying your reality or calling you 'too sensitive' is gaslighting.","persona":"any","source":"gaslighting"},
  {"id":"rr-036","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Real love means losing yourself in each other.\"","myth":{"un":"Real love means losing yourself in each other.","re":"Healthy love keeps your independence, friends and identity intact.","why":"Losing yourself is a warning sign, not romance."},"relearn":"Healthy love keeps your independence, friends and identity intact.","persona":"any","source":"losing yourself"},
  {"id":"rr-037","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two coercive-control moves (the red flags).","scene":[{"id":"a","text":"Controlling what you wear and who you see","trick":true},{"id":"b","text":"Asking how your day was","trick":false},{"id":"c","text":"Controlling your money 'for your own good'","trick":true},{"id":"d","text":"Glad you made it to your friend's","trick":false},{"id":"e","text":"Fine with you having alone time","trick":false}],"why":"Dictating your clothes, contacts or money is coercive control; ordinary interest isn't.","relearn":"Dictating your clothes, contacts or money is coercive control.","persona":"any","source":"coercive control"},
  {"id":"rr-038","cat":"red-flags-grown-up","type":"sort","hook":"Sort: love, or control dressed as love?","items":[{"id":"a","text":"Trusting you with your own choices"},{"id":"b","text":"Demanding your passwords"},{"id":"c","text":"Being glad you have friends"},{"id":"d","text":"Sulking when you see them"},{"id":"e","text":"Cheering on your own plans"},{"id":"f","text":"Tracking where you are all day"}],"bins":[{"id":"love","label":"Love","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"love","b":"control","c":"love","d":"control","e":"love","f":"control"},"relearn":"Trusting your choices and your friendships is love; demanding passwords and sulking is control.","persona":"any","source":"love vs control"},
  {"id":"rr-039","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"If I just love them harder, they'll stop controlling me.\"","myth":{"un":"If I love them harder, they'll stop controlling me.","re":"You can't love someone out of controlling or abusing you; that isn't yours to fix.","why":"The control is their choice, not your failing."},"relearn":"You can't love someone out of controlling you; it isn't yours to fix.","persona":"any","source":"not yours to fix"},
  {"id":"rr-040","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two red flags behind the romantic-sounding lines.","scene":[{"id":"a","text":"\"I can't live without you\" used to guilt you","trick":true},{"id":"b","text":"\"I love spending time with you\"","trick":false},{"id":"c","text":"\"If you leave, I'll do something drastic\"","trick":true},{"id":"d","text":"\"I'm proud of you\"","trick":false},{"id":"e","text":"\"Take all the time you need\"","trick":false}],"why":"Guilt and threats dressed as devotion are control; genuine warmth isn't.","relearn":"Guilt and threats dressed as devotion are control, not romance.","persona":"any","source":"romanticised control"},
  {"id":"rr-041","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They only get angry because they love me so much.\"","myth":{"un":"They only get angry because they love me so much.","re":"Intensity and anger aren't proof of love; respect and safety are.","why":"Love isn't measured in jealousy or rage."},"relearn":"Anger and intensity aren't proof of love; respect and safety are.","persona":"any","source":"intensity myth"},
  {"id":"rr-042","cat":"red-flags-grown-up","type":"sort","hook":"Sort: a healthy boundary, or controlling behaviour?","items":[{"id":"a","text":"\"I'm not comfortable with that, let's talk\""},{"id":"b","text":"\"You can't wear that out\""},{"id":"c","text":"\"I need some alone time tonight\""},{"id":"d","text":"\"Delete all your friends' numbers\""},{"id":"e","text":"\"Please don't read my phone\""},{"id":"f","text":"\"You're not allowed to go out\""}],"bins":[{"id":"boundary","label":"Boundary","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"boundary","b":"control","c":"boundary","d":"control","e":"boundary","f":"control"},"relearn":"Naming your own comfort and needs is a boundary; dictating their clothes or contacts is control.","persona":"any","source":"boundary vs control"},
  {"id":"rr-043","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"naming it","hook":"Your girlfriend Riya checks who you text and sulks when you meet friends. You keep finding reasons it's okay.","steps":[{"prompt":"Tonight she asks again who you were texting. Later, alone, what do you tell yourself?","options":[{"text":"She's insecure because her ex cheated. It's not about me","then":"You feel sorry for her, and the checking carries on."},{"text":"She only does it because she loves me so much","then":"The thought feels warm, then uneasy, as her messages keep coming."},{"text":"This is control, not love. I'll stop excusing it","then":"The word feels heavy, but for the first time things make sense.","best":true},{"text":"Maybe I give her reasons to worry","then":"You start explaining every text before she even asks."}],"why":"Naming control honestly, instead of explaining it away, is the first step to seeing clearly."},{"prompt":"Your friend Kunal says you've seemed jumpy about your phone lately. What do you do?","options":[{"text":"Laugh it off: \"She's just a bit possessive, yaar\"","then":"Kunal shrugs and lets it go. The jumpiness stays."},{"text":"Tell him honestly what's been happening","then":"Kunal listens, then asks, \"That sounds like control. Are you okay?\"","best":true},{"text":"Say it's nothing and change the subject","then":"Kunal drops it, and you feel oddly alone at the table."},{"text":"Defend Riya before he can say anything","then":"Kunal looks surprised. \"I didn't say anything about her.\""}],"why":"Telling a friend the truth breaks the silence that control depends on."},{"prompt":"A week later, Riya says she'll be upset if you go to a friend's birthday. What do you do?","options":[{"text":"Skip it, since real love means putting her first","then":"Riya is sweet all evening. Your friends invite you a little less."},{"text":"Go, and calmly say your friends stay in your life","then":"She's cold when you leave. At the party you laugh like you used to.","best":true},{"text":"Go, but tell her you're at the library","then":"You spend the party checking your phone, afraid she'll find out."},{"text":"Take her along so she has nothing to worry about","then":"She comes, and watches who you talk to all night."}],"why":"Keeping your friends is healthy, not disloyal. Love expands your world. Control shrinks it."}],"debrief":"Naming control instead of excusing it is how you start to get clear and safe. It is never your fault.","relearn":"Name controlling behaviour honestly instead of excusing it."},
  {"id":"rr-044","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two early control signs (the red flags).","scene":[{"id":"a","text":"Moving very fast and 'you're my everything'","trick":true},{"id":"b","text":"Getting to know each other slowly","trick":false},{"id":"c","text":"Subtle put-downs framed as jokes","trick":true},{"id":"d","text":"Happy when you make your own plans","trick":false},{"id":"e","text":"Respects it when you need space","trick":false}],"why":"Rushing intimacy and put-down 'jokes' are early control signs; a slow, respectful start isn't.","relearn":"Rushing intensity and put-down 'jokes' are early control warning signs.","persona":"any","source":"early signs"},
  {"id":"rr-045","cat":"red-flags-grown-up","type":"sort","hook":"Sort: expands your world, or shrinks it?","items":[{"id":"a","text":"Encourages your goals and friends"},{"id":"b","text":"Slowly cuts off your support"},{"id":"c","text":"Celebrates your independence"},{"id":"d","text":"Makes you account for every hour"},{"id":"e","text":"Backs your own interests"},{"id":"f","text":"Resents any time you're not together"}],"bins":[{"id":"expands","label":"Expands","valence":"pos"},{"id":"shrinks","label":"Shrinks","valence":"neg"}],"key":{"a":"expands","b":"shrinks","c":"expands","d":"shrinks","e":"expands","f":"shrinks"},"relearn":"Love expands your world; control slowly shrinks it.","persona":"any","source":"expand vs shrink"},
  {"id":"rr-046","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"supporting a friend","hook":"Your friend Rahul's boyfriend reads his messages and decides who he sees. Rahul barely shows up anymore.","steps":[{"prompt":"Rahul cancels on your group plan for the third time. What do you do?","options":[{"text":"Message him: \"Miss you. No pressure. I'm here.\"","then":"Rahul replies with a heart, then later: \"Thanks. Things are complicated.\"","best":true},{"text":"Tell him to dump the guy or stop calling you","then":"Rahul stops replying. You only see his name in the group chat now."},{"text":"Stop inviting him, since he always cancels","then":"Rahul sees the plans he isn't part of, and drifts further."},{"text":"Vent about his boyfriend in the group chat","then":"Someone screenshots it. Rahul hears, and pulls away from all of you."}],"why":"A steady, no-pressure message keeps a lifeline open. Ultimatums can isolate him more."},{"prompt":"Weeks later, Rahul says his boyfriend only checks his phone because he cares. What do you say?","options":[{"text":"Agree, since it's his relationship and not yours","then":"Rahul looks relieved, and the checking goes on unnamed."},{"text":"Tell him he's being blind about what's happening","then":"Rahul's face shuts. \"I knew you'd judge me.\""},{"text":"Gently name it as control, and say you're with him","then":"Rahul goes quiet. \"Maybe. I don't know yet.\"","best":true},{"text":"Say nothing and change the topic","then":"The moment passes, and so does the chance to name it."}],"why":"Naming it gently, without judging him, plants a thought he can come back to."},{"prompt":"Rahul asks you not to tell anyone what he's shared. What do you do?","options":[{"text":"Tell his family anyway, for his own good","then":"His family calls him in a panic. Rahul feels betrayed and stops talking to you."},{"text":"Promise total secrecy, whatever happens","then":"Rahul relaxes. You wonder what you'd do if things got worse."},{"text":"Say you can't keep hearing about it","then":"Rahul apologises for being a burden and goes quiet again."},{"text":"Keep it private unless he's ever in danger","then":"Rahul nods. \"That's fair.\" That night he sends you a meme.","best":true}],"why":"Keeping his trust while being honest about safety keeps the lifeline strong."},{"prompt":"One night Rahul messages from his laptop: his boyfriend smashed his phone, and he's scared. What do you do?","options":[{"text":"Go over and confront his boyfriend","then":"You arrive to shouting, and Rahul looks more scared than before."},{"text":"Offer your place, and 112 if he's in danger","then":"\"Can I come now?\" he writes. You book him a cab and wait at the gate.","best":true},{"text":"Tell him to calm down and talk it out tomorrow","then":"He goes silent. You don't hear from him until the next afternoon."},{"text":"Tell him this is why he should have left","then":"\"I know,\" he writes, and stops replying."}],"why":"When he's scared, safety comes first: a safe place now, and 112 if he's in danger."}],"debrief":"For someone being controlled, a steady, non-judging friend is a vital lifeline. It's never their fault.","relearn":"Be a steady, non-judgmental lifeline for a friend."},
  {"id":"rr-047","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: love expands your world; control shrinks it. A line you can hold onto?","prompt":"What do you think?","options":["Yes","I'll remember","Expands vs shrinks"],"affirm":"That one line, love expands, control shrinks, can keep you clear for life.","relearn":"Love expands your world; control shrinks it.","persona":"any","source":"the line"},
  {"id":"rr-048","cat":"leaving-safely","type":"strike-rewrite","hook":"\"Leaving means I failed at the relationship.\"","myth":{"un":"Leaving means I failed.","re":"Leaving an unhealthy or unsafe relationship is brave and valid, not a failure.","why":"Choosing your safety and wellbeing is strength."},"relearn":"Leaving an unhealthy or unsafe relationship is brave and valid, not a failure.","persona":"any","source":"leaving is valid"},
  {"id":"rr-049","cat":"leaving-safely","type":"reflect","hook":"Lensy: if a relationship is hurting or controlling you, none of it is your fault. Hear that?","prompt":"What do you think?","options":["Yes","Not my fault","Thank you"],"affirm":"Abuse and control are never the target's fault; the responsibility is the person doing it.","relearn":"Abuse and control are never the target's fault.","persona":"any","source":"not your fault"},
  {"id":"rr-050","cat":"leaving-safely","type":"branch","persona":"any","source":"exit safety","hook":"You've decided to leave Kunal, who checks your phone and controls who you see.","steps":[{"prompt":"You feel scared and don't know where to start. What do you do first?","options":[{"text":"Tell one trusted person your plan, quietly","then":"Your friend Tanvi listens and says you can stay with her whenever you need.","best":true},{"text":"Tell Kunal you're leaving next time he checks your phone","then":"His anger spikes. He starts checking your phone even more often."},{"text":"Keep it all to yourself so nothing leaks out","then":"No one knows what's going on. The plan feels heavy to carry alone."},{"text":"Ask his best friend to talk some sense into him","then":"Within a day Kunal knows. He asks you, coldly, what you've been saying."}],"why":"Telling one trusted person first means you're not planning, or leaving, alone."},{"prompt":"A few days later, you think about where you'd go. What do you do?","options":[{"text":"Line up a safe place to stay, like a friend or relative","then":"Your aunt says her spare room is yours, no questions asked.","best":true},{"text":"Decide you'll sort out a place after you've left","then":"The plan now has a gap right where you'll need it most."},{"text":"Plan to go to your hostel, though he knows your room","then":"It's close by, and he knows exactly where to find you."},{"text":"Wait until you can afford a place of your own","then":"Saving alone could take months, and the checking keeps growing."}],"why":"A safe place ready in advance means you have somewhere to go the moment you need it."},{"prompt":"You realise your ID and certificates are still at his place. What do you do?","options":[{"text":"Quietly move them, or copies, to someone you trust","then":"Your friend keeps the folder safe. One less thing tying you there.","best":true},{"text":"Leave them and plan to ask for them later","then":"Getting them back later could mean facing him alone."},{"text":"Decide they don't matter. You can get new ones","then":"Replacing them could take months of forms and visits."},{"text":"Ask Kunal to hand them over, saying it's for college","then":"He asks why you need them now, and watches you more closely."}],"why":"Having your documents safe means they can't be used to hold you back."},{"prompt":"A friend asks if you know who to call if things get frightening. What do you do?","options":[{"text":"Learn 181 and 112 by heart instead of saving them","then":"You say them over on the walk home. Now they're yours, and he can't find them.","best":true},{"text":"Say you'd just call your parents if anything happened","then":"Your parents live far away and don't know any of this."},{"text":"Laugh it off. It won't come to that","then":"Your friend doesn't laugh. She looks worried for you."},{"text":"Say you'll look up numbers if something happens","then":"In a scary moment, searching could take time you don't have."}],"why":"Knowing the helplines by heart puts help one call away, with nothing on your phone for him to find."},{"prompt":"The day you've planned arrives, and Kunal starts a fight over breakfast. What do you do?","options":[{"text":"Leave as planned, and message him once you're safe","then":"Later, you message him from your safe place, your friend beside you.","best":true},{"text":"Tell him mid-fight that you're leaving him today","then":"His anger spikes fast, and he starts asking where you're going."},{"text":"Write him a long note explaining everything before you go","then":"The note takes an hour, and every sound makes you jump."},{"text":"Call his parents first so they can calm him down","then":"His mother calls him at once. Now he knows something is going on."}],"why":"Leaving quietly and telling him from somewhere safe protects you at the riskiest moment."}],"debrief":"Abuse can escalate around leaving, so plan quietly and get support; the control was never your fault.","relearn":"Leave with a plan: tell someone, a safe place, key documents, a helpline."},
  {"id":"rr-051","cat":"leaving-safely","type":"role-play","persona":"any","source":"reaching for support","hook":"You're planning to leave your controlling boyfriend, Rishi, and you need support.","setup":"Your friend Farah picks up your call.","steps":[{"prompt":"Farah asks: \"You sounded tense. What's going on?\"","options":[{"text":"\"Nothing much. I just wanted to talk.\"","then":"\"Okay,\" she says. Then, gently: \"You still sound tense. I'm here.\""},{"text":"\"I'm leaving Rishi, but I've got it handled alone.\"","then":"\"Alone?\" she asks. \"That sounds like a lot to carry by yourself.\""},{"text":"\"I'm planning to leave Rishi. I'm scared. Help me?\"","then":"She pauses. \"Of course. I'm so glad you called me.\"","best":true},{"text":"\"Honestly, I think I'm the problem.\"","then":"\"Why would you say that?\" Farah sounds worried and confused."}],"why":"Naming the plan and the fear lets someone you trust actually help."},{"prompt":"Farah says: \"I've noticed how scared you seem around Rishi. How can I help?\"","options":[{"text":"\"It's not that bad. I'll manage.\"","then":"\"Maybe,\" she says. \"But I'm worried, and I'm not going anywhere.\""},{"text":"\"Can you go and confront him for me?\"","then":"\"I'd love to,\" she says. \"But would that make it worse for you?\""},{"text":"\"Just promise you won't tell anyone. Ever.\"","then":"\"Not unless you're in danger,\" she says slowly. \"But how do I help if no one knows?\""},{"text":"\"Help me plan how to leave him safely.\"","then":"\"Okay,\" she says softly. \"Then we plan it together.\"","best":true}],"why":"Asking for help to leave safely works better than going it alone or starting a confrontation."},{"prompt":"Farah asks: \"Whenever you're ready to leave, what would make it safer?\"","options":[{"text":"\"A place to stay, my documents, and you knowing when.\"","then":"\"You can stay with me,\" she says. \"Let's list what you need.\"","best":true},{"text":"\"I'll tell him it's over in our next fight.\"","then":"Farah sounds uneasy. \"In the middle of a fight? That worries me.\""},{"text":"\"Nothing. I'll just pack a bag one day and go.\"","then":"\"Just like that?\" she asks. \"Where would you go?\""},{"text":"\"If I stay calmer with him, maybe I won't need to.\"","then":"She's quiet. \"His anger isn't about how calm you are.\""}],"why":"Risk can rise around leaving. A safe place, documents and a trusted person lower it."},{"prompt":"Farah asks: \"And if he turns up or threatens you, then what?\"","options":[{"text":"\"He won't. He's never actually hit me.\"","then":"\"Maybe,\" Farah says. \"But he scares you. That counts too.\""},{"text":"\"I'll ask his parents to talk sense into him.\"","then":"\"His parents?\" she asks. \"Would they really be on your side?\""},{"text":"\"I'll handle it. I don't want to make a fuss.\"","then":"\"It isn't a fuss if you're scared,\" she says quietly."},{"text":"\"I'll call 112, and 181 can help me plan.\"","then":"\"Save them now,\" she says. \"And text me every evening.\"","best":true}],"why":"Help is one call away, and you don't have to do this alone. It's never your fault."}],"relearn":"Tell a trusted person and ask for help to leave safely; you don't have to do it alone."},
  {"id":"rr-052","cat":"leaving-safely","type":"branch","persona":"any","source":"the cycle","hook":"After weeks of Ritika reading your messages, she cries and promises she'll change.","steps":[{"prompt":"It's the third time she's promised this. What do you do?","options":[{"text":"Notice the pattern: promises, then the same control","then":"You remember the last two times. The tears feel familiar now.","best":true},{"text":"Believe her. The tears seem so real this time","then":"Things are sweet for a week. Then she asks for your password again."},{"text":"Blame yourself for making her this insecure","then":"You start apologising for things you haven't done."},{"text":"Ask her friends whether she really means it this time","then":"They say she loves you. That doesn't change what she does."}],"why":"Promises without real change aren't safety. The pattern tells the truth."},{"prompt":"A friend says all couples go through rough patches. What do you do?","options":[{"text":"Say it's control, not a rough patch, and ask for support","then":"Your friend goes quiet, then says, \"I didn't know. I'm here.\"","best":true},{"text":"Agree. Maybe you're making too much of it","then":"The doubt settles in. You stop mentioning it to anyone."},{"text":"Take the advice and try harder to keep Ritika happy","then":"You check every message before sending. It's exhausting."},{"text":"Stop telling anyone, since no one seems to get it","then":"You feel more alone. Fewer people know what's happening."}],"why":"Naming control plainly helps the people around you actually support you."},{"prompt":"A week later, Ritika asks for your phone password again. What do you do?","options":[{"text":"See the pattern, and plan a safe exit with support","then":"You call your cousin that night. Together, you start a plan.","best":true},{"text":"Tell yourself couples should share everything anyway","then":"It feels like sharing. It also means she reads every chat."},{"text":"Argue it out with her until she admits it's control","then":"She cries again and says you're the one being cruel."},{"text":"Give the promise more time. Change can be slow","then":"The weeks pass. The checking carries on as before."}],"why":"Control coming back after a promise is the cycle, and it is never your fault."}],"debrief":"Promise-and-repeat cycles are common in controlling relationships; the pattern is the truth, and it's never your fault.","relearn":"Promises without real change aren't safety; trust the pattern."},
  {"id":"rr-053","cat":"leaving-safely","type":"reflect","hook":"Lensy: you deserve to feel safe and free in love, fully. Believe that for yourself?","prompt":"What do you think?","options":["Yes","I deserve that","Safe and free"],"affirm":"You absolutely deserve to feel safe, respected and free; never settle below that.","relearn":"You deserve to feel safe, respected and free in a relationship.","persona":"any","source":"you deserve safety"},
  {"id":"rr-054","cat":"leaving-safely","type":"branch","persona":"any","source":"after leaving","hook":"Since you left Vikram, he messages daily, begging and then blaming you for leaving.","steps":[{"prompt":"Tonight he sends ten messages in an hour. What do you do?","options":[{"text":"Stop replying, tell a friend, and block him if needed","then":"Your friend helps you block him. The phone finally goes quiet.","best":true},{"text":"Reply politely, so he doesn't think you're cruel","then":"He replies within seconds. Now he's asking to meet."},{"text":"Read every message, looking for a real apology","then":"By midnight you've read them all, and you feel worse."},{"text":"Tell him firmly, one more time, to leave you alone","then":"He takes it as an opening and sends twenty more."}],"why":"No-contact and telling someone protect you. You owe no reply to pressure."},{"prompt":"The next day, his sister messages that he's not eating since you left. What do you do?","options":[{"text":"Say you're sorry he's struggling, and keep your distance","then":"She replies, \"Okay.\" Your chest feels tight, but you hold steady.","best":true},{"text":"Feel responsible, and message him to check he's okay","then":"He replies at once: \"I knew you still cared. Come back.\""},{"text":"Ask his sister to tell him you still care about him","then":"Within an hour, he's sending hopeful messages again."},{"text":"Snap at her for guilt-tripping you like this","then":"She forwards your message to him. He calls you heartless."}],"why":"His struggles are real, but they aren't yours to fix by going back."},{"prompt":"A week later, angry messages arrive, some from numbers you don't know. What do you do?","options":[{"text":"Block them, screenshot each one, and tell a friend","then":"A friend helps you start a record of them. You feel less alone.","best":true},{"text":"Reply once to ask what he wants from you","then":"He takes it as an opening, and messages all evening."},{"text":"Keep it to yourself, so no one worries about you","then":"Each new message lands on you, and no one else knows."},{"text":"Decide it's harmless, since he's only texting","then":"The messages keep coming, a little angrier each day."}],"why":"A record, and someone who knows, make it easier to get help if it keeps up."},{"prompt":"A mutual friend says Vikram keeps asking where you live now. What do you do?","options":[{"text":"Ask friends not to share your address. Call 112 if unsafe","then":"The mutual friend promises to keep it quiet, and your friends set up a daily check-in.","best":true},{"text":"Decide it's harmless. Vikram isn't the type to turn up","then":"The questions keep coming, and you start checking the street."},{"text":"Plan to handle him yourself if he ever turns up","then":"You rehearse what you'd say, alone, and sleep badly."},{"text":"Offer to meet him once, alone, to end it for good","then":"The mutual friend passes it on. Vikram replies within minutes: \"Finally.\""}],"why":"Pressure after leaving is a warning, and it's never your fault. Help is a call away."}],"debrief":"No-contact and support after leaving protect you; persistent pressure is itself a warning.","relearn":"After leaving, go no-contact, tell someone, and block if needed."},
  {"id":"rr-055","cat":"leaving-safely","type":"role-play","persona":"any","source":"supporting safely","hook":"Your friend Karan admits his girlfriend controls where he goes, and her anger frightens him.","setup":"He's staring into his chai, waiting.","steps":[{"prompt":"Karan says: \"I don't even know why I'm telling you this.\"","options":[{"text":"\"Are you sure you're not overreacting a bit?\"","then":"Karan's face closes. \"Forget it. It's probably nothing.\""},{"text":"\"Bro, you need to dump her today.\"","then":"He shakes his head. \"It's not that simple. You don't get it.\""},{"text":"\"I believe you, and it's not your fault. I'm here.\"","then":"His shoulders drop. \"I didn't think anyone would believe me.\"","best":true},{"text":"\"Wow. She always seemed so sweet.\"","then":"He shrinks back. \"Yeah. Everyone says that.\""}],"why":"Believing him first, and saying it's not his fault, makes it safe for him to keep talking."},{"prompt":"Karan asks: \"Do you think I'm weak for letting it get this far?\"","options":[{"text":"\"A bit, maybe. You should have stood up to her.\"","then":"\"Yeah,\" he mutters, and stares at the table."},{"text":"\"No. Control traps people by design. It's on her.\"","then":"He lets out a long breath. \"I've been blaming myself for months.\"","best":true},{"text":"\"Honestly, guys don't usually get pushed around.\"","then":"Karan goes red. \"So it is weird. Great.\""},{"text":"\"Don't think about that. Let's talk about something fun.\"","then":"He forces a smile, and the question stays with him."}],"why":"Control works on anyone. Saying it isn't weakness lifts the shame that keeps people quiet."},{"prompt":"Karan asks: \"So what do I even do now?\"","options":[{"text":"\"Leave her tonight. I'll come and help you pack.\"","then":"Karan looks panicked. \"Tonight? I'm not ready for that.\""},{"text":"\"I'll talk to her myself and sort this out.\"","then":"\"No, please,\" he says fast. \"She'll know I told you.\""},{"text":"\"It's your call. Want to plan how to stay safe?\"","then":"\"Yeah,\" he says. \"Maybe start with where I'd go if it gets bad.\"","best":true},{"text":"\"Try being extra patient with her for now.\"","then":"He nods slowly, already bracing for the next time she's angry."}],"why":"Respecting his pace and planning safety together keeps him in charge of his own life."},{"prompt":"Karan asks: \"What if she finds out I told you?\"","options":[{"text":"\"Then say sorry and calm her down.\"","then":"He nods, and you watch him slip back into the old pattern."},{"text":"\"Call me any time, and 112 if you're in danger.\"","then":"He saves your number at the top. \"Okay. Thanks. Really.\"","best":true},{"text":"\"Then you'll finally have to face it.\"","then":"Karan goes pale. \"That's exactly what I'm scared of.\""},{"text":"\"I'll keep quiet about it. Let's not mention it again.\"","then":"He looks relieved, then lost. \"Right. Okay.\""}],"why":"Steady contact and a real route to help mean he's never facing it on his own."}],"relearn":"Believe a friend, tell them it's not their fault, and offer to plan safety together."},
  {"id":"rr-056","cat":"leaving-safely","type":"sort","hook":"Sort: a safer-leaving step, or a risk?","items":[{"id":"a","text":"Confiding in a trusted person"},{"id":"b","text":"Threatening them back in a fight"},{"id":"c","text":"Knowing a helpline and safe place"},{"id":"d","text":"Going to confront them alone"},{"id":"e","text":"Packing key documents quietly in advance"},{"id":"f","text":"Announcing you're leaving mid-argument"}],"bins":[{"id":"safer","label":"Safer","valence":"pos"},{"id":"risk","label":"Risk","valence":"neg"}],"key":{"a":"safer","b":"risk","c":"safer","d":"risk","e":"safer","f":"risk"},"relearn":"Confiding, knowing a helpline and packing ahead are safer; confronting alone, threats and mid-fight announcements are risks.","persona":"any","source":"exit safety"},
  {"id":"rr-057","cat":"leaving-safely","type":"reflect","hook":"Lensy: walking away from what's hurting you is one of the bravest things a person does. Own that?","prompt":"What do you think?","options":["Yes","It's brave","I can do it"],"affirm":"Leaving takes real courage; if you do it, you're brave, not a failure.","relearn":"Walking away from what's hurting you is brave, not a failure.","persona":"Rohan","source":"courage"},
  {"id":"rr-058","cat":"leaving-safely","type":"branch","persona":"any","source":"no shame","hook":"You're out of a controlling relationship, and you feel ashamed you let it go on so long.","steps":[{"prompt":"Lying awake, you replay every sign you missed. What do you tell yourself?","options":[{"text":"Control is built to trap people. The shame isn't mine","then":"It doesn't fix everything, but your shoulders ease a little.","best":true},{"text":"I should have seen it sooner. I was so naive","then":"The replay starts again, harsher each time."},{"text":"Only weak people end up in a relationship like that","then":"You feel smaller, and don't want anyone to know."},{"text":"It wasn't that bad. Others have it much worse","then":"It dulls the feeling, and blurs what really happened."}],"why":"Control traps capable people by design. What happened was never your fault."},{"prompt":"Your cousin asks why you didn't just leave earlier. What do you do?","options":[{"text":"Say control makes leaving hard, for anyone","then":"Your cousin pauses. \"I never thought of it like that.\"","best":true},{"text":"Agree you were foolish, so the talk ends quickly","then":"She nods. The word 'foolish' follows you around for days."},{"text":"Snap that she has no idea what it was like","then":"She goes quiet. You both feel worse."},{"text":"Laugh it off and change the subject","then":"She lets it go. The question stays with you."}],"why":"Explaining how control works protects you from other people's blame, and your own."},{"prompt":"A month later, you notice you're still quietly blaming yourself. What do you do?","options":[{"text":"Talk it through with a counsellor or someone you trust","then":"As you say it out loud to someone kind, it starts to feel lighter.","best":true},{"text":"Keep it to yourself. You got yourself into it","then":"The shame stays tucked away, and it stays heavy."},{"text":"Throw yourself into work so there's no time to think","then":"You're busy all day. At night, the thoughts come back."},{"text":"Read up alone on red flags so it never happens again","then":"You learn a lot, and still feel it was all your fault."}],"why":"Shame shrinks when it's shared with someone kind. You don't have to carry it alone."}],"debrief":"Coercive control traps capable people by design; staying as long as you did is not a personal failing.","relearn":"Control traps people by design; the shame isn't yours."},
  {"id":"rr-059","cat":"leaving-safely","type":"branch","persona":"any","source":"the pull","hook":"You've left Neha, who controlled your every plan, but part of you still misses her.","steps":[{"prompt":"Tonight the missing hits hard. What do you do?","options":[{"text":"Remind yourself it's normal, and call a friend","then":"Your friend stays on the phone till you feel steadier.","best":true},{"text":"Take it as a sign you should go back to her","then":"You open her chat and start typing, heart racing."},{"text":"Decide something's wrong with you for missing her","then":"The feeling mixes with shame and gets heavier."},{"text":"Scroll through old photos to feel close to her","then":"The good days fill the screen. The hard ones don't show."}],"why":"Missing someone who hurt you is normal, and not your fault. It isn't a reason to go back."},{"prompt":"A few days later, Neha likes an old photo of yours. What do you do?","options":[{"text":"Mute or block her, and tell your friend it happened","then":"Your friend replies, \"Thanks for telling me. Want to meet tomorrow?\"","best":true},{"text":"Like one of hers back, just to be friendly","then":"A message arrives within minutes: \"I miss you.\""},{"text":"Stare at it for an hour, wondering what it means","then":"By midnight you've read into it a dozen different ways."},{"text":"Message her to ask why she did it","then":"She replies at once, warm and familiar. The pull gets stronger."}],"why":"Closing the small doors back protects the distance you've worked for."},{"prompt":"Your weekend is empty, and that's when the pull feels strongest. What do you do?","options":[{"text":"Fill it with friends and something of your own","then":"It isn't magic, but Sunday passes without that ache.","best":true},{"text":"Stay in and wait for the feeling to pass on its own","then":"The hours drag, and your thoughts keep drifting to her."},{"text":"Keep busy on your phone all weekend, scrolling","then":"The hours vanish, and so does the weekend. The ache is still there."},{"text":"Walk past her hostel, just to see","then":"Her window light is on. You walk back more shaken than before."}],"why":"Rebuilding your own life, with people around you, is what gets you through the pull."}],"debrief":"Missing an ex, even a harmful one, is normal; it isn't a signal to go back.","relearn":"Missing an ex is normal; it isn't a reason to return to harm."},
  {"id":"rr-060","cat":"leaving-safely","type":"match","hook":"Match the need to the help (India).","pairs":[{"left":"In danger right now","right":"Emergency 112"},{"left":"Woman facing violence","right":"Women's helpline 181"},{"left":"Need to talk it through","right":"A counsellor or trusted person"},{"left":"Heavy low mood after leaving","right":"Tele-MANAS 14416"},{"left":"Woman in distress, any time","right":"1091"}],"relearn":"112 for danger, 181 / 1091 for violence and distress, Tele-MANAS 14416 for low mood, a counsellor to talk.","persona":"Meena","source":"help routes"},
  {"id":"rr-061","cat":"leaving-safely","type":"reflect","hook":"Lensy: leaving isn't the end of your story, it's the start of a safer one. Hold onto that?","prompt":"What do you think?","options":["Yes","A new start","Safer story"],"affirm":"Leaving opens a safer, freer chapter; your story keeps going, better.","relearn":"Leaving is the start of a safer story, not the end.","persona":"any","source":"new chapter"},
  {"id":"rr-062","cat":"breakups","type":"reflect","hook":"Lensy: heartbreak is real grief, and it's survivable. Does naming it that way help?","prompt":"What do you think?","options":["Yes","It's grief","Survivable"],"affirm":"Treating heartbreak as real grief, and survivable, is the honest, kind way through it.","relearn":"Heartbreak is real grief, and it is survivable.","persona":"any","source":"grief"},
  {"id":"rr-063","cat":"breakups","type":"strike-rewrite","hook":"\"A breakup means something's wrong with me.\"","myth":{"un":"A breakup means something's wrong with me.","re":"Breakups are painful but normal; they're not a verdict on your worth.","why":"Not every relationship is meant to last."},"relearn":"A breakup is painful but normal; it's not a verdict on your worth.","persona":"Deepak","source":"self-worth"},
  {"id":"rr-064","cat":"breakups","type":"branch","persona":"any","source":"no-contact","hook":"Two days after you and Kabir broke up, your thumb keeps drifting to his chat.","steps":[{"prompt":"It's late, and you've typed \"hey\" into his chat. What do you do?","options":[{"text":"Send it. Staying friendly will make this easier","then":"He replies an hour later with \"hey\". You stay up reading into one word."},{"text":"Send a meme you both used to laugh at","then":"He sends back a laughing emoji. For a minute nothing has ended. Then it hurts more."},{"text":"Delete it and mute his chat for a few weeks","then":"The screen stays quiet. It aches, but the night isn't spent waiting for a reply.","best":true},{"text":"Keep the draft and decide in the morning","then":"Morning comes, and the draft is still there, waiting for you."}],"why":"A break from contact lets the wound start to close instead of reopening each night."},{"prompt":"A week later, your friend Tanvi says a clean break is too dramatic. What do you do?","options":[{"text":"Tell her you need space from Kabir first","then":"Tanvi shrugs, then nods. \"Fair. Take the time you need.\"","best":true},{"text":"Agree and invite Kabir for coffee as friends","then":"He talks about his week. You walk home feeling raw all over again."},{"text":"Stay friends, but only text him on weekends","then":"Weekends turn into the part of the week you wait for, and dread."},{"text":"Tell Tanvi to mind her own business","then":"Tanvi goes quiet, and you lose the one friend asking how you are."}],"why":"You set the pace. Space comes first, and friendship later only if you both want it."},{"prompt":"Kabir texts that he misses talking every day. What do you reply?","options":[{"text":"Leave it on read without answering","then":"He sends two more messages asking if you're okay. The question hangs open."},{"text":"Say you need no contact for a while to heal","then":"He replies \"okay\" and nothing more. The quiet is hard, and a little lighter each day.","best":true},{"text":"Say you can talk, but only about light stuff","then":"Light stuff turns into long chats by the third night."},{"text":"Reply that you never want to hear from him again","then":"He sends an angry paragraph back, and you spend the night rereading it."}],"why":"A clear, calm line gives you both room to heal, without leaving him guessing."},{"prompt":"One lonely Sunday, you feel like rereading your old chats with Kabir. What do you do?","options":[{"text":"Read them all, just this once","then":"Two hours later you're back at the start, missing him like it's day one."},{"text":"Message him that you've been thinking of him","then":"He replies within minutes, and you're pulled right back in."},{"text":"Archive the chat and call a friend instead","then":"Your friend Sneha picks up. Twenty minutes of her gossip, and the pull eases.","best":true},{"text":"Screenshot the sweet ones to keep forever","then":"You now have forty screenshots, and a new folder to look at."}],"why":"Pointing the urge somewhere new gives you room to keep healing."}],"debrief":"A period of no-contact is one of the most reliable ways to heal after a breakup.","relearn":"A period of no-contact after a breakup helps you heal."},
  {"id":"rr-065","cat":"breakups","type":"sort","hook":"Sort: healthy coping, or numbing/harm?","items":[{"id":"a","text":"Leaning on friends and routine"},{"id":"b","text":"Drowning it in substances"},{"id":"c","text":"Moving your body and sleeping"},{"id":"d","text":"Reckless, self-punishing choices"},{"id":"e","text":"Naming what you feel out loud"},{"id":"f","text":"Skipping meals to 'feel nothing'"}],"bins":[{"id":"healthy","label":"Healthy coping","valence":"pos"},{"id":"harm","label":"Numbing / harm","valence":"neg"}],"key":{"a":"healthy","b":"harm","c":"healthy","d":"harm","e":"healthy","f":"harm"},"relearn":"Friends, routine, movement, sleep and naming feelings are healthy coping; substances or self-punishing choices aren't.","persona":"any","source":"coping"},
  {"id":"rr-066","cat":"breakups","type":"role-play","persona":"any","source":"supporting a friend","hook":"Your friend Rhea just broke up with her boyfriend of two years.","setup":"She calls you, crying.","steps":[{"prompt":"Rhea says: \"I feel like such a failure. I couldn't even keep one relationship.\"","options":[{"text":"\"Honestly, he was never good enough for you.\"","then":"\"That doesn't help,\" she says. \"I loved him.\""},{"text":"\"It hurts because it mattered, not because you failed.\"","then":"She sniffs. \"It really did matter. Can I just talk for a bit?\"","best":true},{"text":"\"Just get over it. There are other people.\"","then":"Rhea goes quiet. \"Right. Sorry for bothering you.\""},{"text":"\"You're not a failure. Let's not even talk about him.\"","then":"\"But I need to talk about him,\" she says, voice cracking."}],"why":"Naming the pain as proof it mattered takes away the shame of failing."},{"prompt":"Rhea asks: \"Was it my fault? Did I ruin everything?\"","options":[{"text":"\"Maybe a bit. You were quite clingy with him.\"","then":"Rhea's voice breaks. \"So it is me.\""},{"text":"\"No. It was all him, every bit of it.\"","then":"\"It wasn't all him either,\" she says, not comforted."},{"text":"\"A breakup isn't a verdict on you. What's on your mind?\"","then":"She takes a breath. \"I keep replaying our last fight.\"","best":true},{"text":"\"Don't think about that now. Want to watch a movie?\"","then":"\"Maybe later,\" she says. The question is still in her voice."}],"why":"Taking blame off the table and listening helps her think clearly."},{"prompt":"A few days later, Rhea says: \"I think I'm just not meant for love.\"","options":[{"text":"\"Don't say that! You'll find someone in no time.\"","then":"\"You don't know that,\" she says flatly."},{"text":"\"Maybe take a break from dating for a year.\"","then":"Rhea sighs. \"I'm not thinking about dating. I'm thinking about me.\""},{"text":"\"Same. Love is overrated anyway.\"","then":"She laughs weakly, then goes quiet. \"I guess.\""},{"text":"\"You're hurting. It won't always feel like this.\"","then":"Rhea exhales. \"I hope so. Thanks for sticking around.\"","best":true}],"why":"Validating the hurt and offering hope helps more than rushing her to the next person."}],"relearn":"Remind a heartbroken friend the pain means it mattered, not that they failed."},
  {"id":"rr-067","cat":"breakups","type":"branch","persona":"any","source":"healing pace","hook":"Six weeks after the breakup, most days are okay, but some mornings still hit hard.","steps":[{"prompt":"Today is one of the hard ones, and you have class at ten. What do you do?","options":[{"text":"Stay in bed. You've earned a full day off","then":"The hours slide by. By evening you feel lower, and the day feels lost."},{"text":"Scold yourself for still being sad after six weeks","then":"The pressure piles on top of the sadness, and both feel heavier."},{"text":"Go to class, then plan an easy evening with a friend","then":"Class is a blur, but chai with Neha afterwards makes the day lighter.","best":true},{"text":"Pack the day with gym and work so you can't feel it","then":"You're busy till midnight, and the sadness is waiting when you lie down."}],"why":"Gentle routines carry you through hard days without forcing the feelings away."},{"prompt":"Your cousin Raghav says you should be over it by now. What do you say?","options":[{"text":"Say healing has no deadline, and you're getting there","then":"Raghav pauses. \"Fair. Tell me if you want to get out sometime.\"","best":true},{"text":"Agree that something must be wrong with you","then":"The thought follows you home and sits with you all evening."},{"text":"Laugh and say you're totally over it","then":"The topic changes, and you feel more alone with it than before."},{"text":"Promise him you'll be over it by next week","then":"Next week brings a low morning, and now it feels like failing a test."}],"why":"There's no timetable for healing. Saying so calmly protects your pace."},{"prompt":"A month later, a song on the bus brings it all back for a moment. What do you tell yourself?","options":[{"text":"This proves I'm back to square one","then":"You spend the evening feeling like the last month didn't count."},{"text":"A wave like this is normal, and it will pass","then":"The song ends. By your stop the feeling has eased, and the day goes on.","best":true},{"text":"I need to delete every song that reminds me of them","then":"An hour of clearing playlists later, the same song plays in a shop."},{"text":"I should text them that our song came on","then":"They reply \"haha same\", and you're checking your phone all night."}],"why":"Low moments after progress are part of healing, not a sign you've slipped back."}],"debrief":"Healing from heartbreak isn't a race. Gentle routines and time do the work.","relearn":"Healing takes its own time; keep your routines and be patient."},
  {"id":"rr-068","cat":"breakups","type":"strike-rewrite","hook":"\"I should be over it by now.\"","myth":{"un":"I should be over it by now.","re":"Grief follows no timetable; healing isn't a race, and your pace is okay.","why":"Pushing past grief just delays it."},"relearn":"Grief follows no timetable; your healing pace is okay.","persona":"any","source":"no timetable"},
  {"id":"rr-069","cat":"breakups","type":"branch","persona":"Zoya","source":"rebuilding","hook":"After you and Ishita split, you notice your weekends, friends and plans had all become hers.","steps":[{"prompt":"Saturday arrives and your phone is quiet. What do you do?","options":[{"text":"Download a dating app to fill up the weekend","then":"A few chats start and fizzle out. The weekend still feels empty."},{"text":"Message Farah, an old friend, and suggest chai","then":"Farah replies fast. \"Finally! Tomorrow at five, our old place.\"","best":true},{"text":"Scroll through Ishita's stories to see how she is","then":"She's at a café you both loved, and the day sinks from there."},{"text":"Spend the whole day giving your room a makeover","then":"The room looks new by night. You still feel like a guest in your own life."}],"why":"Reaching back to an old friend starts rebuilding a life that is yours."},{"prompt":"A few days later, you find your old sketchbook under Ishita's gifts. What do you do?","options":[{"text":"Put it away. It feels like someone else's hobby","then":"The sketchbook goes back under the gifts, and the evening feels flat."},{"text":"Sketch Ishita from memory to get her out of your head","then":"It helps for an hour. Then you're back to thinking about her."},{"text":"Sign up for the Sunday sketch walk you used to love","then":"You're rusty and shy, but two strangers ask to see your pages.","best":true},{"text":"Throw out the gifts and the sketchbook together","then":"The shelf is emptier, and somehow so are you."}],"why":"Picking up what you loved before brings back the parts of you that were yours."},{"prompt":"At a friend's birthday, someone asks what you're into these days. What do you say?","options":[{"text":"Talk about the shows Ishita loved, out of habit","then":"Halfway through, you realise you're describing her life, not yours."},{"text":"Say you don't really have hobbies","then":"They nod politely and drift off to someone else."},{"text":"Say you're figuring it out, and change the subject","then":"It's honest, but the chance to share something passes."},{"text":"Name one thing you're getting back into","then":"Turns out they're into it too. You swap numbers before the cake.","best":true}],"why":"Naming what's yours, even something small, helps you rebuild who you are."},{"prompt":"Two months on, you start seeing someone new, Aditi. How do you plan your weekends?","options":[{"text":"Keep your own plans, and make room for her too","then":"Saturday is for Aditi and Sunday is yours. You like both.","best":true},{"text":"Clear them all to spend with her","then":"The weekends fill up fast, and your friends' messages go quiet again."},{"text":"Keep your plans, but drop them whenever she asks","then":"She asks often. By the third week, your Sundays are hers too."},{"text":"Cancel on Aditi to prove you're independent now","then":"Aditi is confused, and you're not sure what you proved."}],"why":"Keeping your own friends and interests means someone new adds to your life, not replaces it."}],"debrief":"Reclaiming your friendships, interests and identity is how you truly rebuild after a breakup.","relearn":"Rebuild your own friendships, interests and identity."},
  {"id":"rr-070","cat":"breakups","type":"role-play","persona":"any","source":"reaching out","hook":"Since your breakup, you've been hiding in your room and telling everyone you're fine.","setup":"Your friend Yusuf calls about Saturday.","steps":[{"prompt":"Yusuf asks: \"So are you coming to the match on Saturday or what?\"","options":[{"text":"\"Can't. I'm swamped with assignments.\"","then":"\"Okay, next time then,\" he says, and hangs up."},{"text":"\"Yeah, obviously. I'm totally fine.\"","then":"\"Great!\" He moves on to who's bringing snacks."},{"text":"\"Honestly, the breakup's hit me hard. Can we talk?\"","then":"Yusuf goes quiet. \"Of course. I'm listening.\"","best":true},{"text":"\"I'm a bit low lately, but it's nothing, really.\"","then":"\"Oh, okay. Feel better,\" he says, unsure whether to push."}],"why":"Saying plainly that you're struggling lets a friend actually help."},{"prompt":"Later that week, Yusuf texts: \"You've been quiet on the group. All okay?\"","options":[{"text":"\"Just busy. Nothing to worry about.\"","then":"\"Cool,\" he replies, and the chat goes quiet."},{"text":"\"Not really. Could you come over this evening?\"","then":"\"On my way after class,\" he replies. \"Bringing samosas.\"","best":true},{"text":"\"I don't want to be a burden with my drama.\"","then":"\"You're not a burden,\" he writes. \"But I can't help if you don't tell me.\""},{"text":"\"I should be able to handle this myself.\"","then":"\"Sure,\" he writes. \"But you don't have to.\""}],"why":"A specific ask makes it easy for a friend to show up."},{"prompt":"A week on, Yusuf asks: \"Be honest. What would actually help right now?\"","options":[{"text":"\"Nothing. I'll sort myself out.\"","then":"\"Okay,\" he says, sounding a bit shut out."},{"text":"\"Help me get my ex back.\"","then":"Yusuf pauses. \"I don't think that's what you need.\""},{"text":"\"Check in now and then, and drag me out sometimes.\"","then":"\"Done,\" he says. \"Chai on Sundays, no excuses.\"","best":true},{"text":"\"Just distract me. Never mention the breakup.\"","then":"He agrees. The games are fun, but the hurt stays unspoken."}],"why":"Telling a friend what helps turns their care into real support."}],"relearn":"Reaching out to a friend when heartbroken is healthy, not weak."},
  {"id":"rr-071","cat":"breakups","type":"branch","persona":"any","source":"wellbeing / help","hook":"A month after the breakup, you're sleeping badly, skipping meals and feel low almost every day.","steps":[{"prompt":"Your roommate Mitali asks if you're okay. What do you say?","options":[{"text":"Say you're just tired from exams","then":"Mitali nods and heads out. The room goes quiet again."},{"text":"Say you'll snap out of it if you try harder","then":"She looks unsure but lets it go. You lie awake making promises to yourself."},{"text":"Tell her honestly that it's been heavy for weeks","then":"Mitali sits on your bed. \"Thanks for telling me. We'll figure this out.\"","best":true},{"text":"Say it's too much to explain right now","then":"Mitali hovers at the door, then leaves you to it."}],"why":"Telling one trusted person the truth is the first step out of carrying it alone."},{"prompt":"A few days later, the low feeling hasn't lifted at all. What do you do?","options":[{"text":"Wait it out. Everyone feels this after a breakup","then":"Another week passes, and the heaviness settles in deeper."},{"text":"Call Tele-MANAS 14416 or see the campus counsellor","then":"The first talk feels awkward. By the end, someone has listened and you have a next step.","best":true},{"text":"Ask Mitali to keep you busy every evening","then":"The evenings pass faster, but the heaviness is waiting each night."},{"text":"Stay up scrolling so you don't have to think","then":"It's 4am before you sleep, and the next day starts heavier."}],"why":"Weeks of heavy low mood deserve real support. Reaching for it is strength, not weakness."},{"prompt":"Your friend Varun says counselling is only for serious problems. What do you do?","options":[{"text":"Drop the idea of getting help for now","then":"The relief lasts a day. Then the heaviness is back, with no plan."},{"text":"Wait to see if it's still bad next month","then":"Varun nods, relieved. Getting help turns into a vague someday."},{"text":"Say weeks of low mood are serious enough","then":"Varun thinks for a second. \"Okay. I didn't know it worked like that.\"","best":true},{"text":"Agree, and hide how you feel from everyone","then":"You smile through class. At night, it's heavier than ever."}],"why":"Persistent low mood is a real reason for support. You don't need a bigger problem first."},{"prompt":"Two weeks on, the heaviness comes and goes. What do you do?","options":[{"text":"Set a weekly check-in with a counsellor or Mitali","then":"In the third week, you notice you slept through the night twice.","best":true},{"text":"Decide nothing will help and stop trying","then":"Without a plan, the evenings get long and heavy again."},{"text":"Keep going, but hide the bad days from everyone","then":"Your friends think you're fine, so no one checks in on the worst nights."},{"text":"Push yourself to feel fine by the weekend","then":"The weekend comes, and the pressure makes it heavier."}],"why":"Healing is gradual. Steady support and small steps help it along."},{"prompt":"A month later, you feel steadier, though some nights still dip. What do you do?","options":[{"text":"Stop talking about it now that you're better","then":"A bad week hits, and you feel alone with it again."},{"text":"Treat each dip as proof you're back at the start","then":"One low night turns into three days of doubting yourself."},{"text":"Lean on people you trust, dips and all","then":"The dips come less often, and when they do, you know who to text.","best":true},{"text":"Only reach out once a dip gets really bad","then":"A rough patch comes, and you wait three hard nights before texting anyone."}],"why":"People you trust keep you steady, even after the worst has passed."}],"debrief":"Persistent heavy low mood after a breakup is worth real support, not toughing out alone.","relearn":"If heartbreak's low mood stays heavy, reach for real support."},
  {"id":"rr-072","cat":"breakups","type":"reflect","hook":"Lensy: you were whole before this person, and you're whole after. Feel the truth in that?","prompt":"What do you think?","options":["Yes","Whole on my own","I'll be okay"],"affirm":"You're a whole person on your own; a breakup changes your life, not your worth.","relearn":"You were whole before, and you're whole after; you'll be okay.","persona":"any","source":"wholeness"},
  {"id":"rr-073","cat":"breakups","type":"sort","hook":"Sort: helps you move forward, or keeps you stuck?","items":[{"id":"a","text":"Unfollowing to get space"},{"id":"b","text":"Stalking their profile daily"},{"id":"c","text":"Investing in friends and goals"},{"id":"d","text":"Replaying it on a loop alone"},{"id":"e","text":"Trying something new this month"},{"id":"f","text":"Re-reading old chats every night"}],"bins":[{"id":"forward","label":"Moves forward","valence":"pos"},{"id":"stuck","label":"Keeps stuck","valence":"neg"}],"key":{"a":"forward","b":"stuck","c":"forward","d":"stuck","e":"forward","f":"stuck"},"relearn":"Space, new things and investing in your life move you forward; stalking, looping and re-reading chats keep you stuck.","persona":"any","source":"moving on"},
  {"id":"rr-074","cat":"breakups","type":"reflect","hook":"Lensy: which breakup truth will you keep close?","prompt":"Pick one.","options":["It's grief, and survivable","No timetable for healing","I'm whole on my own","Rebuild my own life"],"affirm":"Hold onto that one, and heartbreak becomes something you grow through, not just survive.","relearn":"Heartbreak is survivable grief; heal at your pace and rebuild your life.","persona":"any","source":"consolidation"},
  {"id":"rr-075","cat":"tools-and-help","type":"match","persona":"any","source":"toolkit","relearn":"'I' statements, calming breaks, repair, appreciation and owning your part each have their moment.","hook":"Match the relationship tool to when you'd use it.","pairs":[{"left":"'I felt...' statement","right":"Raising a hurt"},{"left":"Take a break, then return","right":"When you're too flooded"},{"left":"Repair attempt","right":"After a fight"},{"left":"Appreciation out loud","right":"Countering contempt"},{"left":"Owning your part","right":"Instead of defending"}]},
  {"id":"rr-076","cat":"tools-and-help","type":"sort","persona":"any","source":"flags","relearn":"Free, respected, repairing and keeping your friends is green; controlled, watched, eggshells, shrinking is red.","hook":"Sort: a relationship green flag, or red flag, to remember?","items":[{"id":"a","text":"Feeling free and respected"},{"id":"b","text":"Feeling controlled and watched"},{"id":"c","text":"Repairing after conflict"},{"id":"d","text":"Walking on eggshells"},{"id":"e","text":"Keeping your own friends"},{"id":"f","text":"Your world quietly shrinking"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"}},
  {"id":"rr-077","cat":"tools-and-help","type":"match","persona":"any","source":"help routes","relearn":"181/1091/112 for violence, Tele-MANAS 14416 for low mood, a trusted person or counsellor to talk it through.","hook":"Match the need to the route (India).","pairs":[{"left":"Facing violence or threats","right":"181 / 1091 / 112"},{"left":"Heavy low mood after a breakup","right":"Tele-MANAS 14416"},{"left":"Want to think it through","right":"A counsellor or trusted person"},{"left":"Need a safe place tonight","right":"Someone you trust"},{"left":"Unsure if it's even abuse","right":"Name it to a counsellor"}]},
  {"id":"rr-078","cat":"tools-and-help","type":"branch","persona":"any","source":"the check","hook":"You've been seeing Aditya for two months, and you want to know if it's good for you.","steps":[{"prompt":"Your feelings are strong, but you're not sure. Which question do you ask yourself?","options":[{"text":"How intense are my feelings for him?","then":"Very intense, you realise. It still doesn't tell you much."},{"text":"Would my family approve of him?","then":"You picture your parents' faces, and your own view gets lost."},{"text":"Does it expand my world and respect me?","then":"You think of your friends, your classes, how he listens. The answers come fast.","best":true},{"text":"Does he make me happy most days?","then":"Mostly, yes. But you can't tell whether you're treated well."}],"why":"Intensity isn't the test. A good relationship widens your world and respects you."},{"prompt":"A friend says Aditya must be great because he texts you all day. What do you think?","options":[{"text":"Texting all day proves he's serious","then":"You feel flattered, and stop noticing when texts feel like check-ins."},{"text":"Maybe I should text him that much too","then":"Your phone never leaves your hand, and your evenings shrink."},{"text":"She's right. That's what love looks like","then":"You relax, and the question you started with goes unanswered."},{"text":"Texts show interest. Respect is the real test","then":"You check the markers instead: space, respect, your friends.","best":true}],"why":"Attention can feel like love. Respect and room for your own life are truer markers."},{"prompt":"Weeks later you notice you see your friends less since you started dating. What do you do?","options":[{"text":"Ask if this expands your world, then call friends","then":"You plan a Saturday with friends. Aditya says, \"Have fun!\"","best":true},{"text":"Figure it's normal to see friends less when dating","then":"The weeks go by, and your world gets quietly smaller."},{"text":"Blame yourself for being a bad friend","then":"You feel guilty, but nothing changes."},{"text":"Ask Aditya to decide how much time is fair","then":"He shrugs and says it's up to you. The choice was always yours."}],"why":"The test is worth asking again. Healthy love keeps your friends and interests in your life."}],"debrief":"\"Does it expand my world and treat me with respect?\" is a simple, reliable check.","relearn":"A good test: does it expand your world and respect you?"},
  {"id":"rr-079","cat":"tools-and-help","type":"reflect","hook":"Lensy: knowing how to build, repair, recognise and leave, you're equipped for real love. Feel it?","prompt":"What do you think?","options":["Yes","Equipped","Ready for real love"],"affirm":"Build, repair, recognise, leave, that toolkit sets you up for healthy love and a safe exit if you need one.","relearn":"You're equipped to build, repair, recognise and leave; that's real-love-ready.","persona":"any","source":"equipped"},
  {"id":"rr-080","cat":"tools-and-help","type":"sort","persona":"any","source":"healthy habits","relearn":"Talking, naming needs and a breather-then-return is healthy; bottling, silent punishment or trashing them isn't.","hook":"Sort: a healthy thing to do after a hard relationship moment, or not?","items":[{"id":"a","text":"Talking to a trusted friend"},{"id":"b","text":"Bottling it up entirely"},{"id":"c","text":"Naming what you need"},{"id":"d","text":"Punishing them with silence"},{"id":"e","text":"Taking a breather, then returning"},{"id":"f","text":"Trashing them to everyone online"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"}},
  {"id":"rr-081","cat":"tools-and-help","type":"match","persona":"any","source":"antidotes","relearn":"Each conflict-wrecker has an antidote: 'I' statement, appreciation, owning it, a calming break, naming a need.","hook":"Match the wrecker to its antidote.","pairs":[{"left":"Criticism","right":"Gentle 'I' statement"},{"left":"Contempt","right":"Appreciation and respect"},{"left":"Defensiveness","right":"Take responsibility"},{"left":"Stonewalling","right":"Self-soothe, then return"},{"left":"Score-keeping","right":"Name one specific need"}]},
  {"id":"rr-082","cat":"tools-and-help","type":"reflect","hook":"Lensy: if you ever feel unsafe in a relationship, getting help is strength, not weakness. Clear?","prompt":"What do you think?","options":["Yes","Strength","I'd reach out"],"affirm":"Reaching for help when unsafe is one of the strongest, wisest things you can do.","relearn":"If you feel unsafe in a relationship, getting help is strength, not weakness.","persona":"any","source":"help is strength"},
  {"id":"rr-083","cat":"tools-and-help","type":"branch","persona":"any","source":"passing it on","hook":"Your friend Faisal has started dating someone new, and asks how to tell if it's healthy.","steps":[{"prompt":"He's half joking, but he means it. What do you tell him?","options":[{"text":"Say love can't be analysed. Just feel it","then":"Faisal laughs, but he still looks unsure."},{"text":"Share the markers: respect, trust, equality, space","then":"Faisal counts on his fingers. \"Okay. That's actually useful.\"","best":true},{"text":"Tell him to wait and see how he feels in a year","then":"\"A year?\" he says. \"I was hoping for something sooner.\""},{"text":"Ask what his parents think of her","then":"He shrugs. \"They haven't met her. Does that matter?\""}],"why":"Real markers give him something to check, not just a feeling to trust."},{"prompt":"Faisal asks if there's one quick test he could remember. What do you say?","options":[{"text":"If you're happy, that's enough","then":"\"But I'm always happy at the start,\" he says."},{"text":"If she texts back fast, she's into you","then":"He grins. \"She does reply in seconds. So that's a yes?\""},{"text":"If you never fight, it's healthy","then":"\"We haven't fought yet,\" he says. \"Is that a sign?\""},{"text":"Does it expand your world and respect you?","then":"\"Expand my world, respect me,\" he repeats. \"I can remember that.\"","best":true}],"why":"One portable question checks both respect and whether his world is growing."},{"prompt":"A month later, Faisal says it's so intense with her that it must be right. What do you do?","options":[{"text":"Agree that a feeling that strong means it's real","then":"He beams, and stops asking himself anything else."},{"text":"Warn him that intensity always burns out","then":"Faisal frowns. \"So I should just wait for it to end?\""},{"text":"Ask if it expands his world and respects him","then":"Faisal thinks. \"She's met my friends, and she really listens. So, yes.\"","best":true},{"text":"Say his friends' verdict will tell him for sure","then":"He plans a group dinner, still unsure what he's checking for."}],"why":"Intensity isn't the test. Whether it grows his world and respects him is the truer check."}],"debrief":"Passing on the healthy markers and the simple test helps a friend read their own relationship.","relearn":"Share the healthy markers and the 'expands or shrinks' test with a friend."},
  {"id":"rr-084","cat":"tools-and-help","type":"reflect","hook":"Lensy: which relationship truth will you carry forward?","prompt":"Pick one.","options":["Built, not found","Fight kind, repair well","Love expands, control shrinks","Leaving can be brave"],"affirm":"Carry that, and you're set to build healthy love and protect yourself if it isn't.","relearn":"Built not found, fight kind, love expands not shrinks, leaving can be brave.","persona":"any","source":"carry forward"},
  {"id":"rr-900","cat":"breakups","type":"reflect","hook":"Lensy: a breakup is not a verdict on your worth. Sit with that for a second?","prompt":"What do you think?","options":["Yes","Not a verdict","My worth is mine"],"affirm":"A breakup ends a relationship, not your worth: nothing is 'wrong with you'.","relearn":"A breakup is not a verdict on your worth.","persona":"any","source":"worth"},
  {"id":"rr-902","cat":"breakups","type":"reflect","hook":"Lensy: the missing them and the relief can both be true at once. Feel that?","prompt":"What do you think?","options":["Yes","Both are real","Mixed feelings are okay"],"affirm":"Missing them and feeling relieved can coexist: mixed feelings don't mean you chose wrong.","relearn":"Missing them and feeling relief can both be true; mixed feelings are normal.","persona":"any","source":"ambivalence"},
  {"id":"rr-903","cat":"breakups","type":"reflect","hook":"Lensy: what helped a little today, even by 5%? Name one thing.","prompt":"Pick one.","options":["A friend texting back","A walk outside","Sleeping properly","One thing I finished"],"affirm":"Tiny things that helped count: stacking small good days is how heartbreak lifts.","relearn":"Small things that help still count; stack the good days.","persona":"any","source":"small wins"},
  {"id":"rr-904","cat":"breakups","type":"reflect","hook":"Lensy, to Rohan: rejection stings, but it isn't proof you're unlovable. True?","prompt":"What do you think?","options":["Yes","It's not proof","One no isn't all of me"],"affirm":"One rejection is data about fit, not a verdict on whether you're worth loving.","relearn":"Rejection is about fit, not proof you're unlovable.","persona":"Rohan","source":"rejection"},
  {"id":"rr-905","cat":"breakups","type":"reflect","hook":"Lensy: you were a whole person before them, and you still are. Sit with that?","prompt":"What do you think?","options":["Yes","Whole on my own","Still me"],"affirm":"You were whole before the relationship and you're whole after: your worth is your own.","relearn":"You were whole before, and you're whole after.","persona":"any","source":"wholeness"},
  {"id":"rr-906","cat":"breakups","type":"reflect","hook":"Lensy: which support will you reach for first this week?","prompt":"Pick one.","options":["Call a close friend","Keep my routine","Tele-MANAS 14416 if it's heavy","Talk to a counsellor"],"affirm":"Knowing your first move before a low day hits makes the day easier to get through.","relearn":"Pick your support move in advance: a friend, routine, or Tele-MANAS 14416 if it's heavy.","persona":"any","source":"plan ahead"},
  {"id":"rr-907","cat":"breakups","type":"reflect","hook":"Lensy: the version of you after this gets to be a little freer. Picture her?","prompt":"What do you think?","options":["Yes","A bit freer","Room to grow"],"affirm":"A breakup clears space; the you on the other side has room you didn't have inside it.","relearn":"A breakup clears space for the freer you on the other side.","persona":"Zoya","source":"forward self"},
  {"id":"rr-908","cat":"breakups","type":"reflect","hook":"Lensy: nobody taught us how to grieve a person who's still alive. You're learning it now.","prompt":"What do you think?","options":["Yes","I'm learning","That's why it's hard"],"affirm":"Grieving someone still around is genuinely hard and rarely taught: being new at it isn't failing.","relearn":"Grieving someone still alive is hard and rarely taught; being new at it isn't failing.","persona":"any","source":"living grief"},
  {"id":"rr-909","cat":"breakups","type":"reflect","hook":"Lensy: you can wish them well and still keep your distance. Both at once?","prompt":"What do you think?","options":["Yes","Distance is kind too","Wish well, stay back"],"affirm":"Wishing them well and keeping distance aren't a contradiction: distance is how you heal.","relearn":"You can wish an ex well and still keep your distance.","persona":"any","source":"goodwill + space"},
  {"id":"rr-910","cat":"breakups","type":"reflect","hook":"Lensy: what's one thing you put on hold for the relationship that you'll restart?","prompt":"Pick one.","options":["A friendship I dropped","A hobby I loved","A plan I shelved","Time just for me"],"affirm":"Picking up what you paused for them is how you come back to your own life.","relearn":"Restart what you paused for the relationship: it brings you back to yourself.","persona":"any","source":"reclaim"},
  {"id":"rr-912","cat":"breakups","type":"strike-rewrite","hook":"\"If they moved on fast, what we had meant nothing.\"","myth":{"un":"If they moved on fast, what we had meant nothing.","re":"How fast someone moves on says nothing about what the relationship meant to you.","why":"People cope at different speeds; their timeline isn't a verdict on yours."},"relearn":"How fast an ex moves on doesn't define what the relationship meant.","persona":"any","source":"their pace"},
  {"id":"rr-913","cat":"breakups","type":"strike-rewrite","hook":"\"Going no-contact is just being petty.\"","myth":{"un":"Going no-contact is just being petty.","re":"No-contact is a healing tool that gives the wound room to close, not a punishment.","why":"Constant contact keeps reopening the hurt and stalls recovery."},"relearn":"No-contact is a healing tool, not pettiness.","persona":"any","source":"no-contact"},
  {"id":"rr-915","cat":"breakups","type":"strike-rewrite","hook":"\"I have to keep busy every minute or I'll fall apart.\"","myth":{"un":"I have to keep busy every minute or I'll fall apart.","re":"You're allowed to feel the grief; letting it move through is healthier than outrunning it.","why":"Constant distraction just delays the feelings; they wait for you."},"relearn":"You don't have to outrun grief; feeling it is healthier than constant distraction.","persona":"any","source":"feel it"},
  {"id":"rr-916","cat":"breakups","type":"strike-rewrite","hook":"Rohan: \"A real man just shrugs a breakup off.\"","myth":{"un":"A real man just shrugs a breakup off.","re":"Feeling a breakup deeply isn't weakness. It's being human; suppressing it costs more later.","why":"Bottled grief leaks out as anger or numbness; naming it is the stronger move."},"relearn":"Feeling a breakup isn't unmanly; bottling it costs more later.","persona":"Rohan","source":"masculinity myth"},
  {"id":"rr-917","cat":"breakups","type":"strike-rewrite","hook":"\"If I just message them once, I'll get closure.\"","myth":{"un":"If I just message them once, I'll get closure.","re":"Closure usually comes from inside you, not from one more conversation with them.","why":"That 'one' message tends to reopen things and rarely gives the answer you wanted."},"relearn":"Closure comes from within, not from one more message to an ex.","persona":"any","source":"closure"},
  {"id":"rr-918","cat":"breakups","type":"strike-rewrite","hook":"\"Jumping straight into someone new will fix this.\"","myth":{"un":"Jumping straight into someone new will fix this.","re":"A rebound can numb the gap for a while, but the grief waits until you actually feel it.","why":"Using a new person as a painkiller is unfair to them and delays your own healing."},"relearn":"A new person can't shortcut grief; the feelings wait to be felt.","persona":"any","source":"rebound"},
  {"id":"rr-920","cat":"breakups","type":"branch","persona":"any","source":"unsent letter","hook":"Three days after the breakup, you've written a long text to Aman about everything that went wrong.","steps":[{"prompt":"It's 2am and your thumb is over Send. What do you do?","options":[{"text":"Send it. He deserves to know how you feel","then":"The ticks turn blue. No reply comes, and you lie awake until dawn."},{"text":"Cut it down to one line and send that","then":"\"I miss you\" goes through. He replies \"take care\", and it stings for days."},{"text":"Copy it into a private note, and don't send it","then":"The words are out of your head and safe on the page. You sleep, eventually.","best":true},{"text":"Send it to a friend first to check the tone","then":"She's asleep. You reread it forty times waiting for her reply."}],"why":"Writing it down lets the feelings out without reopening contact."},{"prompt":"The next morning, the feelings are still loud. What do you do with them?","options":[{"text":"Write them down privately as they come","then":"By the fourth entry, you notice you're angrier than sad, and that helps.","best":true},{"text":"Post a vague sad quote on your story","then":"Aman views it within minutes, and you wonder all day what he thought."},{"text":"Push them down and stay busy","then":"You get through the day. At night the feelings come back louder."},{"text":"Reread what you wrote, point by point","then":"Each read restarts the same argument in your head."}],"why":"A private place for the feelings keeps them moving instead of stuck."},{"prompt":"A week later, you think of one more thing he should hear. What do you do?","options":[{"text":"Send just that one line","then":"He replies \"ok\". The one line turns into a long night of waiting."},{"text":"Write it down, and leave it there","then":"It's on the page now. The urge to tell him fades by lunch.","best":true},{"text":"Ask a mutual friend to pass it on","then":"It reaches him twisted, and now two people are caught up in it."},{"text":"Save it for when he reaches out first","then":"Saying it to yourself, you realise you're still waiting for him."}],"why":"Keeping the words for yourself gives release without restarting contact."}],"debrief":"Writing it for yourself gives release. Sending it restarts the contact you need a break from.","relearn":"Write the feelings down for yourself instead of sending them to an ex."},
  {"id":"rr-921","cat":"breakups","type":"branch","persona":"any","source":"belongings","hook":"After the breakup, your hoodie and books are at Nikhil's flat, and his charger and jacket are at yours.","steps":[{"prompt":"Nikhil texts suggesting coffee to swap everything back. What do you do?","options":[{"text":"Say yes. Coffee might help you both","then":"Coffee turns into two hours of old jokes, and the swap never happens."},{"text":"Suggest one quick handover, or a friend's help","then":"Nikhil replies \"ok, Saturday at 11, at the gate\". It's settled in one message.","best":true},{"text":"Say you'll swap things bit by bit when you meet","then":"He agrees. Now there's a reason to meet every week."},{"text":"Leave it for now and keep his things","then":"His charger sits on your desk, a small reminder every morning."}],"why":"One calm handover closes the loop without turning it into ongoing contact."},{"prompt":"A few days later, packing his things, you find a note he once wrote you. What do you do?","options":[{"text":"Set it aside to decide on later, and keep packing","then":"The bag is packed in twenty minutes. The note waits in a drawer.","best":true},{"text":"Slip the note into his bag so he sees it","then":"You picture him finding it, and wonder about it all week."},{"text":"Stop packing and reread all his old messages","then":"An hour disappears into old chats, and the bag is still half-empty."},{"text":"Tear it up and throw it out right now","then":"It feels good for a second. Later you wish you had waited."}],"why":"Setting a keepsake aside lets you finish the task without reopening it all."},{"prompt":"The day you swap the last of your things, Nikhil suggests dinner sometime. What do you do?","options":[{"text":"Say yes, just to be polite","then":"The dinner sits in your calendar like a weight."},{"text":"Say maybe, and let him keep asking","then":"\"Maybe\" turns into three more texts over the next week."},{"text":"Say thanks, but you need space for now","then":"He replies \"yeah, fair\". Your hoodie is back on your shelf, and the loop is closed.","best":true},{"text":"Say you'll go only if he explains why it ended","then":"He sighs, and the swap turns into the argument you both left behind."}],"why":"A clear, friendly no protects the clean ending you just made."}],"debrief":"A single, low-drama exchange of belongings beats turning logistics into ongoing contact.","relearn":"Close out shared belongings in one calm handover, not a drip of meetings."},
  {"id":"rr-922","cat":"breakups","type":"branch","persona":"any","source":"shared friends","hook":"You and Priya broke up, but you share the same friends, and Sana's birthday party is on Friday.","steps":[{"prompt":"Priya will definitely be there. What do you do?","options":[{"text":"Go with Rhea, and agree you can leave early","then":"Rhea promises to stick with you and keep an eye on the door.","best":true},{"text":"Skip it and quietly leave the group chat","then":"The chat carries on. By Sunday, nobody asks where you went."},{"text":"Ask Sana to uninvite Priya","then":"Sana goes quiet. \"That puts me in a really tough spot.\""},{"text":"Go alone and act like nothing happened","then":"You hold it together, but no one catches your eye when it gets hard."}],"why":"Going with support and an exit plan keeps your friends without trapping you."},{"prompt":"The week after the party, Arjun messages asking whose side the group should take. What do you say?","options":[{"text":"Tell him the full story so he sees your side","then":"By evening half the group has heard it, and Priya's friends go cold on you."},{"text":"Say no one has to take sides","then":"Arjun relaxes. \"Okay. It's been weird not knowing what to do.\"","best":true},{"text":"Ask him to back you, since you knew him first","then":"Arjun shifts uneasily. \"Please don't make me choose.\""},{"text":"Say it doesn't matter, and stop replying to the group","then":"Arjun sends a thumbs up. The chat gets quieter for you each day."}],"why":"Not asking friends to pick sides keeps your whole circle, and theirs."},{"prompt":"A few weeks later, Sana invites you on a group trek. Priya is coming too. What do you do?","options":[{"text":"Say no, and skip every plan she's part of","then":"Sana says okay. The next three plans happen without you."},{"text":"Go, and spend the day watching what Priya does","then":"You come home tired, and can't remember a single view."},{"text":"Go, but ask Sana to keep you and Priya apart","then":"Sana tries, but she spends the day managing you both."},{"text":"Go, stay near your people, and say a simple hi","then":"The hi is awkward for a second. Then you're laughing with Rhea on the trail.","best":true}],"why":"You don't have to lose your circle to avoid an ex. A simple hi is enough."}],"debrief":"You don't have to lose your friends to avoid an ex. Go with a plan and permission to leave.","relearn":"Don't drop your friend group to avoid an ex; go with an exit plan."},
  {"id":"rr-923","cat":"breakups","type":"branch","persona":"any","source":"breadcrumbs","hook":"Weeks after the breakup, your ex Rahul watches every story you post and likes old photos.","steps":[{"prompt":"Another like pops up on a photo from last year. What do you do?","options":[{"text":"Screenshot it and send it to friends to decode","then":"The group chat spends an hour on theories. You go to bed more confused."},{"text":"Like one of his photos back to see what happens","then":"He replies with a heart emoji. Now you're both watching each other."},{"text":"Mute or restrict him so his taps stop reaching you","then":"The alerts stop. The first day you still check. By the third, you forget.","best":true},{"text":"Post more stories so he sees you're doing fine","then":"You post five stories and check who viewed each one."}],"why":"Muting takes his taps out of your day, so your attention comes back to you."},{"prompt":"Your friend Juhi says the likes mean he wants you back. What do you think?","options":[{"text":"She's probably right. I should reach out","then":"You draft a message, and your evening becomes about Rahul again."},{"text":"It means he's trying to hurt me","then":"The anger stays with you all day, over a tap on a screen."},{"text":"I'll ask Rahul directly what they mean","then":"He says \"nothing, just saw it\". You spend the night reading into that."},{"text":"Maybe, maybe not. I'm not decoding it","then":"Juhi laughs. \"Fair. Chai instead?\"","best":true}],"why":"You can't know what a tap means, and you don't have to find out."},{"prompt":"A month later, you open the app and wonder what Rahul's been up to. What do you do?","options":[{"text":"Close the app and do something that's yours","then":"You go for a walk with music. The wondering fades before you're home.","best":true},{"text":"Check his profile, just this once","then":"Once becomes three times that week, and he's back in your head."},{"text":"Ask a mutual friend what he's doing","then":"She tells you about his new job, and you think about it all night."},{"text":"Watch his stories, since you're mostly over it","then":"You watch every one, and the tight feeling in your chest comes back."}],"why":"Turning your attention to your own life is how the pull fades."}],"debrief":"You can't control what an ex taps. Muting it stops it running your day.","relearn":"Mute an ex's activity instead of decoding it; reclaim your attention."},
  {"id":"rr-925","cat":"breakups","type":"branch","persona":"any","source":"sharing reflex","hook":"You just got the internship you wanted, and your first instinct is to text your ex Mohit.","steps":[{"prompt":"The good news is buzzing in your chest. What do you do?","options":[{"text":"Text Mohit. He'd want to know","then":"He replies \"congrats!!\" and you spend the evening rereading it."},{"text":"Post it and hope Mohit sees it","then":"You check who viewed it every ten minutes. He does. It doesn't feel like much."},{"text":"Call your best friend and tell her first","then":"Ira screams down the phone. \"I knew it! We're celebrating.\"","best":true},{"text":"Keep it to yourself so you don't text him","then":"The news goes unshared, and the win feels strangely flat."}],"why":"Telling a friend keeps the joy of sharing and gives the reflex a new home."},{"prompt":"A week later, your scooter breaks down in the rain, and you want to vent to Mohit. What do you do?","options":[{"text":"Send a voice note to your sister instead","then":"Your sister sends back a laughing voice note and an auto driver's number.","best":true},{"text":"Text Mohit. It's only a small thing","then":"He's sweet about it, and you miss him all over again."},{"text":"Draft a text to Mohit, but don't send it","then":"You don't send it, but you spend twenty minutes perfecting it."},{"text":"Bottle it up. Venting is just complaining","then":"You get home soaked and cross, and snap at your roommate."}],"why":"Each time you point the urge at someone else, the pull toward your ex weakens."},{"prompt":"A month on, the urge to tell Mohit things comes less often. What do you do now?","options":[{"text":"Allow yourself one message a month","then":"The monthly message becomes the thing you plan your month around."},{"text":"Text him once to say you've moved on","then":"He replies. You reply. Suddenly it's midnight again."},{"text":"Tell friends first, or write it down","then":"Each week there are fewer moments when he's the first person you think of.","best":true},{"text":"Stop sharing with anyone. You're fine now","then":"The good days pass quietly, with no one to tell."}],"why":"Each time you share elsewhere, the old reflex fades a little more."}],"debrief":"The reflex to share with them fades faster when you point it somewhere new each time.","relearn":"Redirect the urge to text an ex toward a friend or journal."},
  {"id":"rr-926","cat":"breakups","type":"branch","persona":"Zoya","source":"reconnect","hook":"Since things ended with Mehr, you realise you'd stopped seeing your old friends while you were together.","steps":[{"prompt":"You miss Kavya, who you used to talk to every day. What do you do?","options":[{"text":"Wait for Kavya to reach out first","then":"Days pass. You see her at the canteen and look away."},{"text":"Assume she's moved on with new friends","then":"You scroll past her photos with new people and feel even further away."},{"text":"Message her this week and say you've missed her","then":"Kavya replies a few hours later. \"I missed you too. Coffee on Thursday?\"","best":true},{"text":"Send a long apology for vanishing","then":"Kavya replies \"it's okay!!\" and the chat stops there, with no plan."}],"why":"Most friends welcome a reach-back. A simple message is how it starts."},{"prompt":"When you next talk, Kavya asks why you disappeared for so long. What do you say?","options":[{"text":"Say you were just really busy","then":"Kavya says \"okay\" and the talk stays polite and shallow."},{"text":"Say you got lost in it, and you'd like to be back","then":"Kavya softens. \"I'm glad you're back. I was worried about you.\"","best":true},{"text":"Say you thought she didn't want you around","then":"Kavya looks hurt. \"I texted you so many times.\""},{"text":"Say it doesn't matter now, and change the subject","then":"Kavya lets it go, but something between you stays unsaid."}],"why":"Being honest about why you drifted lets a friendship restart on real ground."},{"prompt":"Kavya invites you to her group's game night, where you know nobody. What do you do?","options":[{"text":"Go, and say yes to meeting new people","then":"It's awkward for ten minutes. By the end, you're in a new group chat.","best":true},{"text":"Say no. It's too much, too soon","then":"Kavya says okay. The invite doesn't come again for a while."},{"text":"Go, but stay on your phone all night","then":"People try to chat, then give up. You leave early, feeling left out."},{"text":"Say you'll come next time instead","then":"Next time comes, and you find another reason to skip it."}],"why":"Saying yes to a friend's world grows the support that was always yours."}],"debrief":"Reconnecting with the friends you drifted from is one of the surest ways to rebuild.","relearn":"Reach back out to friends you drifted from; it's rarely too late."},
  {"id":"rr-927","cat":"breakups","type":"branch","persona":"any","source":"narrative","hook":"Since the breakup, your ex Siddharth has been telling people a story that makes you the villain.","steps":[{"prompt":"A classmate brings up his version at lunch. What do you do?","options":[{"text":"Tell the whole table your side, in full detail","then":"The table goes quiet. By evening, your version is doing the rounds too."},{"text":"Say there's more to it, and leave it there","then":"Your classmate shrugs and says \"fair enough\". The talk moves on.","best":true},{"text":"Agree you were the problem so it blows over","then":"The table nods. You feel sick about it for the rest of the day."},{"text":"Walk out without a word","then":"People exchange looks, and the story gets a new chapter."}],"why":"Calm and brief keeps your dignity without feeding a public fight."},{"prompt":"That evening, you're tempted to post a long story with screenshots. What do you do?","options":[{"text":"Post it. People deserve the facts","then":"It gets shared fast. His friends reply, and it drags on for days."},{"text":"Post a cryptic quote about liars instead","then":"Everyone knows who it's about. Three people message to ask what happened."},{"text":"Message Siddharth and demand he stop","then":"He sends screenshots of his own, and you're arguing past midnight."},{"text":"Close the app and talk it through with a friend","then":"Your friend hears you out. \"People who know you will know better,\" she says.","best":true}],"why":"Talking to a friend lets the anger out without handing him a bigger stage."},{"prompt":"A few days later, your close friend Ritu asks what really happened. What do you do?","options":[{"text":"Tell her calmly and honestly, since she's asking","then":"Ritu listens. \"Thanks for telling me. That's not how I heard it.\"","best":true},{"text":"Refuse to talk about it with anyone","then":"Ritu backs off, a bit hurt that you won't trust her."},{"text":"Ask her to spread your version to everyone","then":"Ritu hesitates. \"I don't want to be stuck in the middle.\""},{"text":"Tell her it was all his fault, every bit","then":"Ritu nods slowly, but you can tell she has questions."}],"why":"Your close people deserve the truth. That's different from a public campaign."},{"prompt":"Weeks later, the talk has mostly died down. What do you do?","options":[{"text":"Bring it up again so everyone knows the truth","then":"The story comes alive again, and you're back in the middle of it."},{"text":"Keep checking what he's saying through friends","then":"Every update ruins another evening."},{"text":"Avoid anyone who heard his version","then":"Your world gets smaller, and some of those people liked you anyway."},{"text":"Get on with your life and let it fade","then":"A month on, nobody mentions it. They're busy with exams.","best":true}],"why":"Living well and staying calm does more for your name than any argument."}],"debrief":"You rarely win a breakup PR war. Living well and staying calm does more for you.","relearn":"Don't fight an ex's narrative publicly; live well and stay calm."},
  {"id":"rr-928","cat":"breakups","type":"branch","persona":"any","source":"ready to date","hook":"Two months after your breakup, your friends keep telling you to \"get back out there\".","steps":[{"prompt":"Tanya makes a dating profile for you as a surprise. What do you do?","options":[{"text":"Go along with it so she doesn't feel bad","then":"Three matches message you. You feel tired just looking at them."},{"text":"Delete it and stop replying to her","then":"Tanya's hurt. \"I was only trying to help.\""},{"text":"Thank her, and say you'll date when you're ready","then":"Tanya looks deflated, then nods. \"Okay. Your pace.\"","best":true},{"text":"Keep the profile up, but never actually open it","then":"Tanya keeps asking about your matches, and the pressure doesn't stop."}],"why":"You decide when you're ready. Saying so warmly keeps both the friendship and your pace."},{"prompt":"At dinner, Rhea jokes that you'll be alone forever at this rate. What do you do?","options":[{"text":"Agree to a blind date to prove her wrong","then":"The date is polite and long. You spend it thinking about your ex."},{"text":"Laugh, and say you're on your own timeline","then":"Rhea grins. \"Okay, okay. I'll stop.\"","best":true},{"text":"Go quiet and leave dinner early","then":"Your friends text \"what happened?\" and the evening ends on a sour note."},{"text":"Say you're never dating again, just to end it","then":"It works for tonight. It isn't what you actually feel, though."}],"why":"Holding your timeline lightly stops the pressure without a fight."},{"prompt":"A month later, you notice you're curious about meeting someone. What do you do?","options":[{"text":"Trust it, and take things at your own pace","then":"You set up a profile yourself, and only reply when you're curious.","best":true},{"text":"Wait until you feel nothing at all for your ex","then":"Weeks pass, waiting for a feeling that may never fully vanish."},{"text":"Book three dates this week to make up for lost time","then":"By Friday you're exhausted, and you can't remember who said what."},{"text":"Ask your friends to pick who you should meet","then":"They pick with excitement. You feel like a guest at your own dates."}],"why":"Your own curiosity is the sign you're ready, not anyone else's timeline."}],"debrief":"Other people's timelines aren't yours. You get to decide when you're ready to date.","relearn":"Date again when you're ready, not when others push you to."},
  {"id":"rr-929","cat":"breakups","type":"branch","persona":"Rohan","source":"bitterness","hook":"Nidhi ended things with you last week, and your feed keeps serving videos saying all women are the same.","steps":[{"prompt":"It's midnight, and one of those videos has you nodding along. What do you do?","options":[{"text":"Keep watching. At least these guys get it","then":"An hour later you feel angrier, and somehow lonelier."},{"text":"Comment that women only care about money","then":"Strangers pile on with likes. You still can't sleep."},{"text":"Close the app and text a mate that you're gutted","then":"Sahil calls back. \"That's rough, bro. Food tomorrow?\"","best":true},{"text":"Tell yourself you don't care, and play games","then":"Three matches later it's 3am, and the hurt hasn't moved."}],"why":"Reaching a friend lets the hurt move. Feeds that blame women keep you stuck in it."},{"prompt":"Next day, your friend Sahil asks what actually happened with Nidhi. What do you say?","options":[{"text":"She's like all of them. Used me and left","then":"Sahil frowns. \"Nidhi? She never seemed like that.\""},{"text":"She said we wanted different things. It stings","then":"Sahil nods. \"That does sting. You really liked her.\"","best":true},{"text":"Nothing. I'm totally fine","then":"Sahil lets it drop. You eat in silence."},{"text":"It hurts, and it's all because I'm not enough","then":"Sahil pushes back. \"One breakup doesn't make you a loser, man.\""}],"why":"Saying the plain, painful truth is how grief starts to heal."},{"prompt":"A week later, your group chat is joking about \"crazy exes\". What do you do?","options":[{"text":"Add a meme about Nidhi to get a laugh","then":"It gets laughs. Later you feel a bit sick scrolling back up."},{"text":"Leave the group chat for good, without a word","then":"You're out of the jokes, and out of the cricket plans too."},{"text":"Laugh along, but don't add anything yourself","then":"Nobody notices. You feel like you signed off on something."},{"text":"Say you'd rather not trash her, and move on","then":"One friend sends a thumbs up. The chat moves on to cricket.","best":true}],"why":"Keeping your respect for her keeps you out of the contempt that feeds loneliness."},{"prompt":"A month on, a classmate, Pooja, asks you to join her study group. What do you do?","options":[{"text":"Say yes. Study groups help","then":"The group is fun, and you catch yourself laughing for real.","best":true},{"text":"Say no. Women always have an angle","then":"She shrugs and asks someone else. You study alone again."},{"text":"Say yes, but keep your guard up the whole time","then":"You sit stiffly through two sessions, and nobody gets to know you."},{"text":"Say yes, and vent to her about Nidhi","then":"She listens politely, then steers back to the exam."}],"why":"Treating people as people, not types, is how the loneliness lifts."}],"debrief":"Heartbreak that becomes contempt traps you. Heartbreak you feel moves through.","relearn":"Feel breakup pain honestly instead of turning it into contempt."},
  {"id":"rr-930","cat":"breakups","type":"branch","persona":"any","source":"dumper guilt","hook":"You ended things with Kunal a week ago. He's struggling, and you feel guilty.","steps":[{"prompt":"Kunal texts that he can't sleep and begs you to talk tonight. What do you do?","options":[{"text":"Call him and stay on the line till 2am","then":"He feels better by the end. You wake up tired, unsure what you are now."},{"text":"Say you care, but you can't be his support now","then":"A long gap, then \"okay\". You feel awful, and also clear.","best":true},{"text":"Say you might get back together, if it helps","then":"He cheers up at once, and now you've promised something you don't mean."},{"text":"Talk tonight, and tell him it's the last time","then":"Tonight becomes one more night, and he texts again tomorrow."}],"why":"Caring and a boundary can go together. You can't be both his ex and his comfort."},{"prompt":"His best friend Vivek messages asking you to check on Kunal daily. What do you do?","options":[{"text":"Say he needs his friends now, not you","then":"Vivek pauses. \"Yeah. I'll get the guys round tonight.\"","best":true},{"text":"Agree to daily check-ins so he's okay","then":"Each check-in pulls you both back into the relationship."},{"text":"Tell Vivek it's not your problem","then":"Vivek replies \"wow\" and tells two friends you're heartless."},{"text":"Agree to check on him until his exams end","then":"His exams end, and then there's another reason to keep checking."}],"why":"Pointing him to his own people helps him heal and lets you step back."},{"prompt":"Two weeks later, you see Kunal looking low in the canteen. What do you do?","options":[{"text":"Sit with him for lunch to cheer him up","then":"He brightens, then asks if you've changed your mind."},{"text":"Walk out so he doesn't see you","then":"You skip lunch, and the guilt follows you to class."},{"text":"Give a small nod and sit with your own friends","then":"He nods back. It's awkward, and it passes.","best":true},{"text":"Text him later to ask if he's eating","then":"He replies at length, and you're his support again for the night."}],"why":"Staying polite from a distance respects the ending you both need."},{"prompt":"A month later, you still feel guilty whenever you think of him. What do you tell yourself?","options":[{"text":"I should never have ended it","then":"You replay the breakup all evening, doubting a decision you made with care."},{"text":"I'll make it up to him by staying close friends","then":"The idea pulls you back toward daily messages."},{"text":"I was allowed to end it. He has his people","then":"The guilt doesn't vanish, but it stops running your days.","best":true},{"text":"I'll check his profile to see if he's okay","then":"He looks fine in one photo and sad in another. The guilt starts over."}],"why":"You can end things with care and still not carry their healing for them."}],"debrief":"You can be the one who ended it and still not be their ongoing support. That's allowed.","relearn":"You can end it kindly and still not be their daily comfort."},
  {"id":"rr-931","cat":"breakups","type":"branch","persona":"any","source":"location habit","hook":"You and Aarav broke up a month ago, but you both still share live location.","steps":[{"prompt":"It's 11pm and you've opened the map for the third time today. What do you do?","options":[{"text":"Check once more, then stop for real","then":"He's at a friend's place. You wonder who else is there until 1am."},{"text":"Turn sharing off both ways and hide the app","then":"The map is gone from your screen. Your hand reaches for it twice, then less.","best":true},{"text":"Keep sharing, but only look once a day","then":"Once a day becomes the moment you wait for."},{"text":"Screenshot his location to show a friend","then":"Your friend asks why you're still tracking him. You don't have an answer."}],"why":"Switching it off stops the loop at its source, and gives your head back to you."},{"prompt":"Aarav texts that you should always have each other's location, for safety. What do you do?","options":[{"text":"Agree. Safety matters most","then":"The pin stays on your map, and so does he."},{"text":"Agree, but promise yourself not to look","then":"You don't look for two days. On the third, you do."},{"text":"Ignore the message completely","then":"He asks again the next day, and the question hangs over you."},{"text":"Say no, and share with a friend or family instead","then":"He sends \"ok fair\". You add your roommate as your safety contact.","best":true}],"why":"A friend or family member can be your safety contact. An ex doesn't need to be."},{"prompt":"A week later, you reach for the app out of habit. What do you do instead?","options":[{"text":"Put the phone down and call a friend","then":"Ten minutes of chatting, and the itch to check is gone.","best":true},{"text":"Look for his activity on other apps","then":"You find his last seen, his likes, his playlist. The loop just moved."},{"text":"Tell yourself you're pathetic for wanting to look","then":"The harsh words sting, and the urge doesn't go anywhere."},{"text":"Hold the phone and wait for the urge to pass","then":"The urge passes, but you're staring at the screen the whole time."}],"why":"Swapping the habit for something that's yours helps it fade faster."}],"debrief":"Tracking an ex keeps the wound fresh. Switching it off is a gift to yourself.","relearn":"Turn off location sharing with an ex; tracking keeps you stuck."},
  {"id":"rr-933","cat":"breakups","type":"branch","persona":"Aarti","source":"arranged mismatch","hook":"The match your family arranged with Vikas didn't work out, and relatives are calling it a scandal.","steps":[{"prompt":"Your mother keeps saying the family has been shamed. What do you do?","options":[{"text":"Apologise and agree you let everyone down","then":"Your mother nods. The shame settles on you like it's yours to carry."},{"text":"Shout that you never wanted the match anyway","then":"The house erupts. Your father joins in, and nobody is listening."},{"text":"Tell her calmly it was a mismatch, not a disgrace","then":"Your mother goes quiet. \"Maybe. But the relatives won't see it that way.\"","best":true},{"text":"Ask your cousin to explain it to her for you","then":"Your cousin tries, but your mother only hears that you're hiding."}],"why":"Naming it as a mismatch keeps your dignity and gives her a new way to see it."},{"prompt":"At a family function, Pushpa Aunty asks loudly why the match broke. What do you do?","options":[{"text":"Say it simply didn't fit, then ask about her trip","then":"Aunty blinks, then launches into her Haridwar trip.","best":true},{"text":"Tell her everything Vikas's family did","then":"The whole room is listening now, and your mother looks mortified."},{"text":"Say it was all your fault","then":"Aunty clicks her tongue. Three relatives start giving advice."},{"text":"Laugh and tell her to ask your mother","then":"Aunty turns to your mother, and the questions double."}],"why":"A short, calm answer closes the topic without shame or a scene."},{"prompt":"That night, your father says he's already found a new match for you. What do you do?","options":[{"text":"Agree, since parents always know best","then":"A meeting is fixed for next week. Your stomach drops."},{"text":"Ask for time, and say the final yes must be yours","then":"Your father sighs. \"Fine. No rush. Nothing is fixed without your yes.\"","best":true},{"text":"Tell him you'll never trust his choices again","then":"Your father's face hardens, and the room goes silent."},{"text":"Let your mother argue it out with him","then":"Your parents talk late into the night. Nobody asks what you want."}],"why":"It's your life. Asking for time and the final say is fair, not rebellion."},{"prompt":"A cousin forwards gossip that something must be wrong with you. What do you do?","options":[{"text":"Start wondering what's wrong with you","then":"You spend the night listing your flaws in your head."},{"text":"Post the screenshot to shame the gossips","then":"The family group explodes, and the story gets bigger."},{"text":"Reply that a mismatch says nothing about you","then":"Your cousin sends a heart. \"True. Sorry, I shouldn't have forwarded it.\"","best":true},{"text":"Reply \"lol\" and leave it there","then":"Your cousin takes it as a joke, and forwards the next one too."}],"why":"A match ending is information, not a verdict on your worth."},{"prompt":"Weeks later, your mother asks what you really want when it comes to marriage. What do you do?","options":[{"text":"Say a good daughter doesn't have preferences","then":"Your mother looks relieved. You feel yourself shrink a little."},{"text":"Tell her honestly where you stand right now","then":"She listens all the way through. \"I didn't know that. Thank you for telling me.\"","best":true},{"text":"Snap that you're sick of the topic and walk out","then":"She drops it, hurt, and asks your father instead."},{"text":"Give her a list of what you don't want","then":"She nods at each item, and still doesn't know what you do want."}],"why":"Saying where you truly stand, even if it's \"not yet\", gives you a real voice in your own life."}],"debrief":"A match that doesn't fit is information, not a verdict on you. You're allowed to say so.","relearn":"A match ending is a mismatch, not your disgrace."},
  {"id":"rr-935","cat":"breakups","type":"branch","persona":"any","source":"photos","hook":"After the breakup, your gallery is full of photos with Ishaan, and opening it hurts.","steps":[{"prompt":"It's 1am, and you feel the urge to delete it all tonight. What do you do?","options":[{"text":"Delete everything, including the cloud backup","then":"It feels good for a minute. In the morning, you wish you'd kept a few."},{"text":"Move them to a hidden album to decide on later","then":"Your gallery looks like yours again. The photos wait, out of sight.","best":true},{"text":"Scroll through all of them one last time","then":"It's 3am, and you're crying over a photo from a beach trip."},{"text":"Delete only the ones where you look happiest","then":"You stop halfway, too tired to choose. Half the gallery is gone."}],"why":"Archiving takes the sting away now, and leaves the choice for a calmer day."},{"prompt":"A week later, a friend says you should erase every trace of Ishaan to move on. What do you think?","options":[{"text":"She's right. Every trace goes, right now","then":"You wipe chats and photos in a rush, and feel hollow instead of free."},{"text":"I'll reread our old chats until I'm ready","then":"Every scroll is a small jolt of him."},{"text":"Moving on isn't erasing. I'll go at my own pace","then":"Your friend shrugs. \"Fair. As long as it isn't hurting you.\"","best":true},{"text":"I'll check his profile now and then, to test myself","then":"Each check turns into an hour of reliving it."}],"why":"You don't have to erase everything to heal. You set the pace."},{"prompt":"Months later, feeling calmer, you find photos of you two on your old phone. What do you do?","options":[{"text":"Decide calmly which ones to keep","then":"You keep two from a trip with friends and let the rest go. It takes ten minutes.","best":true},{"text":"Scroll through them all again for old times' sake","then":"An hour later, the calm you'd built has gone."},{"text":"Send one to Ishaan with \"remember this?\"","then":"He replies with a laughing emoji, and you're back in his chat."},{"text":"Leave them untouched so you never have to decide","then":"The old phone goes back in a drawer, and so does the question."}],"why":"Deciding with a clear head means keeping what still feels good, and letting the rest go."}],"debrief":"You don't have to erase your history in one night. Archiving gives you space to choose.","relearn":"Archive reminders for now; you don't have to erase everything at once."},
  {"id":"rr-936","cat":"breakups","type":"branch","persona":"any","source":"post-mortem","hook":"A week after Neel ended things with you, he wants to \"talk it all through one more time\".","steps":[{"prompt":"You've already had two long talks about it. What do you do?","options":[{"text":"Agree. Maybe this time it will make sense","then":"Three hours of the same points. You leave more tangled than before."},{"text":"Agree, but only if he admits it was his fault","then":"The talk becomes a trial, and neither of you feels heard."},{"text":"Say maybe, and keep putting it off","then":"He asks again on Monday, and again on Thursday."},{"text":"Say gently that another talk would reopen it for you","then":"Neel goes quiet. \"Okay. I just wanted closure,\" he writes.","best":true}],"why":"You're allowed to say no to a replay that only sets your healing back."},{"prompt":"Your friend Mansi says one more talk might finally give you closure. What do you think?","options":[{"text":"She's right. I'll message him about it now","then":"You message Neel, and your evening fills up with the old argument."},{"text":"I'll write him a long email instead of talking","then":"You spend three evenings writing it, living through it all again."},{"text":"Closure can come from me, not another replay","then":"Mansi thinks about it. \"Okay. How do you do that?\"","best":true},{"text":"Closure is nonsense. I'm fine","then":"The words sound strong. The questions keep you up anyway."}],"why":"Closure often comes from your own understanding, not from reopening the wound."},{"prompt":"A month later, Neel texts that he finally understands what went wrong and wants to explain. What do you do?","options":[{"text":"Say yes. You've been waiting for this","then":"His explanation is long. By the end, you're both crying and nothing has changed."},{"text":"Say you're glad, but you don't need it now","then":"He sends a thumbs up. It's a small ache, and it passes.","best":true},{"text":"Ask for just the short version over text","then":"The short version is six paragraphs, and you reread them all night."},{"text":"Tell him he has no right to text you","then":"He replies with a hurt message, and you both stew for days."}],"why":"You can wish him well and still protect the healing you've done."}],"debrief":"You're allowed to say no to repeat post-mortems that only set your healing back.","relearn":"You can decline repeat post-mortems that only reopen the wound."},
  {"id":"rr-937","cat":"breakups","type":"role-play","persona":"any","source":"comforting","hook":"Your friend Aisha was dumped by text last night.","setup":"She comes to your room with red eyes.","steps":[{"prompt":"Aisha says: \"I'm just unlovable. Nobody's ever going to want me.\"","options":[{"text":"\"One no isn't the world's verdict. You're lovable.\"","then":"Aisha wipes her eyes. \"It doesn't feel like it.\"","best":true},{"text":"\"Maybe work on yourself, and he'll come back.\"","then":"Aisha flinches. \"So it was me.\""},{"text":"\"Don't be silly. You'll have someone new in a week.\"","then":"She shakes her head. \"You don't get it.\""},{"text":"\"Honestly, same. Dating is hopeless.\"","then":"She laughs weakly, then cries harder."}],"why":"Separating one rejection from her worth answers the fear underneath."},{"prompt":"Aisha asks: \"Why does it feel like something's wrong with me?\"","options":[{"text":"\"Let's list what you could change for next time.\"","then":"Aisha nods, then goes quiet. \"So there is a list.\""},{"text":"\"Because rejection hurts like that. It's pain, not proof.\"","then":"She thinks about it. \"Pain, not proof. Okay.\"","best":true},{"text":"\"Stop thinking about it. Let's go out tonight.\"","then":"\"I can't face people tonight,\" she says."},{"text":"\"Show me his text. Let's see what he said.\"","then":"She hands over her phone, and you both reread the worst line."}],"why":"Naming the feeling as pain, not evidence, takes its power down a notch."},{"prompt":"Later, Aisha says: \"I don't want to be alone tonight.\"","options":[{"text":"\"You'll be fine. Just get some sleep.\"","then":"She nods and goes. Ten minutes later she texts \"you up?\""},{"text":"\"Want me to message him and tell him off?\"","then":"\"No!\" she says. \"Please don't make it worse.\""},{"text":"\"I've got an assignment, but text me anytime.\"","then":"She nods. The door clicks shut, and she's alone with it."},{"text":"\"Then stay. We'll order food and watch something.\"","then":"She pulls a blanket over. \"Okay. Your pick.\"","best":true}],"why":"Being present is often the most useful support in the first few nights."},{"prompt":"A week later, Aisha asks: \"Should I just download the apps and move on?\"","options":[{"text":"\"Yes! Fastest way to get over someone.\"","then":"She downloads three apps, and deletes them by morning."},{"text":"\"Only if you want to. There's no rush either way.\"","then":"Aisha relaxes. \"I think I just want my weekends back first.\"","best":true},{"text":"\"No. You're clearly not ready.\"","then":"She bristles. \"You don't get to decide that.\""},{"text":"\"Wait for him. He might change his mind.\"","then":"She checks her phone twice while you talk."}],"why":"Her pace is hers. Support means backing her choice, not making it."}],"relearn":"Remind a heartbroken friend one rejection isn't a verdict on being lovable."},
  {"id":"rr-938","cat":"breakups","type":"role-play","persona":"any","source":"asking for company","hook":"It's a rough night after your breakup, and your empty room feels unbearable.","setup":"You call your friend Diya.","steps":[{"prompt":"Diya answers: \"Hey! You sound off. What's up?\"","options":[{"text":"\"It's nothing. Ignore me. I'm fine.\"","then":"\"You sure?\" she asks. You say yes, and the room goes quiet again."},{"text":"\"Rough breakup night. Can you come over?\"","then":"\"Give me twenty minutes,\" she says. \"I'm coming.\"","best":true},{"text":"\"Sorry, I shouldn't bother you this late.\"","then":"\"You're not bothering me,\" she says. \"But what's going on?\""},{"text":"\"Do you think my ex is seeing someone?\"","then":"\"I don't know,\" she says carefully. \"Why, what happened?\""}],"why":"Asking plainly for company is healthy, not a burden."},{"prompt":"The next evening, Diya texts: \"How are you today? Honestly.\"","options":[{"text":"\"All good now! Forget last night.\"","then":"\"Okay!\" she replies. The evening stretches ahead, empty."},{"text":"\"I don't want to keep dumping this on you.\"","then":"\"You're not dumping,\" she writes. \"But I can't guess what you need.\""},{"text":"\"Better than last night. Dinner together?\"","then":"\"Yes. I'll bring the rajma my mom sent,\" she replies.","best":true},{"text":"\"Just tired. Talk later.\"","then":"She sends a thumbs up. Later doesn't come."}],"why":"Honest answers and small asks keep support flowing after the first night."},{"prompt":"A week later, Diya asks: \"Do you still want company some nights?\"","options":[{"text":"\"No, I've taken enough of your time.\"","then":"\"That's not how friendship works,\" she says, a bit hurt."},{"text":"\"Only if you've got nothing better to do.\"","then":"\"That's not the question,\" she says. \"Do you want to?\""},{"text":"\"Yes. A couple of nights a week would really help.\"","then":"\"Tuesdays and Fridays, then,\" she says. \"I'll bring snacks.\"","best":true},{"text":"\"I'm fine now. I'll call if I'm not.\"","then":"\"Okay,\" she says. When a bad night comes, calling feels harder."}],"why":"Saying yes to support, and naming what helps, keeps it easy for both of you."}],"relearn":"Asking a friend for company through a breakup is healthy, not a burden."},
  {"id":"rr-939","cat":"breakups","type":"role-play","persona":"any","source":"family pressure","hook":"At your cousin's engagement, relatives keep asking why you're still single since your breakup.","setup":"Kamla Maasi finds you at the dessert counter.","steps":[{"prompt":"Kamla Maasi asks: \"Still no one? You were so close to settling down!\"","options":[{"text":"\"I know, I know. I'll find someone soon. Sorry.\"","then":"\"Soon, na? I'll send you a biodata,\" she says, pleased."},{"text":"\"That's none of your business, Maasi.\"","then":"Her face falls. Two aunties nearby turn to look."},{"text":"\"I'm taking my time, and I'm okay. How's your garden?\"","then":"Maasi blinks, then smiles. \"Oh, the roses are finally blooming!\"","best":true},{"text":"\"It just didn't work out with him.\"","then":"\"Arre, why? What happened?\" she asks, leaning closer."}],"why":"A calm line and a change of topic hold the boundary without a scene."},{"prompt":"Later, your uncle says: \"At your age, you can't be too choosy, beta.\"","options":[{"text":"\"You're right. Maybe I've been too picky.\"","then":"\"See? I'll ask around for you,\" he says, reaching for his phone."},{"text":"\"Okay, Uncle. After college, I promise you can start looking.\"","then":"He nods. \"After college, then. I'll remind your mother.\""},{"text":"\"At your age, you can't give advice, Uncle.\"","then":"His smile vanishes. Your mother shoots you a look across the room."},{"text":"\"I'd rather choose well than rush. I'm happy for now.\"","then":"He chuckles. \"Okay, okay. Just don't wait too long.\"","best":true}],"why":"Saying what you want, kindly and firmly, answers pressure without giving in."},{"prompt":"Your mother whispers: \"Everyone keeps asking me too. What do I tell them?\"","options":[{"text":"\"Tell them I'm looking, if it keeps the peace.\"","then":"She relaxes. By the end of the night, three biodatas are coming your way."},{"text":"\"Tell them to mind their own business.\"","then":"Her lips tighten. \"These are my sisters you're talking about.\""},{"text":"\"Tell them the truth. I'm fine, and in no hurry.\"","then":"She sighs, then nods. \"Okay. I'll say that, and stop pushing.\"","best":true},{"text":"\"Tell them I'm seeing someone, so they stop.\"","then":"Her eyes widen. \"Are you? Who?\""}],"why":"Being honest with care keeps your truth without dismissing your family."},{"prompt":"As you leave, your cousin Nandini asks quietly: \"Doesn't it bother you, being single?\"","options":[{"text":"\"Yes. Being single after a breakup means I failed.\"","then":"Nandini squeezes your hand. \"A breakup doesn't make you a failure. Truly.\""},{"text":"\"Some days. Mostly I'm okay taking my time.\"","then":"Nandini smiles. \"Same, honestly.\"","best":true},{"text":"\"No. Love is just a scam anyway.\"","then":"Nandini raises an eyebrow. \"That sounds like the breakup talking.\""},{"text":"\"Only when people ask. I'd date anyone to stop it.\"","then":"Nandini laughs, then looks at you. \"You don't mean that.\""}],"why":"An honest, balanced answer leaves room for sad days without a verdict on you."}],"relearn":"You can calmly decline pressure about being single after a breakup."},
  {"id":"rr-940","cat":"breakups","type":"role-play","persona":"any","source":"holding no-contact","hook":"You're three weeks into no-contact after breaking up with Tarun, and it hasn't been easy.","setup":"It's 10pm, and you're alone in your room.","steps":[{"prompt":"Tarun texts: \"I miss you. Can we meet? Just to talk.\"","options":[{"text":"\"Okay fine. Where and when?\"","then":"\"Tomorrow, our café, six?\" he replies instantly."},{"text":"\"I need this space to heal. I'm not able to meet.\"","then":"A long pause. \"Okay. I don't like it, but okay.\"","best":true},{"text":"\"I miss you too. But I can't.\"","then":"\"Then why not?\" he writes. \"If we both miss each other...\""},{"text":"\"You don't get to miss me after what you did.\"","then":"\"Wow. I was just being honest,\" he replies."}],"why":"A clear, calm no protects the space you set up to heal."},{"prompt":"The next week, Tarun texts late at night: \"Can't stop thinking about us.\"","options":[{"text":"\"Same. I think about us too.\"","then":"\"Then let's meet,\" he replies at once."},{"text":"\"Seriously? Get a life and stop texting me.\"","then":"\"Wow. Okay,\" he writes, stung."},{"text":"\"Hope you're doing okay these days.\"","then":"\"Not really,\" he writes. \"Can I call?\""},{"text":"\"I need space to heal. Please stop these texts.\"","then":"After a while he replies: \"Okay. Sorry. I'll stop.\"","best":true}],"why":"A calm, clear boundary is kinder than mixed signals or insults."},{"prompt":"Your mutual friend Kriti says: \"He's really sad. Can't you meet him and talk?\"","options":[{"text":"\"Fine. Once, if it helps him.\"","then":"Kriti brightens. \"I'll tell him. He'll be so relieved.\""},{"text":"\"Tell him to get over it.\"","then":"Kriti winces. \"I'm not passing that on.\""},{"text":"\"I care that he's sad. But I need this space.\"","then":"Kriti nods slowly. \"Okay. I won't push.\"","best":true},{"text":"\"Maybe after exams. Tell him that.\"","then":"Kriti passes it on, and Tarun starts counting down to your exams."}],"why":"You can care about someone's sadness and still keep your healing first."},{"prompt":"A month later, Tarun texts: \"Just wanted to say I'm doing better. Hope you are too.\"","options":[{"text":"\"I am. Take care, Tarun.\"","then":"He sends a smile. The chat ends there, and you feel steady.","best":true},{"text":"\"I am! We should catch up soon.\"","then":"\"Yes! This weekend?\" he replies at once."},{"text":"\"Why are you texting me again?\"","then":"\"Sorry. Just being nice,\" he writes, hurt."},{"text":"\"Not really. I miss you so much.\"","then":"\"Then let's meet,\" he writes. \"Tonight?\""}],"why":"A short, warm reply closes the loop without reopening it."}],"relearn":"You can kindly hold no-contact even when an ex says they miss you."},
  {"id":"rr-941","cat":"breakups","type":"role-play","persona":"Rohan","source":"no revenge","hook":"Your ex Pallavi has a new boyfriend, and your mate Jatin thinks you should get even.","setup":"You're at the tea stall after class.","steps":[{"prompt":"Jatin says, grinning: \"Post those old pics of her. Make her regret it.\"","options":[{"text":"\"Yeah. Let's make her regret it.\"","then":"Jatin pulls out his phone, then pauses. \"Her parents would see these by tonight, bro.\""},{"text":"\"Tempting. Maybe one story she'll see.\"","then":"\"Someone screenshots it, and her whole college sees,\" Jatin says, grinning."},{"text":"\"Nah. I'm totally over her. Don't care.\"","then":"Jatin raises an eyebrow. \"Then why do you check her profile daily?\""},{"text":"\"Nah. I'd rather heal than waste energy on that.\"","then":"Jatin shrugs. \"Fair enough. Chai's on me then.\"","best":true}],"why":"Her pics aren't yours to use against her, and healing keeps your energy for your own life."},{"prompt":"Jatin asks: \"Honestly though, how do you feel about her new guy?\"","options":[{"text":"\"It hurts. But hurting her won't fix that.\"","then":"Jatin goes quiet. \"Fair. It hurt when Meera left me too.\"","best":true},{"text":"\"Furious. She used me.\"","then":"\"Exactly,\" Jatin says. \"So do something.\""},{"text":"\"Nothing. I feel nothing at all.\"","then":"\"Sure you don't,\" he laughs."},{"text":"\"Whatever. I'll just act like I'm winning.\"","then":"Jatin grins. \"Gym selfies it is, then.\""}],"why":"Owning the hurt, without turning it on her, is what actually moves you on."},{"prompt":"A week later, Jatin says: \"She's posting couple pics now. You okay?\"","options":[{"text":"\"Totally fine. Let me like one to show her.\"","then":"Jatin winces. \"That'll look like you're watching.\""},{"text":"\"Show me. Who is this guy anyway?\"","then":"Jatin hands you his phone, and you study every photo."},{"text":"\"It stings. I'm muting her and moving on.\"","then":"Jatin nods. \"Cricket on Sunday, then?\"","best":true},{"text":"\"I'll download an app and find someone better.\"","then":"\"Tonight?\" Jatin asks. You're already swiping, not really looking."}],"why":"Muting her and filling your week helps you heal, instead of competing."}],"relearn":"Choosing to heal over revenge is the stronger move after a breakup."},
  {"id":"rr-942","cat":"breakups","type":"role-play","persona":"any","source":"privacy","hook":"Word has got around the office that you and Dhruv broke up.","setup":"At lunch, your colleague Preeti leans in.","steps":[{"prompt":"Preeti asks: \"So what happened with you two? Who ended it?\"","options":[{"text":"\"Ugh, fine. Here's the whole messy story.\"","then":"Preeti leans closer, and two more people pull up chairs."},{"text":"\"Why are you so nosy?\"","then":"Preeti flushes. \"Sorry. I was just asking.\""},{"text":"\"I'd rather not get into it here, but thanks.\"","then":"Preeti nods. \"Of course. Sorry, I didn't mean to pry.\"","best":true},{"text":"\"He did. That's all I'll say.\"","then":"\"Wait, really? Why?\" Preeti asks, eyes wide."}],"why":"A polite no protects your privacy without making it awkward."},{"prompt":"Two days later, Preeti says quietly: \"People are saying he cheated. What should I tell them?\"","options":[{"text":"\"Who's saying that? Tell me exactly who.\"","then":"Preeti lists three names, and you spend the afternoon seething."},{"text":"\"Tell them it's private. Please don't pass it on.\"","then":"Preeti nods. \"Fair. I'll shut it down if I hear it.\"","best":true},{"text":"\"Tell them maybe. I can't really say more.\"","then":"Preeti raises her eyebrows. By evening, \"maybe\" has become \"yes\"."},{"text":"\"Tell them it's much worse than they think.\"","then":"Preeti's jaw drops. \"Worse? How?\""}],"why":"Declining firmly stops a rumour from growing with your name on it."},{"prompt":"The next week, Preeti asks: \"Are you okay, though? Really?\"","options":[{"text":"\"Totally fine. Never better.\"","then":"Preeti nods, unconvinced, and goes back to her desk."},{"text":"\"If you're after gossip, forget it.\"","then":"Preeti looks stung. \"I was just asking.\""},{"text":"\"No. Let me tell you everything now.\"","then":"Preeti listens, and you realise half the floor can hear."},{"text":"\"Some days are hard. Thanks for checking.\"","then":"Preeti smiles. \"Chai at four, if you want a break.\"","best":true}],"why":"Private doesn't mean closed off. You can accept care without sharing the details."}],"relearn":"You can keep breakup details private without being rude."},
  {"id":"rr-943","cat":"breakups","type":"role-play","persona":"any","source":"midnight urge","hook":"It's midnight. Loneliness has hit hard, and you're about to call your ex Ritika.","setup":"Your roommate Harsh sees you pacing with your phone.","steps":[{"prompt":"Harsh asks: \"You're about to call her, aren't you?\"","options":[{"text":"\"Just one call. It can't hurt.\"","then":"Harsh raises his eyebrows. \"Last time it hurt for a week.\""},{"text":"\"Yeah. But this feeling will pass by morning.\"","then":"Harsh nods. \"It usually does. Want to make Maggi?\"","best":true},{"text":"\"Mind your own business.\"","then":"Harsh holds up his hands. \"Okay, okay.\""},{"text":"\"No. I'll just text her instead.\"","then":"\"That's the same thing,\" Harsh says. \"Just quieter.\""}],"why":"Naming the urge and knowing it will pass takes away its power."},{"prompt":"Harsh asks: \"What would you even say to her right now?\"","options":[{"text":"\"That I'll change, and we should try again.\"","then":"Harsh winces. \"You said that last month too.\""},{"text":"\"How much she hurt me. She should know.\"","then":"\"At midnight?\" Harsh asks. \"That's a fight, not a call.\""},{"text":"\"That I'm lonely. Which I can tell you instead.\"","then":"Harsh sits on the bed. \"Go on, then. Tell me.\"","best":true},{"text":"\"Nothing much. I just want to hear her voice.\"","then":"\"And after that?\" Harsh asks. You don't have an answer."}],"why":"Loneliness is real, and a friend in the room can hold it better than an ex."},{"prompt":"Harsh asks: \"So what do you want to do instead?\"","options":[{"text":"\"Keep my phone close, in case she calls.\"","then":"Harsh sighs. \"Then you'll be up till 3am waiting.\""},{"text":"\"Scroll her profile till I fall asleep.\"","then":"\"That's the call, just slower,\" Harsh says."},{"text":"\"Charge my phone in the hall and go to sleep.\"","then":"\"I'll put it by the door,\" he says. \"Night, yaar.\"","best":true},{"text":"\"Sleep, but keep her chat open, just in case.\"","then":"Harsh shakes his head. \"That's a call waiting to happen.\""}],"why":"Putting distance between you and the phone helps the urge pass by morning."}],"relearn":"Ride out a late-night urge to call an ex; reach a friend instead."},
  {"id":"rr-944","cat":"breakups","type":"role-play","persona":"Meena","source":"offline route","hook":"Months after your breakup, you still feel low every day, and there's no counsellor where you live.","setup":"Your roommate Lata sees you've skipped dinner again.","steps":[{"prompt":"Lata asks: \"You've gone so quiet. What's wrong?\"","options":[{"text":"\"Nothing. Just tired from the shift.\"","then":"Lata nods, but keeps glancing at you as she turns off the light."},{"text":"\"The breakup still weighs on me. I'm low every day.\"","then":"Lata sits beside you. \"All this time? I'm glad you told me.\"","best":true},{"text":"\"People like me don't get to be sad. We just work.\"","then":"Lata frowns. \"Who told you that?\""},{"text":"\"I'm a bit low, but it will pass on its own.\"","then":"\"If you say so,\" Lata says, not sure."}],"why":"Telling someone near you is a real first step, even without a counsellor nearby."},{"prompt":"Next evening, Lata says: \"You should talk to someone. But there's no counsellor near here.\"","options":[{"text":"\"Exactly. There's no one for people like me.\"","then":"Lata frowns. \"Don't say that. There must be something.\""},{"text":"\"I'll wait till I go home to the village.\"","then":"\"That's months away,\" Lata says quietly."},{"text":"\"There's Tele-MANAS 14416. I can call from my phone.\"","then":"Lata looks surprised. \"From the phone? Then call. I'll sit with you.\"","best":true},{"text":"\"I'll just work extra shifts so I stop thinking.\"","then":"\"You're already so tired,\" Lata says."}],"why":"Support like Tele-MANAS 14416 reaches you by phone, wherever you live and work."},{"prompt":"Lata finds Tele-MANAS 14416 on her phone and asks: \"If you called now, what would you say?\"","options":[{"text":"\"I don't know. Maybe I'll sound stupid.\"","then":"\"You won't,\" Lata says. \"But you only find out by calling.\""},{"text":"\"That I've felt low every day since the breakup.\"","then":"Lata squeezes your hand. \"That's enough. Let's dial now.\"","best":true},{"text":"\"Nothing. I'll hang up if they answer.\"","then":"Lata shakes her head. \"Then why dial at all?\""},{"text":"\"I'll call only if it gets much worse.\"","then":"Lata looks at you. \"It's already been months.\""}],"why":"You don't need the right words. Saying how you feel is enough to start."}],"relearn":"Support like Tele-MANAS 14416 is reachable even with no counsellor nearby."},
  {"id":"rr-945","cat":"breakups","type":"spot","hook":"Spot the two lines that keep you STUCK after a breakup (the unhealthy ones).","scene":[{"id":"a","text":"\"I'll check their profile just once more tonight.\"","trick":true},{"id":"b","text":"\"I'll call a friend when the evening gets hard.\"","trick":false},{"id":"c","text":"\"I'll keep my morning routine even on low days.\"","trick":false},{"id":"d","text":"\"I'll drink until I stop feeling anything.\"","trick":true},{"id":"e","text":"\"I'll let myself cry instead of bottling it.\"","trick":false}],"why":"Stalking their profile and numbing with drink keep the wound open; the others are healthy coping.","relearn":"Stalking an ex and numbing with drink keep you stuck.","persona":"any","source":"stuck habits"},
  {"id":"rr-946","cat":"breakups","type":"spot","hook":"Spot the two things you should NOT do during no-contact.","scene":[{"id":"a","text":"Mute their stories so you stop checking","trick":false},{"id":"b","text":"Send a 'just checking in' text after a week","trick":true},{"id":"c","text":"Lean on friends and your routine","trick":false},{"id":"d","text":"Like their old photos at 1am","trick":true},{"id":"e","text":"Let yourself feel the grief","trick":false}],"why":"A 'checking in' text and 1am likes both break the space no-contact is meant to give you.","relearn":"'Checking in' texts and late-night likes break no-contact.","persona":"any","source":"no-contact slips"},
  {"id":"rr-947","cat":"breakups","type":"spot","hook":"Spot the two unhelpful things people say to someone heartbroken.","scene":[{"id":"a","text":"\"Take all the time you need.\"","trick":false},{"id":"b","text":"\"You should be over it by now.\"","trick":true},{"id":"c","text":"\"I'm here whenever you want to talk.\"","trick":false},{"id":"d","text":"\"Plenty of fish. Just get back out there.\"","trick":true},{"id":"e","text":"\"It's okay to feel sad about this.\"","trick":false}],"why":"Rushing someone's timeline and pushing them to date again dismiss real grief; the rest honour it.","relearn":"Rushing someone's timeline or pushing them to date dismisses grief.","persona":"any","source":"what not to say"},
  {"id":"rr-948","cat":"breakups","type":"spot","hook":"Spot the two signs your coping has tipped into harm.","scene":[{"id":"a","text":"Skipping meals to feel numb","trick":true},{"id":"b","text":"Calling a friend when it's heavy","trick":false},{"id":"c","text":"Drinking every night to sleep","trick":true},{"id":"d","text":"Going for a walk to clear your head","trick":false},{"id":"e","text":"Writing how you feel in a journal","trick":false}],"why":"Skipping meals to numb and drinking nightly are self-harming coping; the others actually help.","relearn":"Skipping meals to numb and nightly drinking are harm, not coping.","persona":"any","source":"coping vs harm"},
  {"id":"rr-949","cat":"breakups","type":"spot","hook":"Spot the two 'closure' moves that actually reopen the wound.","scene":[{"id":"a","text":"Re-reading every old chat to understand","trick":true},{"id":"b","text":"Writing an unsent letter to yourself","trick":false},{"id":"c","text":"Arranging one last meet-up to 'really talk'","trick":true},{"id":"d","text":"Accepting you may never get a clean answer","trick":false},{"id":"e","text":"Naming what you learned and moving on","trick":false}],"why":"Re-reading chats and one more 'real talk' reopen the loop; closure grows from inside you.","relearn":"Re-reading chats and one more 'talk' reopen the wound, not close it.","persona":"any","source":"false closure"},
  {"id":"rr-950","cat":"breakups","type":"spot","hook":"Spot the two responses to rejection that turn pain into contempt.","scene":[{"id":"a","text":"\"All of them are players anyway.\"","trick":true},{"id":"b","text":"\"That hurt. I'll talk to a mate about it.\"","trick":false},{"id":"c","text":"\"I'll post something to make her look bad.\"","trick":true},{"id":"d","text":"\"One no isn't the whole story of me.\"","trick":false},{"id":"e","text":"\"I'll feel this and let it pass.\"","trick":false}],"why":"Generalising and trying to shame her turn hurt into contempt and keep you stuck; the rest just heal.","relearn":"Generalising or shaming an ex turns hurt into contempt.","persona":"Rohan","source":"contempt trap"},
  {"id":"rr-951","cat":"breakups","type":"spot","hook":"Spot the two ways someone overshares the breakup in a harmful way.","scene":[{"id":"a","text":"Telling one close friend how you feel","trick":false},{"id":"b","text":"Posting their private texts publicly","trick":true},{"id":"c","text":"Naming what you feel in a journal","trick":false},{"id":"d","text":"Rallying mutuals to pick a side","trick":true},{"id":"e","text":"Talking it through with a counsellor","trick":false}],"why":"Leaking their private texts and recruiting mutuals weaponise the breakup; the others are healthy outlets.","relearn":"Leaking an ex's texts or recruiting mutuals weaponises the breakup.","persona":"any","source":"oversharing"},
  {"id":"rr-952","cat":"breakups","type":"spot","hook":"Spot the two thoughts that turn a breakup into a verdict on your worth.","scene":[{"id":"a","text":"\"This proves I'm fundamentally unlovable.\"","trick":true},{"id":"b","text":"\"This relationship ended; I'm still whole.\"","trick":false},{"id":"c","text":"\"No one will ever want me again.\"","trick":true},{"id":"d","text":"\"It hurts because it mattered.\"","trick":false},{"id":"e","text":"\"I'll heal and learn from this.\"","trick":false}],"why":"'Unlovable' and 'no one ever again' twist a breakup into a verdict; the others keep your worth intact.","relearn":"'Unlovable' and 'no one ever again' twist a breakup into a false verdict.","persona":"any","source":"worth thoughts"},
  {"id":"rr-953","cat":"breakups","type":"match","hook":"Match each breakup wobble to the steady response.","pairs":[{"left":"Urge to text them at midnight","right":"Message a friend instead"},{"left":"Their story keeps popping up","right":"Mute or unfollow for space"},{"left":"Low mood that won't lift in weeks","right":"Reach Tele-MANAS 14416"},{"left":"Feeling you lost your whole self","right":"Restart your own interests"},{"left":"Pressure to be 'over it'","right":"Heal at your own pace"}],"relearn":"Each breakup wobble has a steadier next move than the impulse.","persona":"any","source":"wobble to move"},
  {"id":"rr-954","cat":"breakups","type":"match","hook":"Match each feeling to a healthy way to meet it.","pairs":[{"left":"Loneliness at night","right":"Plan a friend to call"},{"left":"Anger at how it ended","right":"Move your body to release it"},{"left":"Numbness and flatness","right":"Name one feeling out loud"},{"left":"Guilt about ending it","right":"Hold a kind boundary"},{"left":"Grief that comes in waves","right":"Let it pass without fighting"}],"relearn":"Every breakup feeling has a healthy way to be met, not numbed.","persona":"any","source":"feeling to action"},
  {"id":"rr-955","cat":"breakups","type":"match","hook":"Match each unhealthy habit to what it quietly does.","pairs":[{"left":"Stalking their profile daily","right":"Keeps the wound open"},{"left":"Drinking to stop feeling","right":"Delays the grief"},{"left":"Jumping into a rebound","right":"Uses someone as a painkiller"},{"left":"Replaying it alone on a loop","right":"Traps you in the past"},{"left":"Demanding 'closure' talks","right":"Reopens the same hurt"}],"relearn":"Each stuck habit has a quiet cost that keeps you from healing.","persona":"any","source":"habit to cost"},
  {"id":"rr-956","cat":"breakups","type":"match","hook":"Match each support need to the right route.","pairs":[{"left":"Want to vent tonight","right":"A trusted friend"},{"left":"Heavy low mood for weeks","right":"Tele-MANAS 14416"},{"left":"Want to think it through","right":"A counsellor"},{"left":"Feel threatened by an ex","right":"181 / 1091 / 112"},{"left":"Need daily steadiness","right":"Your own routine"}],"relearn":"Different breakup needs route to different real supports.","persona":"any","source":"need to route"},
  {"id":"rr-957","cat":"breakups","type":"match","hook":"Match each rebuilding step to what it grows back.","pairs":[{"left":"Reconnect with old friends","right":"Your support circle"},{"left":"Restart a paused hobby","right":"Your own identity"},{"left":"Keep a daily routine","right":"A sense of steadiness"},{"left":"Set a small new goal","right":"A reason to look forward"},{"left":"Take space from the ex","right":"Room for the wound to close"}],"relearn":"Each small rebuilding step grows back a piece of your own life.","persona":"any","source":"step to growth"},
  {"id":"rr-958","cat":"breakups","type":"strike-rewrite","hook":"\"If I still cry, it means I haven't made any progress.\"","myth":{"un":"If I still cry, it means I haven't made any progress.","re":"Healing isn't a straight line; tears on a hard day don't erase the progress you've made.","why":"Grief comes in waves, so good days and low days both belong to recovery."},"relearn":"Healing isn't linear; crying on a hard day doesn't undo your progress.","persona":"any","source":"non-linear"},
  {"id":"rr-959","cat":"breakups","type":"strike-rewrite","hook":"\"I have to figure out exactly who was to blame before I can move on.\"","myth":{"un":"I have to figure out exactly who was to blame before I can move on.","re":"Healing doesn't wait for a perfect verdict on blame; sometimes it just wasn't a fit.","why":"Endless score-keeping keeps you arguing with the past instead of living forward."},"relearn":"You can move on without a perfect verdict on who was to blame.","persona":"any","source":"blame ledger"},
  {"id":"rr-961","cat":"breakups","type":"branch","persona":"any","source":"pile-on","hook":"After a rough split with Dev, your friends offer to \"expose\" him online.","steps":[{"prompt":"Meher shows you a thread she's drafted, with screenshots. What do you do?","options":[{"text":"Thank her, and ask her to keep it offline","then":"Meher sighs, but deletes it. \"Okay. It's your life.\"","best":true},{"text":"Tell her to post it. He deserves it","then":"It spreads fast. By night, strangers are arguing in your comments."},{"text":"Let her post it, but without your name","then":"Everyone guesses it's about you within an hour."},{"text":"Post a vaguer version yourself","then":"People fill in the blanks, and some of them get it wrong."}],"why":"Keeping it offline protects your peace and your name."},{"prompt":"A few days later, classmates ask you what really happened with Dev. What do you do?","options":[{"text":"Tell them everything, and add a few extras","then":"By evening, your words are quoted in three group chats."},{"text":"Say it's private, and you're moving on","then":"They nod and let it drop.","best":true},{"text":"Say nothing happened, really","then":"Nobody believes you, and the guessing gets louder."},{"text":"Say it's private, then share one detail","then":"That one detail is all over the class by lunch."}],"why":"Keeping it private starves the drama and lets you move on."},{"prompt":"A month later, you feel the urge to check what people say about Dev. What do you do?","options":[{"text":"Search his name to see what's being said","then":"An hour of scrolling later, it feels like it all happened yesterday."},{"text":"Ask Meher to keep you updated","then":"Her updates arrive every few days, and each one pulls you back."},{"text":"Leave it, and put that energy into your week","then":"You finish an assignment early and go for chai. Dev barely crosses your mind.","best":true},{"text":"Message Dev to see if he's sorry now","then":"He replies angrily, and you're back in a fight you'd left."}],"why":"Where you put your attention is where your healing happens."}],"debrief":"Letting friends wage a public war for you rarely helps, and it often follows you.","relearn":"Decline a public pile-on on an ex; keep your exit dignified."},
  {"id":"rr-962","cat":"breakups","type":"reflect","hook":"Lensy: this breakup taught you something about what you want next. Name one thing?","prompt":"Pick one.","options":["What I won't settle for","What made me feel free","A need I'll voice sooner","How I want to be treated"],"affirm":"Carrying forward what you learned turns a painful ending into a clearer next chapter.","relearn":"A breakup can teach you what you want next; carry that forward.","persona":"any","source":"lesson forward"},
  {"id":"rr-963","cat":"breakups","type":"reflect","hook":"Lensy: you get to keep the good memories without wanting the relationship back.","prompt":"What do you think?","options":["Yes","Keep the good, not the person","Both can be true"],"affirm":"Treasuring a good memory and not wanting them back can both be true: it isn't contradiction.","relearn":"You can keep the good memories without wanting the relationship back.","persona":"any","source":"keep memories"},
  {"id":"rr-964","cat":"breakups","type":"branch","persona":"Deepak","source":"protect goals","hook":"Exams start next week. Since the breakup, a thought keeps telling you nothing matters anymore.","steps":[{"prompt":"You've already missed two lectures. What do you do tomorrow morning?","options":[{"text":"Skip the week and catch up later","then":"Two days slip by, and the syllabus pile doubles."},{"text":"Go to class, even if you just sit and listen","then":"You catch half of it, but you're there, and the notes are in your bag.","best":true},{"text":"Drop the course and redo it next year","then":"At the office, you learn the drop deadline has passed. The exams are still on."},{"text":"Stay up all night to cram everything at once","then":"By 4am nothing is sticking, and you sleep through the morning class."}],"why":"Showing up, even at half strength, protects what's yours from the breakup's pull."},{"prompt":"Your friend Irfan offers to study with you every evening until the first paper. What do you do?","options":[{"text":"Say yes, and set a small goal for each evening","then":"Two chapters the first evening. It's slow, but it's something.","best":true},{"text":"Say no. You don't want to be a burden","then":"Irfan says okay. You open the book alone and stare at it."},{"text":"Say yes, but use the time to vent about the breakup","then":"Irfan listens patiently. The chapters stay unread."},{"text":"Say you'll join once you feel better","then":"You don't feel better, and the evenings before the exam slip away."}],"why":"A friend and a routine help with grief. If the low days feel heavy, Tele-MANAS 14416 is there now."},{"prompt":"The night before the first paper, you're too sad to focus. What do you do?","options":[{"text":"Give up. What's the point anyway","then":"You lie awake, and the morning comes anyway, unprepared."},{"text":"Text your ex to get closure first","then":"The chat goes nowhere, and it's 1am."},{"text":"Revise the key points for an hour, then sleep","then":"It's not everything, but you walk in rested with the basics clear.","best":true},{"text":"Stay up all night going through every chapter","then":"By dawn the pages blur, and you're running on no sleep."}],"why":"A short, focused revision and sleep does more than panic on a hard night."},{"prompt":"After the last paper, you feel relieved, but the low days haven't lifted. What do you do next?","options":[{"text":"Crash and skip everything for a month","then":"The break helps for a week. Then the sadness fills the empty days."},{"text":"Rest a few days, then see the campus counsellor","then":"The counsellor listens, and you leave with a plan for the weeks ahead.","best":true},{"text":"Tell yourself you should have done much better","then":"The relief turns sour, and you start doubting yourself."},{"text":"Rest, then pile on extra courses to stay busy","then":"You're too busy to feel anything, until you're exhausted."}],"why":"Low days that won't lift deserve real support, like a counsellor or Tele-MANAS 14416."}],"debrief":"Grief is real, and your own goals are worth protecting from it. Keep showing up where you can.","relearn":"Keep showing up for your own goals; don't hand them to the breakup."},
  {"id":"rr-965","cat":"breakups","type":"sort","hook":"Sort: a green-flag way to handle the breakup, or a red-flag one?","items":[{"id":"a","text":"Taking space before any friendship"},{"id":"b","text":"Showing up at their place uninvited"},{"id":"c","text":"Leaning on your own people"},{"id":"d","text":"Threatening to share their photos"},{"id":"e","text":"Letting yourself grieve at your pace"},{"id":"f","text":"Flooding their phone with calls"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Space, leaning on your people and grieving at your pace are green; showing up uninvited, threats or flooding calls are red.","persona":"any","source":"green vs red handling"},
  {"id":"rr-966","cat":"breakups","type":"sort","hook":"Sort each line: kind to yourself, or harsh self-talk?","items":[{"id":"a","text":"\"I did my best with what I knew.\""},{"id":"b","text":"\"I ruined everything, as always.\""},{"id":"c","text":"\"I'm allowed to grieve this.\""},{"id":"d","text":"\"I'm unlovable and always will be.\""},{"id":"e","text":"\"I'll be okay, even if not today.\""},{"id":"f","text":"\"I deserve to feel this bad.\""}],"bins":[{"id":"kind","label":"Kind to self","valence":"pos"},{"id":"harsh","label":"Harsh self-talk","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"Self-compassion sounds like 'I did my best' and 'I'll be okay'; harsh self-talk pins blame and worthlessness on you.","persona":"any","source":"self-talk"},
  {"id":"rr-967","cat":"breakups","type":"sort","hook":"Sort: speak up and reach out, or carry it silently?","items":[{"id":"a","text":"\"Can we talk tonight? I'm struggling.\""},{"id":"b","text":"Telling no one and forcing a smile"},{"id":"c","text":"\"I need support this week.\""},{"id":"d","text":"Pretending you're totally fine"},{"id":"e","text":"\"Heavy days, I'll call Tele-MANAS 14416.\""},{"id":"f","text":"Bottling it until it bursts"}],"bins":[{"id":"speak","label":"Speak up","valence":"tell"},{"id":"silent","label":"Carry it silently","valence":"neg"}],"key":{"a":"speak","b":"silent","c":"speak","d":"silent","e":"speak","f":"silent"},"relearn":"Asking to talk and reaching for support beats forcing a smile and bottling it until it bursts.","persona":"any","source":"speak vs silent"},
  {"id":"rr-968","cat":"breakups","type":"sort","hook":"Sort each into the early days or the rebuilding days of a breakup.","items":[{"id":"a","text":"Raw grief and constant missing them"},{"id":"b","text":"Picking up a paused hobby again"},{"id":"c","text":"Crying out of nowhere"},{"id":"d","text":"Making plans you look forward to"},{"id":"e","text":"Days where it barely stings"},{"id":"f","text":"Wanting to text them every hour"}],"bins":[{"id":"early","label":"Early days","valence":"uhoh"},{"id":"rebuild","label":"Rebuilding days","valence":"pos"}],"key":{"a":"early","b":"rebuild","c":"early","d":"rebuild","e":"rebuild","f":"early"},"relearn":"Raw grief and constant missing them mark the early days; new plans and lighter days mark rebuilding.","persona":"any","source":"early vs rebuild"},
  {"id":"rr-969","cat":"breakups","type":"match","hook":"Match each unhelpful myth to the truer reframe.","pairs":[{"left":"\"Something's wrong with me\"","right":"It's painful but normal"},{"left":"\"I should be over it\"","right":"Grief has no timetable"},{"left":"\"No-contact is petty\"","right":"It's a healing tool"},{"left":"\"I'm nothing without them\"","right":"You were whole before"},{"left":"\"A rebound will fix it\"","right":"Grief waits to be felt"}],"relearn":"Each breakup myth has a kinder, truer reframe.","persona":"any","source":"myth to reframe"},
  {"id":"rr-970","cat":"breakups","type":"branch","persona":"any","source":"performing fine","hook":"Since the breakup, you've posted gym selfies and party pics, but you cry most nights.","steps":[{"prompt":"Your close friend Nisha texts that you look so happy lately. What do you do?","options":[{"text":"Reply \"never better!\" with a smiley","then":"She sends a heart and moves on. You put the phone down, alone again."},{"text":"Post another happy story to keep it up","then":"It gets likes. The night feels just as long."},{"text":"Reply that it's been harder than it looks","then":"Nisha calls within a minute. \"Oh no. Tell me everything.\"","best":true},{"text":"Say it's hard, but quickly add she needn't worry","then":"Nisha isn't sure whether to worry, and waits for you to say more."}],"why":"Letting one trusted person see the truth gets you real support, not an audience."},{"prompt":"A few days later, your older brother Arnav notices you've gone quiet at dinner. What do you do?","options":[{"text":"Say you're fine and ask him to pass the dal","then":"He passes it. The quiet goes back to your room with you."},{"text":"Tell him about the breakup, and that it's hard","then":"Arnav nods slowly. \"That's rough. Want to go for a drive later?\"","best":true},{"text":"Snap that he wouldn't understand","then":"Arnav raises his hands and leaves you alone."},{"text":"Say you'll tell him later, and then don't","then":"He asks once more that week, then stops asking."}],"why":"People close to you can only help with the version of you they can see."},{"prompt":"A classmate compliments your \"glow-up\" posts. What do you say?","options":[{"text":"Say thanks, and that you've never been happier","then":"She smiles, and you feel the act get a little heavier."},{"text":"Say thanks, and admit some days are rough","then":"She pauses. \"Same, after my breakup. Want to grab coffee?\"","best":true},{"text":"Say nothing, and post even more","then":"The likes climb, and the nights stay the same."},{"text":"Tell her the whole breakup story right there","then":"She listens, a bit startled, and you feel exposed afterwards."}],"why":"A small, honest line invites real connection. You don't have to perform."},{"prompt":"A month later, you feel a bit better on some days. What do you do?","options":[{"text":"Go back to showing only the highlights","then":"The good days look great online. The hard ones go unseen again."},{"text":"Stop talking about it. It's time to be fine","then":"Your friends stop asking, just as a rough week hits."},{"text":"Be honest with a few close people about the dips","then":"Nisha checks in on Sundays now, and you tell her how it really went.","best":true},{"text":"Post a long caption about your healing journey","then":"Lots of hearts arrive, but none of them know how today actually felt."}],"why":"Being real with a few trusted people keeps support there for the dips."}],"debrief":"You don't have to perform recovery. The people who matter can hold the real version.","relearn":"Let trusted people see the real you instead of performing 'fine'."},
  {"id":"rr-990","cat":"fight-right","type":"strike-rewrite","hook":"\"The silent treatment makes them learn.\"","myth":{"un":"The silent treatment makes them learn.","re":"Stonewalling teaches nothing; it leaves the rupture open. A calm break with a plan to return repairs.","why":"Going cold punishes; it doesn't solve the issue."},"relearn":"The silent treatment is stonewalling, not a lesson; a break-then-return repairs.","persona":"any","source":"stonewalling"},
  {"id":"rr-991","cat":"fight-right","type":"strike-rewrite","hook":"\"Real passion means shouting it out.\"","myth":{"un":"Real passion means shouting it out.","re":"Volume isn't love. You can feel strongly and still keep your voice and respect intact.","why":"Shouting floods you both and the point gets lost."},"relearn":"Strong feeling doesn't need shouting; calm intensity gets heard better.","persona":"any","source":"calm intensity"},
  {"id":"rr-992","cat":"fight-right","type":"strike-rewrite","hook":"\"'I'm just being honest' lets you say anything.\"","myth":{"un":"'I'm just being honest' lets you say anything.","re":"Honesty isn't a pass for contempt. You can be truthful and kind in the same breath.","why":"Cruelty wrapped as honesty still wounds the bond."},"relearn":"Honesty doesn't license contempt; truth can be kind too.","persona":"Rohan","source":"contempt"},
  {"id":"rr-993","cat":"fight-right","type":"strike-rewrite","hook":"\"Apologising first means you lost.\"","myth":{"un":"Apologising first means you lost.","re":"A repair attempt is strength, not defeat. Owning your part rebuilds trust faster than waiting.","why":"There's no scoreboard; the relationship is the win."},"relearn":"Apologising first is a repair attempt, not a loss.","persona":"any","source":"repair"},
  {"id":"rr-994","cat":"fight-right","type":"strike-rewrite","hook":"\"If they loved me they'd know what's wrong.\"","myth":{"un":"If they loved me they'd know what's wrong.","re":"No one can read your mind. Naming what you feel and need is how a partner can actually meet it.","why":"Expecting mind-reading sets you both up to fail."},"relearn":"Love isn't mind-reading; name your feeling and your need.","persona":"any","source":"naming needs"},
  {"id":"rr-995","cat":"fight-right","type":"strike-rewrite","hook":"\"Telling everyone your side wins the fight.\"","myth":{"un":"Telling everyone your side wins the fight.","re":"Venting the fight to the whole hostel doesn't repair it; it just spreads the rupture. Take it back to them.","why":"An audience can't fix a two-person issue."},"relearn":"Airing the fight to everyone doesn't repair it; bring it back to your partner.","persona":"any","source":"repair"},
  {"id":"rr-996","cat":"fight-right","type":"strike-rewrite","hook":"\"You made me say that.\"","myth":{"un":"You made me say that.","re":"No one makes you choose contempt. Your words are yours; owning them is how repair starts.","why":"'You made me' dodges responsibility and blocks repair."},"relearn":"No one 'makes' you say cruel things; own your words to repair.","persona":"Rohan","source":"take responsibility"},
  {"id":"rr-997","cat":"fight-right","type":"strike-rewrite","hook":"\"Pointing out their flaws helps them improve.\"","myth":{"un":"Pointing out their flaws helps them improve.","re":"Attacking who they are is criticism; naming one specific thing with an 'I' statement is the fair way.","why":"Character attacks shame; they don't motivate change."},"relearn":"Criticising character doesn't improve anyone; a specific 'I' statement does.","persona":"any","source":"criticism vs complaint"},
  {"id":"rr-998","cat":"fight-right","type":"strike-rewrite","hook":"\"Sarcasm is harmless, it's just a joke.\"","myth":{"un":"Sarcasm is harmless, it's just a joke.","re":"Repeated mocking sarcasm is contempt, the strongest predictor of breakdown, even dressed as a joke.","why":"It signals disgust, not affection, over time."},"relearn":"Mocking sarcasm is contempt in disguise, not a harmless joke.","persona":"any","source":"contempt"},
  {"id":"rr-999","cat":"fight-right","type":"strike-rewrite","hook":"\"Giving in every time keeps the peace.\"","myth":{"un":"Giving in every time keeps the peace.","re":"Always caving isn't peace; it buries your needs until they leak out. Fair conflict shares the give-and-take.","why":"A relationship where only one bends quietly erodes."},"relearn":"Always giving in isn't peace; healthy conflict shares the bend.","persona":"any","source":"equality in conflict"},
  {"id":"rr-1000","cat":"fight-right","type":"strike-rewrite","hook":"\"Drag your families in to settle it.\"","myth":{"un":"Drag your families in to settle it.","re":"Pulling relatives in mid-fight usually raises the stakes. Most couple issues are repaired between the two of you.","why":"More voices means more heat, not more repair."},"relearn":"Bringing families into every fight escalates it; repair between the two of you first.","persona":"Aarti","source":"repair"},
  {"id":"rr-1001","cat":"fight-right","type":"strike-rewrite","hook":"\"Defending yourself point-by-point is fair.\"","myth":{"un":"Defending yourself point-by-point is fair.","re":"Instant defensiveness just bats the blame back. Listening and owning even one part de-escalates faster.","why":"Defending against everything means hearing nothing."},"relearn":"Point-by-point defence isn't fair; listening and owning a part de-escalates.","persona":"any","source":"defensiveness"},
  {"id":"rr-1002","cat":"fight-right","type":"strike-rewrite","hook":"\"A relationship with rules for fighting isn't romantic.\"","myth":{"un":"A relationship with rules for fighting isn't romantic.","re":"Agreeing how you'll fight, no contempt, take breaks, repair, is a skill, and the couples who do it last.","why":"Skills aren't unromantic; they keep love alive."},"relearn":"Agreeing how to fight fair is a learnable skill, not unromantic.","persona":"any","source":"conflict skill"},
  {"id":"rr-1003","cat":"fight-right","type":"role-play","persona":"any","source":"gentle start-up","hook":"Tara keeps making weekend plans for you both without asking, and it grates.","setup":"She's on the sofa, scrolling happily.","steps":[{"prompt":"Tara says: \"Guess what? I booked us for Sunday brunch with Riya.\"","options":[{"text":"\"Can we talk? I've felt left out of our plans lately.\"","then":"Tara looks up. \"Left out? Okay, tell me.\"","best":true},{"text":"\"You never ask me anything. What's wrong with you?\"","then":"Tara drops the phone. \"Wow. Where did that come from?\""},{"text":"\"Sure. Sounds fun.\"","then":"Tara grins, then glances up. \"Wait. Do you mind me planning everything?\""},{"text":"\"Brunch is fine. Just saying, you do this a lot.\"","then":"Tara frowns. \"Do what?\" The mood cools."}],"why":"A soft start names the problem, not the person, so she doesn't have to defend herself."},{"prompt":"Tara says: \"I thought you liked me handling plans. You never said otherwise.\"","options":[{"text":"\"Fair. I didn't. I'd like us to plan together.\"","then":"Tara nods. \"Okay. That's easy enough.\"","best":true},{"text":"\"I shouldn't have to say it. You should know.\"","then":"\"How would I know, then?\" she asks."},{"text":"\"I did say it. You just don't listen.\"","then":"She crosses her arms. \"When?\""},{"text":"\"Forget it. It's not a big deal.\"","then":"\"Okay,\" she says, then hesitates. \"Wait, do you even want this brunch?\""}],"why":"Owning that you didn't speak up, then naming what you'd like, keeps it a shared problem."},{"prompt":"Tara asks: \"And Sunday's brunch? Should I cancel it?\"","options":[{"text":"\"No, let's go. And plan the next weekend together.\"","then":"She smiles. \"Deal. You pick next time.\"","best":true},{"text":"\"Yes. Cancel it, so the point really sinks in.\"","then":"She texts Riya, embarrassed. It feels like a punishment."},{"text":"\"Do what you want. You always do.\"","then":"Her face falls. \"That's not fair.\""},{"text":"\"I'll go, but honestly I won't enjoy it one bit.\"","then":"She sighs. \"Then what's the point?\""}],"why":"Keeping this plan and changing the next one shows the talk was about repair, not punishment."}],"relearn":"Open a hard topic with a soft 'I' start-up, not a 'you never' attack."},
  {"id":"rr-1004","cat":"fight-right","type":"role-play","persona":"any","source":"self-soothing","hook":"Arguing with Omar about money, you feel your chest tighten and your voice rise.","setup":"He's waiting for your answer.","steps":[{"prompt":"Omar says: \"Go on, say it. What's your problem?\"","options":[{"text":"\"I'm too worked up to be fair. Can we pause for an hour?\"","then":"Omar hesitates. \"Okay. One hour.\"","best":true},{"text":"\"My problem? You're useless with money. That's it.\"","then":"Omar's face goes still. \"Right. Good to know.\" He leaves the room."},{"text":"\"I can't do this. I'm going out.\"","then":"You grab your keys. Omar calls twice, and you let both ring out."},{"text":"\"Fine. Let's finish this right now and get it over with.\"","then":"You push on until you've both said things you regret. Omar walks out."}],"why":"Naming that you're flooded and asking for a timed break stops you saying what you'll regret."},{"prompt":"Twenty minutes later, Omar texts: \"I hate leaving it like this.\"","options":[{"text":"\"Me too. I'm calming down. I'll come find you soon.\"","then":"\"Okay,\" he replies. \"I'll put the kettle on.\"","best":true},{"text":"\"Then you shouldn't have started it.\"","then":"He sends a single \"Wow.\" Then nothing."},{"text":"\"Can't talk now. Busy.\"","then":"He doesn't reply. The silence stretches into the night."},{"text":"\"Let's just sort it all out over text, right now.\"","then":"Messages fly fast. On screen, your words come out harsher than you meant."}],"why":"Reassuring him you're coming back makes the break feel safe, not like a punishment."},{"prompt":"Back together, Omar asks: \"What's really bothering you about the money?\"","options":[{"text":"\"I'm stressed about rent, and I took it out on you.\"","then":"Omar exhales. \"Me too, honestly. Let's look at it together.\"","best":true},{"text":"\"Honestly? You're just hopeless with money.\"","then":"\"You waited all that time to say that?\" he asks."},{"text":"\"Doesn't matter now. I'm fine, really. Forget it.\"","then":"\"You're clearly not,\" he says, puzzled."},{"text":"\"Nothing. I'm right about this, and you know it.\"","then":"He shakes his head. \"We're back where we started.\""}],"why":"Once calm, naming the real worry, and your part in it, moves the talk forward."},{"prompt":"Omar asks: \"How do we stop it getting that heated again?\"","options":[{"text":"\"Either of us can call a break, with a time to return.\"","then":"\"I like that,\" Omar says. \"Let's both use it.\"","best":true},{"text":"\"Just don't provoke me when I'm this stressed out.\"","then":"His face falls. \"So it's all on me?\""},{"text":"\"Let's never talk about money when we're tired.\"","then":"\"We're always tired,\" he says, half laughing."},{"text":"\"We won't. That was a one-off, honestly.\"","then":"He looks doubtful. \"It happened last month too.\""}],"why":"A break either of you can call, with a return, is a tool you can both use next time."}],"relearn":"When flooded, ask for a short break with a clear time to return."},
  {"id":"rr-1005","cat":"fight-right","type":"role-play","persona":"Rohan","source":"take responsibility","hook":"You hurried Ishita out of her friend's party so you'd make the movie on time.","setup":"In the auto, she's been quiet since.","steps":[{"prompt":"Ishita says: \"You rushed me out. I didn't even say goodbye.\"","options":[{"text":"\"You're right. I did rush you. I'm sorry.\"","then":"Ishita looks over. \"Thank you. That helps.\" Then she hesitates.","best":true},{"text":"\"Well, you make me late all the time too.\"","then":"\"So this is payback?\" she asks."},{"text":"\"We'd have missed the start of the movie otherwise.\"","then":"\"We'd have made it,\" she says. \"Just.\""},{"text":"\"Okay, sorry, but you're overreacting.\"","then":"Her mouth tightens. \"Don't do that.\""}],"why":"Owning a fair complaint straight away stops it growing into a bigger fight."},{"prompt":"Ishita says: \"It's not just tonight. You decide our timings a lot.\"","options":[{"text":"\"That's fair. What would feel better to you?\"","then":"\"Just ask me first,\" she says. \"Even a quick check.\"","best":true},{"text":"\"Somebody has to, or we'd never get anywhere.\"","then":"She turns to the window. \"Right.\""},{"text":"\"A lot? Name one other time I've done it.\"","then":"She names three. The ride feels longer."},{"text":"\"Fine. You decide everything from now on.\"","then":"\"That's not what I said,\" she sighs."}],"why":"Asking what would help shows you heard the pattern, not just tonight."},{"prompt":"Ishita asks: \"So do we still watch the movie?\"","options":[{"text":"\"Yes. And after, let's work out timings together.\"","then":"She smiles a little. \"Okay. Popcorn's on you.\"","best":true},{"text":"\"Let's skip it. The mood's ruined anyway.\"","then":"She shrugs. \"If that's what you want.\""},{"text":"\"Only if you're done being upset about it.\"","then":"\"I'm not a switch,\" she says quietly."},{"text":"\"Yes. And from now on, you choose every plan.\"","then":"She laughs uneasily. \"You don't have to go that far.\""}],"why":"Carrying on together, with a plan to share decisions, turns an apology into change."}],"relearn":"Meet a fair complaint by owning your part, not firing back."},
  {"id":"rr-1006","cat":"fight-right","type":"role-play","persona":"any","source":"repair attempt","hook":"After last night's argument, you and Leela haven't texted all morning.","setup":"You spot her outside the library.","steps":[{"prompt":"Leela says, a little stiffly: \"Oh. Hi.\"","options":[{"text":"\"I hate how we left things. Chai and a redo?\"","then":"Her face softens. \"Yeah. I hated it too.\"","best":true},{"text":"\"Hi. Anyway, got to run to class.\"","then":"She nods. You both walk off, the cold still between you."},{"text":"\"So are you going to say sorry, or shall I wait?\"","then":"Leela's eyes narrow. \"Seriously?\""},{"text":"\"I'm so sorry. It was all my fault, every bit.\"","then":"She blinks. \"It wasn't all you. Don't do that.\""}],"why":"A small, warm move reconnects faster than waiting for the other person to crack."},{"prompt":"That evening, Leela messages: \"I still think you were unfair yesterday.\"","options":[{"text":"\"Maybe I was. Can you tell me which part?\"","then":"\"There's one part,\" she replies. \"Can we talk tonight?\"","best":true},{"text":"\"And you weren't? Come on.\"","then":"She replies, \"Forget it, then.\""},{"text":"\"I wasn't unfair. I was just being honest.\"","then":"\"Honest isn't the same as fair,\" she writes."},{"text":"\"Let's not. We'll only end up fighting again.\"","then":"\"Okay,\" she replies. It doesn't feel settled."}],"why":"Getting curious about her side keeps the repair going instead of reopening the fight."},{"prompt":"Later, Leela says: \"You laughed at my idea in front of everyone. I felt small.\"","options":[{"text":"\"You're right. I'm sorry. Tell me the idea again?\"","then":"She explains it slowly. It's actually a good idea.","best":true},{"text":"\"It was a joke. Everyone laughed, not just me.\"","then":"\"That's what made it worse,\" she says."},{"text":"\"You take things too seriously sometimes.\"","then":"She goes quiet. The cold creeps back."},{"text":"\"Sorry. I'll keep my opinions to myself from now.\"","then":"\"That's not what I want either,\" she says."}],"why":"Owning the moment and showing real interest in her idea repairs what the laugh broke."}],"relearn":"A small, warm repair attempt reconnects faster than a stand-off."},
  {"id":"rr-1007","cat":"fight-right","type":"role-play","persona":"any","source":"fair fighting","hook":"You're talking to Aditya about his missed call, and he keeps dragging in old fights.","setup":"Your voices are rising on the phone.","steps":[{"prompt":"Aditya says: \"And what about Goa? And your birthday?\"","options":[{"text":"\"Those matter too. Can we finish this one first?\"","then":"Aditya pauses. \"Okay. Fine. The call.\"","best":true},{"text":"\"Fine. Let's list everything you've done wrong too.\"","then":"\"Go ahead,\" he says. Now you're fighting about six things."},{"text":"\"Okay, you're right. I'm always the problem.\"","then":"He goes quiet, unsure. The missed call is forgotten."},{"text":"\"Goa was a year ago. Just drop it.\"","then":"\"Easy for you to say,\" he snaps."}],"why":"Keeping to one issue gives the fight a chance to end somewhere."},{"prompt":"Aditya says: \"I bring those up because they never got sorted.\"","options":[{"text":"\"That's fair. Let's pick a time to talk about them.\"","then":"\"Sunday?\" he asks. It sounds like a peace offer.","best":true},{"text":"\"They did get sorted. You just won't let go.\"","then":"\"Did they?\" he asks. \"When?\""},{"text":"\"Let's do every single one of them right now, then.\"","then":"It's midnight before you stop. Nothing is resolved."},{"text":"\"Then let's agree never to bring up the past again.\"","then":"\"That won't make them go away,\" he says."}],"why":"Old hurts deserve their own time. Setting one keeps both talks fair."},{"prompt":"Aditya asks: \"So, the missed call. Why were you so upset?\"","options":[{"text":"\"I was waiting at the station and felt forgotten.\"","then":"\"I didn't know that,\" he says. \"I'm sorry.\"","best":true},{"text":"\"Because you're careless. Obviously.\"","then":"\"Obviously,\" he repeats, flat."},{"text":"\"I wasn't upset. You're imagining things.\"","then":"\"You hung up on me,\" he says, confused."},{"text":"\"Because you do this all the time, and you know it.\"","then":"\"All the time?\" He sounds hurt."}],"why":"Naming the one feeling behind this fight lets him answer that, not a pile of charges."},{"prompt":"A few days later, Aditya says: \"Okay. Goa. Can we talk about it now?\"","options":[{"text":"\"Yes. Tell me what still hurts about it.\"","then":"He talks for a while. You listen, and it feels lighter after.","best":true},{"text":"\"Only if we can go through my list after.\"","then":"\"So it's a trade,\" he says, tired."},{"text":"\"Can we skip it? It was ages ago.\"","then":"\"It still bugs me,\" he says, and goes quiet."},{"text":"\"Sure. But I was right about Goa, you know.\"","then":"He sighs. \"Then why are we even talking?\""}],"why":"Giving an old hurt its own calm time is how it finally stops coming back."}],"relearn":"Keep a fight on one issue; don't match kitchen-sinking with more of it."},
  {"id":"rr-1008","cat":"fight-right","type":"role-play","persona":"any","source":"stonewalling","hook":"Kavya cancelled on you at the last minute again, and you want to ignore her for days.","setup":"Her message has just come in.","steps":[{"prompt":"Kavya writes: \"Are you mad at me? Please say something.\"","options":[{"text":"\"I'm hurt and need a bit of space. I'll call tonight.\"","then":"\"Okay,\" she writes. \"I'll wait. I'm sorry.\"","best":true},{"text":"\"No. I'm fine.\"","then":"She sends a worried emoji. You both know it isn't true."},{"text":"\"Why bother asking? You clearly don't care.\"","then":"\"That's not fair,\" she writes, then goes offline."},{"text":"\"I need space. I'll get back to you at some point.\"","then":"\"At some point?\" she writes. \"How long is that?\""}],"why":"Naming the hurt and when you'll return gives you space without punishing her."},{"prompt":"Later, Kavya calls and says: \"I know I keep doing this. I'm sorry.\"","options":[{"text":"\"Thank you. It hurt. Can we figure out what's going on?\"","then":"\"Work's been chaos,\" she says. \"I should have told you.\"","best":true},{"text":"\"You always say sorry. It means nothing now.\"","then":"Kavya goes quiet. \"Then what do you want?\""},{"text":"\"It's fine. Honestly, just forget about it.\"","then":"\"Really?\" she asks, relieved. It isn't really fine."},{"text":"\"Prove it, then. Don't cancel on me for a whole month.\"","then":"\"That sounds like a test,\" she says softly."}],"why":"Accepting the apology and asking what's behind it turns a pattern into a talk."},{"prompt":"Kavya asks: \"What would help next time plans change?\"","options":[{"text":"\"Tell me as early as you can, and let's reschedule.\"","then":"\"I can do that,\" she says. \"Saturday, then?\"","best":true},{"text":"\"Just don't let plans change. It's not that hard.\"","then":"\"Sometimes I can't help it,\" she says."},{"text":"\"Nothing. I'll just stop making plans with you.\"","then":"\"Please don't,\" she says, hurt."},{"text":"\"I'll go quiet for a day. Then you'll know.\"","then":"\"I'd rather you just told me,\" she says."}],"why":"A clear ask and a new date do more than silence ever could."}],"relearn":"Name that you need space and when you'll return; don't weaponise silence."},
  {"id":"rr-1009","cat":"fight-right","type":"role-play","persona":"any","source":"repair","hook":"You and Yash both said unkind things last night, and now he's reached out first.","setup":"He's at your door with two cups of chai.","steps":[{"prompt":"Yash says: \"I'm sorry for what I said. I didn't mean it.\"","options":[{"text":"\"Thank you. I wasn't fair either. I'm sorry for my part.\"","then":"Yash smiles, relieved. \"Chai's getting cold. Come.\"","best":true},{"text":"\"Good. You should be sorry.\"","then":"His smile fades. \"Right.\" He hands you the cup anyway."},{"text":"\"It's okay. Let's just forget the whole thing happened.\"","then":"\"Okay,\" he says, a little unsure what you meant."},{"text":"\"Thanks. Next time, think before you speak, maybe.\"","then":"He nods slowly. \"Yeah. You too, maybe.\""}],"why":"Meeting an apology with your own ownership makes it a repair, not a win."},{"prompt":"Yash asks: \"Can we talk about what started it?\"","options":[{"text":"\"Yes. I think we both felt ignored. Can I go first?\"","then":"\"Go,\" he says, settling down beside you.","best":true},{"text":"\"Why? It's done now. Let's not dig it all up.\"","then":"\"Because it'll happen again,\" he says."},{"text":"\"Sure. You started it, so you go first and explain.\"","then":"He sighs. \"Here we go.\""},{"text":"\"Only if you promise not to get angry this time.\"","then":"\"I'll try,\" he says, uneasy."}],"why":"Talking about the cause, gently, makes the next fight less likely."},{"prompt":"Yash says: \"I think I shut you out when I'm stressed.\"","options":[{"text":"\"Thanks for saying that. I snap when I feel ignored.\"","then":"\"So we set each other off,\" he says, and laughs a little.","best":true},{"text":"\"Yes, you do. It's really annoying.\"","then":"He winces. \"Okay. Noted.\""},{"text":"\"Don't worry about it. I'm used to it by now.\"","then":"He frowns. \"That's not great either.\""},{"text":"\"It's not a big deal. Everyone gets stressed.\"","then":"\"It is to me,\" he says quietly."}],"why":"Matching his honesty with yours keeps the repair two-sided."}],"relearn":"Receive an apology by owning your part too, not by gloating."},
  {"id":"rr-1010","cat":"fight-right","type":"role-play","persona":"Rohan","source":"contempt antidote","hook":"Midway through a fight with Dia, you hear yourself being sarcastic and cutting.","setup":"She's trying to explain why she's upset.","steps":[{"prompt":"Dia asks: \"Did you just roll your eyes at me?\"","options":[{"text":"\"I did. That was nasty. Sorry. Let me try again.\"","then":"Dia takes a breath. \"Okay. Try again.\"","best":true},{"text":"\"Oh, can't take a joke now?\"","then":"Dia's face hardens. \"That wasn't a joke.\""},{"text":"\"No. You're seeing things now.\"","then":"\"I'm not,\" she says. \"I saw it.\""},{"text":"\"Maybe. But you were being really dramatic.\"","then":"\"So I deserved it?\" she asks."}],"why":"Catching your own contempt and resetting shows respect, even mid-fight."},{"prompt":"Dia says: \"It feels like you look down on me when we argue.\"","options":[{"text":"\"I don't want you to feel that. I'm listening now.\"","then":"\"Okay,\" she says, and starts again, calmer.","best":true},{"text":"\"I don't look down on you. You're too sensitive.\"","then":"She goes silent. You can see she's done talking."},{"text":"\"Well, sometimes your arguments are just weak.\"","then":"\"Wow,\" she says quietly."},{"text":"\"Sorry. I'm just a sarcastic person. That's all.\"","then":"\"That doesn't make it okay,\" she says."}],"why":"Respect is the antidote to contempt. Showing it now matters more than winning the point."},{"prompt":"The next day, Dia asks: \"How do we argue without it getting nasty?\"","options":[{"text":"\"Call it out when I'm sarcastic. I'll stop and reset.\"","then":"\"Deal,\" she says. \"And you can do the same for me.\"","best":true},{"text":"\"Just don't start fights, then. Simple.\"","then":"She raises an eyebrow. \"It takes two.\""},{"text":"\"We'll just avoid arguing altogether from now on.\"","then":"\"That never works,\" she says."},{"text":"\"I'll try to be nicer to you, I promise.\"","then":"\"Nicer how?\" she asks."}],"why":"A shared signal to stop and reset makes respect a habit, not a hope."}],"relearn":"Catch your own contempt mid-fight and reset to respect."},
  {"id":"rr-1011","cat":"fight-right","type":"role-play","persona":"any","source":"stonewalling","hook":"After a fight, Sahil hasn't replied to any of your messages for a whole day.","setup":"He finally picks up your call.","steps":[{"prompt":"Sahil says quietly: \"I don't know what to say.\"","options":[{"text":"\"No rush. When you're ready, I'm here to fix this.\"","then":"A long breath. \"Thanks. Give me till tomorrow?\"","best":true},{"text":"\"Talk now, or I'm done with you.\"","then":"\"Don't threaten me,\" he says, and goes quiet again."},{"text":"\"Fine. Say nothing, then. I'm used to it by now.\"","then":"He's silent. You hear him breathe, then the call ends."},{"text":"\"Just tell me whose fault it was, then.\"","then":"\"Mine, okay?\" he says. It doesn't sound like he means it."}],"why":"A soft door, with no ultimatum, makes it easier for a shut-down partner to come back."},{"prompt":"The next day, Sahil says: \"I shut down when I feel blamed.\"","options":[{"text":"\"Thanks for telling me. How can I raise things better?\"","then":"\"Start with how you feel,\" he says. \"Not what I did.\"","best":true},{"text":"\"But you were the one to blame for that fight.\"","then":"He goes quiet again. You're back where you began."},{"text":"\"Okay. I'll never bring anything up again, then.\"","then":"\"That's not it either,\" he says, frustrated."},{"text":"\"Everyone feels blamed sometimes. You just deal with it.\"","then":"\"I'm trying,\" he says, stung."}],"why":"Learning what shuts him down helps you both fight in a way that works."},{"prompt":"Sahil asks: \"Can we try talking about the fight again?\"","options":[{"text":"\"Yes. I felt hurt when you left our dinner early.\"","then":"\"I didn't think of that,\" he says. \"I'm sorry.\"","best":true},{"text":"\"Only if you don't go silent on me this time.\"","then":"\"I'll try,\" he says, tense."},{"text":"\"Let's not. I don't want another silent day.\"","then":"\"Okay,\" he says. It's left hanging."},{"text":"\"Sure. You walked out of dinner and ignored me.\"","then":"He tenses. \"See, this is the blaming.\""}],"why":"Starting with your feeling, not his fault, lets him stay in the talk this time."}],"relearn":"Offer a shut-down partner a soft door back, not an ultimatum."},
  {"id":"rr-1012","cat":"fight-right","type":"role-play","persona":"any","source":"boundary in conflict","hook":"In today's fight, Rahul called you stupid, and you don't want to let it slide.","setup":"He's still talking, voice raised.","steps":[{"prompt":"Rahul says: \"Honestly, only an idiot would do it your way.\"","options":[{"text":"\"I'll talk, but not while you call me names.\"","then":"Rahul stops. \"Fine. Fine. I'm listening.\"","best":true},{"text":"\"You're the idiot here, not me. You know that?\"","then":"\"Me?\" he shouts. The fight gets louder."},{"text":"\"Okay. Maybe my way really is stupid.\"","then":"He nods and carries on, until he sees your face. \"What?\""},{"text":"\"Sorry. I know I wind you up when I argue.\"","then":"He shrugs. \"You do. So don't take it so personally.\""}],"why":"Naming the line calmly holds your ground without matching his contempt."},{"prompt":"Rahul says: \"Relax. It's just how I talk when I'm angry.\"","options":[{"text":"\"You can be angry. The names still aren't okay.\"","then":"Rahul pauses. \"Okay. I hear you.\"","best":true},{"text":"\"Then maybe you should talk a lot less.\"","then":"\"Wow,\" he says. The fight flares again."},{"text":"\"Okay. I know you don't really mean it.\"","then":"He nods, relieved. Nothing has changed."},{"text":"\"Fine. Then I'll start talking like that too.\"","then":"He laughs, but not kindly. \"Go on, then.\""}],"why":"Anger is allowed. Name-calling isn't, and it's never your fault. Holding that line respects you both."},{"prompt":"When things settle, Rahul says: \"I still think your way won't work.\"","options":[{"text":"\"Okay. Tell me why, and then hear my side.\"","then":"He explains, calmer, then listens to yours. No names this time.","best":true},{"text":"\"Maybe you're right. You usually know better.\"","then":"He nods. You drop your idea without saying why it mattered."},{"text":"\"Because you think I'm stupid, right?\"","then":"He sighs. \"I'm talking about the plan, not you.\""},{"text":"\"There's no point. You never listen anyway.\"","then":"He throws up his hands. \"I'm listening now.\""}],"why":"Once the names stop, you can disagree about the plan as equals."},{"prompt":"Later, Rahul says: \"I'm sorry I called you stupid. That wasn't okay.\"","options":[{"text":"\"Thank you. Disagree all you like, just no names.\"","then":"He nods. \"Deal. If I feel it coming, I'll take a walk.\"","best":true},{"text":"\"It's fine. Everyone says things in a fight.\"","then":"He looks relieved. The word still sits with you."},{"text":"\"Maybe see how it feels when I do it back to you.\"","then":"He winces. \"That's not fair.\""},{"text":"\"It's okay. I'll try not to make you angry again.\"","then":"He nods. Somehow the apology has turned into yours."}],"why":"His words are his to change. If names keep coming, talk it through with someone you trust."}],"relearn":"You can hold a boundary on respect without matching their contempt."},
  {"id":"rr-1013","cat":"fight-right","type":"role-play","persona":"any","source":"take responsibility","hook":"You snapped at Jaya over a photo with her ex, then learned it was a group trip.","setup":"She's waiting for you after class.","steps":[{"prompt":"Jaya asks: \"So? Do you still think I was hiding something?\"","options":[{"text":"\"No. I jumped to conclusions and snapped. I'm sorry.\"","then":"Jaya's face relaxes a little. \"Thanks for saying it straight.\"","best":true},{"text":"\"Well, it looked bad. What was I meant to think?\"","then":"\"You could have asked,\" she says."},{"text":"\"Sorry, but you should have told me he'd be there.\"","then":"\"I didn't know he'd be there,\" she says, tired."},{"text":"\"Let's not make a big deal out of it, okay?\"","then":"\"You made it a big deal,\" she says."}],"why":"Owning a wrong assumption plainly repairs faster than explaining why it looked bad."},{"prompt":"Jaya says: \"It scared me how fast you got angry.\"","options":[{"text":"\"That's fair to feel. I want to handle it better.\"","then":"\"How?\" she asks, but gently.","best":true},{"text":"\"I wasn't that angry. You're exaggerating.\"","then":"She steps back. \"I know what I saw.\""},{"text":"\"I get jealous because I love you so much.\"","then":"Jaya frowns. \"That doesn't make it okay.\""},{"text":"\"It won't ever happen again, I swear.\"","then":"\"I hope not,\" she says, not quite sure."}],"why":"Taking her fear seriously, without excuses, is part of owning the snap."},{"prompt":"Jaya asks: \"What will you do next time you feel that way?\"","options":[{"text":"\"Ask you calmly, before deciding anything.\"","then":"\"That's all I'd want,\" she says, and takes your hand.","best":true},{"text":"\"Check your phone, so I don't have to wonder.\"","then":"Jaya pulls back. \"No. That's not okay.\""},{"text":"\"Keep it to myself and deal with it alone.\"","then":"\"That sounds like it'll blow up later,\" she says."},{"text":"\"Just tell me about every guy you talk to.\"","then":"\"Every guy?\" she says. \"That's too much.\""}],"why":"Asking, instead of assuming or checking, builds trust and keeps her free."}],"relearn":"Own a wrong assumption plainly instead of justifying the snap."},
  {"id":"rr-1014","cat":"fight-right","type":"role-play","persona":"any","source":"gentle start-up","hook":"Nikhil keeps turning up late to your plans, and you've always let it go.","setup":"Today he's twenty minutes late again.","steps":[{"prompt":"Nikhil says, breathless: \"Sorry, sorry. Traffic. Shall we go?\"","options":[{"text":"\"Sure. Small thing, though. Can we talk about timing?\"","then":"\"Oh,\" he says. \"Yeah, okay. Tell me.\"","best":true},{"text":"\"No problem at all. Let's go.\"","then":"He grins, then catches your face. \"Wait. Are you annoyed?\""},{"text":"\"Traffic, again? Every single time, it's traffic?\"","then":"He stiffens. \"It's not every time.\""},{"text":"\"Let's go. We'll talk about it some other day.\"","then":"\"Sure,\" he says, but over coffee he keeps glancing at you."}],"why":"Raising it early, while it's still small, stops it piling into a blow-up."},{"prompt":"Nikhil asks: \"Is my being late really that big a deal?\"","options":[{"text":"\"It's small. But it makes me feel like an afterthought.\"","then":"He's quiet. \"I didn't know it felt like that.\"","best":true},{"text":"\"It's a huge deal. It's so disrespectful to me.\"","then":"\"Huge?\" he says, defensive now."},{"text":"\"No, not really. Just forget I said anything, honestly.\"","then":"\"Okay,\" he says, then frowns. \"You don't sound like it's nothing.\""},{"text":"\"My last partner was never late. That's all.\"","then":"He goes quiet. \"Right. Good for them.\""}],"why":"Saying how it lands on you is clearer than calling it big, small or rude."},{"prompt":"After a moment, Nikhil asks: \"So what would actually help?\"","options":[{"text":"\"A quick text if you're running late.\"","then":"\"Easy,\" he says. \"I can do that.\"","best":true},{"text":"\"Just never be late again. That's all.\"","then":"\"I'll try,\" he says. \"Traffic's traffic, though.\""},{"text":"\"I'll start being late too, so we're even.\"","then":"He laughs uneasily. \"Is that a joke?\""},{"text":"\"Nothing. I'll just come later myself.\"","then":"\"Oh,\" he says. It solves the wait, not the feeling."}],"why":"A small, doable ask gives him a clear way to fix it."}],"relearn":"Raise small hurts early and gently, before they pile into a blow-up."},
  {"id":"rr-1015","cat":"fight-right","type":"role-play","persona":"any","source":"defensiveness antidote","hook":"You told Anjali her messages felt cold lately, and she got defensive fast.","setup":"You're both sitting on the hostel steps.","steps":[{"prompt":"Anjali says: \"So now I'm a terrible girlfriend? Great.\"","options":[{"text":"\"I'm not attacking you. I'm on your side here.\"","then":"She stops. \"Okay. Then what do you mean?\"","best":true},{"text":"\"See? You can't take even one bit of feedback.\"","then":"\"Feedback?\" she says. \"I'm not your intern.\""},{"text":"\"Forget it. I shouldn't have said anything.\"","then":"She shrugs, still hurt. The cold stays."},{"text":"\"I didn't say that. You always twist my words.\"","then":"\"I'm not twisting anything,\" she snaps."}],"why":"Reassuring her you're on her side lowers the heat so she can hear the rest."},{"prompt":"Anjali says: \"I've been buried in exam prep. I'm not cold on purpose.\"","options":[{"text":"\"That makes sense. I've just missed you.\"","then":"Her face softens. \"I've missed you too.\"","best":true},{"text":"\"Everyone has exams. I still make time for you.\"","then":"\"Good for you,\" she says, arms crossed."},{"text":"\"Okay, but you could at least reply properly.\"","then":"She sighs. \"I'm doing my best.\""},{"text":"\"So it's the exams' fault. How convenient.\"","then":"\"Wow,\" she says. She starts to get up, then stays."}],"why":"Hearing her reason and naming your real feeling moves the talk from blame to missing each other."},{"prompt":"After a pause, Anjali asks: \"What would make you feel less shut out?\"","options":[{"text":"\"A short call at night, till exams are over.\"","then":"\"I can do that,\" she says, smiling.","best":true},{"text":"\"Just reply faster. It's really not hard.\"","then":"\"It is hard right now,\" she says."},{"text":"\"Nothing. I'll deal with it on my own.\"","then":"She looks unsure. \"Are you sure?\""},{"text":"\"Text me good morning and good night, every day.\"","then":"\"Every day? That feels like homework,\" she says."}],"why":"A small, time-bound ask fits her real week, so it can actually happen."}],"relearn":"Defuse defensiveness by reassuring you're on their side, not scoring."},
  {"id":"rr-1016","cat":"fight-right","type":"sort","hook":"Sort each move: fair fighting, or one of the four wreckers?","items":[{"id":"a","text":"Naming one specific upset calmly"},{"id":"b","text":"Eye-rolling while they talk"},{"id":"c","text":"Owning your part of it"},{"id":"d","text":"Going stone silent for days"},{"id":"e","text":"Asking for a short break, then returning"},{"id":"f","text":"\"You always, you never\" attacks"}],"bins":[{"id":"fair","label":"Fair fighting","valence":"pos"},{"id":"wrecker","label":"A wrecker","valence":"neg"}],"key":{"a":"fair","b":"wrecker","c":"fair","d":"wrecker","e":"fair","f":"wrecker"},"relearn":"Specific complaints, owning your part and breaks are fair; eye-rolling, stonewalling and 'always/never' wreck.","persona":"any","source":"four horsemen"},
  {"id":"rr-1017","cat":"fight-right","type":"sort","hook":"Each wrecker has an antidote. Sort: the wrecker, or its antidote?","items":[{"id":"a","text":"A gentle 'I felt...' opener"},{"id":"b","text":"Harsh 'you always' criticism"},{"id":"c","text":"Appreciation and respect"},{"id":"d","text":"Mockery and contempt"},{"id":"e","text":"Taking responsibility"},{"id":"f","text":"Defensiveness and blame-back"}],"bins":[{"id":"antidote","label":"Antidote","valence":"pos"},{"id":"wrecker","label":"Wrecker","valence":"neg"}],"key":{"a":"antidote","b":"wrecker","c":"antidote","d":"wrecker","e":"antidote","f":"wrecker"},"relearn":"'I' openers, appreciation and ownership are antidotes to criticism, contempt and defensiveness.","persona":"any","source":"antidotes"},
  {"id":"rr-1018","cat":"fight-right","type":"sort","hook":"After a fight, sort each move: helps repair, or harms?","items":[{"id":"a","text":"A genuine apology that owns it"},{"id":"b","text":"Silent treatment for days"},{"id":"c","text":"A kind check-in later"},{"id":"d","text":"Bringing it up to win next time"},{"id":"e","text":"Naming what you'll do differently"},{"id":"f","text":"Threatening to leave to make a point"}],"bins":[{"id":"helps","label":"Helps repair","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Apology, a check-in and naming change repair; silence, score-keeping and leave-threats harm.","persona":"any","source":"repair"},
  {"id":"rr-1019","cat":"fight-right","type":"sort","hook":"Sort each line: a 'you' attack, or an 'I' statement?","items":[{"id":"a","text":"\"I felt left out at the party.\""},{"id":"b","text":"\"You ignored me on purpose.\""},{"id":"c","text":"\"I get anxious when plans change late.\""},{"id":"d","text":"\"You're so selfish, always.\""},{"id":"e","text":"\"I need a heads-up next time.\""},{"id":"f","text":"\"You ruin everything we do.\""}],"bins":[{"id":"istatement","label":"'I' statement","valence":"pos"},{"id":"attack","label":"'You' attack","valence":"neg"}],"key":{"a":"istatement","b":"attack","c":"istatement","d":"attack","e":"istatement","f":"attack"},"relearn":"'I felt / I need' names your experience; 'you always / you ruin' attacks their character.","persona":"any","source":"I statements"},
  {"id":"rr-1020","cat":"fight-right","type":"sort","hook":"Sort: a real repair attempt, or a fake one that dodges?","items":[{"id":"a","text":"\"I was wrong, here's what I'll change.\""},{"id":"b","text":"\"Sorry you feel that way.\""},{"id":"c","text":"\"Let's start over, I missed your point.\""},{"id":"d","text":"\"Sorry, but you started it.\""},{"id":"e","text":"\"That's on me, I'll do better.\""},{"id":"f","text":"\"Fine, I'm sorry, happy now?\""}],"bins":[{"id":"real","label":"Real repair","valence":"pos"},{"id":"fake","label":"Fake / dodges","valence":"neg"}],"key":{"a":"real","b":"fake","c":"real","d":"fake","e":"real","f":"fake"},"relearn":"A real repair owns it and names change; 'sorry you feel that way' or 'but you started it' dodge.","persona":"any","source":"apology"},
  {"id":"rr-1021","cat":"fight-right","type":"sort","hook":"A break mid-fight: sort each as a healthy break, or stonewalling?","items":[{"id":"a","text":"\"I need 20 minutes, then let's finish this.\""},{"id":"b","text":"Walking off and ghosting for two days"},{"id":"c","text":"\"Let me cool down, I'll text you tonight.\""},{"id":"d","text":"Refusing to ever speak of it again"},{"id":"e","text":"Stepping out to breathe, then returning"},{"id":"f","text":"Going cold to punish them"}],"bins":[{"id":"healthy","label":"Healthy break","valence":"pos"},{"id":"stonewall","label":"Stonewalling","valence":"neg"}],"key":{"a":"healthy","b":"stonewall","c":"healthy","d":"stonewall","e":"healthy","f":"stonewall"},"relearn":"A break names a return time; stonewalling vanishes, refuses, and goes cold to punish.","persona":"any","source":"break vs stonewalling"},
  {"id":"rr-1022","cat":"fight-right","type":"sort","hook":"Sort each: about the problem, or about winning/hurting?","items":[{"id":"a","text":"\"How do we fix the money thing?\""},{"id":"b","text":"\"I'll prove you wrong if it kills me.\""},{"id":"c","text":"\"What would feel fair to us both?\""},{"id":"d","text":"\"I'll bring up your worst moments.\""},{"id":"e","text":"\"Let's solve this as a team.\""},{"id":"f","text":"\"I just need to win this one.\""}],"bins":[{"id":"problem","label":"On the problem","valence":"pos"},{"id":"win","label":"On winning/hurting","valence":"neg"}],"key":{"a":"problem","b":"win","c":"problem","d":"win","e":"problem","f":"win"},"relearn":"Fight the problem together; fighting to win or wound your partner loses the relationship.","persona":"any","source":"problem not partner"},
  {"id":"rr-1023","cat":"fight-right","type":"sort","hook":"Sort each as a green sign of repair, or a red sign of contempt.","items":[{"id":"a","text":"Genuine appreciation mid-disagreement"},{"id":"b","text":"Sneering and name-calling"},{"id":"c","text":"\"I see your point.\""},{"id":"d","text":"Mimicking them to mock"},{"id":"e","text":"A soft touch or check-in"},{"id":"f","text":"Eye-rolling at everything they say"}],"bins":[{"id":"repair","label":"Repair (green)","valence":"pos"},{"id":"contempt","label":"Contempt (red)","valence":"neg"}],"key":{"a":"repair","b":"contempt","c":"repair","d":"contempt","e":"repair","f":"contempt"},"relearn":"Appreciation, 'I see your point' and a check-in repair; sneering, mocking and eye-rolling are contempt.","persona":"any","source":"contempt"},
  {"id":"rr-1024","cat":"fight-right","type":"sort","hook":"Sort each into when it's the right tool to reach for.","items":[{"id":"a","text":"\"I felt...\" statement"},{"id":"b","text":"A short break"},{"id":"c","text":"A repair attempt"},{"id":"d","text":"Appreciation"},{"id":"e","text":"Owning your part"},{"id":"f","text":"\"Let's come back to it.\""}],"bins":[{"id":"raise","label":"To raise a hurt","valence":"tell"},{"id":"calm","label":"When flooded / cold","valence":"uhoh"}],"key":{"a":"raise","b":"calm","c":"calm","d":"raise","e":"raise","f":"calm"},"relearn":"'I' statements, appreciation and owning your part raise a hurt; breaks and repairs are for cooling and reconnecting.","persona":"any","source":"tools"},
  {"id":"rr-1025","cat":"fight-right","type":"sort","hook":"Sort each statement: takes responsibility, or shifts blame?","items":[{"id":"a","text":"\"I should've told you sooner.\""},{"id":"b","text":"\"You made me forget.\""},{"id":"c","text":"\"That was my mistake.\""},{"id":"d","text":"\"It's only because you nag.\""},{"id":"e","text":"\"I'll own my half of this.\""},{"id":"f","text":"\"If you were easier I'd be nicer.\""}],"bins":[{"id":"owns","label":"Owns it","valence":"pos"},{"id":"shifts","label":"Shifts blame","valence":"neg"}],"key":{"a":"owns","b":"shifts","c":"owns","d":"shifts","e":"owns","f":"shifts"},"relearn":"'I should've / my mistake / my half' owns it; 'you made me / because you' shifts blame.","persona":"any","source":"take responsibility"},
  {"id":"rr-1026","cat":"fight-right","type":"spot","hook":"In this argument, spot the two contempt red flags to catch.","scene":[{"id":"a","text":"\"I felt dismissed when you cut me off.\"","trick":false},{"id":"b","text":"\"Wow, genius logic as always.\" (sarcasm)","trick":true},{"id":"c","text":"\"Can we slow down and hear each other?\"","trick":false},{"id":"d","text":"Rolling eyes and scoffing at them","trick":true},{"id":"e","text":"\"I want to understand your side.\"","trick":false}],"why":"Mocking sarcasm and eye-rolling are contempt, the most corrosive pattern; the other lines are fair complaints or repair.","relearn":"Mocking sarcasm and eye-rolling are contempt; calm complaints and repair are not.","persona":"any","source":"contempt"},
  {"id":"rr-1027","cat":"fight-right","type":"spot","hook":"Spot the two lines that are stonewalling, not a real break.","scene":[{"id":"a","text":"\"Give me 10 minutes, then let's finish.\"","trick":false},{"id":"b","text":"Walking off and refusing to speak for days","trick":true},{"id":"c","text":"\"I'll text you when I've cooled down.\"","trick":false},{"id":"d","text":"Going totally cold to make them suffer","trick":true},{"id":"e","text":"\"Let's pause and pick this up at night.\"","trick":false}],"why":"Vanishing for days and going cold to punish are stonewalling; a real break names a return time.","relearn":"Vanishing and going cold are stonewalling; a real break names when you'll return.","persona":"any","source":"stonewalling"},
  {"id":"rr-1028","cat":"fight-right","type":"spot","hook":"Spot the two fake apologies that dodge responsibility.","scene":[{"id":"a","text":"\"I was wrong, and here's what I'll change.\"","trick":false},{"id":"b","text":"\"Sorry you took it that way.\"","trick":true},{"id":"c","text":"\"That's on me, I'm sorry.\"","trick":false},{"id":"d","text":"\"Sorry, but you started it.\"","trick":true},{"id":"e","text":"\"I missed your point, let me redo it.\"","trick":false}],"why":"'Sorry you took it that way' and 'sorry, but you started it' shift blame; a real apology owns it and names change.","relearn":"Fake apologies shift blame; a real one owns it and names what you'll change.","persona":"any","source":"apology"},
  {"id":"rr-1029","cat":"fight-right","type":"spot","hook":"Spot the two criticism-of-character lines (not fair complaints).","scene":[{"id":"a","text":"\"I felt hurt when the call got cancelled.\"","trick":false},{"id":"b","text":"\"You're a selfish person, always have been.\"","trick":true},{"id":"c","text":"\"I'd like more notice next time.\"","trick":false},{"id":"d","text":"\"This is just who you are: useless.\"","trick":true},{"id":"e","text":"\"Can we plan together earlier?\"","trick":false}],"why":"Attacking who they 'are' (selfish, useless) is criticism of character; the others name one specific upset, a fair complaint.","relearn":"Attacking character is criticism; naming one specific upset is a fair complaint.","persona":"any","source":"criticism vs complaint"},
  {"id":"rr-1030","cat":"fight-right","type":"spot","hook":"Spot the two moves that escalate the fight instead of repairing.","scene":[{"id":"a","text":"\"I'm on your side, let's solve it.\"","trick":false},{"id":"b","text":"Dragging up every old grievance","trick":true},{"id":"c","text":"\"Help me see your point.\"","trick":false},{"id":"d","text":"Threatening to leave to win","trick":true},{"id":"e","text":"\"Let's take a breath and restart.\"","trick":false}],"why":"Kitchen-sinking old grievances and leave-threats escalate; the others are repair attempts that lower the heat.","relearn":"Dredging old grievances and leave-threats escalate; repair attempts lower the heat.","persona":"any","source":"escalation"},
  {"id":"rr-1031","cat":"fight-right","type":"spot","hook":"Spot the two defensive moves that block hearing the complaint.","scene":[{"id":"a","text":"\"Tell me more, I want to get it.\"","trick":false},{"id":"b","text":"\"Well you do it constantly too.\"","trick":true},{"id":"c","text":"\"You're right, I did rush you.\"","trick":false},{"id":"d","text":"\"That never happened, you're imagining it.\"","trick":true},{"id":"e","text":"\"Okay, I hear you, let's fix it.\"","trick":false}],"why":"Counter-attacking and flat denial are defensiveness; listening and owning a part lets the complaint actually land.","relearn":"Counter-attacking and denial are defensiveness; listening and owning lets a complaint land.","persona":"any","source":"defensiveness"},
  {"id":"rr-1032","cat":"fight-right","type":"spot","hook":"Spot the two lines that turn a complaint into contempt.","scene":[{"id":"a","text":"\"I was upset the chores slipped.\"","trick":false},{"id":"b","text":"\"You're pathetic, honestly.\"","trick":true},{"id":"c","text":"\"Can we share these better?\"","trick":false},{"id":"d","text":"Laughing meanly at their effort","trick":true},{"id":"e","text":"\"I'd love a hand with this.\"","trick":false}],"why":"Calling them pathetic and mocking their effort are contempt; the others are specific complaints or requests, not attacks.","relearn":"Calling them pathetic or mocking their effort is contempt, not a fair complaint.","persona":"any","source":"contempt"},
  {"id":"rr-1033","cat":"fight-right","type":"branch","persona":"any","source":"self-soothing","hook":"On a late video call, your fight with Rehaan about his trip home is spiralling.","steps":[{"prompt":"Your heart is racing, and you're close to saying something cruel. What do you do?","options":[{"text":"Push through while you're this worked up","then":"You say his family always comes first. His face shuts down."},{"text":"End the call without saying anything at all","then":"He calls back three times. You watch the phone ring."},{"text":"Ask for a 20-minute break and promise to call back","then":"Rehaan pauses. \"Okay. Twenty minutes.\" The screen goes dark.","best":true},{"text":"Mute yourself and let him vent until he's done","then":"He talks for ten minutes, then realises you've gone silent."}],"why":"Naming a break and a return time protects you both from words you'd regret."},{"prompt":"Twenty minutes later, the call has ended and you're calmer. What do you do?","options":[{"text":"Text \"forget it\" and go to sleep","then":"\"Okay,\" he replies. The fight stays unfinished."},{"text":"Call back and say what's really upsetting you","then":"Rehaan listens. \"I didn't know you felt left out. Tell me more.\"","best":true},{"text":"Call back and pick up exactly where you left off","then":"Within minutes, you're both shouting again."},{"text":"Wait till tomorrow without telling him","then":"He stays up, unsure where things stand."}],"why":"Coming back calm to the real issue is what makes the break worth it."},{"prompt":"The next day, Rehaan says he hates it when either of you steps away mid-fight. What do you do?","options":[{"text":"Explain a break is to calm down, with a set time to return","then":"He thinks about it. \"Okay. As long as you always come back.\"","best":true},{"text":"Tell him that's his problem","then":"\"Wow,\" he says, and the call goes cold."},{"text":"Agree never to take a break in a fight again","then":"He's relieved. Next time, you're both flooded and nobody stops."},{"text":"Change the subject and hope it passes","then":"It passes for now. After the next fight, the same question comes back."}],"why":"A break with a clear return is a pause, not the silent treatment."}],"debrief":"A short, agreed break when flooded, then returning, is the antidote. It's not the silent treatment.","relearn":"When flooded, take a short break and return; don't push on or vanish."},
  {"id":"rr-1034","cat":"fight-right","type":"branch","persona":"any","source":"gentle start-up","hook":"Your partner Yash cancelled plans at the last minute, for the third time this month.","steps":[{"prompt":"He texts \"sorry, something came up\". What do you reply?","options":[{"text":"\"You always do this. You're so selfish, Yash.\"","then":"\"Wow. Okay,\" he replies. Nothing more comes."},{"text":"\"No worries!\"","then":"\"Thanks!\" he replies. The hurt stays with you all evening."},{"text":"\"I felt let down. Can we talk about how we plan?\"","then":"Yash calls. \"Yeah. I've been flaky. Let's talk.\"","best":true},{"text":"\"Fine. I'll make other plans from now on.\"","then":"Yash sends a confused \"??\" and you don't reply."}],"why":"A soft \"I felt\" start opens a real talk instead of a fight."},{"prompt":"The next day, Yash says work keeps running late. What do you say?","options":[{"text":"Say work is always his excuse","then":"He bristles. \"It's not an excuse. It's my job.\""},{"text":"Ask if you can plan on days he knows he's free","then":"He thinks. \"Sundays, mostly. Let's lock those in.\"","best":true},{"text":"Say you totally understand, no problem","then":"He relaxes. Nothing about the plans changes."},{"text":"Suggest he quit if it's that bad","then":"He laughs, then sees you're serious. \"Come on.\""}],"why":"Solving the pattern together works better than blaming or brushing it off."},{"prompt":"Two weeks later, he has to cancel again, but calls first to explain. What do you do?","options":[{"text":"Bring up every past cancellation","then":"The call turns into a list, and he gets defensive."},{"text":"Say nothing, and quietly stop making plans","then":"He doesn't notice at first. Then he wonders why you're distant."},{"text":"Say it's totally fine, even though it stings","then":"He's relieved. You hang up feeling small."},{"text":"Thank him for calling, and pick a new day","then":"\"Thursday?\" he offers. \"I'll block it off.\"","best":true}],"why":"Noticing his effort and replanning together builds the trust back."},{"prompt":"A month later, Yash asks how you feel about how things are going. What do you say?","options":[{"text":"Name what's working, and what still hurts","then":"He nods. \"Okay. Let's keep working on that part.\"","best":true},{"text":"Say everything's perfect now","then":"He smiles. The small thing still bothering you stays unsaid."},{"text":"Say the damage is already done","then":"Yash looks lost. \"Then why did we try?\""},{"text":"Say it's on him to fix it, not you","then":"Yash frowns. \"I thought we were doing this together.\""}],"why":"Honest check-ins, on the good and the hard, keep a couple on track."}],"debrief":"Raise a recurring hurt with a soft \"I felt\" start-up, not a character attack.","relearn":"Open a recurring hurt softly with 'I felt', not 'you always'."},
  {"id":"rr-1035","cat":"fight-right","type":"branch","persona":"any","source":"repair","hook":"You and your partner Kiran fought about weekend plans. He snapped, and you went cold on him.","steps":[{"prompt":"Kiran comes back and says he's sorry for his tone. What do you do?","options":[{"text":"List everything else he's done this month","then":"Kiran's shoulders drop. \"I was trying to fix this.\""},{"text":"Say \"okay\" and change the subject","then":"He nods. The apology hangs there, half-finished."},{"text":"Accept it, and own the part where you shut him out","then":"Kiran exhales. \"Thanks. That helps. Let's start again.\"","best":true},{"text":"Say you'll forgive him once he's actually earned it","then":"Kiran goes quiet. He looks sorry he said anything."}],"why":"Meeting an apology with your own part closes the rupture instead of scoring points."},{"prompt":"Later, Kiran asks how you can both avoid this fight next time. What do you say?","options":[{"text":"Say he just needs to stop snapping","then":"Kiran nods stiffly. \"And you?\""},{"text":"Suggest you both speak up early when something bugs you","then":"Kiran nods. \"Before it builds up. Yeah, let's try that.\"","best":true},{"text":"Say fights can't be avoided, so why try","then":"Kiran shrugs, a little deflated."},{"text":"Promise you'll keep him happy so it doesn't happen","then":"He smiles, but it's a promise you can't keep alone."}],"why":"A shared habit, used by both, prevents the next blow-up better than blame."},{"prompt":"A week later, you snap at Kiran over something small. What do you do?","options":[{"text":"Say he started it last week","then":"Kiran sighs. \"Are we keeping score now?\""},{"text":"Hope he doesn't bring it up","then":"He doesn't. But he's quieter than usual all evening."},{"text":"Apologise for your tone, the way he did","then":"Kiran smiles. \"Thanks. Rough day?\"","best":true},{"text":"Buy him his favourite snack instead of saying sorry","then":"He enjoys the snack. The snap still sits between you."}],"why":"Apologising the way you'd want an apology keeps repair a two-way habit."}],"debrief":"Meet an apology by accepting it and owning your own part, not by scoring points.","relearn":"Receive an apology by owning your part too, not by piling on."},
  {"id":"rr-1036","cat":"fight-right","type":"branch","persona":"Rohan","source":"contempt antidote","hook":"Mid-fight with your girlfriend Mahi, you've just said, \"Wow, genius plan, as always.\"","steps":[{"prompt":"Mahi goes quiet and looks hurt. What do you do?","options":[{"text":"Say it was just a joke","then":"\"It didn't sound like one,\" Mahi says, arms folded."},{"text":"Keep going. She started it","then":"The next jab lands harder. Mahi stops arguing and walks out."},{"text":"Name it: \"That was nasty. Let me say it properly.\"","then":"Mahi blinks. \"Okay. Go on.\"","best":true},{"text":"Say sorry, then add that she's way too sensitive","then":"Mahi's eyes narrow. \"So now it's my fault I'm hurt?\""}],"why":"Catching your own contempt and resetting keeps respect alive in a fight."},{"prompt":"Later that night, Mahi says your sarcasm makes her feel stupid. What do you do?","options":[{"text":"Tell her she's overreacting","then":"Mahi shakes her head and stops talking."},{"text":"Promise you'll never be sarcastic with her again","then":"She half-smiles. You both know that's a big promise."},{"text":"Go quiet until the mood passes","then":"The silence drags on. Mahi goes to bed without a word."},{"text":"Admit it, and say what was really bothering you","then":"Mahi uncrosses her arms. \"Okay. I didn't know that.\"","best":true}],"why":"Owning the jab and naming the real issue turns contempt back into conversation."},{"prompt":"The next day, your friend Vikram laughs that sarcasm is just banter and she needs to chill. What do you think?","options":[{"text":"Banter's fine when it's shared. That wasn't","then":"Your friend shrugs. \"Fair. You know her better.\"","best":true},{"text":"He's right. She's too sensitive","then":"You feel justified for a minute, then uneasy."},{"text":"Maybe, but I'll avoid her till it blows over","then":"Two days of distance, and the hurt hardens on both sides."},{"text":"Sarcasm is who I am. Take it or leave it","then":"It sounds tough out loud. Alone, it sounds lonely."}],"why":"Contempt dressed as banter still corrodes. Knowing the difference protects what you have."},{"prompt":"A week later, you feel another sharp line coming mid-argument. What do you do?","options":[{"text":"Let it out. Holding back is fake","then":"It lands. Mahi's face closes, and the fight gets bigger."},{"text":"Swallow it and go completely silent","then":"The line stays in, but so does everything else. Mahi can't reach you."},{"text":"Pause, then say what you're actually feeling","then":"\"I'm stressed and taking it out on you,\" you say. Mahi softens.","best":true},{"text":"Say it with a laugh so it lands a bit softer","then":"She doesn't laugh. \"Same thing, different tone.\""}],"why":"Swapping the jab for the real feeling is the antidote to contempt."}],"debrief":"Catch your own contempt mid-fight, name it, and reset to respect. Don't excuse it as a joke.","relearn":"Catch and reset your own contempt; don't excuse it as a joke."},
  {"id":"rr-1037","cat":"fight-right","type":"branch","persona":"any","source":"repair attempt","hook":"After last night's fight, you and Nikita pass each other in the college canteen without a word.","steps":[{"prompt":"You're both in the queue for morning chai. What do you do?","options":[{"text":"Wait for her to break the silence first","then":"She waits too. You drink your chai at separate tables."},{"text":"Buy two chais and ask, \"Can we try again?\"","then":"Nikita hesitates, then takes the cup. \"Yeah. I hated last night.\"","best":true},{"text":"Say a stiff \"morning\" and leave it there","then":"\"Morning,\" she says back. The chill stays."},{"text":"Tell her you're still angry about last night","then":"Nikita's face tightens. \"Here? Now?\""}],"why":"A small repair, even chai and a kind word, reconnects you faster than a stand-off."},{"prompt":"In the afternoon, Nikita says she's still upset about something you said. What do you do?","options":[{"text":"Say you've both moved on, so why bring it up","then":"Nikita looks away. \"I guess I haven't.\""},{"text":"Say she said worse things","then":"Now you're both defending, and the afternoon is gone."},{"text":"Apologise quickly so it's done with","then":"She nods, but she can tell you didn't ask what hurt."},{"text":"Ask her to tell you what hurt, and listen","then":"Nikita takes a breath and explains. You hadn't seen it that way.","best":true}],"why":"Listening to what hurt is how repair actually lands."},{"prompt":"That weekend, a small argument starts again. What do you do?","options":[{"text":"Offer a repair early: a joke, a touch, a \"sorry\"","then":"Nikita laughs despite herself. The argument shrinks back to its real size.","best":true},{"text":"Let it run its course, then sulk for a bit","then":"It runs for an hour. The sulk runs for two days."},{"text":"Walk away and wait for it to blow over by itself","then":"It blows over, but nothing's resolved."},{"text":"Win this one, since you gave in last time","then":"You win the point, and lose the evening."}],"why":"Early, small repairs stop little fights from growing."}],"debrief":"A small repair attempt, even chai and a kind word, keeps couples close after a fight.","relearn":"Make a small repair attempt after a fight; don't wait it out."},
  {"id":"rr-1038","cat":"fight-right","type":"branch","persona":"any","source":"defensiveness","hook":"Your partner Ankit says you never ask about his day anymore.","steps":[{"prompt":"Your instinct is to snap that he doesn't ask about yours either. What do you do?","options":[{"text":"Point out that he doesn't ask about yours","then":"Ankit's jaw tightens. \"This isn't a competition.\""},{"text":"Explain how busy your week has been","then":"Ankit sighs. \"I know you're busy. That's not the point.\""},{"text":"Listen fully, then own any part that's fair","then":"Ankit looks surprised. \"Oh. Okay. Thanks for hearing me.\"","best":true},{"text":"Say \"fine, whatever\" and pick up your phone","then":"Ankit stares at you, then leaves the room."}],"why":"Listening before you respond breaks the loop of blame bouncing back."},{"prompt":"Later, Ankit comes back and says it's made him feel like an afterthought. What do you do?","options":[{"text":"Say you're sorry that he feels that way","then":"Ankit looks away. \"That's not really sorry.\""},{"text":"Tell him he's being a bit oversensitive about it","then":"He goes quiet. \"Forget I said anything.\""},{"text":"Say he should have told you about this sooner","then":"\"I'm telling you now,\" he says, frustrated."},{"text":"Admit you've been distracted, and ask about his week","then":"Ankit smiles a little and tells you about his internship interview.","best":true}],"why":"Owning it and acting on it right away shows him he matters."},{"prompt":"Next week, Ankit mentions another small thing that bothered him. What do you do?","options":[{"text":"Say \"here we go again\"","then":"His face falls. \"Never mind.\""},{"text":"Nod along, then change the subject fast","then":"It ends quickly. He can tell you weren't listening."},{"text":"Thank him for saying it, and hear him out","then":"Ankit relaxes. \"I was nervous to bring it up.\"","best":true},{"text":"Explain why it isn't really your fault","then":"Ankit sighs. \"I wasn't blaming you. I just wanted you to know.\""}],"why":"Welcoming small complaints keeps them small and keeps trust growing."}],"debrief":"Defensiveness escalates. Listening and owning your part de-escalates and repairs.","relearn":"Listen and own your part instead of defending or counter-attacking."},
  {"id":"rr-1039","cat":"fight-right","type":"branch","persona":"any","source":"stonewalling","hook":"Your partner Neha joked about your accent at a party, and you're tempted to go silent for days.","steps":[{"prompt":"On the walk home, Neha asks if you're okay. What do you do?","options":[{"text":"Say \"I'm fine\" and go quiet on her for days","then":"Neha tries twice more that night. Each reply is one word."},{"text":"Ask for space tonight, and set a time to talk","then":"Neha nods. \"Okay. Tomorrow, then.\"","best":true},{"text":"Tell her off right there on the road, loudly","then":"Neha gets defensive. \"It was a joke! Everyone laughed.\""},{"text":"Laugh it off and say it was nothing, really","then":"Neha relaxes, but gives you a searching look. The hurt comes back when you're alone."}],"why":"Naming that you need space, and when you'll return, makes it a break, not a punishment."},{"prompt":"The next day, Neha texts that last night felt off, and asks to talk. What do you do?","options":[{"text":"Reply \"whatever\" and stay cold","then":"She stops asking for now. The hurt settles in on both sides."},{"text":"Say you're busy, maybe next week","then":"A week passes, and the joke grows bigger in your head."},{"text":"Say yes, and pick a time today to talk","then":"Neha replies at once: \"Six, at the chai stall. I'll be there.\"","best":true},{"text":"Send a long angry message instead of talking","then":"She reads it and replies with an angry one of her own."}],"why":"Coming back to talk about the hurt is what separates space from stonewalling."},{"prompt":"When you and Neha sit down to talk, she says she didn't know the joke would hurt. What do you do?","options":[{"text":"Say she should have known","then":"Neha's face falls. \"How? I'm not a mind reader.\""},{"text":"Believe her, and ask her not to joke about it again","then":"\"Deal,\" she says. \"I'm sorry. I mean that.\"","best":true},{"text":"Say it doesn't matter anymore","then":"Neha looks unsure. The talk ends without any agreement."},{"text":"Remind her of a time she got upset at a joke","then":"Now you're comparing hurts, and neither of you feels heard."}],"why":"Accepting her honesty and making a clear ask turns the hurt into a fix."},{"prompt":"Weeks later, something else hurts you in the moment. What do you do?","options":[{"text":"Go silent and wait until she guesses what's wrong","then":"She doesn't guess. Two days of quiet follow."},{"text":"Say it doesn't matter, then stew","then":"The stewing leaks out in snippy replies all week."},{"text":"Say it stung, and that you'll talk once you're calm","then":"Neha nods. \"Okay. I'm here when you're ready.\"","best":true},{"text":"Snap back with a joke about her","then":"She laughs, then goes quiet. Now you've both been stung."}],"why":"Saying you're hurt and naming a return keeps space healthy, not a weapon."}],"debrief":"Name that you need space and when you'll return. Don't use silence as a weapon.","relearn":"Take space openly with a return time; don't weaponise silence."},
  {"id":"rr-1040","cat":"fight-right","type":"branch","persona":"any","source":"needs under conflict","hook":"You and Sana have had the same fight about weekend plans three times this month.","steps":[{"prompt":"Tonight it starts again, almost word for word. What do you do?","options":[{"text":"Pause and ask what each of you needs from weekends","then":"Sana goes quiet, then says she needs rest. You admit you need time with friends.","best":true},{"text":"Say your point again, louder, until she gives in","then":"Sana's voice rises to match yours. She stops arguing, but nothing is settled."},{"text":"Give in to her plan just to end the fight tonight","then":"The fight stops. You spend Saturday quietly resentful, and it's still unsolved."},{"text":"Bring up every weekend she cancelled on your friends","then":"Sana fires back with her own list. Now it's about everything, not weekends."}],"why":"Naming the need under the fight gives you both something to solve, not a point to win."},{"prompt":"On Friday, Sana says you care more about your friends than her. What do you do?","options":[{"text":"Ask what makes her feel that way","then":"Sana says Saturdays feel like leftovers. It stings, and now you understand.","best":true},{"text":"Say that's not true and list all you do for her","then":"Sana folds her arms. \"So it's a scorecard now?\""},{"text":"Tell her she's being clingy about a few Saturdays","then":"Sana looks stung and leaves the room. The word hangs there all evening."},{"text":"Promise to spend every weekend with her from now on","then":"Sana smiles, surprised. You feel a knot, knowing you can't keep that."}],"why":"Asking what's behind her words finds the real need before you defend or give in."},{"prompt":"Over Sunday chai, Sana asks if you two can sort out weekends properly. What do you do?","options":[{"text":"Share your own need too, and suggest planning together","then":"Sana nods slowly. Together you sketch out the next month of weekends.","best":true},{"text":"Apologise and cancel your friends for the next month","then":"Sana looks relieved. You already miss your friends, and don't say so."},{"text":"Tell her she's overreacting to a couple of weekends","then":"Sana puts her cup down. The rest of Sunday is cold."},{"text":"Say maybe you two should just do separate weekends","then":"Sana asks, \"Is that what you want?\" You're not sure."}],"why":"Both needs count. Putting both on the table is how a looping fight becomes a plan."},{"prompt":"A month later, a friend's birthday falls on a Saturday Sana had hoped to share with you. What do you do?","options":[{"text":"Tell Sana early and ask how you could make it work","then":"Sana thinks, then suggests Sunday for the two of you. It's settled in minutes.","best":true},{"text":"Go without mentioning it, since it's only once","then":"Sana finds out from a photo. The old fight is back by evening."},{"text":"Skip the birthday so there's no fight at all","then":"Sana never knows. You sulk through the day and she can't tell why."},{"text":"Tell her you're going, and she can come or not","then":"Sana says fine, flatly. You go, but the evening feels tense."}],"why":"Raising a clash early, as a shared problem, keeps the old loop from starting again."}],"debrief":"When a fight loops, surface the need under it instead of getting louder.","relearn":"Break a looping fight by naming each person's underlying need."},
  {"id":"rr-1041","cat":"fight-right","type":"branch","persona":"Aarti","source":"repair","hook":"You and Kabir disagree about a trip he's planned, and your family says you must win this one.","steps":[{"prompt":"Your mother offers to call Kabir and set him straight. What do you do?","options":[{"text":"Thank her, and say you'll sort it with Kabir yourself","then":"Your mother sighs but agrees. You text Kabir to talk this weekend.","best":true},{"text":"Let her call. He might listen to an elder","then":"Kabir picks up, stiff and polite. Afterwards he goes quiet with you."},{"text":"Share his messages in the family group so they see","then":"Relatives pile in with opinions. Kabir hears about it and feels ambushed."},{"text":"Stop replying to Kabir until he gives in","then":"Kabir sends two messages, then nothing. By the weekend, the silence feels heavy."}],"why":"Most couple disagreements repair between the two of you. An audience raises the heat."},{"prompt":"At the weekend, Kabir says he wants to talk the trip through properly. What do you do?","options":[{"text":"Ask why it matters to him, then share your worry","then":"Kabir says it's a friend's farewell. You say you're worried about the cost.","best":true},{"text":"Say your parents think it's a bad idea too","then":"Kabir's jaw tightens. \"So it's all of you against me now?\""},{"text":"Say he can go, but you're not happy about it","then":"Kabir hesitates. The trip is on, and so is the tension."},{"text":"Start with a list of why the trip makes no sense","then":"Kabir crosses his arms and starts a list of his own."}],"why":"Hearing each other's reasons turns a contest into a problem you can solve together."},{"prompt":"Your cousin asks in the family group who won the fight. What do you do?","options":[{"text":"Say you two are sorting it out, and leave it there","then":"A few thumbs-up, then the group moves on to someone's birthday.","best":true},{"text":"Explain both sides so they can see you've been fair","then":"Relatives start taking sides anyway, and Kabir's name keeps coming up."},{"text":"Say Kabir finally admitted you were right","then":"The group cheers. You feel uneasy, because that isn't quite true."},{"text":"Leave the group for a while so no one can ask","then":"The questions move to your mother's phone instead."}],"why":"Keeping it private protects the repair you're making, and his dignity in your family."}],"debrief":"Most couple disagreements repair between the two of you; pulling in family escalates them.","relearn":"Repair disagreements between the two of you, not by recruiting family."},
  {"id":"rr-1042","cat":"fight-right","type":"branch","persona":"Rohan","source":"repair","hook":"Mid-fight, you told Nisha she was pathetic, and you saw it land hard.","steps":[{"prompt":"She goes silent and turns away. What do you do?","options":[{"text":"Say, \"That was cruel and unfair of me. I'm sorry.\"","then":"Nisha doesn't turn around, but her shoulders drop a little.","best":true},{"text":"Say, \"You pushed me to it, so it doesn't count.\"","then":"Nisha turns, eyes wet. \"So it's my fault you said it?\""},{"text":"Say, \"Come on. You know I didn't mean it.\"","then":"She shakes her head. \"You said it, though.\""},{"text":"Leave the room to let things cool down","then":"The door clicks shut. The word stays in the room with her."}],"why":"A clean apology that owns the words starts repair before the hurt sets."},{"prompt":"The next morning, Nisha is still distant at breakfast. What do you do?","options":[{"text":"Ask if she's willing to talk about last night","then":"She nods slowly. \"Later. I need a bit of time.\"","best":true},{"text":"Act normal and hope it has blown over","then":"She answers in single words. It clearly hasn't."},{"text":"Bring her favourite chai and say nothing about it","then":"She takes the cup and thanks you, politely. The hurt is still there."},{"text":"Tell her last night is done, and it's time to move on","then":"Nisha puts her cup down. \"It isn't done for me.\""}],"why":"Checking in lets her set the pace, so repair isn't rushed or skipped."},{"prompt":"That evening Nisha says: \"It wasn't just the word. It was how you said it.\" What do you do?","options":[{"text":"Listen, then say what you'll do differently in fights","then":"She listens and nods. \"I'd like that to be true.\"","best":true},{"text":"Explain how stressed you were about exams that week","then":"She sighs. \"I get it. It still hurt.\""},{"text":"Point out that she says hurtful things too","then":"Her face closes. The talk turns into a new fight."},{"text":"Apologise again, over and over, until she smiles","then":"She says, \"Stop. I don't need you grovelling.\""}],"why":"Owning the tone as well as the word, and naming a change, is what rebuilds trust."},{"prompt":"A week later, another argument starts heating up. What do you do?","options":[{"text":"Notice the anger rising and ask for a short break","then":"You step onto the balcony. Ten minutes later you come back calmer.","best":true},{"text":"Push through, and just bite back the insults","then":"You bite back the worst of it, just. Your voice is sharp all the same."},{"text":"Say nothing at all, so nothing cruel comes out","then":"Nisha keeps talking to a wall. She ends up more upset."},{"text":"Tell her to stop before she makes you say something","then":"Nisha stares at you. \"Makes you?\""}],"why":"Catching the heat early and pausing is how you stop cruel words before they come out."}],"debrief":"When you cross a line, own it with a clean apology; don't justify it.","relearn":"Own cruel words with a clean apology; don't justify them."},
  {"id":"rr-1043","cat":"fight-right","type":"reflect","hook":"Lensy: think of the last small fight that actually got resolved well.","prompt":"What helped most?","options":["We took a break","We really listened","Someone repaired first","We stuck to one issue"],"affirm":"All of these are real conflict skills, and they're learnable. Noticing what works is how you get better at it.","relearn":"Breaks, listening, repairing first and staying on one issue are the skills that resolve fights.","persona":"any","source":"skill"},
  {"id":"rr-1044","cat":"fight-right","type":"reflect","hook":"Lensy: when a fight floods you, what helps you cool down before you speak?","prompt":"What's yours?","options":["Step outside","Breathe slowly","A short walk","Some water"],"affirm":"There's no single right way to self-soothe; whatever steadies you so you return calmer is the win.","relearn":"Self-soothing before returning to a flooded fight is healthy; the method is yours to choose.","persona":"any","source":"self-soothing"},
  {"id":"rr-1045","cat":"fight-right","type":"reflect","hook":"Lensy: a repair attempt can be tiny, a look, a touch, a joke, chai.","prompt":"What's a repair move that feels like you?","options":["A small joke","Making chai","A hand on theirs","\"Can we restart?\""],"affirm":"Any of these can reconnect you after a rupture; the couples who repair, in their own way, are the ones who last.","relearn":"A repair attempt can be small and personal; what matters is that you reach back.","persona":"any","source":"repair attempt"},
  {"id":"rr-1046","cat":"fight-right","type":"reflect","hook":"Lensy: it's natural to want to win an argument. What would 'we both feel okay' look like instead?","prompt":"Sit with that.","options":["Both heard","Issue solved","Still close","No one humiliated"],"affirm":"Aiming for 'we're both okay' over 'I won' is the shift that protects the relationship. Wanting the win is human; choosing repair is the skill.","relearn":"The goal in conflict is both people okay and the problem solved, not a win.","persona":"any","source":"problem not partner"},
  {"id":"rr-1047","cat":"fight-right","type":"reflect","hook":"Lensy: think of how conflict was handled in homes you grew up around.","prompt":"What do you want to keep, or do differently?","options":["Stay calmer","Repair sooner","Less silence","More honesty"],"affirm":"You get to choose how you handle conflict, not just inherit it. Noticing the pattern is the first step to changing it.","relearn":"How you handle conflict is a choice you can build, not just inherit.","persona":"any","source":"learnable skill"},
  {"id":"rr-1048","cat":"fight-right","type":"reflect","hook":"Lensy: which of the four wreckers is your own tempting one under stress?","prompt":"Be honest, just with yourself.","options":["Criticism","Contempt","Defensiveness","Stonewalling"],"affirm":"We all reach for one under pressure; naming yours is how you catch it next time. No judgment, just awareness.","relearn":"Naming your own go-to wrecker is how you start to catch and replace it.","persona":"any","source":"four horsemen"},
  {"id":"rr-1049","cat":"fight-right","type":"reflect","hook":"Lensy: after a fight, what helps you reconnect rather than stay cold?","prompt":"What works for you?","options":["Talk it out","Some space first","A kind gesture","Naming feelings"],"affirm":"Different things reconnect different people; whatever closes the gap kindly is right for you both.","relearn":"Reconnecting after a fight matters more than how; pick what closes the gap kindly.","persona":"any","source":"repair"},
  {"id":"rr-1050","cat":"fight-right","type":"match","hook":"Match each wrecker to its antidote.","pairs":[{"left":"Criticism","right":"A gentle 'I' statement"},{"left":"Contempt","right":"Appreciation and respect"},{"left":"Defensiveness","right":"Take responsibility"},{"left":"Stonewalling","right":"Self-soothing break, then return"},{"left":"Kitchen-sinking","right":"Stay on one issue"}],"relearn":"Each wrecker has an antidote: 'I' statements, appreciation, taking responsibility, a break-and-return, one issue.","persona":"any","source":"antidotes"},
  {"id":"rr-1051","cat":"fight-right","type":"match","hook":"Match each moment to the tool that fits it.","pairs":[{"left":"Raising a hurt","right":"\"I felt...\" statement"},{"left":"Too flooded to think","right":"A short break"},{"left":"After a fight","right":"A repair attempt"},{"left":"They got defensive","right":"\"I'm on your side\""},{"left":"Fight is looping","right":"Name the need under it"}],"relearn":"'I felt' raises a hurt, a break cools flooding, a repair follows a fight, reassurance defuses defence.","persona":"any","source":"tools"},
  {"id":"rr-1052","cat":"fight-right","type":"match","hook":"Match each wrecker line to what it really is.","pairs":[{"left":"\"You always ruin things\"","right":"Criticism of character"},{"left":"Eye-rolling and sneering","right":"Contempt"},{"left":"\"You started it, not me\"","right":"Defensiveness"},{"left":"Going cold for days","right":"Stonewalling"},{"left":"\"And another thing...\"","right":"Kitchen-sinking"}],"relearn":"'Always' is criticism, sneering is contempt, blame-back is defensiveness, going cold is stonewalling.","persona":"any","source":"four horsemen"},
  {"id":"rr-1053","cat":"fight-right","type":"match","hook":"Match each fake apology to the dodge it's doing.","pairs":[{"left":"\"Sorry you feel that way\"","right":"Blames your reaction"},{"left":"\"Sorry, but you started it\"","right":"Shifts the blame"},{"left":"\"Fine, I'm sorry, okay?\"","right":"Resents apologising"},{"left":"\"I'm sorry if anything happened\"","right":"Denies it happened"},{"left":"\"I said sorry, drop it\"","right":"Skips the repair"}],"relearn":"A real apology owns what you did and names change; these dodge by blaming, denying or rushing past it.","persona":"any","source":"apology"},
  {"id":"rr-1054","cat":"fight-right","type":"match","hook":"Match each green move to the repair skill it shows.","pairs":[{"left":"\"I felt hurt when...\"","right":"Soft start-up"},{"left":"\"You're right, that was me\"","right":"Taking responsibility"},{"left":"\"Let's pause, talk at 8\"","right":"Healthy break"},{"left":"\"Thank you for hearing me\"","right":"Appreciation"},{"left":"\"Can we try that again?\"","right":"Repair attempt"}],"relearn":"Soft start-ups, owning your part, timed breaks, appreciation and 'try again' are the repair skills.","persona":"any","source":"repair skills"},
  {"id":"rr-1055","cat":"fight-right","type":"match","hook":"Match each conflict situation to a steady next step.","pairs":[{"left":"You snapped unfairly","right":"Apologise and own it"},{"left":"You're flooded","right":"Ask for a short break"},{"left":"They're stonewalling","right":"Offer a soft door back"},{"left":"Old grievances creep in","right":"Bring it back to one issue"},{"left":"Things feel cold after","right":"Make a repair attempt"}],"relearn":"Apologise when unfair, break when flooded, offer a door to a shut-down partner, stay on one issue, repair the cold.","persona":"any","source":"tools"},
  {"id":"rr-1056","cat":"fight-right","type":"match","hook":"Match each belief to the truer reframe.","pairs":[{"left":"\"Fighting means we're doomed\"","right":"How you repair is what counts"},{"left":"\"Winning is the point\"","right":"Understanding is the point"},{"left":"\"Silence teaches them\"","right":"A break with a return repairs"},{"left":"\"Apologising first means losing\"","right":"Repairing first is brave"},{"left":"\"Honesty excuses harshness\"","right":"Truth can be kind too"}],"relearn":"Repair beats no-conflict, understanding beats winning, breaks beat silence, repairing first is brave, truth can be kind.","persona":"any","source":"reframes"},
  {"id":"rr-1057","cat":"fight-right","type":"match","hook":"Match each 'I' opener to the need it names underneath.","pairs":[{"left":"\"I felt unheard\"","right":"A need to be listened to"},{"left":"\"I felt rushed\"","right":"A need for more time"},{"left":"\"I felt left out\"","right":"A need to be included"},{"left":"\"I felt criticised\"","right":"A need for respect"},{"left":"\"I felt alone in this\"","right":"A need for support"}],"relearn":"Under each 'I felt' is a real need; naming it lets a partner actually meet it.","persona":"any","source":"needs under conflict"},
  {"id":"rr-1080","cat":"leaving-safely","type":"strike-rewrite","hook":"\"If I just love them harder, they'll stop controlling me.\"","myth":{"un":"I can love them out of it.","re":"You can't love someone out of controlling you; their behaviour isn't yours to fix.","why":"Change is the controller's job, not your love's reward."},"relearn":"You can't love someone out of controlling you; it isn't yours to fix.","persona":"any","source":"not yours to fix"},
  {"id":"rr-1081","cat":"leaving-safely","type":"strike-rewrite","hook":"\"It wasn't that bad. There were good days too.\"","myth":{"un":"The good days mean it wasn't abuse.","re":"Good days don't cancel control; the cycle of good and bad is part of how it traps you.","why":"Intermittent kindness is what keeps people hoping and staying."},"relearn":"Good days don't cancel control; the good-bad cycle is part of the trap.","persona":"any","source":"the good days"},
  {"id":"rr-1082","cat":"leaving-safely","type":"strike-rewrite","hook":"\"I have nowhere to go, so I have to stay.\"","myth":{"un":"No money or place means I'm stuck.","re":"There are routes even with no money: a trusted person, a women's helpline, a safe place can be arranged.","why":"Support exists offline; you don't have to solve it alone first."},"relearn":"Even with no money there are routes: a trusted person and the helplines.","persona":"Meena","source":"i'm stuck"},
  {"id":"rr-1083","cat":"leaving-safely","type":"strike-rewrite","hook":"\"He only gets like that because I provoke him.\"","myth":{"un":"I cause his temper, so it's on me.","re":"No one's actions force another adult to control or threaten; that choice is fully theirs.","why":"Abuse is never caused by the person being abused."},"relearn":"No one provokes another adult into controlling or threatening them.","persona":"any","source":"i provoke it"},
  {"id":"rr-1084","cat":"leaving-safely","type":"strike-rewrite","hook":"\"Men can't really be abused. I should just handle it.\"","myth":{"un":"A man can't be a victim of control.","re":"Anyone of any gender can be controlled or abused, and deserves to be believed and supported.","why":"Abuse isn't a one-gender story; help is for everyone."},"relearn":"Anyone of any gender can be abused and deserves support.","persona":"Rohan","source":"men too"},
  {"id":"rr-1085","cat":"leaving-safely","type":"strike-rewrite","hook":"\"I waited too long, so it's too late to leave now.\"","myth":{"un":"I left it too long to get out.","re":"It's never too late to leave; the right time to start a safe plan is whenever you're ready.","why":"How long you stayed doesn't lock the door: control is built to delay people."},"relearn":"It's never too late to leave; you can start a safe plan whenever you're ready.","persona":"any","source":"too late"},
  {"id":"rr-1086","cat":"leaving-safely","type":"strike-rewrite","hook":"\"If I leave, I'll have ruined the family's name.\"","myth":{"un":"Leaving shames my family.","re":"Your safety matters more than appearances; staying in harm to protect a reputation isn't your duty.","why":"No one is owed your wellbeing for the sake of image."},"relearn":"Your safety matters more than reputation; harm isn't yours to absorb for image.","persona":"Aarti","source":"family name"},
  {"id":"rr-1087","cat":"leaving-safely","type":"reflect","hook":"Lensy: noticing it's not okay is the first brave step, long before you act. Sit with that?","prompt":"What do you think?","options":["Yes","I noticed","First step"],"affirm":"Naming that something's wrong is real courage; you don't have to have a plan yet to be brave.","relearn":"Naming that something is wrong is the first brave step.","persona":"any","source":"naming it"},
  {"id":"rr-1088","cat":"leaving-safely","type":"reflect","hook":"Lensy: the fear you feel about leaving is information, not weakness. Hear that?","prompt":"What do you think?","options":["Yes","It's information","Not weakness"],"affirm":"Fear about leaving often means your gut has read real danger; that's worth planning around, not ignoring.","relearn":"Fear about leaving is information about real risk, not weakness.","persona":"any","source":"fear is data"},
  {"id":"rr-1089","cat":"leaving-safely","type":"reflect","hook":"Lensy: you don't owe anyone the years of your life to fix them. Let that land?","prompt":"What do you think?","options":["Yes","I don't owe that","It's not mine to fix"],"affirm":"You're not responsible for fixing an adult who controls you; your life isn't a repair project.","relearn":"You don't owe anyone your life to fix their behaviour.","persona":"any","source":"not a project"},
  {"id":"rr-1090","cat":"leaving-safely","type":"reflect","hook":"Lensy: the version of you that wanted out has been right all along. Trust her?","prompt":"What do you think?","options":["Yes","She was right","I trust her"],"affirm":"The part of you that's been saying 'this isn't okay' has been telling the truth; you can trust it.","relearn":"The part of you that wants out has been telling you the truth.","persona":"any","source":"trust yourself"},
  {"id":"rr-1091","cat":"leaving-safely","type":"reflect","hook":"Lensy: you can love someone and still be right to leave them. Both can be true. Okay?","prompt":"What do you think?","options":["Yes","Both true","I can still love and leave"],"affirm":"Leaving doesn't mean you never cared; you can grieve someone and still choose your safety.","relearn":"You can love someone and still be right to leave them.","persona":"any","source":"love and leave"},
  {"id":"rr-1092","cat":"leaving-safely","type":"reflect","hook":"Lensy: asking for help to get out is strength, not failure. Believe that for yourself?","prompt":"What do you think?","options":["Yes","It's strength","I can ask"],"affirm":"Reaching for help when you're unsafe is one of the strongest things you can do, not a weakness.","relearn":"Asking for help to leave safely is strength, not weakness.","persona":"Deepak","source":"asking is strength"},
  {"id":"rr-1093","cat":"leaving-safely","type":"reflect","hook":"Lensy: your future self is already proud of you for thinking about this. Feel that?","prompt":"What do you think?","options":["Yes","She's proud","I'm starting"],"affirm":"Even reading this is a step toward freedom; the you on the other side is grateful you began.","relearn":"Even thinking about getting out is a real step toward freedom.","persona":"any","source":"future self"},
  {"id":"rr-1094","cat":"leaving-safely","type":"reflect","hook":"Lensy: you are allowed to want a life that isn't built around managing someone's moods. Yes?","prompt":"What do you think?","options":["Yes","I'm allowed","I want that life"],"affirm":"Wanting calm, space and a life of your own isn't selfish; it's the most ordinary, fair thing to want.","relearn":"You're allowed to want a life not built around managing someone's moods.","persona":"any","source":"allowed to want"},
  {"id":"rr-1095","cat":"leaving-safely","type":"reflect","hook":"Lensy: the friends control pushed away will mostly be glad to hear from you. Let that in?","prompt":"What do you think?","options":["Yes","They'll be glad","I can reach out"],"affirm":"Isolation feels permanent but isn't; most people you were cut off from will welcome you back.","relearn":"The people control isolated you from will mostly welcome you back.","persona":"Zoya","source":"reconnecting"},
  {"id":"rr-1096","cat":"leaving-safely","type":"reflect","hook":"Lensy: leaving rarely happens in one clean move. A few tries is normal, not failure. Okay?","prompt":"What do you think?","options":["Yes","A few tries is normal","I keep going"],"affirm":"Many people leave and return more than once before it sticks; each attempt is practice, not failure.","relearn":"Leaving often takes a few attempts; that's normal, not failure.","persona":"any","source":"more than once"},
  {"id":"rr-1097","cat":"leaving-safely","type":"reflect","hook":"Lensy: the quiet relief you feel imagining being out. That's your answer. Notice it?","prompt":"What do you think?","options":["Yes","That's relief","I noticed"],"affirm":"If imagining the relationship over brings relief rather than loss, your body has already answered.","relearn":"Relief at imagining it over is your gut already answering.","persona":"any","source":"the relief test"},
  {"id":"rr-1098","cat":"leaving-safely","type":"reflect","hook":"Lensy: you don't need everyone to understand your choice to leave for it to be right. Yes?","prompt":"What do you think?","options":["Yes","I don't need approval","It's still right"],"affirm":"Your safety doesn't need a committee's approval; a choice can be right even if others don't get it.","relearn":"You don't need everyone's approval for leaving to be right.","persona":"any","source":"no approval needed"},
  {"id":"rr-1099","cat":"leaving-safely","type":"reflect","hook":"Lensy: the calm after you finally leave is not boredom. It's safety. Let yourself feel it?","prompt":"What do you think?","options":["Yes","It's safety","I can rest"],"affirm":"After chaos, calm can feel strange or empty at first; that quiet is your nervous system finally resting.","relearn":"The calm after leaving is safety, not emptiness.","persona":"any","source":"the calm"},
  {"id":"rr-1100","cat":"leaving-safely","type":"reflect","hook":"Lensy: you can set the pace of your own leaving. No one gets to rush you. Okay?","prompt":"What do you think?","options":["Yes","My pace","No rushing"],"affirm":"You decide when and how you leave; a safe plan can be slow and quiet, and still be the right one.","relearn":"You set the pace of your own leaving; a slow, safe plan is valid.","persona":"any","source":"your pace"},
  {"id":"rr-1101","cat":"leaving-safely","type":"reflect","hook":"Lensy: a partner's threat to harm themselves if you leave is pressure, not your responsibility. Hear it?","prompt":"What do you think?","options":["Yes","It's pressure","Not my responsibility"],"affirm":"You're not responsible for another adult's choices; route that threat to help and still protect yourself.","relearn":"A 'I'll hurt myself if you leave' threat is pressure, not your responsibility.","persona":"any","source":"the threat-to-self"},
  {"id":"rr-1102","cat":"leaving-safely","type":"branch","persona":"Meena","source":"financial control","hook":"You want to leave Raju, but he takes your wages and checks your phone every night.","steps":[{"prompt":"You have no money of your own and no private phone. What do you do first?","options":[{"text":"Quietly ask a trusted person to keep some cash for you","then":"Your co-worker Sunita agrees and keeps a small envelope for you.","best":true},{"text":"Wait until you've secretly saved enough on your own","then":"Weeks pass. Raju counts the money, and almost nothing is left over."},{"text":"Tell Raju you want your own money from now on","then":"He laughs, then starts checking your wages more closely."},{"text":"Decide leaving is impossible without money","then":"The thought makes you feel stuck, and you stop planning."}],"why":"A small lifeline outside his control is a real first step. You don't have to do it alone."},{"prompt":"You want a helpline number Raju won't find on your phone. What do you do?","options":[{"text":"Learn 181 by heart instead of saving it","then":"You repeat it on the walk to work. Now it's yours, and he can't see it.","best":true},{"text":"Save it in your phone, since he rarely looks at contacts","then":"Two nights later he scrolls your contacts and asks who it is."},{"text":"Write it on a slip and keep it in your purse","then":"That night he counts the wages in your purse, and the slip is right beside them."},{"text":"Skip it. Helplines are for emergencies, not this","then":"You leave it. The number isn't there if things get worse."}],"why":"A number you know by heart can't be found or taken away. 181 is there for you too."},{"prompt":"Weeks later, you start thinking about where you'd go. What do you do?","options":[{"text":"Call 181 from a friend's phone to ask about safe places","then":"The woman on the line speaks slowly and tells you what's possible nearby.","best":true},{"text":"Plan to just walk out and find a room somehow","then":"Without a place lined up, the first night could leave you nowhere safe."},{"text":"Ask Raju's kind cousin to help you find a place","then":"She means well, but she tells Raju's mother by evening."},{"text":"Wait until you've saved enough for a room of your own","then":"Months pass. With Raju taking your wages, the savings barely grow."}],"why":"Helplines like 181 can point you to safe places, from a phone he doesn't see."},{"prompt":"One evening Raju shouts about money, and you feel afraid. What do you do?","options":[{"text":"Get somewhere safe, and call 112 if you're in danger","then":"You go to your neighbour's. She lets you in and sits with you.","best":true},{"text":"Tell yourself it's your fault for upsetting him","then":"The fear stays, and so does the blame, all night."},{"text":"Argue back so he knows you won't be pushed around","then":"His shouting gets louder, and you feel less safe, not more."},{"text":"Plan to tell his mother so she can control him","then":"His mother says men get angry sometimes and you must be patient."}],"why":"Your safety comes first, and his anger is never your fault. 112 is there for danger."}],"debrief":"Money and phone control are common tactics; a trusted ally is a first step.","relearn":"If money and phone are controlled, ask a trusted person for a lifeline."},
  {"id":"rr-1103","cat":"leaving-safely","type":"branch","persona":"any","source":"prep before announce","hook":"You're ready to leave Sameer, whose temper scares you, and you want it to be safe.","steps":[{"prompt":"You're tempted to tell him tonight and get it over with. What do you do?","options":[{"text":"First line up a safe place, a person and your papers","then":"Your friend Priya says you can stay with her, and keeps your papers.","best":true},{"text":"Tell him tonight, and figure out the rest after","then":"He goes quiet, then starts asking where you'll go and who knows."},{"text":"Tell his friends first so he hears it gently","then":"By morning he knows, and he's angry you told others first."},{"text":"Pack a bag in plain sight so he gets the message","then":"He sees the bag. The questions start, and so does his temper."}],"why":"Risk can rise the moment you announce it. Getting ready first keeps you safer."},{"prompt":"A few days later, you plan the day you'll actually go. What do you do?","options":[{"text":"Leave while he's out, with a friend beside you","then":"Your friend will come at ten, once he's left. You'll message him later.","best":true},{"text":"Meet him alone somewhere private to say goodbye","then":"Picturing being alone with him at that moment makes you uneasy."},{"text":"Ask his parents to help him take it calmly","then":"His parents call you, upset, and try to talk you out of it."},{"text":"Send him a long message now, before you've left","then":"He calls within minutes, and you're still at home."}],"why":"Going while he's out, with someone beside you, protects you at the riskiest moment."},{"prompt":"A friend asks what you'll do if he turns up angry afterwards. What do you do?","options":[{"text":"Note 181 and 112, and agree a code word with her","then":"You pick 'mango' as the word. She'll know to come or call.","best":true},{"text":"Say you'll handle him yourself if he turns up","then":"Your friend looks worried. \"You shouldn't have to.\""},{"text":"Say helplines would be overreacting","then":"She frowns. \"It's not overreacting to be ready.\""},{"text":"Say you'd call his brother to calm him down","then":"His brother means well, but he'd likely take Sameer's side."}],"why":"Knowing who to call, and having a friend on alert, means you won't face it alone."}],"debrief":"Risk rises around leaving, so quiet prep comes first; his temper is never your fault.","relearn":"Plan the safe place, the person and documents before you announce leaving."},
  {"id":"rr-1104","cat":"leaving-safely","type":"branch","persona":"any","source":"one time","hook":"Last week, Kartik hit you in an argument. Now he's in tears, with flowers and gifts.","steps":[{"prompt":"He swears it will never happen again. What do you do?","options":[{"text":"Treat it as a line crossed, and tell someone you trust","then":"You tell your sister. She holds your hand and says she's glad you told her.","best":true},{"text":"Tell yourself one time in anger doesn't count","then":"The gifts keep coming. You start watching his mood before you speak."},{"text":"Wonder what you said that set him off","then":"You replay the argument, looking for your mistake."},{"text":"Keep it to yourself so his family never finds out","then":"No one knows. The secret sits heavy in your chest."}],"why":"One act of violence is a line crossed, and it is never your fault."},{"prompt":"A friend who heard you two fought says Kartik is just a good guy with a temper. What do you do?","options":[{"text":"Tell her he hit you, and ask her to back you","then":"She goes still. \"That's not okay. What do you need from me?\"","best":true},{"text":"Agree. Maybe you're blowing it out of proportion","then":"The doubt grows. You start explaining it away to yourself too."},{"text":"Stop talking to anyone about it at all","then":"You feel more alone with it now."},{"text":"Ask her to talk to him and sort it out","then":"She talks to him. He's angry that you've been talking about him."}],"why":"Violence isn't a phase or a misunderstanding. You deserve people who back you."},{"prompt":"Two weeks on, things seem calm, but you can't forget the night he hit you. What do you do?","options":[{"text":"Start a quiet plan: a safe place, a person, your papers","then":"A friend says her door is open. You start a list in your head.","best":true},{"text":"Believe that if you love him enough, he won't do it again","then":"You pour everything into keeping him happy, and watch every word."},{"text":"Tell him you'll leave if it ever happens again","then":"He promises it won't. The warning becomes just another promise."},{"text":"Confront him and demand he gets help for his anger","then":"He shouts that you're the problem, and storms out."}],"why":"Don't wait for it to happen again. A quiet plan, with support and 181 or 112 if needed, keeps you safer."},{"prompt":"Kartik's mother calls and asks you to forgive him for the family's sake. What do you do?","options":[{"text":"Say you're keeping yourself safe, and end the call","then":"She's upset. You put the phone down and call your friend.","best":true},{"text":"Tell yourself a good partner would forgive him","then":"The thought puts his temper on you to manage."},{"text":"Explain everything so she'll take your side","then":"She listens, then says every couple has fights."},{"text":"Ask her to make Kartik see a counsellor for you","then":"She promises to try. Nothing changes at home."}],"why":"Your safety comes before anyone's comfort, and his violence is never yours to fix."}],"debrief":"The apology-and-gifts phase is part of the cycle, and the violence is never your fault.","relearn":"One act of violence is a line crossed: start a safe plan, and don't wait for a pattern."},
  {"id":"rr-1105","cat":"leaving-safely","type":"branch","persona":"any","source":"shared lease","hook":"You want to leave Mohit, who controls you, but both your names are on the flat's lease.","steps":[{"prompt":"You're tempted to pack up and go this weekend. What do you do first?","options":[{"text":"Get advice on the lease before you move out","then":"Your cousin, who's a lawyer, talks you through your options.","best":true},{"text":"Just walk out and deal with the lease later","then":"You start packing, then realise any rent he skips could still fall on you."},{"text":"Ask Mohit to agree to take your name off","then":"He refuses, and starts asking why you want it off."},{"text":"Decide you're stuck until the lease runs out","then":"Eight more months feels endless. You stop planning."}],"why":"Advice first stops the lease being used to hold you. If you're ever in danger, leave first and call 112."},{"prompt":"Days later, Mohit checks your phone again, and you know you can't wait out the lease. How do you handle the landlord?","options":[{"text":"Tell the landlord in writing once you've moved out","then":"You draft it on paper, away from your phone, ready to send from your new place.","best":true},{"text":"Ask Mohit to come with you to see the landlord","then":"Mohit says he'll handle it, and you're left out of the call."},{"text":"Message the landlord now about everything Mohit does","then":"The landlord replies, awkward, and mentions it to Mohit."},{"text":"Leave the landlord out of it. It's not his business","then":"The lease stays as it is, with your name tied to the flat."}],"why":"Telling the landlord once you're out keeps word of your plan from reaching Mohit early."},{"prompt":"A college friend asks how she can help with the move. What do you do?","options":[{"text":"Ask her to be there on the day, while Mohit's out","then":"She keeps Saturday free and borrows her brother's car.","best":true},{"text":"Say you can manage the boxes alone","then":"She lets it go. On the day, you're on your own if he comes back."},{"text":"Ask her to come with you to tell Mohit first","then":"She agrees, nervous. Telling him face to face feels risky even with her."},{"text":"Say you'd rather not drag her into your mess","then":"She looks hurt. \"I want to help, though.\""}],"why":"Having someone with you on moving day keeps you safer and less alone."}],"debrief":"A shared lease is solvable with a word of advice first; his control is never your fault.","relearn":"With a shared lease, get advice before moving so housing doesn't trap you."},
  {"id":"rr-1106","cat":"leaving-safely","type":"branch","persona":"Ananya","source":"unavoidable contact","hook":"You've left Varun after months of his control, but you share three classes.","steps":[{"prompt":"On Monday, he's waiting by the classroom door. What do you do?","options":[{"text":"Walk in with a friend and sit away from him","then":"Your friend Meher walks in beside you. Varun watches, but doesn't follow.","best":true},{"text":"Stop and let him talk, so it isn't awkward","then":"He starts on how much he misses you. The room fills up around you."},{"text":"Tell him loudly, in front of everyone, to stay away","then":"Heads turn. Varun smirks, and you feel more exposed."},{"text":"Tell yourself you're overreacting. It's just a door","then":"You walk past him alone. He falls into step beside you."}],"why":"Brief, public and with a friend is the safe shape for an overlap you can't avoid."},{"prompt":"Later that week, Varun asks you to meet alone to 'clear the air'. What do you do?","options":[{"text":"Say no. If it needs saying, it can be in public","then":"He sighs loudly, but lets it drop for now.","best":true},{"text":"Agree, since closure might help you both move on","then":"He picks a quiet spot, and the old pressure starts the moment you sit."},{"text":"Say yes, but secretly bring a friend along","then":"He's annoyed to see her and spends the time arguing about it."},{"text":"Ask his friends to tell him to back off","then":"They tell him you're being dramatic. Now they avoid you too."}],"why":"Alone is where pressure restarts. Keeping contact public keeps you safe."},{"prompt":"Your professor puts you and Varun in the same project group. What do you do?","options":[{"text":"Ask the professor privately to move you","then":"She nods and moves you to another group the next day.","best":true},{"text":"Tell yourself you have to put up with it for your grade","then":"At every meeting, he sits beside you and talks about 'us'."},{"text":"Tell the group everything so they're on your side","then":"The story spreads fast. Varun tells his version too."},{"text":"Stay in the group, but only talk over messages","then":"He uses the project chat to message you late at night."}],"why":"Asking quietly for a change is allowed. Your safety matters more than any group project."},{"prompt":"Your friend asks how she can help this term. What do you do?","options":[{"text":"Share your timetable so she can walk with you","then":"She sets reminders. You're rarely alone near his classes now.","best":true},{"text":"Say you're fine and don't want to be a burden","then":"She nods, unsure. You carry the worry alone."},{"text":"Ask her to keep an eye on Varun's social media","then":"She checks it daily. It keeps him at the centre of both your lives."},{"text":"Ask her to confront him on your behalf","then":"She marches over. Varun laughs it off and turns colder towards you."}],"why":"A friend who knows your schedule makes the overlap safer. Needing that is not your fault."}],"debrief":"When you can't avoid an ex, public, brief and witnessed is the safe shape.","relearn":"Unavoidable contact: keep it brief, public, and never alone."},
  {"id":"rr-1107","cat":"leaving-safely","type":"branch","persona":"any","source":"following","hook":"Since you ended things with Simran, she keeps turning up at your canteen and your gym.","steps":[{"prompt":"Today she's outside your hostel gate again. What do you do?","options":[{"text":"Stay inside, note the time and place, and tell a friend","then":"Your friend comes down to walk with you, and you start a notes file.","best":true},{"text":"Assume she just wants to talk, and go out to her","then":"She says she'll keep coming till you give her another chance."},{"text":"Take it as a sign of how much she still cares about you","then":"She comes back the next day, and the next."},{"text":"Say nothing to anyone. It's too embarrassing","then":"No one knows. You start checking the gate before you go out."}],"why":"Turning up uninvited is following, not romance. A record and a friend are the start."},{"prompt":"A week later, she's turned up four more times. What do you do?","options":[{"text":"Tell your warden and a friend, with dates and times","then":"The warden takes it seriously and tells the gate staff.","best":true},{"text":"Message her to ask her nicely to stop","then":"She replies at once: \"I just want to see you.\" She's back the next day."},{"text":"Decide it's your fault for ending it badly","then":"The guilt grows. You start wondering if you owe her a talk."},{"text":"Post about it online so she's shamed into stopping","then":"The post spreads. She messages, furious, and turns up again."}],"why":"Following you is serious. Telling people with authority adds protection."},{"prompt":"One evening she follows you from the bus stop, and you feel afraid. What do you do?","options":[{"text":"Go into a busy shop, and call 112 if you feel in danger","then":"The shopkeeper lets you wait inside. Your friend comes to walk you back.","best":true},{"text":"Turn and confront her on the quiet road","then":"Your voice sounds small on the empty road. She steps closer, not away."},{"text":"Tell yourself you're overreacting. She's harmless","then":"She's still behind you when you reach the gate, and your heart is pounding."},{"text":"Call her mother to come and get her","then":"Her mother says Simran is heartbroken and asks you to be kinder."}],"why":"When you feel afraid, getting to people and calling 112 is exactly what help is for."},{"prompt":"Your friend asks what you want to do about it now. What do you do?","options":[{"text":"Report it formally, with the dates written down","then":"Your friend comes with you. Saying it all out loud, you feel steadier.","best":true},{"text":"Let it go and hope she gets bored","then":"Things go quiet for a week. Then she's back at the gym."},{"text":"Believe one last talk with her will make it stop","then":"She takes the meeting as hope, and turns up even more."},{"text":"Decide writing it down is petty, and skip it","then":"Without a record, it's harder to show how often it happened."}],"why":"A record and a formal report help others step in, and it's never your fault."}],"debrief":"Following you after a breakup is a warning sign, and it is never your fault.","relearn":"Showing up uninvited is serious: document it, tell people, call 112 if in danger."},
  {"id":"rr-1108","cat":"leaving-safely","type":"branch","persona":"any","source":"smear campaign","hook":"Since your breakup, Aman has been sending your friends and cousins lies about you.","steps":[{"prompt":"Your cousin forwards you one of his messages. What do you do?","options":[{"text":"Tell your people your side calmly, once","then":"Your cousin replies, \"Thanks for telling me. I believe you.\"","best":true},{"text":"Post a long public reply calling out his lies","then":"He screenshots it and shares it everywhere, with his own spin."},{"text":"Message Aman and demand he stop lying","then":"He replies with a laughing emoji and keeps going."},{"text":"Say nothing. People who know you won't believe him","then":"A few people start going quiet around you."}],"why":"A calm word once keeps your dignity. A public fight hands him the chaos he wants."},{"prompt":"A few friends still seem unsure of you. What do you do?","options":[{"text":"Let them decide, and lean on the ones who stay","then":"It stings, but the people who stay feel closer than ever.","best":true},{"text":"Keep explaining until every one of them believes you","then":"Each explanation takes hours, and some still aren't convinced."},{"text":"Cut off anyone who hasn't taken your side yet","then":"Your circle shrinks fast, just as he'd want."},{"text":"Wonder if you really were as bad as he says","then":"The doubt creeps in, and you start replaying everything."}],"why":"Those who matter will decide for themselves. Your energy is better spent on them."},{"prompt":"A month on, a friend asks how you're really doing. What do you do?","options":[{"text":"Tell her honestly it's been hard, and ask to meet up","then":"She's at your door that evening with snacks.","best":true},{"text":"Say you're totally fine and change the subject","then":"She lets it go. You go home feeling alone with it."},{"text":"Spend the whole time going over every one of Aman's lies","then":"By the end you're both drained, and he's still the topic."},{"text":"Ask her to screenshot Aman's chats for you","then":"She hesitates. \"I'd rather not get into that.\""}],"why":"Leaning on the people who stayed is how you rebuild after a smear."}],"debrief":"Turning your circle against you is a control tactic, and it's never your fault.","relearn":"Answer a smear calmly once; don’t get drawn into a public war."},
  {"id":"rr-1109","cat":"leaving-safely","type":"branch","persona":"any","source":"image threats","hook":"Pooja says she'll share your private photos if you leave her.","steps":[{"prompt":"The threat arrives by text, late at night. What do you do?","options":[{"text":"Screenshot the threat and save it somewhere safe","then":"The screenshots are saved. Your hands shake, but you have proof.","best":true},{"text":"Delete it so you don't have to look at it again","then":"It's gone from your phone, but not from your mind."},{"text":"Decide staying is the only way to keep the photos safe","then":"The threat hangs over you, and you lie awake feeling trapped."},{"text":"Blame yourself for ever sharing the photos","then":"Shame keeps you from telling anyone at all."}],"why":"Saving the threat as proof is the first step to stopping it."},{"prompt":"The next morning, you feel too ashamed to tell anyone. What do you do?","options":[{"text":"Tell one trusted person. The shame is hers, not yours","then":"Your friend listens and says: \"This is a crime, and it's not on you.\"","best":true},{"text":"Keep it secret and try to handle it yourself","then":"Alone, every buzz of your phone makes your stomach drop."},{"text":"Ask Pooja's friends to talk her out of it","then":"Pooja hears you've told people and sends another threat."},{"text":"Search online for ways to wipe photos from her phone","then":"You find nothing that works, and it's 3 a.m."}],"why":"Sharing photos was trust, not a mistake. The threat is on her, never your fault."},{"prompt":"Two days later, another threat comes, and you read that it can be reported. What do you do?","options":[{"text":"Call the cybercrime helpline 1930 and report it","then":"The person on the line takes your details and explains the next steps.","best":true},{"text":"Wait, and report it only if she actually posts","then":"You wait, and the threats keep coming."},{"text":"Decide it's too embarrassing to report","then":"The threats go on, and so does the fear."},{"text":"Threaten her back with something about her","then":"She laughs it off, and the messages get nastier."}],"why":"Threatening to share private images is a crime. Reporting it is the route, not staying."},{"prompt":"Pooja messages, softer now, saying she didn't mean it and asking to forget it all. What do you do?","options":[{"text":"Don't reply. Screenshot it, and report it to 1930","then":"It's on record now. You block her number, and your hands steady.","best":true},{"text":"Reply kindly, since she seems sorry now","then":"She replies at once, and the threats return the moment you pull away."},{"text":"Threaten to report her, so she gets scared","then":"She panics and sends a flood of angry messages."},{"text":"Wonder if you overreacted by taking it so seriously","then":"The doubt nags, even though the threat was real."}],"why":"A softer message after a threat is part of the pattern. Your safety comes first."}],"debrief":"Image-based threats are abuse and a crime; reporting is the route, not staying.","relearn":"Threatening to share private photos is a crime: save proof and report it to cybercrime 1930."},
  {"id":"rr-1110","cat":"leaving-safely","type":"branch","persona":"any","source":"the wavering","hook":"You keep almost leaving Siddharth, who controls your time, then talking yourself out of it.","steps":[{"prompt":"After another bad week, you feel clear, for tonight at least. What do you do?","options":[{"text":"Write down what's made you want to leave","then":"The list fills a page. Seeing it in your own words feels solid.","best":true},{"text":"Trust you'll remember how bad it was when it matters","then":"By Sunday he's sweet again, and the week feels blurry."},{"text":"Tell him how you feel, hoping he'll change","then":"He apologises and promises. The clear feeling fades."},{"text":"Decide you're just too emotional to think straight","then":"You push the clear feeling away as drama."}],"why":"Control fogs memory on the hard days. Your own words keep your clarity close."},{"prompt":"A few days on, Siddharth is sweet again, and doubt creeps in. What do you do?","options":[{"text":"Talk to a friend who's seen what's been happening","then":"She reminds you of what you told her last month, word for word.","best":true},{"text":"Tell yourself the sweet days prove it's fine now","then":"You relax. A week later, he's controlling your time again."},{"text":"Blame yourself for doubting him in the first place","then":"You apologise to him for nothing in particular."},{"text":"Wait and see which version of him lasts","then":"The weeks pass the same way: sweet, then tight again."}],"why":"Someone who's seen the pattern can hold your clarity when you can't."},{"prompt":"A friend asks what would make it easier to follow through. What do you do?","options":[{"text":"Plan it with her: a place, a date, your reasons","then":"She writes the date in her calendar. It feels real now.","best":true},{"text":"Say you'll leave when you feel completely sure","then":"Sure never quite comes. The doubts always find a way in."},{"text":"Say you'll leave the moment he does something big","then":"Small things keep piling up, none of them 'big enough'."},{"text":"Ask her to decide for you, so you can't back out","then":"She hesitates. \"I can help, but it has to be your decision.\""}],"why":"A plan with a friend turns a wavering wish into steps, and wavering is never your fault."}],"debrief":"Doubt and forgetting are part of the trap, never your fault; your written reasons are an anchor back.","relearn":"Write down your reasons to leave, to read on the days you waver."},
  {"id":"rr-1111","cat":"leaving-safely","type":"branch","persona":"Zoya","source":"outing threat","hook":"Mehr knows you're not out at home, and says she'll tell your family if you leave her.","steps":[{"prompt":"Her threat keeps you up all night. What do you do the next day?","options":[{"text":"Talk to a friend from your chosen family who gets it","then":"Tara listens and says: \"You're not alone in this. We'll figure it out.\"","best":true},{"text":"Decide you can't get help without coming out to everyone","then":"The thought traps you, and you stay scared and alone with it."},{"text":"Keep it to yourself so no one else ever finds out","then":"The secret sits heavy, and Mehr's threat feels bigger alone."},{"text":"Wonder if you deserve this for hiding who you are","then":"The shame piles on top of the fear."}],"why":"Threatening to out you is control. People who get the stakes can help, and it's never your fault."},{"prompt":"Online, you read advice to come out at home now, so Mehr has nothing to threaten. What do you do?","options":[{"text":"Decide you'll come out on your own timeline, not hers","then":"You close the page. When and whether stays your call.","best":true},{"text":"Take the advice, and plan to tell your parents this weekend","then":"The weekend looms. It feels like Mehr is still choosing for you."},{"text":"Ask Mehr to agree on when you'll come out","then":"She laughs. It hands her even more control."},{"text":"Ask a cousin to sound out your parents first","then":"Your cousin hints at it over dinner, and your mother starts asking questions."}],"why":"When and whether you come out is yours to decide, never something forced by a threat."},{"prompt":"You want to end things with Mehr as safely as you can. What do you do?","options":[{"text":"Plan it with friends: where you'll be and who's with you","then":"Your friends pick a date and a place to be when you tell her.","best":true},{"text":"End it in a heated moment so it's over fast","then":"Mehr's anger spikes, and she starts typing a message to your mother."},{"text":"Believe that if you keep her happy, she'll drop the threat","then":"Nothing is forgotten. She brings it up whenever you pull away."},{"text":"Plan it all alone so no one else finds out","then":"It's a lot to hold alone, and you second-guess every step."}],"why":"Leaving with people around you who get the stakes keeps you safer, and less alone."},{"prompt":"One night, Mehr messages that she'll tell your mother tonight. What do you do?","options":[{"text":"Save the message and reach out to your friends right away","then":"Within minutes, two friends are on a call with you, planning what to say.","best":true},{"text":"Tell yourself it's your fault for not being out already","then":"The blame makes the fear even heavier."},{"text":"Delete the message and hope she's bluffing","then":"You don't know if she'll do it, and you've no proof if she does."},{"text":"Threaten to tell people about her in return","then":"She sends back a screenshot of a message she's typing to your mother."}],"why":"Outing as blackmail is abuse. Your people, and a record, are how you get through it."}],"debrief":"Threatening to out you is a control tactic, and it's never your fault.","relearn":"Outing-as-threat is abuse; lean on people who get the stakes, and keep your own timeline."},
  {"id":"rr-1112","cat":"leaving-safely","type":"branch","persona":"Aarti","source":"family pressure","hook":"Vivek's temper frightens you, but your family says leaving him would shame everyone.","steps":[{"prompt":"Your mother says every couple fights and you should adjust. What do you do?","options":[{"text":"Find one ally who'll put your safety first","then":"Your aunt Rekha listens, then says, \"Your safety matters more than gossip.\"","best":true},{"text":"Wonder if you're just not adjusting well enough","then":"You start blaming yourself each time Vivek's temper flares."},{"text":"Hide how scared you are so the family isn't shamed","then":"No one knows how afraid you are. It's lonely."},{"text":"Take her advice and try harder to keep Vivek calm","then":"You watch every word. His temper doesn't change."}],"why":"Even one person who puts your safety over appearances makes a real difference."},{"prompt":"A few days later, your father says people will talk if you leave. What do you do?","options":[{"text":"Say your safety matters more than what people say","then":"He goes quiet. It isn't agreement, but he's listening.","best":true},{"text":"Agree that the talk would be too much to bear","then":"The worry about gossip grows bigger than the fear of Vivek."},{"text":"Shout that he cares more about gossip than you","then":"He shouts back, and the talk ends with a slammed door."},{"text":"Ask Vivek's parents to step in and calm him down","then":"They say he's a good boy and you must be patient."}],"why":"Naming your safety plainly helps family see what's really at stake."},{"prompt":"One evening, Vivek's anger scares you again. What do you do?","options":[{"text":"Call someone you trust, and 181 or 112 if in danger","then":"Your cousin picks up at once and tells you to come over.","best":true},{"text":"Tell yourself it's normal, like your mother said","then":"The fear stays, and so does the pressure to stay quiet."},{"text":"Argue back so he knows you won't be pushed","then":"His anger climbs, and you feel less safe, not more."},{"text":"Post about it in the family group so they see","then":"The group explodes with opinions, and Vivek hears of it within minutes."}],"why":"Your safety comes first, and his temper is never your fault. 181 and 112 are there for you."}],"debrief":"Even one person who puts your safety over reputation makes leaving more possible.","relearn":"Find one ally who backs your safety over appearances."},
  {"id":"rr-1113","cat":"leaving-safely","type":"branch","persona":"any","source":"they've changed","hook":"Two months after you left Ishita, she messages to say she's changed and wants to meet.","steps":[{"prompt":"Her message is long, and it sounds sincere. What do you do?","options":[{"text":"Hold off meeting, and see if the change lasts for months","then":"You reply that you need space, and let the coming weeks show you who she is.","best":true},{"text":"Meet her soon. The message feels too genuine to ignore","then":"She replies within seconds, already picking a time and a place near your hostel."},{"text":"Say you'll think about it, and keep chatting meanwhile","then":"The messages flow daily again. By Friday she asks why you took so long to reply."},{"text":"Wonder if you gave up on her too fast","then":"You reread old chats hunting for your own mistakes, and doubt creeps in."}],"why":"Words cost nothing. Real change shows in steady action over time, watched from a safe distance."},{"prompt":"A week later, a mutual friend says: \"She's really different now. Give her a chance.\" What do you do?","options":[{"text":"Say you'll go by her actions over months, not by reports","then":"He shrugs. \"Fair enough. I just wanted you to know.\"","best":true},{"text":"Agree to a group hangout, since friends will be around","then":"At the hangout she sits next to you and keeps asking who you're texting."},{"text":"Wonder if everyone else sees something you're missing","then":"You start to feel like the unreasonable one, though nothing has actually changed."},{"text":"Tell him everything she did, so he takes your side","then":"He looks uneasy, and by the next day Ishita knows all you said."}],"why":"Her track record over time tells you more than anyone's reassurance."},{"prompt":"A month on, Ishita writes that if you really cared, you'd give her one more chance. What do you do?","options":[{"text":"Keep your distance, and talk it over with someone you trust","then":"Your sister reminds you how small your world felt back then. You don't reply.","best":true},{"text":"Take her pleading as proof she really has changed","then":"Her next message already asks where you are and who you're with."},{"text":"Meet her once, just to hear her out properly","then":"She's charming for an hour, then asks why you've been ignoring her."},{"text":"Feel you owe her an answer, since you did leave","then":"You write three drafts, each more apologetic than the last."}],"why":"Guilt isn't evidence. Distance keeps you safe while time shows the truth."}],"debrief":"Promises are easy. Only steady action over time is evidence, and how she treated you was never your fault.","relearn":"Judge change by lasting action over time, not one sweet message."},
  {"id":"rr-1114","cat":"leaving-safely","type":"branch","persona":"any","source":"their hard past","hook":"You plan to leave Nikhil, who controls who you see, but his hard childhood fills you with guilt.","steps":[{"prompt":"Tonight he talks about his father again, and your resolve wobbles. What do you do?","options":[{"text":"Feel for him, and keep your plan to leave","then":"It aches, but later you still text your friend the date you're going.","best":true},{"text":"Believe your love can heal what his past did","then":"You shelve the plan. His rules about who you see stay exactly the same."},{"text":"Get him to see a counsellor, then leave once he's started","then":"He agrees, then skips the first session. Your date to leave slides."},{"text":"Wonder if leaving makes you as cruel as his father","then":"The thought sticks, and you can't bring yourself to look at your plan."}],"why":"You can feel for his past and still leave. His healing isn't your job to stay for."},{"prompt":"A few days later, his sister calls: \"He's been through so much. Please don't give up on him.\" What do you do?","options":[{"text":"Hear her out, and keep your plans to yourself","then":"She sighs and says she'll pray for you both. Your plan stays safe.","best":true},{"text":"Explain all he's done, so she understands why you'd go","then":"She goes quiet, then says, \"I'll talk to him.\" He may now hear of your plan."},{"text":"Promise her you'll stay until he's doing better","then":"She thanks you warmly. You feel the promise tighten around you."},{"text":"Agree that his past means you should try harder","then":"You spend the week tiptoeing round his moods, feeling smaller."}],"why":"Control can get worse when someone leaves, so your plan stays with people you trust."},{"prompt":"Later that week, the guilt about his past hits hard at 2am. What do you do?","options":[{"text":"Call a friend who knows the whole story","then":"Priya stays on the line. \"You can care about him and still keep yourself safe.\"","best":true},{"text":"Message Nikhil to check he's okay","then":"He replies at once, asking why you're awake and who else you're talking to."},{"text":"Remind yourself that good people don't give up on others","then":"The guilt wins for tonight, and your plan feels further away."},{"text":"Keep it to yourself, since no one would understand","then":"You lie awake alone, replaying his stories until dawn."}],"why":"Guilt is heavy to carry alone. A friend helps you honour his past and still stay safe."}],"debrief":"Compassion for his past and your own safety can both be true. Leaving isn't cruel, and his control was never your fault.","relearn":"You can have compassion for their past and still leave; their healing isn't your job."},
  {"id":"rr-1115","cat":"leaving-safely","type":"branch","persona":"any","source":"leaving night","hook":"Tonight is the night you planned to leave Aryan, and your hands won't stop shaking.","steps":[{"prompt":"He's out until nine, and your bag is packed under the bed. What do you do first?","options":[{"text":"Follow the plan: call Sana, then head to her flat","then":"Sana picks up on the first ring. \"I'm here. Come now.\"","best":true},{"text":"Drop the plan and go wherever feels right in the moment","then":"You're out the door with no clear idea where to go, and your phone nearly dead."},{"text":"Wait for Aryan, and tell him face to face. He deserves that","then":"The minutes crawl toward nine, and toward a talk you can't control."},{"text":"Wonder if you're overreacting and he's not that bad","then":"You sit on the bed as the clock ticks on, the plan slipping out of reach."}],"why":"You made the plan calmly for this frightened moment. Trusting it is how past-you helps you now."},{"prompt":"Your phone buzzes. Aryan texts: \"Coming home early. Be there.\" What do you do?","options":[{"text":"Tell Sana he's coming early, and get to her place now","then":"Sana says she'll wait at her gate. Within minutes you're on your way.","best":true},{"text":"Reply that you're leaving him, so it's finally said","then":"Three missed calls land within a minute, then: \"Don't you dare.\""},{"text":"Head to your cousin's instead, since it's closer","then":"Halfway there, you remember Aryan has dropped you at your cousin's twice."},{"text":"Post on your story that you're safe and moving on","then":"Friends start reacting, and one of them is still close to Aryan."}],"why":"Control can spike when someone leaves. Moving fast, with your person in the loop, keeps you safest."},{"prompt":"By midnight, Aryan's angry texts turn into \"I'm sorry. Please, let's just talk.\" What do you do?","options":[{"text":"Leave it unanswered, and tell Sana how hard it's pulling","then":"Sana listens. \"That pull is normal. It doesn't mean go back.\"","best":true},{"text":"Reply that you'll talk tomorrow, once he's calmer","then":"He answers with a time and a place, and says to come alone."},{"text":"Believe the apology. He sounds like the old Aryan again","then":"You reread his texts and start doubting why you left at all."},{"text":"Think you caused this by leaving the way you did","then":"The guilt keeps you awake, rereading every message he sent."}],"why":"The pull back is strongest on the first night. Silence and support help you hold steady."},{"prompt":"The next morning you have college, and Aryan knows your timetable. What do you do?","options":[{"text":"Ask a friend to walk in with you, and save 181 and 112","then":"Sana walks you to class, and the numbers sit ready in your phone.","best":true},{"text":"Go alone as usual. He won't change your routine","then":"You spot Aryan's bike by the gate, and your heart starts pounding."},{"text":"Message Aryan asking him to stay away from college","then":"He replies within seconds: \"We need to talk. I'll be at the gate.\""},{"text":"Tell yourself he'd never make a scene in public","then":"You walk in alone, glancing over your shoulder all morning."}],"why":"The days after leaving need a plan too. Company and helplines keep you safer."}],"debrief":"The plan exists for this frightened moment. Follow it, lean on your people, and remember his control was never your fault.","relearn":"On leaving night, trust the calm plan: the call, the place, the bag."},
  {"id":"rr-1116","cat":"leaving-safely","type":"branch","persona":"Meena","source":"the neighbour","hook":"Lakshmi, a neighbour you barely know, heard Suresh shouting at you last night.","steps":[{"prompt":"Next morning at the water tap, she quietly asks if you're okay. What do you do?","options":[{"text":"Be honest, and ask if you can knock if it gets bad","then":"Lakshmi nods. \"Any time, day or night. I'm right here.\"","best":true},{"text":"Say it was just the TV. It's too shameful to share","then":"She looks unsure, then goes back inside. The chance passes."},{"text":"Tell her everything, and ask her to warn Suresh off","then":"Lakshmi looks worried. \"If I say something, won't he know you told?\""},{"text":"Say couples fight, and it's your job to keep him calm","then":"Lakshmi frowns but lets it go. You walk back feeling smaller."}],"why":"A neighbour who knows the truth can be a safe door, close by and fast."},{"prompt":"At work that week, a co-worker says there are free phone numbers for women in trouble. What do you do?","options":[{"text":"Ask for the numbers, and learn them by heart","then":"She says them slowly: 181, 1091, 112. You repeat them until they stick.","best":true},{"text":"Say those numbers are for bigger problems than yours","then":"She shrugs. You go home without them."},{"text":"Ask her to call for you if anything ever happens","then":"She agrees, but she lives across the city. The nights stay the same."},{"text":"Worry that calling would get Suresh into trouble","then":"You change the subject, and the worry rides home with you on the bus."}],"why":"Knowing 181, 1091 and 112 by heart puts help one call away, with nothing on your phone to find."},{"prompt":"One night the shouting starts again, and it frightens you more than before. What do you do?","options":[{"text":"Go to Lakshmi's door, and call 181 or 112 if in danger","then":"Lakshmi opens at once and pulls you inside, her phone already in hand.","best":true},{"text":"Shout back, so he knows you won't take it","then":"He gets louder, and the small room feels more dangerous."},{"text":"Tell yourself it's your fault for answering back earlier","then":"The blame sits on you, and the fear keeps growing."},{"text":"Call your mother back home to ask her to calm him","then":"She is far away and can only say, \"Try not to make him angry.\""}],"why":"A safe door nearby and 181 or 112 bring help fast. What he does is never your fault."}],"debrief":"A neighbour who knows something's wrong can be a fast, nearby exit.","relearn":"A concerned neighbour can be a nearby safe door: tell the truth and ask."},
  {"id":"rr-1117","cat":"leaving-safely","type":"branch","persona":"any","source":"holding no-contact","hook":"You blocked your ex Karan weeks ago, but his messages keep arriving from new numbers.","steps":[{"prompt":"Tonight another one lands: \"Just talk to me once.\" What do you do?","options":[{"text":"Screenshot it, block the number, and don't reply","then":"The folder of screenshots grows. This number goes quiet.","best":true},{"text":"Reply once, firmly, telling him to stop","then":"Within a minute he answers: \"Finally. I knew you'd talk to me.\""},{"text":"Block the number, and delete the message so it's gone","then":"It's off your phone, and so is the proof that he keeps doing this."},{"text":"Wonder if ignoring him makes you cruel","then":"You open the chat three times, and each time the guilt pulls harder."}],"why":"Silence gives him nothing to chase, and screenshots build a record if you need help later."},{"prompt":"A few days later, a friend says: \"Just talk to him. He'll stop if you do.\" What do you do?","options":[{"text":"Say it's no contact, and ask her not to carry messages","then":"She pauses. \"Okay. I didn't know it was this much.\"","best":true},{"text":"Agree to one call with her there, to end it for good","then":"Karan picks up on the first ring and won't let the call end."},{"text":"Wonder if she's right and you're dragging this out","then":"You start to feel like the problem, though he's the one chasing."},{"text":"Stop talking to her, in case she's on his side","then":"You lose a friend you could have leaned on, and feel more alone."}],"why":"No-contact works when it has no side doors, even friendly ones."},{"prompt":"Weeks later, a text says he's outside your hostel and won't leave until you come down. What do you do?","options":[{"text":"Stay inside, tell the warden, and call 112 if unsafe","then":"The warden sends a guard to the gate, and Karan is gone within minutes.","best":true},{"text":"Go down just once, so he'll finally leave you in peace","then":"He's by the gate, saying he isn't going anywhere without a real talk."},{"text":"Reply that you'll call the police unless he leaves","then":"He writes back: \"So you are reading my messages.\" He stays put."},{"text":"Think you must have led him on somehow","then":"The guilt makes it harder to ask anyone for help."}],"why":"When chasing becomes waiting outside, get real help fast. None of this is your fault."}],"debrief":"New numbers test the wall. No reply plus a record is strongest, and his chasing is never your fault.","relearn":"New-number messages: block, screenshot, don't reply. Silence holds the line."},
  {"id":"rr-1118","cat":"leaving-safely","type":"branch","persona":"any","source":"he seems nice","hook":"You tell your friend Nisha how Varun treats you in private. She says, \"But he seems so nice to everyone.\"","steps":[{"prompt":"Her words stay with you all evening. What do you do next?","options":[{"text":"Keep arguing with Nisha until she sees it","then":"Nisha gets defensive. An hour later you're drained and she still isn't sure."},{"text":"Trust what you lived, and tell someone who'll listen","then":"You message an old school friend. She hears it all. \"I believe you,\" she says.","best":true},{"text":"Wonder if you're exaggerating, since people like him","then":"You replay every fight, hunting for the version where it was your fault."},{"text":"Decide not to bring it up with anyone again","then":"The next time Varun checks your phone, there's no one you feel you can tell."}],"why":"You don't have to win the argument. Find someone who believes you instead."},{"prompt":"At a friend's birthday, Varun charms everyone, then goes cold and sharp with you on the way home. What do you make of it?","options":[{"text":"He was warm tonight, so maybe it's getting better","then":"You hold on to the good evening, and the cold ride home slips out of view."},{"text":"Maybe I'm the one who brings out his cold side","then":"You spend the night planning how to be easier to be around."},{"text":"Public charm and private control can both be real","then":"The switch stops confusing you. You note down what he said on the ride.","best":true},{"text":"I'll wait until others see it, so I have proof","then":"You start waiting for him to slip in public. He never does."}],"why":"Many controlling people are charming in public. Both are real, and your experience counts."},{"prompt":"A few days later, your sister Meera asks why you've seemed so tense lately. What do you do?","options":[{"text":"Say it's just college stress","then":"She lets it go, and you go to bed feeling more alone than before."},{"text":"Tell her, and ask her to confront Varun for you","then":"Meera wants to call him right now. You worry it will make things worse for you."},{"text":"Tell her it's probably you being too sensitive","then":"Meera frowns and says that isn't what she's hearing. You change the subject."},{"text":"Tell her the truth and ask her to stand by you","then":"Meera hugs you. \"I believe you. What do you need from me?\"","best":true}],"why":"Someone close who believes you is real support. It's never your fault, and you need no proof."}],"debrief":"Public charm and private control often go together. Trust your experience and find people who believe you.","relearn":"Public charm doesn't override your experience: find someone who believes you."},
  {"id":"rr-1119","cat":"leaving-safely","type":"branch","persona":"any","source":"the lonely urge","hook":"A week after leaving your controlling ex, Sameer, the loneliness at night is loud.","steps":[{"prompt":"It's midnight and your thumb hovers over his name. What do you do?","options":[{"text":"Send him one message, just to feel less alone","then":"He replies at once, warm and sorry. By morning he's asking to meet."},{"text":"Text a friend: \"Rough night. Can we talk?\"","then":"Ritika calls back in minutes and stays on the line till you're sleepy.","best":true},{"text":"Type the text and save it as a draft, just in case","then":"The draft sits there. You open it four more times before sunrise."},{"text":"Tell yourself leaving was wrong if it hurts this much","then":"The thought grows louder, and the reasons you left start to blur."}],"why":"The urge is normal and never your fault. A friend meets the loneliness without reopening the door."},{"prompt":"Two days later, Sameer's cousin messages: \"He's a mess without you. Just talk to him once.\" What do you do?","options":[{"text":"Explain everything so his family understands","then":"The cousin passes it all on. Sameer now has your words to argue with."},{"text":"Agree to one call, to give him closure","then":"The call runs an hour. He cries, and you hang up half-promising to meet."},{"text":"Reply \"I won't discuss this\" and mute the chat","then":"The cousin sends a sad emoji. The chat goes quiet, and so does the pull.","best":true},{"text":"Feel guilty, as if his pain is yours to fix","then":"The guilt tugs at you all day, and you start drafting a reply to him."}],"why":"You don't owe anyone access to you through others. One short line and silence protect you."},{"prompt":"Sunday evening, the hour you two always talked, your room feels empty. What do you do?","options":[{"text":"Check his profile to see if he's okay","then":"He's posted a sad song. You spend the evening reading into it."},{"text":"Keep so busy with assignments there's no time to feel","then":"You finish three. At midnight the ache arrives anyway."},{"text":"Tough it out alone, since you chose this","then":"The evening drags, and by night the pull to text him is stronger."},{"text":"Make Sunday evening a plan with friends","then":"Two friends come over with chai and a film. Sunday starts to feel like yours.","best":true}],"why":"Loneliness is real. Filling that hour with people eases it without reopening the door."}],"debrief":"The pull to reconnect is strongest when you're lonely. Redirect it to a friend, not the ex.","relearn":"When lonely, redirect the urge to a friend, not the ex."},
  {"id":"rr-1120","cat":"leaving-safely","type":"branch","persona":"any","source":"rebuilding","hook":"You're safely out of a controlling relationship. Now you want your own life back.","steps":[{"prompt":"It's been months since you did anything just for you. Where do you start?","options":[{"text":"Wait until you feel fully healed, then begin","then":"Weeks pass. You feel much the same, and waiting becomes its own routine."},{"text":"Message one old friend and rejoin one class you loved","then":"Pooja replies with ten hearts. On Saturday you're back at dance, rusty and smiling.","best":true},{"text":"Sign up for five new things at once","then":"By the second week you're exhausted and skipping all of them."},{"text":"Wait for your friends to reach out first","then":"A couple do, gently. Most assume you still need space."}],"why":"Rebuilding is how you heal, not a reward for healing. One friend and one joy is enough."},{"prompt":"An old friend, Tanvi, asks why you went quiet for a whole year. What do you say?","options":[{"text":"Apologise again and again for being a bad friend","then":"Tanvi keeps saying it's fine, and the chat ends feeling awkward."},{"text":"Say he wasn't that bad and you just drifted apart","then":"She accepts it, and you feel the old habit of covering for him."},{"text":"Share as much as feels okay, and say you missed her","then":"Tanvi goes quiet, then says, \"I missed you too. I'm so glad you're back.\"","best":true},{"text":"Make up a story so she won't ask more","then":"She believes it, but the distance between you stays."}],"why":"You don't owe anyone the whole story. Sharing what feels okay lets friends back in without shame."},{"prompt":"A few weeks in, a bad day hits and you feel back at square one. What do you tell yourself?","options":[{"text":"\"I'll never be who I was before him.\"","then":"The thought makes the day heavier, and you cancel your evening plans."},{"text":"\"Maybe I left too soon.\"","then":"You find yourself scrolling old photos of the good times."},{"text":"\"One bad day isn't going back.\"","then":"You call a friend, cook dinner, and wake up a little lighter.","best":true},{"text":"\"Hide it and push through, so no one worries.\"","then":"You smile through class, and the heaviness follows you home."}],"why":"Bad days are part of healing, not proof you failed. Your life keeps widening."}],"debrief":"A controlled life shrinks, and that was never your fault. Rebuild it one connection and one joy at a time.","relearn":"Rebuild by reconnecting and restarting one thing at a time; that's how you heal."},
  {"id":"rr-1121","cat":"leaving-safely","type":"role-play","persona":"any","source":"the no-contact line","hook":"Weeks after you ended things with Neel, he keeps \"checking in\" by text.","setup":"Tonight another message lights up your phone.","steps":[{"prompt":"Neel texts: \"Hey, just checking in. Miss talking to you.\"","options":[{"text":"\"Maybe we could be friends again after some time.\"","then":"\"Yes! I'd love that,\" he replies at once. \"Coffee next week?\""},{"text":"\"I'm not in contact with you anymore. Please stop.\"","then":"A minute later: \"Wow. Okay. I was only being nice.\"","best":true},{"text":"\"Hi. I'm okay. How are you?\"","then":"He sends three long messages and a voice note within minutes."},{"text":"\"Why can't you just leave me alone?!\"","then":"\"Relax,\" he replies. \"Why are you so angry at me?\""}],"why":"One plain line says no-contact clearly, without starting a conversation."},{"prompt":"Neel texts: \"I just want closure. Can we meet once and talk properly?\"","options":[{"text":"\"Okay, one coffee, and then that's it.\"","then":"\"Thank you,\" he writes. \"Saturday, our old place?\""},{"text":"\"Fine. Here's everything you did wrong.\"","then":"He argues every point, and you're up till 2 a.m. texting."},{"text":"\"No. I won't reply to more messages.\"","then":"He sends two more texts. Then, for the first time, nothing.","best":true},{"text":"\"I'm sorry if leaving hurt you.\"","then":"\"It did,\" he replies. \"So you owe me one talk.\""}],"why":"Closure doesn't need a meeting. His hurt is not your fault, and not yours to fix."},{"prompt":"The next day, your friend Divya asks: \"Is Neel still messaging you? What will you do?\"","options":[{"text":"\"Keep him unblocked, just to see what he says.\"","then":"You check your phone every hour, and each message pulls at you."},{"text":"\"Post a story calling him out.\"","then":"It gets likes, and his friends start messaging you too."},{"text":"\"Send one kinder text so he stops hurting.\"","then":"He reads it as a door opening and replies within seconds."},{"text":"\"Block him, and tell you if he turns up.\"","then":"Divya nods. \"Do it now. I'll keep my phone on.\"","best":true}],"why":"Blocking and telling a friend makes no-contact real, and you're not holding it alone."}],"relearn":"State no-contact plainly once: 'I'm not in contact anymore. Please don't message me.'"},
  {"id":"rr-1122","cat":"leaving-safely","type":"role-play","persona":"Deepak","source":"asking for a plan","hook":"Your relationship has become unsafe, and today you've booked a slot with the college counsellor, Ms Iyer.","setup":"She closes the door and smiles.","steps":[{"prompt":"Ms Iyer asks: \"What brings you in today?\"","options":[{"text":"\"Things are a bit hard at home. It's probably nothing.\"","then":"\"Okay,\" she says. \"Take your time. This is a safe place to talk.\""},{"text":"\"Just exam stress, I think.\"","then":"She shares study tips, then asks gently: \"Is anything else weighing on you?\""},{"text":"\"I'm in an unsafe relationship. I want a plan to leave.\"","then":"She nods. \"Thank you for telling me. Let's make that plan together.\"","best":true},{"text":"\"I need advice on keeping my partner happy.\"","then":"She tilts her head. \"Tell me what happens when they're not happy.\""}],"why":"Naming it plainly gets real help. It's never your fault, and you need no proof it's bad enough."},{"prompt":"Ms Iyer asks: \"Whatever you're facing, is there someone you trust who could know?\"","options":[{"text":"\"No. I don't want to be a burden to anyone.\"","then":"She pauses. \"Can we come back to that?\" The question stays with you."},{"text":"\"I'd rather keep this between us.\"","then":"\"It can stay here,\" she says. \"But who would you call on a bad night?\""},{"text":"\"My older cousin. I'll tell her this week.\"","then":"She writes it down. \"Let's think about what you'll say to her.\"","best":true},{"text":"\"I'll tell our whole group so they're on my side.\"","then":"She looks thoughtful. \"Would all of them keep it safe?\""}],"why":"One trusted person who knows means you're not alone if things get worse."},{"prompt":"Ms Iyer says: \"I ask everyone this. If you had to leave in a hurry, what would you take?\"","options":[{"text":"\"Nothing. I'd just run.\"","then":"\"You could,\" she says. \"But how would you manage the next day?\""},{"text":"\"My ID, phone, charger, some cash and documents.\"","then":"\"Keep them ready in one place,\" she says. \"Somewhere safe.\"","best":true},{"text":"\"My laptop and books, so college doesn't suffer.\"","then":"She nods. \"And your ID, papers, money?\" You hadn't thought of those."},{"text":"\"I'll figure it out when it happens.\"","then":"\"Things move fast then,\" she says gently. \"Let's decide now.\""}],"why":"ID, documents and money kept ready make a quick exit much safer."}],"relearn":"Name it and ask: 'I'm in an unsafe relationship and want help making a plan to leave.'"},
  {"id":"rr-1123","cat":"leaving-safely","type":"role-play","persona":"any","source":"no debate owed","hook":"Weeks after you ended things, your ex, Aman, blocks your path outside the library.","setup":"People are walking past nearby.","steps":[{"prompt":"Aman asks: \"Just tell me the real reason you left. Don't I deserve that?\"","options":[{"text":"\"You deserve the truth, so let me explain it all.\"","then":"He cuts in on every point, and twenty minutes later you're still there."},{"text":"\"I've made my decision. I'm not discussing it. Bye.\"","then":"\"Seriously?\" he calls after you as you walk towards the gate.","best":true},{"text":"\"I'm sorry. I should have explained before I left.\"","then":"\"Yes, you should have,\" he says, not moving. \"So explain now.\""},{"text":"\"You know exactly why. You ruined everything!\"","then":"His voice rises, and he steps closer."}],"why":"You don't owe a debate. A short line and walking away keeps you safer."},{"prompt":"That night Aman texts: \"You owe me one honest talk. Five minutes.\"","options":[{"text":"\"Okay. I guess you do deserve closure.\"","then":"\"Thank you,\" he replies. \"Tomorrow at six, the café?\""},{"text":"\"I'm sorry. I know I hurt you.\"","then":"\"You did,\" he writes back. \"So you can at least explain.\""},{"text":"\"I don't owe you that. Don't contact me again.\"","then":"He sends a long reply. You leave it unopened.","best":true},{"text":"\"Stop, or I'll tell everyone what you're like.\"","then":"\"Go ahead,\" he replies. \"Let's see who they believe.\""}],"why":"Your decision is enough. You don't have to earn the right to leave."},{"prompt":"Your friend Pallavi asks: \"You look shaken. Did something happen?\"","options":[{"text":"\"It's nothing. He just wanted to talk.\"","then":"Pallavi closes her laptop. \"Aman? He doesn't get to scare you like this.\""},{"text":"\"It's my fault for leaving so suddenly.\"","then":"Pallavi frowns. \"Leaving Aman wasn't a fault. What did he do?\""},{"text":"\"I'll meet him once and settle it for good.\"","then":"Pallavi looks alarmed. \"Meet Aman alone? After this? Please don't.\""},{"text":"\"Aman cornered me today. I'm scared.\"","then":"\"Come here,\" Pallavi says. \"Tell me everything. You're not alone.\"","best":true}],"why":"Telling someone you trust means you don't carry it alone. His pressure is never your fault."},{"prompt":"Pallavi asks: \"What will you do if Aman comes looking for you tomorrow?\"","options":[{"text":"\"He won't. He's not violent, just upset.\"","then":"\"I hope so,\" she says, not sounding sure."},{"text":"\"I'll walk with someone and call 112 if I'm scared.\"","then":"\"Deal,\" she says. \"I'll send you my timetable.\"","best":true},{"text":"\"I'll just give him the talk so he stops.\"","then":"Pallavi shakes her head. \"That's what he's pushing for.\""},{"text":"\"I'll ask his friends to calm him down.\"","then":"\"His friends?\" she asks. \"Won't they tell him everything?\""}],"why":"Company on your route and a way to call for help keep you safer if he turns up again."}],"relearn":"You don't owe an explanation: 'I've made my decision and I'm not discussing it.'"},
  {"id":"rr-1124","cat":"leaving-safely","type":"role-play","persona":"any","source":"opening a door","hook":"Your friend Simran says her boyfriend checks her phone and won't let her meet you anymore.","setup":"She's calling quietly between classes.","steps":[{"prompt":"Simran says: \"He'd be so angry if he knew I was calling you.\"","options":[{"text":"\"Why don't you just stand up to him and say no?\"","then":"Silence. \"You make it sound easy,\" she says quietly."},{"text":"\"That sounds really hard, and it's not your fault.\"","then":"She lets out a shaky breath. \"I thought you'd be mad I disappeared.\"","best":true},{"text":"\"Honestly, I was hurt when you stopped replying.\"","then":"\"I'm sorry,\" she whispers, sounding even smaller."},{"text":"\"He sounds awful. You have to break up now.\"","then":"\"I can't just do that,\" she says. A long pause, but she stays on the line."}],"why":"Believing her and saying it's not her fault keeps the line between you open."},{"prompt":"Simran asks: \"Do you think I'm stupid for staying?\"","options":[{"text":"\"Not stupid. But you're smarter than this.\"","then":"\"I know,\" she says flatly, and goes quiet."},{"text":"\"Every relationship has its problems, yaar.\"","then":"\"I guess,\" she says, and starts talking herself out of it."},{"text":"\"Only if you're still there after this call.\"","then":"She goes silent. \"That's not fair,\" she says, but she doesn't hang up."},{"text":"\"No. Control like this traps anyone. It's on him.\"","then":"\"Thank you,\" she says, voice breaking. \"I needed that.\"","best":true}],"why":"Staying is never stupid. Control traps capable people, and it's never their fault."},{"prompt":"Simran asks: \"What can I even do if he watches everything?\"","options":[{"text":"\"Let me call him and tell him to back off.\"","then":"\"No!\" she says fast. \"He'd know it came from me.\""},{"text":"\"My door's always open when you need a safe place.\"","then":"\"Even at 2 a.m.?\" she asks, and you hear her breathe easier.","best":true},{"text":"\"Just wait it out. He'll relax eventually.\"","then":"\"Maybe,\" she says, not believing it herself."},{"text":"\"Tell your parents and let them handle him for you.\"","then":"\"They love him,\" she says. \"They'd tell me to adjust.\""}],"why":"A standing safe place, with no pressure, lets her reach you whenever she's ready."},{"prompt":"Simran asks: \"What if one day it gets really scary?\"","options":[{"text":"\"Then you'll finally leave him, right?\"","then":"\"I don't know,\" she whispers. \"Maybe.\""},{"text":"\"It won't. He's controlling, not dangerous.\"","then":"\"You think so?\" she asks, sounding almost relieved."},{"text":"\"Call 112 first, then me. 181 can help you plan.\"","then":"\"Okay,\" she says slowly. \"I'll save them under other names.\"","best":true},{"text":"\"Then come to me and we'll confront him together.\"","then":"\"Together?\" she asks, scared. \"That could make it worse.\""}],"why":"Knowing 112 and 181 gives her help beyond you if things get worse."}],"relearn":"Believe a friend, name it's not their fault, and offer a standing safe place."},
  {"id":"rr-1125","cat":"leaving-safely","type":"role-play","persona":"Aarti","source":"telling family","hook":"You've decided to leave Vikram, whose control has made you afraid. Now you're telling your parents.","setup":"Your mother switches off the TV.","steps":[{"prompt":"Your mother asks: \"What happened? Why do you look so serious?\"","options":[{"text":"\"Sorry to disappoint you all. Maybe I'm wrong.\"","then":"\"Wrong about what?\" she asks, worried. \"Is it Vikram?\""},{"text":"\"Nothing. I'll tell you later.\"","then":"She frowns and leaves the TV off. \"Is it Vikram? Tell us.\""},{"text":"\"We fight a lot. It's probably both our faults.\"","then":"\"Every couple fights,\" she says. \"You'll sort it out.\""},{"text":"\"Vikram isn't safe for me, so I'm leaving him.\"","then":"She sits down slowly. \"Not safe? What do you mean?\"","best":true}],"why":"Leading with safety, not apology, tells your family what's really at stake."},{"prompt":"Your father says: \"Vikram has always been such a good boy with us.\"","options":[{"text":"\"He's different in private. I need your support.\"","then":"Your father is quiet a long moment. \"Tell us what's been happening.\"","best":true},{"text":"\"You're right. Maybe I'm overreacting.\"","then":"\"See?\" he says, relieved. \"Talk to him and fix it.\""},{"text":"\"You never listen to me anyway!\"","then":"\"Don't raise your voice,\" he snaps, and the room tightens."},{"text":"\"I'll explain every fight so you believe me.\"","then":"You talk for an hour. He picks holes in each story."}],"why":"You can ask for support directly. You don't need to win a debate for your safety to count."},{"prompt":"Your mother asks: \"What will people say? Can't you adjust a little?\"","options":[{"text":"\"Maybe if I love him more, he'll change.\"","then":"She nods, relieved. The fear settles back in your chest."},{"text":"\"I won't adjust to being unsafe. Stand with me.\"","then":"She looks at your father, then at you. \"Okay. We're listening.\"","best":true},{"text":"\"Fine. I'll handle it without you.\"","then":"Her eyes fill. \"Why would you shut us out?\""},{"text":"\"Let's ask Vikram's parents what they think.\"","then":"She reaches for her phone, and now his family is involved too."}],"why":"You can't love someone out of controlling you. You deserve safety, and it's never your fault."},{"prompt":"Your father asks: \"So what do you need from us?\"","options":[{"text":"\"Go and talk some sense into Vikram for me.\"","then":"He's already reaching for his keys. You feel a flash of dread."},{"text":"\"Promise you won't get involved at all.\"","then":"\"If that's what you want,\" he says, and steps back."},{"text":"\"Help me stay safe while I end it.\"","then":"He nods. \"Stay here for now. We'll save 112 on all our phones.\"","best":true},{"text":"\"Nothing. I'll be fine on my own.\"","then":"He looks unsure. \"If you're sure.\" The offer hangs there."}],"why":"Naming what you need turns worried family into real support."}],"relearn":"Lead with safety: 'This isn't safe for me, so I'm leaving. I need support, not doubt.'"},
  {"id":"rr-1126","cat":"leaving-safely","type":"role-play","persona":"any","source":"the love-hook","hook":"A month after you left, your ex, Tarun, calls from a new number.","setup":"His voice is soft, the way it used to be.","steps":[{"prompt":"Tarun says: \"No one will ever love you like I did. You know that.\"","options":[{"text":"\"Maybe you're right. I might regret this forever.\"","then":"\"You will,\" he says gently. \"So come home.\""},{"text":"\"That's not love. It's a hook. I'm not coming back.\"","then":"A pause. \"So that's it? After everything?\"","best":true},{"text":"\"How dare you call me! You ruined everything!\"","then":"\"See? You still feel so much for us,\" he says."},{"text":"\"Maybe. But I need more time to think.\"","then":"\"Of course,\" he says softly. \"But talk to me a little first.\""}],"why":"Naming the hook takes its power away. Love doesn't threaten you with \"never again\"."},{"prompt":"Tarun says: \"I still think about us every day. Tell me you don't.\"","options":[{"text":"\"Of course I do. Every single day.\"","then":"\"Then why are we doing this?\" he asks, voice warm again."},{"text":"\"No. I never loved you anyway.\"","then":"\"Liar,\" he says, and the call turns into an argument."},{"text":"\"I miss who you were at the start.\"","then":"\"I can be that again,\" he says quickly. \"Give me a chance.\""},{"text":"\"Missing you doesn't change my decision.\"","then":"He goes quiet. \"I didn't think you'd say that.\"","best":true}],"why":"You can miss someone and still be sure. Feelings don't cancel the reasons you left."},{"prompt":"Tarun says: \"If you hang up, I'll come to your hostel and wait.\"","options":[{"text":"\"Fine, come. I'm not scared of you.\"","then":"\"We'll see,\" he says, and hangs up first."},{"text":"\"You'd only do that because you love me so much.\"","then":"\"Exactly,\" he says. \"So see you at eight.\""},{"text":"\"Don't come. I'm hanging up and telling the warden.\"","then":"\"You'd really do that?\" he says, and his voice falters.","best":true},{"text":"\"Please don't. Everyone will think I'm the problem.\"","then":"\"Then don't make me come,\" he says."}],"why":"A threat to turn up is control, not love. Ending the call and telling someone keeps you safer."},{"prompt":"Your friend Megha asks: \"Who was that? You've gone pale.\"","options":[{"text":"\"Nobody. Just a wrong number.\"","then":"She shrugs, and later you lie awake listening for the gate."},{"text":"\"It's my own fault for picking up.\"","then":"Megha frowns. \"How is that your fault? What did he say?\""},{"text":"\"Tarun. He says he'll come here. Stay with me?\"","then":"\"Of course,\" Megha says. \"And if he shows up, we call 112.\"","best":true},{"text":"\"My ex. I'll go and deal with him myself.\"","then":"Megha looks worried. \"Alone? What if he gets angry?\""}],"why":"Telling a friend means you're not alone with a threat. It is never your fault."}],"relearn":"Name the hook: 'That's not love. It's a hook. I'm not coming back.'"},
  {"id":"rr-1127","cat":"leaving-safely","type":"role-play","persona":"any","source":"mirror talk","hook":"A month after leaving a controlling relationship, you wake up wavering.","setup":"You catch your own eyes in the mirror.","steps":[{"prompt":"The doubt in your head says: \"Maybe you should have tried harder.\"","options":[{"text":"\"You're right. I gave up on us far too fast.\"","then":"The doubt grows louder. \"Call him. Say sorry.\""},{"text":"\"Stop it. I'm totally over him.\"","then":"The doubt waits. Your eyes sting anyway."},{"text":"\"Leaving was brave. I can be sad and still sure.\"","then":"The doubt softens, but it doesn't leave.","best":true},{"text":"\"I'll stay busy all day so I don't have to think.\"","then":"The doubt goes quiet for an hour, then creeps back."}],"why":"Sadness doesn't make the choice wrong. You can grieve and still be sure."},{"prompt":"The doubt asks: \"So why does it still hurt this much?\"","options":[{"text":"\"Because something must be really wrong with me.\"","then":"The doubt agrees. \"Everyone else moves on faster.\""},{"text":"\"Because I cared. Grief isn't a sign to go back.\"","then":"The doubt has no reply. The ache stays, but lighter.","best":true},{"text":"\"Because maybe he really was the one for me.\"","then":"The doubt pounces. \"So what are you waiting for?\""},{"text":"\"It doesn't. I'm completely fine.\"","then":"The doubt waits. The lump in your throat says otherwise."}],"why":"Heartbreak is real grief. Hurting means you cared, and none of what he did was your fault."},{"prompt":"The doubt says: \"Don't tell anyone how shaky you feel. They'll think you're weak.\"","options":[{"text":"\"True. I'll keep smiling so no one worries.\"","then":"The doubt settles in. \"That's it. Keep it all inside.\""},{"text":"\"I'll only tell people once I'm fully better.\"","then":"The doubt nods along, and the hard morning stays yours alone."},{"text":"\"Needing support isn't weak. I'm texting Anjali.\"","then":"The doubt shrinks as Anjali replies: \"Coming over after class.\"","best":true},{"text":"\"I'll post a sad quote online and see who notices.\"","then":"A few likes arrive. The doubt smirks. \"See? No one asked.\""}],"why":"Leaning on a friend is strength. You don't have to hold a hard morning alone."}],"relearn":"Tell yourself: leaving was brave; I can feel sad and still be sure."},
  {"id":"rr-1128","cat":"leaving-safely","type":"role-play","persona":"Meena","source":"first call","hook":"You're scared of your partner, Suresh, and for the first time you dial 181, the Women Helpline.","setup":"A calm voice answers.","steps":[{"prompt":"The counsellor says: \"Hello. Take your time. What's happening?\"","options":[{"text":"\"Sorry to bother you. It's probably not serious.\"","then":"\"It's no bother,\" she says. \"Whatever it is, I'm listening.\""},{"text":"\"I'm scared of my partner. What can I do?\"","then":"\"Thank you for calling,\" she says. \"Let's look at your options together.\"","best":true},{"text":"\"How do I make him less angry?\"","then":"She pauses. \"Managing his anger isn't your job. Let's talk.\""},{"text":"\"It's my friend who has the problem, not me.\"","then":"\"Okay,\" she says gently. \"What is your friend going through?\""}],"why":"Saying it plainly gets you real help. You never have to be \"serious enough\" to call."},{"prompt":"The counsellor asks: \"Can you tell me what happens when things go wrong?\"","options":[{"text":"\"Nothing much, really. He just has a bad temper.\"","then":"\"Okay,\" she says slowly. The call drifts, and you almost hang up."},{"text":"\"It's my fault. I make him angry.\"","then":"\"His anger isn't your fault,\" she says gently. \"What happens when he gets like this?\""},{"text":"\"He shouts, breaks things, and says he'll hurt me.\"","then":"\"Thank you for telling me,\" she says. \"That is serious, and it's not your fault.\"","best":true},{"text":"\"I can't say. You'll think badly of him.\"","then":"\"I'm here for you, not to judge,\" she says. \"Only if you want.\""}],"why":"Saying what really happens lets them help. His behaviour is never your fault."},{"prompt":"The counsellor asks: \"Is there somewhere you could go if you needed to?\"","options":[{"text":"\"I'll go to his family. They can control him.\"","then":"\"Would they be on your side?\" she asks. You aren't sure."},{"text":"\"I'll decide if things get really bad.\"","then":"\"It's easier to decide now, while it's calm,\" she says."},{"text":"\"Nowhere. I have to stay, no matter what.\"","then":"\"There are more options than it feels like,\" she says. \"Let's find one.\""},{"text":"\"My sister's place, across the city.\"","then":"\"Keep her number and your ID ready,\" she says. \"And 112 is always there.\"","best":true}],"why":"Knowing where you'd go before you need it makes leaving much safer."}],"relearn":"You're allowed to call: 'I'm scared of my partner. Can you talk me through my options?'"},
  {"id":"rr-1129","cat":"leaving-safely","type":"sort","hook":"Sort each step: part of a safe exit plan, or a risky move?","items":[{"id":"a","text":"Pack a small bag of documents and essentials in advance"},{"id":"b","text":"Tell a trusted person your plan and timing"},{"id":"c","text":"Confront them alone to demand they change first"},{"id":"d","text":"Save the women's helpline number you can reach"},{"id":"e","text":"Announce you're leaving mid-argument"},{"id":"f","text":"Threaten to expose their secrets as leverage"}],"bins":[{"id":"plan","label":"Safe plan","valence":"pos"},{"id":"risk","label":"Risky move","valence":"neg"}],"key":{"a":"plan","b":"plan","c":"risk","d":"plan","e":"risk","f":"risk"},"relearn":"Pack ahead, tell someone, keep a helpline ready; don’t confront alone.","persona":"any","source":"exit plan vs risk"},
  {"id":"rr-1130","cat":"leaving-safely","type":"sort","hook":"Sort each line: your responsibility, or never your fault?","items":[{"id":"a","text":"Choosing when and how to leave safely"},{"id":"b","text":"Your partner's decision to control you"},{"id":"c","text":"Reaching out for support"},{"id":"d","text":"The threats they make when you go"},{"id":"e","text":"Looking after your own safety"},{"id":"f","text":"Their choice to monitor your phone"}],"bins":[{"id":"yours","label":"Yours to own","valence":"pos"},{"id":"theirs","label":"Never your fault","valence":"neg"}],"key":{"a":"yours","b":"theirs","c":"yours","d":"theirs","e":"yours","f":"theirs"},"relearn":"You own leaving and your safety; their control, threats and monitoring are never your fault.","persona":"any","source":"whose fault"},
  {"id":"rr-1131","cat":"leaving-safely","type":"sort","hook":"Sort each thing your ex says: a genuine sign of change, or a hook to pull you back?","items":[{"id":"a","text":"Respecting your no-contact without pushing"},{"id":"b","text":"\"I'll kill myself if you don't come back\""},{"id":"c","text":"Steady, lasting change shown over months"},{"id":"d","text":"\"No one will ever love you like I do\""},{"id":"e","text":"Giving you space and not chasing"},{"id":"f","text":"Showering you with sudden grand gifts"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"hook","label":"A hook","valence":"neg"}],"key":{"a":"real","b":"hook","c":"real","d":"hook","e":"real","f":"hook"},"relearn":"Real change respects your space and lasts; threats, 'no one else will love you' and grand gifts are hooks.","persona":"any","source":"change vs hook"},
  {"id":"rr-1132","cat":"leaving-safely","type":"sort","hook":"Sort each one: a healthy way to cope after leaving, or a way to get pulled back?","items":[{"id":"a","text":"Leaning on friends and routine"},{"id":"b","text":"Re-reading their old loving messages at night"},{"id":"c","text":"Naming what you feel to someone safe"},{"id":"d","text":"Stalking their profile for updates"},{"id":"e","text":"Filling your days with things you enjoy"},{"id":"f","text":"Keeping a 'maybe' door open just in case"}],"bins":[{"id":"forward","label":"Moves you forward","valence":"pos"},{"id":"back","label":"Pulls you back","valence":"neg"}],"key":{"a":"forward","b":"back","c":"forward","d":"back","e":"forward","f":"back"},"relearn":"Friends, routine and naming feelings move you forward; the rest pull you back.","persona":"any","source":"forward vs back"},
  {"id":"rr-1133","cat":"leaving-safely","type":"sort","hook":"Sort each belief: a true thing to hold onto, or a trap that keeps you stuck?","items":[{"id":"a","text":"My safety matters more than appearances"},{"id":"b","text":"If I loved them enough they'd stop"},{"id":"c","text":"Leaving is brave, not a failure"},{"id":"d","text":"I provoked it, so it's on me"},{"id":"e","text":"It's never too late to leave"},{"id":"f","text":"The good days mean it wasn't really abuse"}],"bins":[{"id":"true","label":"True: hold on","valence":"pos"},{"id":"trap","label":"A trap","valence":"neg"}],"key":{"a":"true","b":"trap","c":"true","d":"trap","e":"true","f":"trap"},"relearn":"Hold onto: safety over image, leaving is brave, never too late. Drop: love-them-out, I provoked it, good days excuse it.","persona":"any","source":"true vs trap"},
  {"id":"rr-1134","cat":"leaving-safely","type":"sort","hook":"Sort who can help with what after you decide to leave (India).","items":[{"id":"a","text":"Immediate danger right now"},{"id":"b","text":"A woman facing violence at home"},{"id":"c","text":"Talking the decision through slowly"},{"id":"d","text":"A partner threatening to hurt you right now"},{"id":"e","text":"Heavy, lasting low mood after it all"},{"id":"f","text":"A safe place to stay tonight"}],"bins":[{"id":"emergency","label":"Call now: 112","valence":"uhoh"},{"id":"support","label":"Support & talk","valence":"tell"}],"key":{"a":"emergency","b":"emergency","c":"support","d":"emergency","e":"support","f":"support"},"relearn":"Danger and threats of harm need urgent routes (112); talking it through, low mood and a place to stay are support.","persona":"Meena","source":"who helps with what"},
  {"id":"rr-1135","cat":"leaving-safely","type":"match","hook":"Match each worry about leaving to a real route or truth (India).","pairs":[{"left":"In danger right now","right":"Call emergency 112"},{"left":"A woman facing violence","right":"Women's helpline 181"},{"left":"Heavy low mood after leaving","right":"Tele-MANAS 14416"},{"left":"Want to think it through","right":"A counsellor or trusted person"},{"left":"Feeling it was my fault","right":"Abuse is always the controller's fault"}],"relearn":"112 for danger, 181 for violence, Tele-MANAS 14416 for low mood, a counsellor to think it through; never your fault.","persona":"any","source":"worry to route"},
  {"id":"rr-1136","cat":"leaving-safely","type":"match","hook":"Match the leaving myth to the truth that frees you from it.","pairs":[{"left":"Leaving means I failed","right":"Leaving an unsafe relationship is brave"},{"left":"I can love them out of it","right":"Their change isn't mine to fix"},{"left":"I waited too long","right":"It's never too late to leave"},{"left":"The good days prove it's fine","right":"Good days don't cancel control"},{"left":"I provoked it","right":"Abuse is never the target's fault"}],"relearn":"Leaving is brave, change isn't yours to fix, never too late, good days don't cancel control, never your fault.","persona":"any","source":"myth to truth"},
  {"id":"rr-1137","cat":"leaving-safely","type":"match","hook":"Match each exit-plan step to why it keeps you safer.","pairs":[{"left":"Tell a trusted person your plan","right":"Someone knows and can help if needed"},{"left":"Pack documents and essentials ahead","right":"You can move fast when the moment comes"},{"left":"Know a safe place to go","right":"You're not stranded after you leave"},{"left":"Save the helpline numbers","right":"Real help is one call away"},{"left":"Avoid announcing it mid-fight","right":"Risk can spike in a heated moment"}],"relearn":"Tell someone, pack ahead, know a safe place, save helplines, and don't announce it mid-fight.","persona":"any","source":"step to reason"},
  {"id":"rr-1138","cat":"leaving-safely","type":"match","hook":"Match what you might feel after leaving to a steadying truth.","pairs":[{"left":"I miss even the bad parts","right":"Missing them is normal, not a reason to return"},{"left":"I feel guilty for leaving","right":"Your safety isn’t something to feel guilty for"},{"left":"I’m scared I can’t cope alone","right":"You were whole before, and whole now"},{"left":"The quiet feels strange","right":"That calm is safety, not emptiness"},{"left":"I doubt I made the right call","right":"Relief it’s over is your answer"}],"relearn":"Missing isn’t a reason to return; no guilt for safety; relief is the answer","persona":"any","source":"feeling to truth"},
  {"id":"rr-1139","cat":"leaving-safely","type":"match","hook":"Match each post-leaving behaviour from an ex to what it really is.","pairs":[{"left":"Showing up uninvited where you are","right":"Following: a warning sign, not romance"},{"left":"Messaging from new numbers after blocks","right":"Testing the wall: keep it up"},{"left":"Texting your friends to turn them","right":"A smear to isolate you again"},{"left":"Threatening to share private photos","right":"A crime: report to cybercrime 1930"},{"left":"Respecting your no-contact","right":"The one healthy response"}],"relearn":"Showing up is following; new numbers test the wall; friend-texts smear.","persona":"any","source":"behaviour to meaning"},
  {"id":"rr-1140","cat":"leaving-safely","type":"spot","hook":"Spot the two lines that are control dressed up as love.","scene":[{"id":"a","text":"\"I just need to know where you are at all times because I love you\"","trick":true},{"id":"b","text":"\"Take your time, see your friends, I trust you\"","trick":false},{"id":"c","text":"\"If you really loved me you'd delete him from your phone\"","trick":true},{"id":"d","text":"\"I'm glad you have your own life outside us\"","trick":false},{"id":"e","text":"\"Your independence is one of the things I love\"","trick":false}],"why":"Tracking you and demanding you cut people off are control; trust is love.","relearn":"Tracking and forced cut-offs are control, not love.","persona":"any","source":"control as love"},
  {"id":"rr-1141","cat":"leaving-safely","type":"spot","hook":"You're planning to leave. Spot the two moves that would make it less safe.","scene":[{"id":"a","text":"Telling a trusted person your plan and timing","trick":false},{"id":"b","text":"Announcing you're leaving in the middle of a fight","trick":true},{"id":"c","text":"Packing key documents quietly in advance","trick":false},{"id":"d","text":"Confronting them alone to make them admit it first","trick":true},{"id":"e","text":"Knowing a safe place you can go to","trick":false}],"why":"Announcing mid-fight and confronting alone are when risk spikes; the rest are safe steps.","relearn":"Announcing mid-fight and confronting alone are the risky moves.","persona":"any","source":"risky exit moves"},
  {"id":"rr-1142","cat":"leaving-safely","type":"spot","hook":"After you left, your ex sends these. Spot the two that are hooks to pull you back.","scene":[{"id":"a","text":"\"I respect your decision. I'll leave you be.\"","trick":false},{"id":"b","text":"\"No one will ever love you the way I did.\"","trick":true},{"id":"c","text":"\"I won't message again unless you want me to.\"","trick":false},{"id":"d","text":"\"If you leave I don't know what I'll do to myself.\"","trick":true},{"id":"e","text":"\"Take all the space you need.\"","trick":false}],"why":"‘No one else will love you’ and the threat-to-self are hooks; the rest respect no-contact.","relearn":"'No one else will love you' and threats-to-self are hooks, not love.","persona":"any","source":"the pull-back hooks"},
  {"id":"rr-1143","cat":"leaving-safely","type":"spot","hook":"A friend confides about their partner. Spot the two replies that quietly blame them.","scene":[{"id":"a","text":"\"I believe you, and none of this is your fault.\"","trick":false},{"id":"b","text":"\"Are you sure you're not provoking him?\"","trick":true},{"id":"c","text":"\"I'm here, whatever you decide to do.\"","trick":false},{"id":"d","text":"\"Well, you did choose to stay this long.\"","trick":true},{"id":"e","text":"\"Want help thinking through a safe plan?\"","trick":false}],"why":"Asking if they provoke it or blaming them for staying shifts fault onto the target.","relearn":"'Are you provoking it?' and 'you chose to stay' are victim-blaming, not support.","persona":"any","source":"blaming replies"},
  {"id":"rr-1144","cat":"leaving-safely","type":"spot","hook":"Spot the two thoughts that are the trap talking, not the truth.","scene":[{"id":"a","text":"\"My safety matters more than what people think.\"","trick":false},{"id":"b","text":"\"If I just try harder, I can fix them.\"","trick":true},{"id":"c","text":"\"Leaving is brave, not a failure.\"","trick":false},{"id":"d","text":"\"It's too late for me to get out now.\"","trick":true},{"id":"e","text":"\"Asking for help is a strength.\"","trick":false}],"why":"'I can fix them' and 'it's too late' are the trap keeping you stuck; the other three thoughts are true.","relearn":"'I can fix them' and 'it's too late' are the trap, not the truth.","persona":"any","source":"trap thoughts"},
  {"id":"rr-1145","cat":"leaving-safely","type":"spot","hook":"Your ex is 'staying in touch' after the breakup. Spot the two boundary-crossing moves.","scene":[{"id":"a","text":"Liking an old photo, then leaving you alone","trick":false},{"id":"b","text":"Showing up at your classes uninvited","trick":true},{"id":"c","text":"Sending one calm 'I wish you well' message","trick":false},{"id":"d","text":"Messaging you from a brand-new number after a block","trick":true},{"id":"e","text":"Telling a mutual friend they're doing okay","trick":false}],"why":"Turning up uninvited and dodging blocks cross your boundary; the others stay on their side.","relearn":"Showing up uninvited and dodging blocks are boundary crossings.","persona":"any","source":"crossing the line"},
  {"id":"rr-1146","cat":"leaving-safely","type":"spot","hook":"Spot the two ‘reasons to stay’ that are really the abuse, not obstacles.","scene":[{"id":"a","text":"\"I genuinely need help planning where to go.\"","trick":false},{"id":"b","text":"\"He controls all the money so I literally can't.\"","trick":true},{"id":"c","text":"\"I want advice about the shared lease first.\"","trick":false},{"id":"d","text":"\"He'll fall apart without me, so I must stay.\"","trick":true},{"id":"e","text":"\"I'd like to know what helplines can do.\"","trick":false}],"why":"Money-control and ‘he’ll fall apart’ are the abuse keeping you in, not real reasons.","relearn":"Money control and ‘he needs me’ are the abuse talking, not reasons to stay.","persona":"any","source":"abuse-as-reason"},
  {"id":"rr-1147","cat":"leaving-safely","type":"spot","hook":"Spot the two ways of coping after leaving that just pull you backwards.","scene":[{"id":"a","text":"Reconnecting with a friend you'd lost touch with","trick":false},{"id":"b","text":"Re-reading their old messages every night","trick":true},{"id":"c","text":"Starting one routine that's just for you","trick":false},{"id":"d","text":"Keeping a 'maybe we'll get back together' door open","trick":true},{"id":"e","text":"Naming your feelings to someone you trust","trick":false}],"why":"Re-reading old messages and a ‘maybe’ door tie you to the past; the other three move you forward.","relearn":"Re-reading old messages and a 'maybe' door pull you backwards.","persona":"any","source":"backward coping"},
  {"id":"rr-1170","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"If they didn't get jealous, it'd mean they don't care.\"","myth":{"un":"If they didn't get jealous, it'd mean they don't care.","re":"Calm trust is the sign of caring; jealousy is about control, not how much someone loves you.","why":"Secure love trusts you instead of policing you."},"relearn":"Calm trust shows caring; jealousy is about control, not love.","persona":"any","source":"jealousy myth"},
  {"id":"rr-1171","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Sharing one location and password is just couple transparency.\"","myth":{"un":"Sharing your location and passwords is just couple transparency.","re":"Healthy transparency is offered freely; passwords demanded and location tracked is monitoring, which is control.","why":"Real trust doesn't need a tracker."},"relearn":"Demanded passwords and tracked location are monitoring, not transparency.","persona":"any","source":"monitoring"},
  {"id":"rr-1172","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They went through my chats, but only because they were insecure.\"","myth":{"un":"They went through my chats, but only because they were insecure.","re":"Insecurity can be felt and named; acting on it by searching your phone is still a controlling choice.","why":"A feeling explains it; it doesn't excuse it."},"relearn":"Insecurity may explain phone-searching, but doesn't make it okay; it's still control.","persona":"any","source":"insecurity excuse"},
  {"id":"rr-1173","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They keep me away from my family for my own good.\"","myth":{"un":"They keep me away from my family for my own good.","re":"Deciding who you may see is isolation, a control tactic that cuts off your support.","why":"Isolation leaves you with no one but them."},"relearn":"Deciding who you can see is isolation, a control tactic, not your good.","persona":"any","source":"isolation"},
  {"id":"rr-1174","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Couples should never need time apart.\"","myth":{"un":"A real couple should never need time apart.","re":"Wanting your own space, friends and time is healthy; 'we must be together always' is a control script.","why":"Togetherness shouldn't erase your own life."},"relearn":"Wanting your own space and friends is healthy, not a betrayal of the couple.","persona":"any","source":"merging myth"},
  {"id":"rr-1175","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"If I'd just explained better, they wouldn't twist my words.\"","myth":{"un":"If I explained better, they wouldn't twist my words on me.","re":"Twisting your words so you doubt your own memory is gaslighting, a tactic, not your failure to explain.","why":"No wording stops someone determined to rewrite reality."},"relearn":"Twisting your words so you doubt yourself is gaslighting, not your fault.","persona":"any","source":"gaslighting"},
  {"id":"rr-1176","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Only weak people end up controlled, that'd never be me.\"","myth":{"un":"Only weak people end up controlled; that could never be me.","re":"Control traps capable, smart people by design; being controlled is never proof of weakness.","why":"It works slowly, on anyone, by degrees."},"relearn":"Control traps capable people by design; it's never a sign of weakness.","persona":"any","source":"not weakness"},
  {"id":"rr-1177","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They check on me every hour because they worry, that's sweet.\"","myth":{"un":"They text to check on me every hour because they worry; it's sweet.","re":"Constant check-ins that you must answer are monitoring; care doesn't demand a reply on the clock.","why":"Worry asks; control tracks."},"relearn":"Check-ins you must answer on the clock are monitoring, not sweetness.","persona":"any","source":"check-ins"},
  {"id":"rr-1178","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They get to approve my outfits because they have good taste.\"","myth":{"un":"They get to approve my outfits because they have better taste.","re":"Dictating what you wear is control dressed as taste; what you wear is yours to choose.","why":"Opinions are fine; veto power isn't."},"relearn":"Dictating your clothes is control dressed as 'taste'; your body, your choice.","persona":"any","source":"clothes control"},
  {"id":"rr-1179","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They blow up sometimes, but they always say sorry, so it's fine.\"","myth":{"un":"They blow up sometimes, but they always apologise, so it evens out.","re":"A cycle of blow-up then sorry isn't repair; it keeps you hooked while the pattern stays the same.","why":"Apologies without change are part of the trap."},"relearn":"Blow-up-then-sorry on repeat isn't repair; it's the control cycle.","persona":"any","source":"the cycle"},
  {"id":"rr-1180","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They control the money so I don't have to stress about it.\"","myth":{"un":"They handle all the money so I don't have to stress about it.","re":"Keeping you with no access to money is financial control; sharing decisions is the healthy version.","why":"No money of your own makes leaving harder by design."},"relearn":"Cutting off your access to money is financial control, not them helping.","persona":"any","source":"financial control"},
  {"id":"rr-1181","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Real men keep their woman in line. That's just respect.\"","myth":{"un":"A real man keeps his partner in line; that's just respect.","re":"Respect is treating a partner as an equal; 'keeping them in line' is control, and it isn't respect.","why":"Equals don't need keeping in line."},"relearn":"'Keeping a partner in line' is control, not respect; respect treats them as equal.","persona":"Rohan","source":"red-pill reframe"},
  {"id":"rr-1182","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They threaten to hurt themselves if I leave, so I can't.\"","myth":{"un":"They say they'll hurt themselves if I leave, so I have to stay.","re":"Threatening self-harm to keep you is control; their safety isn't yours to manage by staying.","why":"You can route them to help without trading away your freedom."},"relearn":"Self-harm threats to keep you are control; you can get them help and still leave.","persona":"any","source":"threats as control"},
  {"id":"rr-1183","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They put me down in front of others, but it's only joking.\"","myth":{"un":"They put me down in front of friends, but it's only joking.","re":"Repeated 'jokes' that shrink you in public are put-downs, an early control tactic, not humour.","why":"A joke that always lands on you isn't a joke."},"relearn":"Repeated public put-down 'jokes' are an early control tactic, not humour.","persona":"any","source":"put-down jokes"},
  {"id":"rr-1184","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"Walking on eggshells just means I should try harder to please them.\"","myth":{"un":"Walking on eggshells means I should try harder to please them.","re":"Eggshells are a red flag that your world is shrinking around their moods, not a sign to try harder.","why":"You can't please your way out of control."},"relearn":"Walking on eggshells is a red flag to read, not a cue to please harder.","persona":"any","source":"eggshells"},
  {"id":"rr-1185","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They read my messages because a real partner has nothing to hide.\"","myth":{"un":"A real partner has nothing to hide, so they can read my messages.","re":"Privacy isn't hiding; demanding to read your messages is control, and you're allowed your own private life.","why":"Trust doesn't audit you."},"relearn":"Wanting privacy isn't hiding; demanding to read your messages is control.","persona":"any","source":"nothing to hide"},
  {"id":"rr-1186","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They decide who I can text. That's a fair rule in a relationship.\"","myth":{"un":"It's a fair couple rule that they decide who I'm allowed to text.","re":"One partner setting who you may talk to is control, not a rule; you keep your own friendships.","why":"Rules made by one person over the other aren't shared rules."},"relearn":"One partner deciding who you can text is control, not a fair rule.","persona":"any","source":"who you can talk to"},
  {"id":"rr-1187","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"They explode when I'm late, but it just shows how much they want me.\"","myth":{"un":"They explode when I'm five minutes late, but it shows they want me.","re":"Rage over your ordinary movements is control and intimidation, not the size of their love.","why":"Love doesn't punish you for living your day."},"relearn":"Rage over your ordinary comings and goings is control, not proof of love.","persona":"any","source":"intensity myth"},
  {"id":"rr-1188","cat":"red-flags-grown-up","type":"strike-rewrite","hook":"\"A man can't really be controlled by his girlfriend, so it's not abuse.\"","myth":{"un":"A man can't really be controlled by a girlfriend, so it isn't abuse.","re":"Anyone of any gender can be coercively controlled; it's abuse, and he'd be believed and supported too.","why":"Control isn't a one-gender story."},"relearn":"Anyone of any gender can be controlled; it's abuse, not impossible.","persona":"any","source":"even-handed"},
  {"id":"rr-1239","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two controlling lines (red flags) hiding among the okay ones.","scene":[{"id":"a","text":"\"Send me a photo proving where you are right now\"","trick":true},{"id":"b","text":"\"Text me when you reach, no rush\"","trick":false},{"id":"c","text":"\"Have fun with your friends tonight\"","trick":false},{"id":"d","text":"\"Delete his number or we're done\"","trick":true},{"id":"e","text":"\"Tell me about your day whenever\"","trick":false}],"why":"Demanding live-location proof and ordering you to cut a contact are control; the relaxed lines aren't.","relearn":"Demands for location proof and orders to cut people off are control.","persona":"any","source":"monitoring lines"},
  {"id":"rr-1189","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two gaslighting lines (the red flags) here.","scene":[{"id":"a","text":"\"You're remembering it wrong, that never happened\"","trick":true},{"id":"b","text":"\"I can see why you felt hurt by that\"","trick":false},{"id":"c","text":"\"You made me do it, this is on you\"","trick":true},{"id":"d","text":"\"Let's figure out what went wrong together\"","trick":false},{"id":"e","text":"\"I'll own my part in that\"","trick":false}],"why":"Denying your memory and flipping blame onto you are gaslighting; acknowledging and owning aren't.","relearn":"Denying your memory and flipping blame onto you are gaslighting.","persona":"any","source":"gaslighting"},
  {"id":"rr-1190","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two isolating moves (red flags) dressed up as care.","scene":[{"id":"a","text":"\"Your friends are a bad influence, drop them\"","trick":true},{"id":"b","text":"\"I'd love to meet your friends sometime\"","trick":false},{"id":"c","text":"\"Why visit family? They don't get us\"","trick":true},{"id":"d","text":"\"Go enjoy your sister's wedding\"","trick":false},{"id":"e","text":"\"Call your mum, I know you miss her\"","trick":false}],"why":"Pushing you to drop friends and skip family cuts your support, that's isolation, not concern.","relearn":"Pushing you to drop friends and skip family is isolation, not concern.","persona":"any","source":"isolation lines"},
  {"id":"rr-1191","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two controlling 'love' lines (red flags) in this chat.","scene":[{"id":"a","text":"\"If you really loved me you'd quit your job for me\"","trick":true},{"id":"b","text":"\"I'm proud of how hard you work\"","trick":false},{"id":"c","text":"\"Prove your loyalty: skip the trip with friends\"","trick":true},{"id":"d","text":"\"Take the trip, send me pics\"","trick":false},{"id":"e","text":"\"Your goals matter to me too\"","trick":false}],"why":"Using 'if you loved me' and loyalty-tests to shrink your life is control; genuine support isn't.","relearn":"'If you loved me' and loyalty-tests that shrink your life are control.","persona":"any","source":"romanticised control"},
  {"id":"rr-1192","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two early control signs (red flags) in a new relationship.","scene":[{"id":"a","text":"Calls you soulmates and wants to move in by week two","trick":true},{"id":"b","text":"Takes time to really get to know you","trick":false},{"id":"c","text":"Sulks for hours when you say you're busy","trick":true},{"id":"d","text":"Is happy when you have your own plans","trick":false},{"id":"e","text":"Says no problem when you reschedule","trick":false}],"why":"Love-bombing speed and sulking at your independence are early control signs; a steady pace isn't.","relearn":"Rushing 'soulmate' speed and sulking at your space are early control signs.","persona":"Ananya","source":"early signs"},
  {"id":"rr-1193","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two financial-control moves (red flags) here.","scene":[{"id":"a","text":"Makes you ask permission for every small spend","trick":true},{"id":"b","text":"You plan a budget together as equals","trick":false},{"id":"c","text":"Takes your card 'so you don't waste money'","trick":true},{"id":"d","text":"You each keep some money of your own","trick":false},{"id":"e","text":"Big buys are a shared decision","trick":false}],"why":"Needing permission to spend and having your card taken is financial control; sharing decisions isn't.","relearn":"Permission to spend and a taken card are financial control, not budgeting.","persona":"Deepak","source":"financial control"},
  {"id":"rr-1194","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two intimidation moves (red flags), not the calm ones.","scene":[{"id":"a","text":"Punches the wall next to you to make a point","trick":true},{"id":"b","text":"Says 'I'm angry, let's pause and talk later'","trick":false},{"id":"c","text":"'Look what you make me do' after scaring you","trick":true},{"id":"d","text":"Takes a breather, then comes back kind","trick":false},{"id":"e","text":"Names the issue without threats","trick":false}],"why":"Wall-punching to frighten you and blaming you for it are intimidation and control, not real conflict.","relearn":"Scaring you with damage, then blaming you, is intimidation, not conflict.","persona":"any","source":"intimidation"},
  {"id":"rr-1195","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two red flags hiding among healthy signs.","scene":[{"id":"a","text":"You hide receipts and texts to avoid a row","trick":true},{"id":"b","text":"You can disagree and still feel safe","trick":false},{"id":"c","text":"You've quietly stopped seeing old friends","trick":true},{"id":"d","text":"You both keep your own hobbies","trick":false},{"id":"e","text":"You can say no without a punishment","trick":false}],"why":"Hiding to avoid a row and a shrinking social world are red flags; safe disagreement and a free no aren't.","relearn":"Hiding to keep peace and a shrinking world are red flags to read.","persona":"any","source":"reading your own"},
  {"id":"rr-1196","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two phone-monitoring red flags, not the okay ones.","scene":[{"id":"a","text":"Demands your phone unlocked and scrolls it nightly","trick":true},{"id":"b","text":"Shares a funny meme from their feed","trick":false},{"id":"c","text":"Makes you screenshot every chat with a colleague","trick":true},{"id":"d","text":"Fine with you taking a call in private","trick":false},{"id":"e","text":"Trusts you when you're out","trick":false}],"why":"Nightly phone scrolling and screenshots-on-demand are monitoring; a meme and trust aren't.","relearn":"Nightly phone checks and screenshot demands are monitoring, not closeness.","persona":"any","source":"phone monitoring"},
  {"id":"rr-1197","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two coercive lines (red flags) in this argument.","scene":[{"id":"a","text":"\"No one else would ever put up with you\"","trick":true},{"id":"b","text":"\"I felt let down, can we talk about it?\"","trick":false},{"id":"c","text":"\"I'll tell everyone your secrets if you leave\"","trick":true},{"id":"d","text":"\"I need a minute, then I'm back to fix this\"","trick":false},{"id":"e","text":"\"Help me understand what you meant\"","trick":false}],"why":"'No one else would have you' and threats to expose secrets are coercion; honest, calm lines aren't.","relearn":"Tearing down your worth and threatening to expose you are coercion.","persona":"any","source":"coercion lines"},
  {"id":"rr-1198","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two queer-targeted control moves (red flags) here.","scene":[{"id":"a","text":"Threatens to out you to your family if you argue","trick":true},{"id":"b","text":"Respects who is and isn't safe to tell","trick":false},{"id":"c","text":"Says no one else will accept someone like you","trick":true},{"id":"d","text":"Celebrates your chosen family","trick":false},{"id":"e","text":"Lets you set your own coming-out timeline","trick":false}],"why":"Threatening to out you and saying no one else will accept you are control that weaponises your closet.","relearn":"Outing threats and 'no one else will accept you' are control, not love.","persona":"Zoya","source":"queer-targeted control"},
  {"id":"rr-1199","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two controlling demands (red flags) framed as commitment.","scene":[{"id":"a","text":"\"Come off social media, you don't need it\"","trick":true},{"id":"b","text":"\"Post whatever you like, it's your account\"","trick":false},{"id":"c","text":"\"Reply within a minute or I assume the worst\"","trick":true},{"id":"d","text":"\"Reply when you can, no pressure\"","trick":false},{"id":"e","text":"\"I trust you when you're offline\"","trick":false}],"why":"Ordering you off social media and demanding instant replies are control dressed as commitment.","relearn":"Banning your accounts and instant-reply rules are control, not commitment.","persona":"any","source":"digital control"},
  {"id":"rr-1200","cat":"red-flags-grown-up","type":"spot","hook":"Spot the two red flags inside a marriage being arranged for you.","scene":[{"id":"a","text":"He says your job ends the day you marry, no debate","trick":true},{"id":"b","text":"He asks what kind of life you both want","trick":false},{"id":"c","text":"He decides you'll have no say in money","trick":true},{"id":"d","text":"He wants your yes to be a real yes","trick":false},{"id":"e","text":"He's glad you'll keep your friendships","trick":false}],"why":"Vetoing your job and your say in money before marriage is control; wanting a genuine, shared yes isn't.","relearn":"Vetoing your work and your money before marriage is control, not tradition.","persona":"Aarti","source":"control in arranged match"},
  {"id":"rr-1201","cat":"red-flags-grown-up","type":"sort","hook":"Sort each line: love, or control dressed as love?","items":[{"id":"a","text":"\"Take the weekend with your friends\""},{"id":"b","text":"\"Share your location so I always know\""},{"id":"c","text":"\"I trust you, no need to check in\""},{"id":"d","text":"\"Quit that class, it eats our time\""},{"id":"e","text":"\"I'm proud of your new job\""},{"id":"f","text":"\"Tell me your password to prove you're loyal\""}],"bins":[{"id":"love","label":"Love","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"love","b":"control","c":"love","d":"control","e":"love","f":"control"},"relearn":"Trust, space and pride are love; tracking, vetoing your time and demanding passwords are control.","persona":"any","source":"love vs control"},
  {"id":"rr-1202","cat":"red-flags-grown-up","type":"sort","hook":"Sort: a healthy boundary, or controlling behaviour?","items":[{"id":"a","text":"\"I'd rather not share my phone passcode\""},{"id":"b","text":"\"You're banned from talking to him\""},{"id":"c","text":"\"I need a quiet evening to myself\""},{"id":"d","text":"\"You can't go unless I approve it\""},{"id":"e","text":"\"Please don't read my journal\""},{"id":"f","text":"\"Account to me for every hour you're out\""}],"bins":[{"id":"boundary","label":"Boundary","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"boundary","b":"control","c":"boundary","d":"control","e":"boundary","f":"control"},"relearn":"Naming your own privacy and needs is a boundary; banning people and demanding accounts is control.","persona":"any","source":"boundary vs control"},
  {"id":"rr-1203","cat":"red-flags-grown-up","type":"sort","hook":"Sort: does this expand your world, or shrink it?","items":[{"id":"a","text":"Backs your new friendships"},{"id":"b","text":"Picks fights when you go out"},{"id":"c","text":"Cheers your promotion"},{"id":"d","text":"Wants you off every group chat"},{"id":"e","text":"Encourages your weekend course"},{"id":"f","text":"Guilts you for visiting family"}],"bins":[{"id":"expands","label":"Expands","valence":"pos"},{"id":"shrinks","label":"Shrinks","valence":"neg"}],"key":{"a":"expands","b":"shrinks","c":"expands","d":"shrinks","e":"expands","f":"shrinks"},"relearn":"Backing your friends, work and learning expands your world; fights, bans and guilt shrink it.","persona":"any","source":"expand vs shrink"},
  {"id":"rr-1204","cat":"red-flags-grown-up","type":"sort","hook":"Sort: ordinary care, or monitoring?","items":[{"id":"a","text":"\"Text me you got home safe\", once"},{"id":"b","text":"Tracks your live location all day"},{"id":"c","text":"Asks how the meeting went, curious"},{"id":"d","text":"Scrolls your call log for names"},{"id":"e","text":"Trusts you when you're unreachable"},{"id":"f","text":"Needs your social-media logins"}],"bins":[{"id":"care","label":"Care","valence":"pos"},{"id":"monitor","label":"Monitoring","valence":"neg"}],"key":{"a":"care","b":"monitor","c":"care","d":"monitor","e":"care","f":"monitor"},"relearn":"A one-off 'home safe', curiosity and trust are care; live-tracking, log-scrolling and logins are monitoring.","persona":"any","source":"care vs monitoring"},
  {"id":"rr-1205","cat":"red-flags-grown-up","type":"sort","hook":"Sort: a green flag, or a red flag, in how they handle your independence?","items":[{"id":"a","text":"Happy you have your own hobbies"},{"id":"b","text":"Sulks every time you see friends"},{"id":"c","text":"Respects your need for alone time"},{"id":"d","text":"Calls your independence 'selfish'"},{"id":"e","text":"Proud you have your own goals"},{"id":"f","text":"Makes you justify any time apart"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Welcoming your hobbies, space and goals is green; sulking, 'selfish' digs and justifying are red.","persona":"any","source":"independence flags"},
  {"id":"rr-1206","cat":"red-flags-grown-up","type":"sort","hook":"Sort: an honest response, or gaslighting?","items":[{"id":"a","text":"\"You're right, that did happen, I'm sorry\""},{"id":"b","text":"\"That never happened, you dreamt it\""},{"id":"c","text":"\"I hear how that landed for you\""},{"id":"d","text":"\"You're crazy, no one else sees it that way\""},{"id":"e","text":"\"Let's check what was actually said\""},{"id":"f","text":"\"You always twist everything, as usual\""}],"bins":[{"id":"honest","label":"Honest","valence":"pos"},{"id":"gaslight","label":"Gaslighting","valence":"neg"}],"key":{"a":"honest","b":"gaslight","c":"honest","d":"gaslight","e":"honest","f":"gaslight"},"relearn":"Owning it, hearing you and checking facts is honest; denying reality and 'you're crazy' is gaslighting.","persona":"any","source":"honest vs gaslight"},
  {"id":"rr-1207","cat":"red-flags-grown-up","type":"sort","hook":"Sort: a safe pull toward you, or an early control sign?","items":[{"id":"a","text":"Gets to know you at a steady pace"},{"id":"b","text":"Calls you 'the one' within days"},{"id":"c","text":"Respects when you say not yet"},{"id":"d","text":"Wants all your time, fast"},{"id":"e","text":"Likes that you have a full life"},{"id":"f","text":"Resents anything that isn't them"}],"bins":[{"id":"safe","label":"Safe","valence":"pos"},{"id":"early","label":"Early control sign","valence":"neg"}],"key":{"a":"safe","b":"early","c":"safe","d":"early","e":"safe","f":"early"},"relearn":"A steady pace, respect and liking your full life is safe; rushing and resenting it is an early control sign.","persona":"any","source":"early-sign sort"},
  {"id":"rr-1208","cat":"red-flags-grown-up","type":"sort","hook":"Sort: respect, or contempt-flavoured control?","items":[{"id":"a","text":"Takes your opinion seriously"},{"id":"b","text":"Mocks you in front of friends"},{"id":"c","text":"Thanks you and means it"},{"id":"d","text":"Calls you stupid when you disagree"},{"id":"e","text":"Listens when you say you're hurt"},{"id":"f","text":"Rolls eyes at everything you want"}],"bins":[{"id":"respect","label":"Respect","valence":"pos"},{"id":"contempt","label":"Contempt-control","valence":"neg"}],"key":{"a":"respect","b":"contempt","c":"respect","d":"contempt","e":"respect","f":"contempt"},"relearn":"Taking you seriously, thanks and listening is respect; mocking, name-calling and eye-rolling aren't.","persona":"any","source":"respect vs contempt"},
  {"id":"rr-1209","cat":"red-flags-grown-up","type":"sort","hook":"Sort: who owns the blame for control or abuse?","items":[{"id":"a","text":"\"They chose to control me\""},{"id":"b","text":"\"I caused it by upsetting them\""},{"id":"c","text":"\"The abuse is theirs, fully\""},{"id":"d","text":"\"If I'd been better, they'd stop\""},{"id":"e","text":"\"It isn't mine to fix\""},{"id":"f","text":"\"I deserved it for staying\""}],"bins":[{"id":"theirs","label":"On the controller","valence":"pos"},{"id":"selfblame","label":"Self-blame (false)","valence":"neg"}],"key":{"a":"theirs","b":"selfblame","c":"theirs","d":"selfblame","e":"theirs","f":"selfblame"},"relearn":"Control and abuse are fully the controller's; 'I caused it' or 'I deserved it' is false self-blame.","persona":"any","source":"whose fault"},
  {"id":"rr-1210","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"password demand","hook":"Your boyfriend Dev wants your phone and email passwords \"to prove there are no secrets\".","steps":[{"prompt":"He asks again at dinner, sounding hurt. What do you do?","options":[{"text":"Share them. Real couples don't have secrets","then":"He's warm all evening. By Sunday he's asking why you deleted a chat."},{"text":"Wonder if you've given him reason to doubt you","then":"You start replaying your week, looking for what you did wrong."},{"text":"Say privacy isn't secrecy, and you won't share them","then":"Dev goes quiet. \"So you are hiding something,\" he says.","best":true},{"text":"Offer to show him your phone whenever he asks","then":"He agrees. Now he asks for it every night."}],"why":"Healthy trust is freely given. Demanded passwords are monitoring, not closeness."},{"prompt":"Dev says that if you loved him, you wouldn't need privacy. How do you see it?","options":[{"text":"Maybe he's right, and love means sharing everything","then":"You start feeling guilty for wanting any space at all."},{"text":"Love and privacy go together. This is control","then":"Your head clears a little, even though he's upset.","best":true},{"text":"He's just insecure. I should reassure him more","then":"You spend days reassuring him. The demands don't shrink."},{"text":"It's a small thing. Why make it a fight?","then":"The password question comes back a week later, bigger."}],"why":"Needing privacy doesn't mean less love. Demanding access is control."},{"prompt":"A few days on, you feel shaken and unsure of yourself. What do you do?","options":[{"text":"Keep it to yourself so no one judges him","then":"You carry it alone, and the doubt gets louder."},{"text":"Search online whether you're being dramatic","then":"The forums disagree, and you end up more confused."},{"text":"Prove your loyalty to him in other ways","then":"You cancel plans to show him you care. He asks for more."},{"text":"Talk it through with someone you trust","then":"Your friend Sneha listens. \"That's not okay. I'm with you.\"","best":true}],"why":"Someone you trust keeps you anchored. His demand is never your fault."}],"debrief":"Demanding passwords is monitoring, a control tactic. Healthy transparency is voluntary.","relearn":"Privacy isn't secrecy; demanded passwords are monitoring, not transparency."},
  {"id":"rr-1211","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"slow isolation","hook":"Your partner Tara keeps finding fault with your friends, one at a time, and you've started to agree.","steps":[{"prompt":"Now she says your closest friend, Nikhil, is \"a bad influence\". What do you do?","options":[{"text":"Trust her judgement, since she knows you best","then":"You reply to Nikhil less. After a while he stops asking why."},{"text":"Tell Nikhil what Tara said about him","then":"Nikhil is hurt and angry, and now he's wary of you both."},{"text":"Wonder if your friends really are the problem","then":"You start seeing your friends through her eyes."},{"text":"Notice the pattern: one friend, then the next","then":"You count four friends she's objected to this year. It stops feeling like chance.","best":true}],"why":"Seeing the pattern shows it's isolation, not a run of bad friends."},{"prompt":"Nikhil invites you to his cricket match on Sunday, and Tara sighs about it. What do you do?","options":[{"text":"Go, and keep your friendships going","then":"Nikhil grins when he spots you. It feels like breathing again.","best":true},{"text":"Skip it: loyal partners put each other first","then":"Sunday is quiet. By evening you realise there's no one else to call."},{"text":"Follow your cousin's advice that love means sacrifice","then":"You skip the match, and your world gets a little smaller."},{"text":"Decide you're too busy for friends this year","then":"The invites slow down, and Sundays get very quiet."}],"why":"Your friends are a safeguard, not disloyalty. Keeping them keeps your world wide."},{"prompt":"A friend, Aisha, says she misses you and wonders if something's up. What do you do?","options":[{"text":"Say you've just been really busy lately","then":"Aisha nods, unconvinced. The gap between you stays."},{"text":"Tell her about the pattern and ask her to stay close","then":"Aisha squeezes your hand. \"I'm not going anywhere.\"","best":true},{"text":"Say Tara's right that you've outgrown some people","then":"Aisha looks hurt. \"Okay. If that's how you feel.\""},{"text":"Apologise for being a bad friend this year","then":"Aisha says it's fine. You both avoid the real reason."}],"why":"Telling a friend what's happening turns your network into real support. It's never your fault."}],"debrief":"Isolating you from friends is a control tactic. Your network protects you, so hold on to it.","relearn":"Turning you against your friends one by one is isolation; keep your network."},
  {"id":"rr-1212","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"gaslighting branch","hook":"After every fight, your boyfriend Omkar insists you've remembered it wrong.","steps":[{"prompt":"Today he says he never called you useless, though you heard it clearly. What do you do?","options":[{"text":"Accept his version. Maybe you misheard","then":"You apologise for accusing him, and feel strangely dizzy."},{"text":"Trust what you heard, and note it down later","then":"That night you write the date and his words. Seeing it written steadies you.","best":true},{"text":"Argue with him until he admits he said it","then":"An hour later he still denies it, and you're the one in tears."},{"text":"Decide your memory has always been bad","then":"You start doubting other things too, like plans and dates."}],"why":"Your memory is valid. Writing things down helps you stay anchored to what happened."},{"prompt":"A week later he says you're \"too sensitive to remember things right\". What do you tell yourself?","options":[{"text":"He's calmer than me, so he must remember better","then":"You start trusting his version over your own."},{"text":"It's just a misunderstanding. Every couple has them","then":"You let it go. The next denial comes sooner."},{"text":"If I were less emotional, this wouldn't happen","then":"You try to feel less. It doesn't change what he says."},{"text":"This is gaslighting, a tactic, not my memory","then":"The word fits. The fog lifts a little.","best":true}],"why":"Making you doubt your memory is a control tactic called gaslighting, not a misunderstanding."},{"prompt":"Your friend Leela notices you apologising for things you didn't do. What do you do?","options":[{"text":"Laugh it off. You're just forgetful","then":"Leela lets it go, and you go home to the same fog."},{"text":"Ask Omkar's friends which version is true","then":"They side with him, and you feel even less sure."},{"text":"Tell her what's been happening with Omkar","then":"Leela listens closely. \"You're not imagining this. I believe you.\"","best":true},{"text":"Keep it private until you're sure who's right","then":"You wait for certainty, and it never quite comes."}],"why":"Someone you trust can confirm your reality. None of this is your fault."}],"debrief":"Gaslighting makes you distrust your own memory. Staying anchored to your reality counters it.","relearn":"Rewriting events so you doubt yourself is gaslighting; trust your memory."},
  {"id":"rr-1213","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"minimising","hook":"When your partner Kiran yells and blocks the door, you tell friends they just had a rough day.","steps":[{"prompt":"Your friend Zainab asks why you left the party early again. What do you say?","options":[{"text":"\"Kiran just had a rough day. It isn't that bad.\"","then":"Zainab nods slowly, and the talk moves on without you."},{"text":"\"I was tired. Nothing to do with Kiran.\"","then":"She accepts it, and the untruth sits heavy in your throat."},{"text":"\"Kiran got angry that I went. It scared me.\"","then":"Zainab puts her plate down. \"Scared you? Tell me what happened.\"","best":true},{"text":"\"It's complicated. You wouldn't get it.\"","then":"Zainab looks hurt and stops asking."}],"why":"Saying what happened plainly, instead of softening it, lets you and your friends see it."},{"prompt":"That night you replay the evening. What do you ask yourself?","options":[{"text":"What did I do to set Kiran off?","then":"You list your mistakes, and Kiran's yelling drops off the list."},{"text":"Would I call this okay if it happened to a friend?","then":"The answer comes fast: no. You sit with that.","best":true},{"text":"Isn't everyone's relationship a bit like this?","then":"You picture couples who seem fine, and decide they must be hiding it."},{"text":"Would it be calmer if I stopped going out?","then":"You start turning down plans before anyone asks."}],"why":"Seeing it as you would for a friend cuts through the excuses. It's never your fault."},{"prompt":"Zainab says you've seemed scared lately and asks what would help. What do you say?","options":[{"text":"\"Nothing. I'll handle it once things calm down.\"","then":"She says she's there anyway. You don't call."},{"text":"\"Talk to Kiran and tell them to be nicer.\"","then":"Zainab hesitates. \"Would that make it harder for you at home?\""},{"text":"\"Help me think about what's safe for me.\"","then":"Zainab nods. \"Okay. We'll work it out together, step by step.\"","best":true},{"text":"\"Promise you won't think badly of Kiran.\"","then":"\"I'm thinking about you,\" she says. What's safe stays unasked."}],"why":"Naming what you need, and planning with a friend, is how safety starts."}],"debrief":"Excusing control hides the red flag. Naming it honestly is how clarity and safety start.","relearn":"Stop minimising controlling behaviour; name it plainly to see it clearly."},
  {"id":"rr-1214","cat":"red-flags-grown-up","type":"branch","persona":"Rohan","source":"even-handed branch","hook":"Your mate Varun jokes that you're \"whipped\". Your girlfriend Nidhi tracks your location and vets your plans.","steps":[{"prompt":"The whole table laughs. What do you do?","options":[{"text":"Laugh along. Guys can't really be controlled","then":"Everyone moves on. Your phone buzzes: Nidhi, asking where you are."},{"text":"Brag that she's just crazy about you","then":"Varun whistles. You feel oddly hollow on the way home."},{"text":"Admit it's not funny. It feels like control","then":"The laughter dies. Varun looks at you properly. \"Wait. Seriously?\"","best":true},{"text":"Snap at them and walk off","then":"The table goes quiet. Later a text: \"Chill, bro. It was a joke.\""}],"why":"Taking it seriously lets you see it clearly. Control is control, whoever does it."},{"prompt":"That night Nidhi calls, upset you went off location sharing for an hour. How do you see it?","options":[{"text":"She's just protective. It means she cares","then":"The call ends warmly. You leave location sharing on for good."},{"text":"A real man handles this without complaining","then":"You swallow it, and it sits in your chest for days."},{"text":"Tracking and vetting me is control, not care","then":"It's uncomfortable to think. It also explains the knot in your stomach.","best":true},{"text":"Maybe I did make her worry for nothing","then":"You apologise, and promise to check in every hour."}],"why":"Anyone can be controlled. Tracking and vetting are control, even when they're called care."},{"prompt":"A few days later, Varun asks quietly if things are actually okay with Nidhi. What do you do?","options":[{"text":"Tell him the truth about the tracking","then":"Varun listens. \"Man, I had no idea. Sorry I joked about it.\"","best":true},{"text":"Say it's fine, so you don't look weak","then":"Varun nods, and it goes back to being a joke."},{"text":"Tell him to mind his own business","then":"Varun backs off. \"Okay, okay.\" The door closes."},{"text":"Blame yourself for letting her get this far","then":"Varun frowns, unsure what to say, and the moment passes."}],"why":"Talking to a mate you trust is strength, not weakness. Being controlled is never your fault."}],"debrief":"Control isn't a one-gender story. A man who is tracked and vetted is being controlled.","relearn":"Men can be controlled too; tracking and vetting is control, not 'whipped'."},
  {"id":"rr-1215","cat":"red-flags-grown-up","type":"branch","persona":"any","source":"guilt-debt","hook":"Your boyfriend Harsh keeps a tally of every favour he's done, and uses it to get his way.","steps":[{"prompt":"He says you owe him for your phone repair, so skip your cousin's birthday dinner. What do you do?","options":[{"text":"Decide he's right. A debt is a debt","then":"You skip the dinner. Your cousin texts: \"Missed you.\""},{"text":"Say plainly that love isn't a ledger you owe into","then":"Harsh scoffs. \"So I'm just an ATM to you?\" But the words are out.","best":true},{"text":"Offer to pay back the repair right away","then":"He takes the money, then mentions the cab rides from last month."},{"text":"Feel guilty, since he does do a lot for you","then":"The guilt decides for you, and you cancel on your cousin."}],"why":"Naming the ledger stops guilt from making your choices. Gifts aren't debts."},{"prompt":"A few days later, he lists everything he's done for you in front of friends. How do you see it?","options":[{"text":"He's right. I should be more grateful","then":"You thank him extra, and the list grows longer."},{"text":"It's awkward, but all couples keep score a bit","then":"You laugh it off, and the tally keeps running."},{"text":"I'll do more for him so we're finally even","then":"You start your own tally, and it never balances."},{"text":"Guilt used as leverage is control, not love","then":"You stop replaying the list. The pattern is clearer than the favours.","best":true}],"why":"Favours turned into debts that buy obedience are leverage. A healthy bond doesn't bill you."},{"prompt":"Your friend Irfan was there when Harsh read out his list. Later he asks if you're okay. What do you do?","options":[{"text":"Tell him about the tally and how it's used","then":"Irfan frowns. \"That's not how love works. I'm glad you told me.\"","best":true},{"text":"Defend Harsh: he's generous, just particular","then":"Irfan shrugs. \"If you say so.\" The subject closes."},{"text":"Say it'll be fine once you've paid him back","then":"Irfan looks doubtful. \"Paid back for what, exactly?\""},{"text":"Change the subject before he asks more","then":"Irfan lets it go. You go home still owing, somehow."}],"why":"Saying it out loud to a friend loosens the guilt's hold. It's never your fault."}],"debrief":"Guilt-debts and scorekeeping are leverage. A healthy bond doesn't bill you into obeying.","relearn":"Scorekeeping favours into a 'debt' to control you is a lever, not love."},
  {"id":"rr-1216","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: jealousy and possessiveness are about control, not the size of someone's love. Sit right?","prompt":"What do you think?","options":["Yes","About control","Not proof of love"],"affirm":"Reading jealousy as control, not love, is what keeps you clear when it gets romanticised.","relearn":"Jealousy and possessiveness are about control, not proof of love.","persona":"any","source":"jealousy reflect"},
  {"id":"rr-1217","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: being controlled is never a sign you're weak or stupid. It's engineered to trap anyone. Hear that?","prompt":"What do you think?","options":["Yes","Not my failing","It traps anyone"],"affirm":"Control traps capable, clever people by design; if it happened to you, that's on the controller.","relearn":"Being controlled is never weakness; control is engineered to trap anyone.","persona":"any","source":"not weakness reflect"},
  {"id":"rr-1218","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: notice how your world feels: bigger and freer, or smaller and watched? Worth checking in?","prompt":"How does your world feel lately?","options":["Bigger and freer","Smaller and watched","I'm not sure yet"],"affirm":"That feel, expanding or shrinking, is real data; a world quietly shrinking is a red flag worth trusting.","relearn":"A shrinking, watched-feeling world is a red flag worth trusting.","persona":"any","source":"world-feel reflect"},
  {"id":"rr-1219","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: if a relationship controls, isolates or frightens you, none of it is your fault. Take that in?","prompt":"What do you think?","options":["Yes","Not my fault","I needed that"],"affirm":"Control and abuse are never the target's fault; the responsibility sits fully with the person doing it.","relearn":"Control, isolation or fear in a relationship is never your fault.","persona":"any","source":"not your fault reflect"},
  {"id":"rr-1220","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: real love keeps you whole. Your friends, identity and space stay yours. Feel the truth in it?","prompt":"What do you think?","options":["Yes","Still whole","Mine to keep"],"affirm":"Healthy love never asks you to disappear; staying whole is the sign it's the real thing.","relearn":"Real love keeps you whole; your friends, identity and space stay yours.","persona":"any","source":"stay whole reflect"},
  {"id":"rr-1221","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: 'they're just protective' is how isolation gets romanticised. Worth keeping an eye on?","prompt":"What do you think?","options":["Yes","I'll watch for it","Protective vs isolating"],"affirm":"Naming the difference between protective and isolating keeps a control tactic from passing as love.","relearn":"'Just protective' is how isolation gets romanticised; name the difference.","persona":"any","source":"protective vs isolating reflect"},
  {"id":"rr-1222","cat":"red-flags-grown-up","type":"reflect","hook":"Lensy: anyone, any gender, can be controlled or do the controlling, and be believed. Land for you?","prompt":"What do you think?","options":["Yes","Any gender","Believed equally"],"affirm":"Control isn't a one-gender story; whoever it happens to deserves to be believed and supported.","relearn":"Anyone of any gender can be controlled or controlling, and be believed.","persona":"any","source":"even-handed reflect"},
  {"id":"rr-1223","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"refuse tracking","hook":"Your boyfriend Aryan wants your live location on at all times.","setup":"He brings it up over coffee, half smiling.","steps":[{"prompt":"Aryan says: \"If you've got nothing to hide, why not share it?\"","options":[{"text":"\"You're right. If I've nothing to hide, why not?\"","then":"He beams and switches it on for you. \"See? Easy.\""},{"text":"\"Wanting privacy isn't hiding. I won't be tracked.\"","then":"His smile fades. \"Wow. Okay. I just worry about you.\"","best":true},{"text":"\"Fine. But then I get to track you as well.\"","then":"\"Deal,\" he says quickly. Now you're both watching dots on a map."},{"text":"\"You're so insecure. It's honestly pathetic.\"","then":"His jaw tightens. \"Nice. Really nice.\""}],"why":"Privacy isn't secrecy. You can refuse to be tracked and still be trustworthy."},{"prompt":"Aryan says: \"I just need to know you're safe. Every minute.\"","options":[{"text":"\"Nothing will happen. Stop being dramatic.\"","then":"\"So now I'm dramatic?\" he asks, voice rising."},{"text":"\"I guess love does mean keeping tabs.\"","then":"\"Exactly,\" he says, and asks for your phone password too."},{"text":"\"I'll text when I'm out late. That's my choice.\"","then":"He pauses. \"Fine. I still don't like it.\"","best":true},{"text":"\"Then I'll share it whenever you're feeling anxious.\"","then":"\"I'm always anxious about you,\" he says, smiling."}],"why":"Checking in because you choose to is care. Being tracked on demand is control."},{"prompt":"Aryan says: \"Everyone shares everything these days. It's normal.\"","options":[{"text":"\"You're right. Maybe I'm the weird one.\"","then":"\"You kind of are,\" he says, and reaches for your phone."},{"text":"\"Fine. For a week, to prove I'm trustworthy.\"","then":"A week turns into a month. He asks why you stopped at a café."},{"text":"\"Everyone? Name one person, then.\"","then":"He names three. The argument goes round in circles."},{"text":"\"Others can choose that. I'm choosing not to.\"","then":"He goes quiet, scrolling his phone without looking at it.","best":true}],"why":"You decide what you share. Refusing surveillance isn't weird. It's healthy."},{"prompt":"Your friend Nandini asks: \"You've seemed off all day. Everything okay?\"","options":[{"text":"\"Yeah. Just tired.\"","then":"\"Okay,\" she says, and the chance to talk slips by."},{"text":"\"He only asks because he loves me so much.\"","then":"Nandini raises an eyebrow. \"Is that how it feels?\""},{"text":"\"I must be giving him reasons to worry about me.\"","then":"Nandini frowns. \"What reasons? You're at college and at home.\""},{"text":"\"Aryan wants to track me. It's bothering me.\"","then":"Nandini puts her phone down. \"That would bother me too. Tell me.\"","best":true}],"why":"Talking to a friend keeps your view clear. Being monitored is never your fault."}],"relearn":"Privacy isn't hiding; you can refuse to be tracked and still be trustworthy."},
  {"id":"rr-1224","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"refuse isolation","hook":"Your partner Mehul tells you to delete your close friend Sana's number, \"or else\".","setup":"He's waiting, arms crossed.","steps":[{"prompt":"Mehul says: \"Delete it now. I won't ask again.\"","options":[{"text":"\"If you love someone, you give things up for them.\"","then":"\"Exactly,\" Mehul says, and watches you scroll to her name."},{"text":"\"Sana's done nothing. You're paranoid!\"","then":"\"Paranoid?\" His voice rises, and he steps closer."},{"text":"\"I'm keeping my friends. I won't cut Sana off.\"","then":"He stares at you. \"So she matters more than me?\"","best":true},{"text":"\"Maybe I do spend too much time with her.\"","then":"\"You do,\" he says, softening. \"So you get it.\""}],"why":"You can keep your friends. Cutting them off on demand is isolation, not love."},{"prompt":"Mehul says: \"And if I ever see you with her, you'll regret it.\"","options":[{"text":"\"You'd never really hurt me. I know you.\"","then":"\"Don't test me,\" he says quietly."},{"text":"\"That sounds like a threat. I'm going now.\"","then":"\"Go, then,\" he says. You pick up your bag and leave.","best":true},{"text":"\"Go ahead. I'm not scared of you.\"","then":"His face darkens, and the room feels much smaller."},{"text":"\"If I explain Sana properly, you'll understand.\"","then":"You explain for twenty minutes. He only grows colder."}],"why":"A threat is a line crossed. Leaving the room is the safest move, and none of it is your fault."},{"prompt":"Later, Sana asks on the phone: \"You sound shaken. What happened?\"","options":[{"text":"\"Nothing much. Just a silly fight.\"","then":"\"Okay,\" Sana says, unsure. \"But I know that voice. Talk to me.\""},{"text":"\"It's my fault. I shouldn't have mentioned you.\"","then":"\"Your fault? What did he say?\" Sana sounds worried."},{"text":"\"Mehul threatened me over you. Can I come over?\"","then":"\"Come right now,\" Sana says. \"I'll put the kettle on.\"","best":true},{"text":"\"I'm going to tell everyone what he's like.\"","then":"\"Wait,\" Sana says. \"Are you safe to do that?\""}],"why":"Telling a friend and getting somewhere safe means you don't face a threat alone."},{"prompt":"Sana asks: \"If Mehul leaves you this shaken again, what will you do?\"","options":[{"text":"\"He was just angry. He didn't mean it.\"","then":"Sana is quiet for a while. \"Just promise you'll call me.\""},{"text":"\"Leave, come to you, and call 112 if I'm in danger.\"","then":"\"Save my number at the top,\" she says. \"Day or night.\"","best":true},{"text":"\"If I'm more careful, it won't happen again.\"","then":"Sana sighs. \"I'll keep my phone on anyway.\""},{"text":"\"I'll handle him myself. I don't want any drama.\"","then":"\"Alone?\" Sana asks. \"Please don't.\""}],"why":"A plan to get safe, and 112, means help is ready if it happens again."}],"relearn":"You get to keep your friends; cutting them off on demand is isolation you can refuse."},
  {"id":"rr-1225","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"name gaslighting","hook":"Mid-argument, you bring up something your girlfriend Shruti did that hurt you.","setup":"It's about the party she walked out of.","steps":[{"prompt":"Shruti says: \"That never happened. You're imagining things again.\"","options":[{"text":"\"Maybe you're right. Maybe I imagined it.\"","then":"\"See?\" she says. \"This is what you always do.\""},{"text":"\"I remember it clearly. I trust my memory.\"","then":"She laughs. \"Your memory? Seriously?\"","best":true},{"text":"\"You're a liar, and you know it!\"","then":"\"Wow,\" she says coldly. \"And you wonder why we fight.\""},{"text":"\"Let me show you the texts to prove it.\"","then":"She scrolls, then shrugs. \"That doesn't prove what you think.\""}],"why":"You can trust your own memory. It doesn't need her agreement to be real."},{"prompt":"Shruti says: \"You're so sensitive. No one else would put up with you.\"","options":[{"text":"\"You're right. I'm lucky you stay.\"","then":"She softens. \"I just want you to see yourself clearly.\""},{"text":"\"No one else would put up with you either!\"","then":"The fight gets louder, and now it's about everything."},{"text":"\"I'll work on being less sensitive. I promise.\"","then":"\"Good,\" she says. \"That's all I've ever asked.\""},{"text":"\"I won't be talked out of what I know happened.\"","then":"She rolls her eyes and walks out. The room goes quiet.","best":true}],"why":"Being told you're too sensitive to trust your memory is gaslighting. Your reality counts."},{"prompt":"Your friend Dhruv asks: \"You've seemed shaken since your fight with Shruti. What's going on?\"","options":[{"text":"\"Nothing. My memory's just bad lately.\"","then":"Dhruv looks unconvinced, but lets it go."},{"text":"\"She denies things I remember. It's scary.\"","then":"Dhruv nods slowly. \"That sounds like gaslighting. You're not imagining it.\"","best":true},{"text":"\"We just remember things differently. It's normal.\"","then":"\"Sure,\" Dhruv says. The worry in your chest stays put."},{"text":"\"I'll figure it out myself. It's my relationship.\"","then":"Dhruv backs off. You go home to the same doubts."}],"why":"A trusted friend helps you hold on to your reality. Gaslighting is never your fault."}],"relearn":"You can trust your own memory and refuse to be talked out of your reality."},
  {"id":"rr-1226","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"name jealousy","hook":"You catch your partner Kavya going through your phone again.","setup":"She doesn't put it down.","steps":[{"prompt":"Kavya says: \"I only check because I love you so much. I get jealous.\"","options":[{"text":"\"Aww. I guess it's sweet that you care that much.\"","then":"She smiles and keeps scrolling. \"So who's this Rohit?\""},{"text":"\"Checking my phone isn't love. It's control.\"","then":"She flushes. \"Control? I'm just scared of losing you.\"","best":true},{"text":"\"Fine. But next time, ask before you look.\"","then":"\"Deal,\" she says, and asks every single night."},{"text":"\"Give it back. You've got real trust issues.\"","then":"\"Trust issues? You're the one hiding things,\" she snaps."}],"why":"Jealousy and checking are control, not proof of love. You can say so kindly and clearly."},{"prompt":"Kavya says: \"Real love means no secrets. I should see everything.\"","options":[{"text":"\"Check whenever you want. I've nothing to hide.\"","then":"She takes you at your word, and checks every night."},{"text":"\"I'll send you screenshots of my chats instead.\"","then":"\"That would help,\" she says, relieved. Soon she wants more."},{"text":"\"I do love you. I need trust, not surveillance.\"","then":"She's quiet. \"I don't know how to trust like that.\"","best":true},{"text":"\"You're just like your mother, you know that?\"","then":"Kavya goes white, and the fight turns into something else."}],"why":"Love and privacy go together. Trust can't be built by watching."},{"prompt":"Your friend Sahil asks: \"Why do you keep flipping your phone face down?\"","options":[{"text":"\"Habit. It's nothing.\"","then":"Sahil shrugs, and you flip it again when it buzzes."},{"text":"\"She's jealous because she loves me. It's cute.\"","then":"Sahil raises an eyebrow. \"Cute? Does it feel cute?\""},{"text":"\"I've probably given her reasons, honestly.\"","then":"Sahil frowns. \"Like what?\" You can't really name one."},{"text":"\"Kavya checks it. I'm starting to feel watched.\"","then":"Sahil puts down his tea. \"That's a lot. Want to talk about it?\"","best":true}],"why":"Telling a friend how it feels keeps you clear. Being watched is never your fault."}],"relearn":"Phone-checking 'out of love' is control; you can name it and ask for trust."},
  {"id":"rr-1227","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"support a friend","hook":"Your friend Priyanka mentions, laughing, that her boyfriend tracks her location and vets who she texts.","setup":"You're walking back from the canteen.","steps":[{"prompt":"Priyanka says: \"It's kind of sweet, right? He just worries.\"","options":[{"text":"\"He probably just loves you. Don't overthink it.\"","then":"\"Yeah,\" she says, relieved. Then, quieter: \"It scares me sometimes.\""},{"text":"\"That sounds like control, not care. How does it feel?\"","then":"Her laugh fades. \"Honestly? Like I'm always being watched.\"","best":true},{"text":"\"That's messed up. Why would you put up with that?\"","then":"She stiffens. \"It's not that deep,\" she says. Her voice wobbles."},{"text":"\"Ha. At least he's not ignoring you.\"","then":"She laughs along, then stops. \"It's not always funny, though.\""}],"why":"Naming it gently, and asking how it feels, lets her look at it without feeling judged."},{"prompt":"Priyanka asks: \"Do you think I'm stupid for letting him?\"","options":[{"text":"\"A little. You're better than this.\"","then":"\"Right,\" she says quietly, pulling her sleeves over her hands."},{"text":"\"It's your life. I don't want to get involved.\"","then":"She nods and walks a little faster."},{"text":"\"If you're not, you'll dump him today.\"","then":"\"Easy for you to say,\" she snaps, and the walk goes quiet."},{"text":"\"No. It isn't your fault. This traps smart people.\"","then":"She blinks back tears. \"I've been feeling so stupid.\"","best":true}],"why":"Control traps capable people by design. Saying it's not her fault lifts the shame."},{"prompt":"Priyanka asks: \"Please don't tell anyone, okay?\"","options":[{"text":"\"Not unless you're unsafe. And there's 181.\"","then":"She squeezes your arm. \"Thanks. I'll save it under another name.\"","best":true},{"text":"\"I have to tell your parents. It's serious.\"","then":"\"Please don't,\" she says, scared. \"I'll just stop telling you things.\""},{"text":"\"Fine, but only if you leave him.\"","then":"She stares at you. \"That's not fair.\""},{"text":"\"Sure. Let's pretend this never came up.\"","then":"She nods, relieved, and neither of you mentions it again."}],"why":"Keeping her trust, being honest about safety and naming where help is makes you a real lifeline."}],"relearn":"Name a friend's situation as control, not care, and stay a steady, non-judging lifeline."},
  {"id":"rr-1228","cat":"red-flags-grown-up","type":"role-play","persona":"any","source":"refuse blame-shift","hook":"Tonight your boyfriend Siddharth blew up at you over a late reply.","setup":"An hour later, his voice is calmer.","steps":[{"prompt":"Siddharth says: \"You made me lose it. If you behaved, I wouldn't get like that.\"","options":[{"text":"\"You're right. I'll try harder not to set you off.\"","then":"He nods, satisfied. \"That's all I'm asking.\""},{"text":"\"How you react is your choice. I won't carry the blame.\"","then":"His eyes narrow. \"So it's all my fault now?\"","best":true},{"text":"\"We both get heated. It's on both of us.\"","then":"He softens. \"Exactly. So let's both do better.\""},{"text":"\"You're a monster. Everyone should know.\"","then":"His face hardens, and he takes a step towards you."}],"why":"His anger is his responsibility, never your fault. If you ever feel unsafe, step away first."},{"prompt":"Siddharth says: \"You know how I get when you push me. So stop pushing.\"","options":[{"text":"\"Maybe you're right. I do push too much.\"","then":"\"I'm glad you see it,\" he says, and the blame settles on you."},{"text":"\"Then let's sit down and fix this together.\"","then":"He agrees, and the talk turns into a list of what you do wrong."},{"text":"\"I'm going to step out for a while.\"","then":"\"Fine, go,\" he mutters. You grab your phone and leave.","best":true},{"text":"\"Say that again and see what happens.\"","then":"He steps closer. The room suddenly feels very small."}],"why":"When someone's anger scares you, getting space is the safe move. It is never your fault."},{"prompt":"Your cousin Anjali asks on the phone: \"Did something happen? You sound off.\"","options":[{"text":"\"No, nothing. I'm just tired.\"","then":"\"Okay,\" she says slowly. \"You'd tell me if Sid was scaring you, right?\""},{"text":"\"Sid blew up and blamed me. I'm scared.\"","then":"\"Where are you now?\" Anjali asks. \"Come to mine. I'm here.\"","best":true},{"text":"\"We had a fight. It was my fault really.\"","then":"\"Your fault how?\" she asks. \"Did he scare you?\""},{"text":"\"He's got a temper. Don't tell anyone, okay?\"","then":"\"Not unless you're in danger,\" she says slowly. \"What does a temper mean?\""}],"why":"Telling someone you trust means you're not alone with it."},{"prompt":"Anjali asks: \"If it ever feels unsafe with Sid, what's your plan?\"","options":[{"text":"\"It won't. He's not usually like this.\"","then":"Anjali pauses. \"I hope not. But I'm keeping my phone on.\""},{"text":"\"Love him through it. He's had a hard life.\"","then":"Anjali sighs. \"That's a lot to carry on your own.\""},{"text":"\"Leave right away, and call 181 or 112.\"","then":"\"Okay,\" Anjali says. \"And my door's open, any hour.\"","best":true},{"text":"\"Confront him in front of his friends.\"","then":"Anjali hesitates. \"Would that make him angrier at you?\""}],"why":"A plan to leave fast and call for help keeps you safer. You can't love him out of it."}],"relearn":"Their reactions are their choice; you don't have to carry the blame for control."},
  {"id":"rr-1229","cat":"red-flags-grown-up","type":"role-play","persona":"Rohan","source":"even-handed role-play","hook":"Your girlfriend Ishita reads your chats and decides which friends you can keep.","setup":"Tonight it's your friend Manav's turn.","steps":[{"prompt":"Ishita says: \"Manav's a bad influence. I've read your chats. Drop him.\"","options":[{"text":"\"A good boyfriend does what his girlfriend asks.\"","then":"Ishita smiles. \"See? That's why I love you.\""},{"text":"\"Guys don't get controlled. You're just nagging.\"","then":"\"Nagging?\" she snaps. \"I'm protecting you.\""},{"text":"\"Reading my chats and picking my friends is control.\"","then":"Ishita blinks. \"Control? I'm looking out for you.\"","best":true},{"text":"\"Fine, but then you drop your friends too.\"","then":"\"That's different,\" she says. The argument goes in circles."}],"why":"Naming it as control, not nagging, lets you see it clearly. Men can be controlled too."},{"prompt":"Ishita asks: \"Why do you need anyone else if you have me?\"","options":[{"text":"\"You're right. You're all I need.\"","then":"She hugs you. Over the next month your group chat goes quiet."},{"text":"\"Maybe I'm too dependent on my friends.\"","then":"\"You are,\" she says gently. \"That's all I'm saying.\""},{"text":"\"I want trust, not a leash. My friends stay.\"","then":"She goes quiet. \"I just don't want to lose you.\"","best":true},{"text":"\"You sound unhinged when you talk like that.\"","then":"Her face drops, and the fight gets personal fast."}],"why":"A healthy relationship keeps your friends in your life. Love expands your world."},{"prompt":"Manav texts: \"Bro, you've gone missing. All good?\"","options":[{"text":"\"All good, bro. Just busy.\"","then":"\"Cool,\" he replies. The chat goes quiet again."},{"text":"\"I'm fine. A man handles his own stuff.\"","then":"\"Sure,\" he replies, a bit confused."},{"text":"\"It's my fault. I've been a rubbish friend.\"","then":"\"Nah,\" Manav replies. \"What's going on, though?\""},{"text":"\"Not really. Things with Ishita are hard. Talk?\"","then":"\"Always,\" Manav replies. \"Chai at six?\"","best":true}],"why":"Reaching out to a friend is strength, not weakness. Being controlled is never your fault."}],"relearn":"A man can name being controlled too; chat-reading and friend-vetting is control, not closeness."},
  {"id":"rr-1230","cat":"red-flags-grown-up","type":"role-play","persona":"Zoya","source":"outing threat","hook":"Whenever you push back on something, your girlfriend Ritu threatens to out you to your parents.","setup":"Tonight you said no to her plan.","steps":[{"prompt":"Ritu says: \"Fine. Maybe your parents should hear about us, then.\"","options":[{"text":"\"I'm sorry. I shouldn't have argued with you.\"","then":"\"That's better,\" she says, and the plan is hers again."},{"text":"\"Using my coming out as a threat is control.\"","then":"Ritu rolls her eyes. \"Relax. I'm just saying.\"","best":true},{"text":"\"Go ahead. Tell them. See if I care.\"","then":"\"Don't tempt me,\" Ritu says, already holding her phone."},{"text":"\"You'd never actually do that. You love me.\"","then":"She shrugs. \"Try me,\" she says lightly."}],"why":"Threatening to out you is control. Your coming out is yours, never a weapon against you."},{"prompt":"Later, Ritu says: \"You know I'd never really tell them. It's just a joke.\"","options":[{"text":"\"You're right. I take things too seriously.\"","then":"\"You always do,\" she says, and kisses your forehead."},{"text":"\"I guess couples joke like that sometimes.\"","then":"\"Exactly,\" she says, and the threat becomes a normal thing."},{"text":"\"It didn't feel like a joke. It scared me.\"","then":"She looks away. \"You're so dramatic about everything.\"","best":true},{"text":"\"Then I'll out you to your friends too.\"","then":"Ritu's face goes hard. \"Now who's threatening who?\""}],"why":"A threat called a joke is still a threat. Saying how it felt is honest."},{"prompt":"Your friend Neha asks: \"You've seemed on edge all week. What's going on?\"","options":[{"text":"\"Nothing. Just exams.\"","then":"\"Okay,\" Neha says. \"But you go quiet every time Ritu calls.\""},{"text":"\"It's my fault. I shouldn't have told her so much.\"","then":"Neha frowns. \"Told her what? Is this about Ritu?\""},{"text":"\"Ritu's insecure. She'd never really do it.\"","then":"\"Are you sure?\" Neha asks. You aren't."},{"text":"\"Ritu keeps threatening to out me. I'm scared.\"","then":"Neha sits down beside you. \"That's awful. You're not alone in this.\"","best":true}],"why":"Telling a trusted friend means you don't carry a threat alone. It's never your fault."},{"prompt":"Neha asks: \"About Ritu. What would help you feel safe?\"","options":[{"text":"\"Post screenshots of her threats online.\"","then":"Neha winces. \"That could make her lash out. Are you sure?\""},{"text":"\"Talk to a counsellor and work out what's safe.\"","then":"\"I'll come with you,\" Neha says. \"Whatever you decide, I'm with you.\"","best":true},{"text":"\"Nothing. It's just hard for people like us.\"","then":"Neha shakes her head gently. \"Hard, maybe. Not like this.\""},{"text":"\"Ask her mother to make her stop.\"","then":"Neha hesitates. \"Then her family knows too. Is that safe?\""}],"why":"Planning with support makes you safer, and when and how you come out is still your choice."}],"relearn":"Threatening to out you is control; your coming-out is yours, never a weapon against you."},
  {"id":"rr-1231","cat":"red-flags-grown-up","type":"match","hook":"Match the controlling move to the tactic it really is.","pairs":[{"left":"Demands your passwords","right":"Monitoring"},{"left":"Cuts you off from friends","right":"Isolation"},{"left":"Says 'that never happened'","right":"Gaslighting"},{"left":"'I get jealous, so I love you'","right":"Possessiveness as 'love'"},{"left":"Controls all the money","right":"Financial control"}],"relearn":"Passwords, cut-off friends, denied reality, jealousy-as-love and money control are named control tactics.","persona":"any","source":"name the tactic"},
  {"id":"rr-1232","cat":"red-flags-grown-up","type":"match","hook":"Match the romanticised line to the red flag underneath it.","pairs":[{"left":"\"They're just protective\"","right":"Isolation"},{"left":"\"They check because they care\"","right":"Monitoring"},{"left":"\"Their jealousy proves their love\"","right":"Control"},{"left":"\"We don't need anyone but each other\"","right":"Cutting off support"},{"left":"\"They can't live without me\"","right":"Guilt as leverage"}],"relearn":"Protective, caring checks, jealousy, 'only each other' and 'can't live without me' often hide control.","persona":"any","source":"unmask the line"},
  {"id":"rr-1233","cat":"red-flags-grown-up","type":"match","hook":"Match the red flag to its calm green-flag counterpart.","pairs":[{"left":"Tracks your every move","right":"Trusts you when you're out"},{"left":"Picks your friends for you","right":"Glad you have your own friends"},{"left":"Rewrites what happened","right":"Owns their part honestly"},{"left":"Sulks at your alone time","right":"Respects your space"},{"left":"Vetoes how you spend","right":"Decides money together"}],"relearn":"Each control move has a healthy counterpart: trust, your own friends, honesty, space, shared money.","persona":"any","source":"red vs green"},
  {"id":"rr-1234","cat":"red-flags-grown-up","type":"match","hook":"Match the gaslighting line to what it's doing to you.","pairs":[{"left":"\"You're imagining it\"","right":"Denying your memory"},{"left":"\"You're too sensitive\"","right":"Dismissing your feelings"},{"left":"\"You made me do it\"","right":"Shifting the blame"},{"left":"\"Everyone agrees you're crazy\"","right":"Isolating your reality"},{"left":"\"I never said that\"","right":"Rewriting events"}],"relearn":"Gaslighting denies memory, dismisses feelings, shifts blame, isolates you and rewrites events.","persona":"any","source":"gaslighting moves"},
  {"id":"rr-1235","cat":"red-flags-grown-up","type":"match","hook":"Match the control tactic to the freedom it quietly takes.","pairs":[{"left":"Monitoring your phone","right":"Your privacy"},{"left":"Isolating you from friends","right":"Your support"},{"left":"Controlling the money","right":"Your independence"},{"left":"Dictating your clothes","right":"Your self-expression"},{"left":"Vetoing your plans","right":"Your free time"}],"relearn":"Control takes something real: your privacy, support, independence, expression and free time.","persona":"any","source":"what control takes"},
  {"id":"rr-1236","cat":"red-flags-grown-up","type":"match","hook":"Match the early warning sign to why it's a red flag.","pairs":[{"left":"Love-bombing in week one","right":"Rushes you past your judgement"},{"left":"Sulking at your independence","right":"Punishes you for a life of your own"},{"left":"Put-down 'jokes'","right":"Chips at your confidence"},{"left":"Testing your loyalty","right":"Manufactures control early"},{"left":"Tracking 'just to feel safe'","right":"Normalises monitoring"}],"relearn":"Love-bombing, sulking, put-down jokes, loyalty-tests and early tracking are warning signs, not phases.","persona":"any","source":"early warning signs"},
  {"id":"rr-1237","cat":"red-flags-grown-up","type":"match","hook":"Match the support a friend in a controlling relationship needs to what it sounds like.","pairs":[{"left":"Believing them","right":"\"I believe you\""},{"left":"No blame","right":"\"None of this is your fault\""},{"left":"Staying connected","right":"\"I'm here, no judgement\""},{"left":"A real route","right":"\"181, 1091 or 112 if it's unsafe\""},{"left":"Their pace","right":"\"You decide what's next\""}],"relearn":"A friend needs belief, no blame, a steady connection, real routes (181/1091/112) and their own pace.","persona":"any","source":"supporting routes"},
  {"id":"rr-1238","cat":"red-flags-grown-up","type":"match","hook":"Match each gut feeling to the red flag it may be pointing at.","pairs":[{"left":"Walking on eggshells","right":"Living around their moods"},{"left":"Your world feels smaller","right":"Isolation creeping in"},{"left":"Always being watched","right":"Monitoring"},{"left":"Doubting your own memory","right":"Gaslighting"},{"left":"Asking permission to exist","right":"Coercive control"}],"relearn":"Eggshells, a shrinking world, feeling watched, self-doubt and asking permission name real red flags.","persona":"any","source":"feeling to flag"},
  {"id":"rr-1240","cat":"red-flags-grown-up","type":"sort","hook":"Sort: a free yes, or coercion?","items":[{"id":"a","text":"\"I want to, on my own terms\""},{"id":"b","text":"\"I said yes so they'd stop sulking\""},{"id":"c","text":"\"We both chose this together\""},{"id":"d","text":"\"I agreed to avoid a blow-up\""},{"id":"e","text":"\"No pressure either way\""},{"id":"f","text":"\"I gave in to their threats\""}],"bins":[{"id":"free","label":"Free yes","valence":"pos"},{"id":"coerced","label":"Coerced","valence":"neg"}],"key":{"a":"free","b":"coerced","c":"free","d":"coerced","e":"free","f":"coerced"},"relearn":"A yes you chose freely is real; a yes to stop sulking, threats or a blow-up is coercion.","persona":"any","source":"free vs coerced"},
  {"id":"rr-1260","cat":"tools-and-help","type":"match","persona":"Meena, 20","source":"route map","relearn":"Violence: 181/1091/112. Heavy low mood: Tele-MANAS 14416. To decide or plan: a trusted person.","hook":"Match the situation to who to reach in India.","pairs":[{"left":"He's threatening to hit me","right":"181 / 1091 / 112"},{"left":"Can't stop crying for weeks","right":"Tele-MANAS 14416"},{"left":"No campus, no counsellor","right":"A trusted neighbour"},{"left":"Just need to decide","right":"Someone steady you trust"},{"left":"Want it written down safely","right":"A note kept off your phone"}]},
  {"id":"rr-1261","cat":"tools-and-help","type":"match","persona":"any","source":"i-statement kit","relearn":"An 'I felt...' line names your hurt without an attack, so the other person can actually hear it.","hook":"Match the blaming line to its 'I felt...' rewrite.","pairs":[{"left":"You never listen","right":"I feel unheard when I'm talking"},{"left":"You always ditch me","right":"I felt let down on Friday"},{"left":"You're so controlling","right":"I need to keep my own plans"},{"left":"You ruined everything","right":"I'm hurt by what happened"},{"left":"You don't care","right":"I'd love to feel a priority"}]},
  {"id":"rr-1262","cat":"tools-and-help","type":"match","persona":"any","source":"green markers","relearn":"Respect, trust, equality, independence and repair each show up as everyday habits, not grand words.","hook":"Match each healthy marker to what it looks like day-to-day.","pairs":[{"left":"Respect","right":"Your no is taken seriously"},{"left":"Trust","right":"No need to check each other"},{"left":"Equality","right":"Decisions are shared"},{"left":"Independence","right":"You keep your own friends"},{"left":"Repair","right":"You both circle back after a fight"}]},
  {"id":"rr-1263","cat":"tools-and-help","type":"match","persona":"any","source":"control decoder","relearn":"Phone-checking, cutting off friends, rewriting reality, tracking and jealousy are control dressed as love.","hook":"Match the romanticised line to what it really is.","pairs":[{"left":"He checks my phone 'cause he cares","right":"Monitoring"},{"left":"She hates my friends, so protective","right":"Isolation"},{"left":"Says I imagined the whole fight","right":"Gaslighting"},{"left":"Wants my location 'for safety'","right":"Tracking"},{"left":"Gets jealous, must be love","right":"Possessiveness"}]},
  {"id":"rr-1264","cat":"tools-and-help","type":"match","persona":"Zoya, 21","source":"breakup toolkit","relearn":"No-contact, routine, naming feelings, support and Tele-MANAS 14416 are real tools for getting through a breakup.","hook":"Match the breakup tool to what it's for.","pairs":[{"left":"No-contact","right":"Space to actually heal"},{"left":"Keeping your routine","right":"Ground under your feet"},{"left":"Naming the feeling","right":"Letting grief move"},{"left":"Leaning on chosen family","right":"Support, not toughing it out"},{"left":"Tele-MANAS 14416","right":"When low mood won't lift"}]},
  {"id":"rr-1265","cat":"tools-and-help","type":"match","persona":"any","source":"exit plan","relearn":"Telling someone, a safe place, your documents, the helplines and timing make leaving safer.","hook":"Match each exit-plan step to why it matters.","pairs":[{"left":"Tell someone you trust","right":"You're not alone in it"},{"left":"Have a safe place","right":"Somewhere to go fast"},{"left":"Gather key documents","right":"ID and papers in hand"},{"left":"Know the helplines","right":"181 / 1091 / 112 ready"},{"left":"Pick a calm moment","right":"Lower the risk of escalation"}]},
  {"id":"rr-1266","cat":"tools-and-help","type":"match","persona":"any","source":"flooded fix","relearn":"Break when flooded, return to repair, pause before cruelty, 'I' statements when calm, target the problem.","hook":"Match what you're feeling to the right move.","pairs":[{"left":"Heart racing, can't think","right":"Take a calming break"},{"left":"Calmer now, still hurt","right":"Come back and repair"},{"left":"About to say something cruel","right":"Pause before you speak"},{"left":"Hurt but not flooded","right":"Use an 'I felt...' line"},{"left":"Wanting to win the fight","right":"Aim at the problem instead"}]},
  {"id":"rr-1267","cat":"tools-and-help","type":"match","persona":"any","source":"myth buster","relearn":"Jealousy is control, repair beats no-fights, leaving is brave, love keeps you whole, you can't fix a controller.","hook":"Match the myth to the truth that replaces it.","pairs":[{"left":"Jealousy means they love you","right":"Jealousy is about control"},{"left":"Fighting means you're doomed","right":"Repair matters more than no fights"},{"left":"Leaving means you failed","right":"Leaving can be brave"},{"left":"Real love means losing yourself","right":"Healthy love keeps you whole"},{"left":"You can fix them by loving more","right":"It isn't yours to fix"}]},
  {"id":"rr-1268","cat":"tools-and-help","type":"match","persona":"Ananya, 19","source":"who-to-call","relearn":"181 and 1091 for women, 112 for emergencies, Tele-MANAS 14416 for the mind, a counsellor to talk it out.","hook":"Match each India helpline to what it's for.","pairs":[{"left":"181","right":"Women's helpline"},{"left":"1091","right":"Women in distress"},{"left":"112","right":"Emergency"},{"left":"Tele-MANAS 14416","right":"Mental-health support"},{"left":"A counsellor","right":"Talking it through"}]},
  {"id":"rr-1269","cat":"tools-and-help","type":"match","persona":"any","source":"boundary scripts","relearn":"Calm boundary lines hold your phone, friends, location and trust without a fight or an apology.","hook":"Match the pressure to a calm boundary line.","pairs":[{"left":"'Send your password if you love me'","right":"'My phone stays mine'"},{"left":"'Skip your friends for me'","right":"'I'm keeping Saturday for them'"},{"left":"'Share your location always'","right":"'I'll text when I'm home'"},{"left":"'Tell me everywhere you go'","right":"'I don't owe a full report'"},{"left":"'Prove you're not lying'","right":"'I won't keep proving myself'"}]},
  {"id":"rr-1270","cat":"tools-and-help","type":"match","persona":"any","source":"repair phrases","relearn":"A small repair line resets a fight, owns your part, asks for a break, apologises or reconnects.","hook":"Match the repair attempt to the moment it fits.","pairs":[{"left":"'Can we start over?'","right":"Mid-fight reset"},{"left":"'I hear you, that's fair'","right":"Owning your part"},{"left":"'I need five minutes'","right":"Asking for a break"},{"left":"'I'm sorry for my tone'","right":"After being harsh"},{"left":"'What do you need now?'","right":"Reconnecting after"}]},
  {"id":"rr-1271","cat":"tools-and-help","type":"match","persona":"any","source":"intensity vs love","relearn":"Intensity isn't proof of love; room, trust and celebrating your wins are the real green flags.","hook":"Match the intense sign to what it actually points to.","pairs":[{"left":"Texts a hundred times a day","right":"Possible control"},{"left":"Wants you all to themselves","right":"Isolation risk"},{"left":"Whirlwind, no space to breathe","right":"A pace to question"},{"left":"Gives you room and trust","right":"A genuine green flag"},{"left":"Celebrates your own wins","right":"Real, secure love"}]},
  {"id":"rr-1272","cat":"tools-and-help","type":"match","persona":"any","source":"self-check","relearn":"Friends, your voice, a growing world, respect and ease are the things a quick self-check looks at.","hook":"Match the question to the part of you it checks.","pairs":[{"left":"Do I still see my friends?","right":"Your independence"},{"left":"Can I disagree safely?","right":"Your voice"},{"left":"Has my world grown?","right":"The expand-or-shrink test"},{"left":"Do I feel respected?","right":"Your worth"},{"left":"Am I walking on eggshells?","right":"Your safety"}]},
  {"id":"rr-1273","cat":"tools-and-help","type":"match","persona":"any","source":"helping a friend","relearn":"To a friend disclosing abuse: it's not your fault, I believe you, let's plan, you're not alone, here's the number.","hook":"A friend opens up. Match what they say to a good response.","pairs":[{"left":"'Maybe it's my fault'","right":"'It's never your fault'"},{"left":"'I'm scared to leave'","right":"'Let's plan it together'"},{"left":"'No one will believe me'","right":"'I believe you'"},{"left":"'I feel so alone'","right":"'I'm staying with you'"},{"left":"'I don't know who to call'","right":"'181, 1091 or 112'"}]},
  {"id":"rr-1274","cat":"tools-and-help","type":"match","persona":"Meena, 20","source":"offline routes","relearn":"Even offline: 112 in danger, a relative for shelter, a neighbour to witness, 15100 for free legal aid.","hook":"No phone of your own? Match each need to an offline route.","pairs":[{"left":"Immediate danger","right":"Borrow a phone, dial 112"},{"left":"Somewhere to sleep safe","right":"A trusted relative"},{"left":"Someone to witness","right":"A neighbour you trust"},{"left":"Talk without being tracked","right":"Meet a friend in person"},{"left":"Free legal help","right":"Legal aid number 15100"}]},
  {"id":"rr-1275","cat":"tools-and-help","type":"match","persona":"any","source":"flag refresher","relearn":"Respecting your pace, trusting you, teaming up, valuing your family and apologising are real green flags.","hook":"Match each line to green flag or what it signals.","pairs":[{"left":"'Take your time deciding'","right":"Respects your pace"},{"left":"'I trust you, go enjoy'","right":"Healthy trust"},{"left":"'Let's sort this out together'","right":"Teamwork in conflict"},{"left":"'Your family matters too'","right":"No isolation"},{"left":"'I was wrong, I'm sorry'","right":"Can repair"}]},
  {"id":"rr-1276","cat":"tools-and-help","type":"match","persona":"Rohan, 20","source":"first-aid card","relearn":"Rejection stings; space, one good friend, staying open, routine and Tele-MANAS 14416 beat lashing out.","hook":"After a rejection, match the urge to a healthier move.","pairs":[{"left":"Blow up her phone","right":"Step back, give space"},{"left":"Trash her to your mates","right":"Vent to one steady friend"},{"left":"Decide women are the enemy","right":"Stay open, it stings now"},{"left":"Numb out alone","right":"Keep your routine going"},{"left":"Spiral at 2am","right":"Tele-MANAS 14416 if it lingers"}]},
  {"id":"rr-1277","cat":"tools-and-help","type":"sort","persona":"any","source":"care or control","relearn":"Care trusts and gives room; control demands location, polices your posts and threatens you over friends.","hook":"Sort each line: genuine care, or control in disguise?","items":[{"id":"a","text":"'Text me if you'll be late, no rush'"},{"id":"b","text":"'Send your location all day'"},{"id":"c","text":"'Have fun with your friends'"},{"id":"d","text":"'Why did he like your post?'"},{"id":"e","text":"'I trust you completely'"},{"id":"f","text":"'Delete him or we're done'"}],"bins":[{"id":"care","label":"Care","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"care","b":"control","c":"care","d":"control","e":"care","f":"control"}},
  {"id":"rr-1278","cat":"tools-and-help","type":"sort","persona":"any","source":"reach the right line","relearn":"Danger goes to 181/1091/112, heavy low mood to Tele-MANAS 14416, just-need-to-talk to a trusted person.","hook":"Sort each situation to the right India route.","items":[{"id":"a","text":"He's blocking the door, I'm scared"},{"id":"b","text":"Can't get out of bed for weeks"},{"id":"c","text":"Threatened with a weapon"},{"id":"d","text":"Numb and hopeless after the split"},{"id":"e","text":"Just need to think out loud"},{"id":"f","text":"Being followed right now"}],"bins":[{"id":"urgent","label":"181 / 1091 / 112","valence":"tell"},{"id":"mood","label":"Tele-MANAS 14416","valence":"uhoh"},{"id":"talk","label":"A trusted person","valence":"neutral"}],"key":{"a":"urgent","b":"mood","c":"urgent","d":"mood","e":"talk","f":"urgent"}},
  {"id":"rr-1279","cat":"tools-and-help","type":"sort","persona":"any","source":"wreckers and antidotes","relearn":"Criticism, contempt and stonewalling wreck; 'I' statements, owning it and a stated break repair.","hook":"Sort each line: a conflict wrecker, or a repair tool?","items":[{"id":"a","text":"'You always mess this up'"},{"id":"b","text":"'I felt hurt when plans changed'"},{"id":"c","text":"An eye-roll and a smirk"},{"id":"d","text":"'Fair point, that was on me'"},{"id":"e","text":"Silent for three days"},{"id":"f","text":"'I need a break, back in ten'"}],"bins":[{"id":"wreck","label":"Wrecker","valence":"neg"},{"id":"repair","label":"Repair","valence":"pos"}],"key":{"a":"wreck","b":"repair","c":"wreck","d":"repair","e":"wreck","f":"repair"}},
  {"id":"rr-1280","cat":"tools-and-help","type":"sort","persona":"any","source":"breakup coping","relearn":"Talking, routine and letting yourself feel heal; numbing, stalking and isolating don't.","hook":"Sort each breakup move: healthy coping, or not?","items":[{"id":"a","text":"Calling a friend to talk"},{"id":"b","text":"Drinking every night to numb"},{"id":"c","text":"Keeping your morning routine"},{"id":"d","text":"Stalking their profile hourly"},{"id":"e","text":"Letting yourself cry"},{"id":"f","text":"Toughing it out totally alone"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"not","c":"healthy","d":"not","e":"healthy","f":"not"}},
  {"id":"rr-1281","cat":"tools-and-help","type":"sort","persona":"any","source":"strength or weakness","relearn":"Reaching for help is strength; 'handle it alone', 'don't need help' and shame are myths that keep you stuck.","hook":"Sort: asking for help here is strength, or is it the myth?","items":[{"id":"a","text":"Calling a helpline when scared"},{"id":"b","text":"'I should handle this alone'"},{"id":"c","text":"Telling a friend the truth"},{"id":"d","text":"'Real adults don't need help'"},{"id":"e","text":"Seeing a counsellor"},{"id":"f","text":"'It's too shameful to say'"}],"bins":[{"id":"strength","label":"Strength","valence":"pos"},{"id":"myth","label":"Myth","valence":"neg"}],"key":{"a":"strength","b":"myth","c":"strength","d":"myth","e":"strength","f":"myth"}},
  {"id":"rr-1282","cat":"tools-and-help","type":"sort","persona":"any","source":"expand or shrink","relearn":"Healthy love expands your world: new things, courage, family. Control shrinks it down to only them.","hook":"Sort each by the test: does it expand your world, or shrink it?","items":[{"id":"a","text":"You picked up a new hobby"},{"id":"b","text":"You dropped all your friends"},{"id":"c","text":"You feel braver lately"},{"id":"d","text":"You censor yourself at home"},{"id":"e","text":"You see your family freely"},{"id":"f","text":"Your world is just them now"}],"bins":[{"id":"expand","label":"Expands","valence":"pos"},{"id":"shrink","label":"Shrinks","valence":"neg"}],"key":{"a":"expand","b":"shrink","c":"expand","d":"shrink","e":"expand","f":"shrink"}},
  {"id":"rr-1283","cat":"tools-and-help","type":"sort","persona":"Aarti, 21","source":"whose fault","relearn":"Threats, isolation and money-control are fully the controller's; wanting a say, hope and staying are never your fault.","hook":"Sort: in an abusive relationship, whose responsibility is each?","items":[{"id":"a","text":"Choosing to threaten you"},{"id":"b","text":"Wanting a say in your life"},{"id":"c","text":"Cutting you off from family"},{"id":"d","text":"Hoping things improve"},{"id":"e","text":"Controlling the money"},{"id":"f","text":"Staying while you found a plan"}],"bins":[{"id":"them","label":"The controller","valence":"neg"},{"id":"notfault","label":"Never your fault","valence":"pos"}],"key":{"a":"them","b":"notfault","c":"them","d":"notfault","e":"them","f":"notfault"}},
  {"id":"rr-1284","cat":"tools-and-help","type":"sort","persona":"any","source":"break vs silence","relearn":"A break is brief, named and you return; the silent treatment is open-ended punishment to control someone.","hook":"Sort: a healthy calming break, or the silent treatment?","items":[{"id":"a","text":"'I'm flooded, back in 20'"},{"id":"b","text":"Ignoring them for days to punish"},{"id":"c","text":"Stepping out, then returning"},{"id":"d","text":"Cold shoulder till they grovel"},{"id":"e","text":"Naming when you'll talk again"},{"id":"f","text":"Withholding to control them"}],"bins":[{"id":"break","label":"Healthy break","valence":"pos"},{"id":"silence","label":"Silent treatment","valence":"neg"}],"key":{"a":"break","b":"silence","c":"break","d":"silence","e":"break","f":"silence"}},
  {"id":"rr-1285","cat":"tools-and-help","type":"sort","persona":"any","source":"verified or not","relearn":"Correct India lines: women 181 or 1091, emergency 112, Tele-MANAS 14416. Memorise the real ones.","hook":"Sort each claim: correct India helpline number, or wrong?","items":[{"id":"a","text":"181 is for women"},{"id":"b","text":"999 is the emergency line here"},{"id":"c","text":"14416 reaches Tele-MANAS"},{"id":"d","text":"1091 is women in distress"},{"id":"e","text":"112 is the emergency line here"},{"id":"f","text":"100 is the women's line"}],"bins":[{"id":"right","label":"Correct","valence":"pos"},{"id":"wrong","label":"Wrong","valence":"neg"}],"key":{"a":"right","b":"wrong","c":"right","d":"right","e":"right","f":"wrong"}},
  {"id":"rr-1286","cat":"tools-and-help","type":"sort","persona":"any","source":"now or wait","relearn":"Raised hands, threats and being followed need help now (181/1091/112); reflection and planning can wait.","hook":"Sort: reach help right now, or this can wait a bit?","items":[{"id":"a","text":"He just raised his hand"},{"id":"b","text":"You're picking a calm hobby"},{"id":"c","text":"You're being threatened tonight"},{"id":"d","text":"You want to journal feelings"},{"id":"e","text":"A friend is being followed home"},{"id":"f","text":"You're planning next week's chat"}],"bins":[{"id":"now","label":"Now: 181/1091/112","valence":"tell"},{"id":"wait","label":"Can wait","valence":"neutral"}],"key":{"a":"now","b":"wait","c":"now","d":"wait","e":"now","f":"wait"}},
  {"id":"rr-1287","cat":"tools-and-help","type":"sort","persona":"any","source":"support or numb","relearn":"Chai with a friend, a walk and Tele-MANAS 14416 are support; scrolling, binge-numbing and picking fights aren't.","hook":"Sort each after-breakup choice: real support, or numbing?","items":[{"id":"a","text":"Joining a friend for chai"},{"id":"b","text":"Endless doom-scrolling"},{"id":"c","text":"Going for a daily walk"},{"id":"d","text":"Binge-numbing till sunrise"},{"id":"e","text":"Tele-MANAS 14416 when it's heavy"},{"id":"f","text":"Picking fights to feel something"}],"bins":[{"id":"support","label":"Support","valence":"pos"},{"id":"numb","label":"Numbing","valence":"neg"}],"key":{"a":"support","b":"numb","c":"support","d":"numb","e":"support","f":"numb"}},
  {"id":"rr-1288","cat":"tools-and-help","type":"branch","persona":"any","source":"first tool","hook":"You and your partner Yash keep blowing up at each other over small things.","steps":[{"prompt":"Tonight a chat about weekend plans turns into shouting. What do you do?","options":[{"text":"Keep going until one of you finally wins the point","then":"The shouting gets louder, and you both say things you regret."},{"text":"Ask for twenty minutes to cool off, then return","then":"Yash nods, breathing hard. Twenty minutes later you sit back down.","best":true},{"text":"Walk out of the room without saying a word","then":"Yash is left staring at the door. The fight waits, unfinished."},{"text":"Say whatever he wants is fine, just to end it","then":"The shouting stops. The resentment doesn't."}],"why":"A named break when flooded stops the spiral, and coming back keeps it fair."},{"prompt":"Afterwards, Yash suggests you both just avoid touchy topics from now on. What do you say?","options":[{"text":"Agree. Fewer topics means fewer fights","then":"Things go quiet. The topics pile up, unspoken."},{"text":"Only talk when you're both totally calm","then":"That day rarely comes, and the unsaid list grows."},{"text":"Say avoiding buries things. Break, then return","then":"Yash thinks. \"Okay. As long as we actually come back.\"","best":true},{"text":"Suggest texting about hard things instead","then":"The texts get misread, and a new fight starts on WhatsApp."}],"why":"Avoiding touchy topics buries them. A break, then a real return, resolves them."},{"prompt":"A week later, your heart races mid-argument. What do you say?","options":[{"text":"\"You always do this. I'm done talking.\"","then":"Yash goes silent, and the evening turns cold."},{"text":"\"Fine. You're right. Whatever.\"","then":"The fight ends, and so does your chance to be heard."},{"text":"\"Let's just forget it ever happened.\"","then":"You both move on, and it comes back bigger next week."},{"text":"\"I'm flooded. Can we pause till eight?\"","then":"Yash exhales. \"Yeah. Eight.\" At eight you both come back calmer.","best":true}],"why":"Naming a break, with a time to return, is the everyday tool that stops fights spiralling."}],"debrief":"A named break when flooded, then a return to repair, is the most useful everyday conflict tool.","relearn":"When fights spiral, take a calming break and come back; don't just avoid the topic."},
  {"id":"rr-1289","cat":"tools-and-help","type":"branch","persona":"Aarti, 21","source":"unsure it's abuse","hook":"Your partner Nitin never hits you, but his moods decide your days, and you're not sure what to call it.","steps":[{"prompt":"This week he went cold for two days over what you wore. What's your first step?","options":[{"text":"Wait until it's bad enough to really count","then":"The weeks pass. Each new thing feels normal next to the last."},{"text":"Tell a counsellor or someone you trust","then":"The college counsellor listens and asks gentle questions. Things feel clearer.","best":true},{"text":"Search online for a checklist of abuse","then":"Some boxes fit, some don't. You close the tab more confused."},{"text":"Decide it's your fault for not knowing his taste","then":"You start checking his mood before every small choice."}],"why":"You don't need proof or a label to ask for help. Naming it early brings clarity."},{"prompt":"A friend says, \"At least he doesn't hit you. Lots of people have it worse.\" How do you take it?","options":[{"text":"She's right. I should be grateful","then":"You swallow the worry, and it comes back at night."},{"text":"Maybe I'm making a fuss about nothing","then":"You stop mentioning it, but the unease keeps coming back."},{"text":"Control counts, even without hitting","then":"The words settle. What you're living with is real.","best":true},{"text":"Stop talking to that friend for good","then":"You feel lonelier, and the question is still there."}],"why":"Abuse isn't only hitting. Moods that control your days are worth taking seriously."},{"prompt":"One evening Nitin sees you're upset and calls you \"too sensitive\". How do you see it?","options":[{"text":"If I explain it better, he'll understand","then":"You explain for an hour. He only gets more annoyed."},{"text":"Every partner is like this sometimes","then":"The thought soothes you, and nothing changes."},{"text":"Maybe I am too sensitive. I'll let it go","then":"The worry goes quiet for a day, then comes back."},{"text":"My feelings are real. His control isn't on me","then":"You hold steady inside, even as he sulks.","best":true}],"why":"Being called too sensitive doesn't make you wrong. You can trust what you feel."},{"prompt":"Your mother notices you've gone quiet and asks if Nitin treats you well. What do you do?","options":[{"text":"Say everything's fine, so she won't worry","then":"She smiles, relieved. You feel more alone than before."},{"text":"Tell her honestly how his moods rule your days","then":"She's quiet, then takes your hand. \"I'm glad you told me. Let's think.\"","best":true},{"text":"Say it's just adjusting, like every couple","then":"She nods. \"All couples adjust,\" she says, and the topic closes."},{"text":"Say you'll handle it, and change the subject","then":"She lets it go, but keeps glancing at you through dinner."}],"why":"Telling someone close breaks the silence. None of this is your fault."}],"debrief":"Naming it to a counsellor or trusted person brings clarity. You need no \"proof\" to ask.","relearn":"Unsure if it's abuse? Name it to a counsellor or trusted person; don't wait for it to get worse."},
  {"id":"rr-1290","cat":"tools-and-help","type":"branch","persona":"any","source":"phone demand","hook":"Your girlfriend Tanya demands your phone password \"to prove your love\".","steps":[{"prompt":"She holds out her hand, waiting. What do you do?","options":[{"text":"Hand it over. Love means no privacy","then":"She scrolls in silence. Next day she asks about a friend's message."},{"text":"Offer yours if she shares hers too","then":"She agrees fast. Now you both check each other's phones."},{"text":"Wonder if you've made her feel insecure","then":"You start going over every text you've sent this month."},{"text":"Say calmly, \"My phone stays mine\"","then":"Tanya's hand drops. \"Wow. So you are hiding something.\"","best":true}],"why":"Healthy transparency is voluntary. A demand to prove love is control, and you can decline it."},{"prompt":"Later, Tanya says real love means sharing everything, always. How do you see that?","options":[{"text":"Love doesn't need a password to prove it","then":"The line in your head gets firmer, even as she sulks.","best":true},{"text":"Maybe my love isn't strong enough","then":"You feel guilty for wanting privacy at all."},{"text":"She's insecure. Giving her access will settle it","then":"You picture it, and every new demand after that."},{"text":"It's normal. All couples share passwords","then":"You look for proof, and find only your own unease."}],"why":"Tying love to access is a control tactic. Real love doesn't need proof by password."},{"prompt":"Days later, Tanya asks to see your chats again. What do you do?","options":[{"text":"Tell no one. Couples sort these things alone","then":"The demands keep coming, and you carry them alone."},{"text":"Buy her a gift to smooth things over","then":"She thanks you, then asks for your phone again."},{"text":"Talk it through with a friend you trust","then":"Your friend Rhea listens. \"Wanting privacy is normal. I'm here.\"","best":true},{"text":"Tell her friends she's being controlling","then":"It gets back to her, and the fight gets much bigger."}],"why":"Someone you trust keeps you steady. Her demand is never your fault."}],"debrief":"Healthy transparency is voluntary. A demand for your password is monitoring, and you can decline it.","relearn":"You can keep your phone private; a demand for passwords is control, not proof of love."},
  {"id":"rr-1291","cat":"tools-and-help","type":"branch","persona":"any","source":"friend discloses","hook":"Your friend Meher tells you, very quietly, that her boyfriend hits her.","steps":[{"prompt":"She's watching your face for a reaction. What do you say?","options":[{"text":"\"What did you do to set him off?\"","then":"Meher flinches and looks down. \"Nothing. Forget it.\""},{"text":"\"Are you sure? He seems so gentle.\"","then":"She goes quiet. \"Yeah. Everyone says that.\""},{"text":"\"I believe you. It's not your fault.\"","then":"Meher's eyes fill. \"I was so scared you'd think I was lying.\"","best":true},{"text":"\"Oh my god. I'm going to kill him.\"","then":"Meher panics. \"No, please. Don't do anything.\""}],"why":"Believing her and saying it's not her fault is the most important thing you can do."},{"prompt":"Meher asks you to promise you won't tell anyone. What do you say?","options":[{"text":"Promise total secrecy, no matter what","then":"She relaxes. You lie awake wondering what you'd do if it got worse."},{"text":"Say you'll go at her pace, unless she's in danger","then":"She nods slowly. \"Okay. That feels fair.\"","best":true},{"text":"Say you're telling her parents tonight","then":"She grabs your arm. \"Please. That would make it all worse.\""},{"text":"Say this is too much, and she should tell someone else","then":"Meher shrinks. \"Sorry. I shouldn't have told you.\""}],"why":"Going at her pace keeps her trust, while being honest that her safety comes first."},{"prompt":"Meher says she can't leave him right now. What do you do?","options":[{"text":"Tell her she has to leave today","then":"\"You don't understand,\" she says, and starts to pull away."},{"text":"Tell her to stop making him angry","then":"She nods, and you watch her shoulders tense."},{"text":"Respect that, and ask what would help her feel safer","then":"She thinks. \"Maybe knowing I can come to yours.\"","best":true},{"text":"Offer to go and confront him yourself","then":"\"Please don't,\" she says. \"He'd know I told you.\""}],"why":"Pushing or taking over can isolate her. Respecting her choices keeps you in her corner."},{"prompt":"Meher asks where she could get help if things get worse. What do you tell her?","options":[{"text":"Just call you, and you'll handle it","then":"She nods. It's a lot to rest on one friend."},{"text":"Wait until she has real proof, like photos","then":"She looks doubtful. \"What if I don't have any?\""},{"text":"Ask his family to step in","then":"Meher shakes her head. \"They'd take his side.\""},{"text":"181 or 1091 for help, 112 if she's in danger","then":"She saves them under a friend's name. \"Okay. I have them now.\"","best":true}],"why":"Knowing 181, 1091 and 112 means help is ready when she needs it, not only you."},{"prompt":"A week later, Meher messages that it happened again and she's scared. What do you do?","options":[{"text":"Tell her she should have left him by now","then":"She goes quiet, and doesn't reply for two days."},{"text":"Go to his flat and have it out with him","then":"He's furious you came. Meher stops answering her phone."},{"text":"Ask if she's safe, offer your place, and 112 if needed","then":"\"Can I come tonight?\" she replies. You text back: \"Door's open.\"","best":true},{"text":"Tell her to keep things calm and wait it out","then":"She sends a thumbs up. You hear nothing more that night."}],"why":"When she's scared, safety comes first: a safe place tonight, and 112 if she's in danger."}],"debrief":"Believe them, don't blame, and help plan with 181, 1091 or 112. Abuse is never the target's fault.","relearn":"To a friend disclosing abuse: believe them, don't blame, help plan with the helplines."},
  {"id":"rr-1292","cat":"tools-and-help","type":"branch","persona":"Zoya, 21","source":"no-contact wobble","hook":"Two weeks into no-contact with your ex Ira, you're aching to text her.","steps":[{"prompt":"It's past midnight and her chat is open on your screen. What do you do?","options":[{"text":"Send Ira a quick \"just checking in\"","then":"She replies with a heart. By morning you're hurting all over again, waiting for more."},{"text":"Only look at her stories. That isn't really contact","then":"Her new photos sting. You're up till three, reading into every caption."},{"text":"Text your friend Tara: \"Wobbling. Can you talk?\"","then":"Tara calls within minutes and keeps you talking till the urge fades.","best":true},{"text":"Type the message, then save it in drafts","then":"It stays unsent, but you open the draft four more times before you sleep."}],"why":"Reaching for a friend meets the ache with support, without reopening a door you closed to heal."},{"prompt":"A few days later, a mutual friend says Ira has been asking about you. What do you do?","options":[{"text":"Change the subject, then check her profile after","then":"The chat moves on. Later you spend an hour on her profile, looking for clues."},{"text":"Take it as a sign and message Ira tonight","then":"Ira replies warmly, then goes quiet for days. The old ache is back."},{"text":"Ask your friend to tell Ira you miss her","then":"The message goes through. Now you check your phone every few minutes for her reply."},{"text":"Say thanks, but you're keeping space for now","then":"Your friend nods. \"Fair. I won't pass things along.\" The day feels lighter.","best":true}],"why":"Keeping space includes news through friends. Saying so kindly protects your healing."},{"prompt":"The weekend stretches ahead and the pull is back. What do you do?","options":[{"text":"Tell your chosen family it's a hard week, and join their lunch","then":"They squeeze you in, tease you gently, and ask how you're really doing.","best":true},{"text":"Stay busy alone with work so there's no time to think","then":"You get a lot done. By Sunday night the ache hits hard, and no one knows."},{"text":"Reread your old chats one last time, for closure","then":"Old jokes pull you back in. Closure feels further away than ever."},{"text":"Download a dating app to prove you're over her","then":"A few matches come in. None of them touch the ache you're carrying."}],"why":"Leaning on people who love you is how no-contact holds while you heal at your own pace."}],"debrief":"No-contact is a healthy tool, not pettiness. When you wobble, reach for support, not the ex.","relearn":"No-contact protects your healing; when you wobble, reach for a friend, not the ex."},
  {"id":"rr-1293","cat":"tools-and-help","type":"branch","persona":"any","source":"isolation creep","hook":"Whenever you plan to see friends, your partner Kabir has a reason you shouldn't go.","steps":[{"prompt":"Tonight is a friend's birthday, and he says he feels low and wants you home. What do you do?","options":[{"text":"Decide it's sweet that he needs you so much","then":"You text the birthday group a sorry. It's the third one this month."},{"text":"Say, \"This keeps happening. I'm going tonight.\"","then":"Kabir goes quiet. \"Fine. Go.\" At the party, you realise how much you'd missed everyone.","best":true},{"text":"Go, but don't mention how often this happens","then":"The party is fun. The next excuse arrives two days later, and you let it pass."},{"text":"Decide you've been going out too much anyway","then":"You start turning down plans before he can even object."}],"why":"Naming the pattern and keeping your plans protects your independence without a fight."},{"prompt":"Next day, Kabir says your friends are a bad influence and he only wants to protect you. How do you see it?","options":[{"text":"He's protective because he loves me","then":"The words feel warm, and your weekend stays empty again."},{"text":"It's isolation, even if he calls it protecting","then":"Seeing it plainly, you count how few plans you've kept this month.","best":true},{"text":"Maybe my friends really aren't good for me","then":"You mute the group chat, and it gets quieter around you."},{"text":"It's a lot, but it'll settle once he feels secure","then":"Weeks go by. Each new plan still comes with a reason not to go."}],"why":"Cutting you off from friends is isolation, not protection. Naming it helps you see it clearly."},{"prompt":"Your friend Pooja texts that she misses you and asks if everything's okay. What do you do?","options":[{"text":"Say you're fine, just busy with college","then":"Pooja sends a heart. The distance between you stays."},{"text":"Say things are hard, but not why","then":"Pooja offers to meet. You're not sure what you'd tell her."},{"text":"Tell her honestly what's been happening","then":"Pooja listens. \"That's not okay. I'm here, whatever you decide.\"","best":true},{"text":"Ask her not to message while you're with Kabir","then":"She agrees, puzzled. You start timing your replies around him."}],"why":"A trusted friend keeps your world wide. None of this is your fault, and you needn't carry it alone."},{"prompt":"A week later, you think about the months ahead with Kabir. What do you hold on to?","options":[{"text":"Every couple drops some friends eventually","then":"You stop replying to invites, and your world gets a little smaller."},{"text":"If I love him enough, he'll feel secure and stop","then":"You try harder. The reasons not to go keep coming anyway."},{"text":"Love should expand my world, not shrink it","then":"You text Pooja: \"Saturday's on.\" She sends back three hearts.","best":true},{"text":"I'll keep my friends, but see them in secret","then":"You meet Pooja for chai, checking the time and your phone the whole hour."}],"why":"The simple test: does it expand your world and respect you? Your friends are part of you."}],"debrief":"A partner who always blocks your friends is isolating you. Keeping your own people is healthy, and it's never your fault.","relearn":"If plans with friends keep getting blocked, name it as isolation and keep your independence."},
  {"id":"rr-1294","cat":"tools-and-help","type":"branch","persona":"Meena, 20","source":"leaving with a plan","hook":"You've decided to leave Suresh, who takes your wages and checks your phone.","steps":[{"prompt":"Before you go, you need someone on your side. Who do you tell first?","options":[{"text":"No one. It's safer if nobody knows","then":"The plan stays in your head, and so does the fear of doing it alone."},{"text":"Suresh's mother, hoping she'll talk sense into him","then":"She sighs, \"All men get angry,\" and you worry she'll tell him."},{"text":"Your cousin Lata across town, who you trust","then":"Lata listens and says, \"Come to mine. We'll plan it together.\"","best":true},{"text":"A coworker, in a chat on your phone","then":"She replies kindly. That night you delete the chat before Suresh can see it."}],"why":"A trusted person makes a plan real and safer. Leaving is brave, and none of this is your fault."},{"prompt":"You think about what you'll need once you're gone. What do you do?","options":[{"text":"Pack a bag now and hide it under the bed","then":"Every time Suresh goes near the bed, your heart races."},{"text":"Leave Aadhaar, passbook and cash with someone you trust","then":"Bit by bit, your papers and savings sit safely away from the room.","best":true},{"text":"Leave your papers. You can come back for them later","then":"You picture going back to the room, and Suresh being there."},{"text":"Take nothing. Just go when it gets bad","then":"You'd be starting over with no ID and no money for the bus."}],"why":"Your documents and some money, kept somewhere safe, make it easier to start again."},{"prompt":"You need somewhere to stay the night you leave. Where do you plan to go?","options":[{"text":"Your village home. He knows it, but family will help","then":"You picture the bus ride, then Suresh turning up at the gate a day later."},{"text":"Wherever feels right on the day","then":"You picture standing on the road with a bag and nowhere fixed."},{"text":"A place he doesn't know, fixed in advance","then":"Your friend nods. \"The spare mat is yours. Come any time.\"","best":true},{"text":"Nowhere yet. Maybe he'll change if you wait","then":"Weeks pass. He's kind for two days, then checks your phone again."}],"why":"A safe place he doesn't know, fixed ahead, keeps you out of reach while things are raw."},{"prompt":"You want help ready in case things turn dangerous. What do you do?","options":[{"text":"Save the helplines in your phone under their real names","then":"They're saved. Then you remember he goes through your contacts every night."},{"text":"Only plan to call for help if he hits you","then":"You tell yourself it isn't that bad yet, and keep waiting."},{"text":"Look the numbers up if you ever need them","then":"You picture searching with shaking hands and no signal."},{"text":"Learn 181, 1091 and 112 by heart","then":"You say them over on the walk to work until they stick.","best":true}],"why":"Knowing 181, 1091 and 112 by heart means help is one call away, even without your phone."},{"prompt":"On the morning you planned, a thought says it's your fault and he deserves one more chance. What do you tell yourself?","options":[{"text":"\"Maybe if I'd been better, he'd be kinder\"","then":"You unpack the bag in your head, and the room feels smaller."},{"text":"\"I'll tell him to his face. He deserves that\"","then":"You imagine saying it, and remember how fast his temper turns."},{"text":"\"It isn't my fault. I'm going, as planned\"","then":"You send one text: \"Coming now.\" The reply is instant: \"I'm here.\"","best":true},{"text":"\"I'll leave a note so he knows where I've gone\"","then":"You start writing, then picture him reading the address."}],"why":"Abuse is never your fault. Sticking to the plan you made is how you get safe."}],"debrief":"Plan the exit: a trusted person, documents, a safe place, and 181, 1091 or 112. Leaving is brave, never a failure.","relearn":"Leaving is brave; plan it: tell someone, ready documents and a safe place, know the helplines."},
  {"id":"rr-1295","cat":"tools-and-help","type":"branch","persona":"any","source":"contempt creeping","hook":"Lately, in arguments with your partner Isha, you've been sneering and calling her names.","steps":[{"prompt":"Tonight you hear yourself say \"Wow, genius\" and see her face drop. What do you tell yourself?","options":[{"text":"It's just venting. Everyone says stuff in a fight","then":"You shrug it off. Isha goes home early and doesn't text goodnight."},{"text":"She pushes my buttons, so she had it coming","then":"You feel justified, and Isha stops trying to finish her point."},{"text":"That was contempt, and it's hurting us","then":"The word lands heavy. You notice how often you've done it lately.","best":true},{"text":"It's not great, but it'll stop once exams are over","then":"Exams end. The digs don't."}],"why":"Naming contempt honestly is the first step. It's the pattern that wears couples down most."},{"prompt":"Next morning, Isha's texts are short and cold. What do you do?","options":[{"text":"Say sorry, but explain she was pushing you","then":"Isha replies: \"So it's still my fault.\""},{"text":"Say, \"Calling you names was wrong. I'm sorry.\"","then":"\"Thank you,\" Isha replies. \"It really hurt.\"","best":true},{"text":"Act normal and hope she's let it go","then":"She answers in single words, and the chat goes quiet."},{"text":"Send her favourite snack instead of talking","then":"She thanks you politely. Last night still sits there, unspoken."}],"why":"A plain apology that owns it, with no \"but\", is a real repair attempt."},{"prompt":"Over the next week, you want things to feel different between you. What do you practise?","options":[{"text":"Bite your tongue and go silent whenever you're annoyed","then":"The digs stop, but so does the talking. Isha asks if you're angry."},{"text":"Keep the sarcasm, but only as jokes","then":"Isha laughs at the first one. By the fourth, she's stopped laughing."},{"text":"Wait for her to be nicer to you first","then":"Days pass with both of you waiting, and nothing changes."},{"text":"Name one thing you value about her, every day","then":"On day three, Isha laughs. \"Okay, who are you and what have you done?\"","best":true}],"why":"Appreciation is the antidote to contempt. Small and genuine beats one grand gesture."},{"prompt":"A week later, you disagree about weekend plans over coffee, and a sneer rises. What do you do?","options":[{"text":"Catch it, then say what you want without the dig","then":"Isha relaxes. \"Okay. Let's find something we both want.\"","best":true},{"text":"Let it out. Holding back isn't honest","then":"The sneer lands, and the talk turns into a fight about the sneer."},{"text":"Walk off without a word","then":"You leave her at the café. Later, neither of you brings it up."},{"text":"Swallow it and go along with her plan","then":"The fight is avoided. You spend Saturday quietly resenting it."}],"why":"Catching the dig and saying what you want keeps it a disagreement, not an attack on her."}],"debrief":"Contempt is the most corrosive pattern. Its antidote is genuine appreciation, and it starts with you.","relearn":"Sneering is contempt, the worst wrecker; counter it with genuine appreciation, led by you."},
  {"id":"rr-1296","cat":"tools-and-help","type":"branch","persona":"Rohan, 20","source":"rohan rejected","hook":"Kavya said no to a second date. It stung a lot more than you expected.","steps":[{"prompt":"That night you keep rereading her message. What do you do?","options":[{"text":"Reply asking her to give it one more try","then":"She replies politely: \"I meant it. Take care.\" Now it stings twice."},{"text":"Tell yourself it doesn't matter and move on","then":"You scroll till two. The sting is still there in the morning."},{"text":"Watch videos on why women reject nice guys","then":"Three hours in, you feel angrier and lonelier than before."},{"text":"Call your friend Aman and admit it stung","then":"Aman listens, then says, \"Oof. Chai tomorrow?\"","best":true}],"why":"Letting it sting and telling one mate stops it hardening into resentment."},{"prompt":"Next day, a guy in your hostel says, \"Women only want rich guys anyway.\" What do you say?","options":[{"text":"\"She's allowed to say no. It just stung.\"","then":"He pauses. \"Fair. It always stings.\"","best":true},{"text":"\"Yeah. That's just how it is.\"","then":"You both nod, and the story feels truer and heavier."},{"text":"Laugh it off and change the subject","then":"The moment passes. His line stays in your head all afternoon."},{"text":"\"Maybe I just need to act more alpha.\"","then":"He grins and sends you a reel. You feel less like yourself watching it."}],"why":"Respecting her no and naming the hurt honestly keeps you out of a bitter story."},{"prompt":"The weekend comes and you feel flat. What do you do?","options":[{"text":"Plan to ask her again in a month, once she misses you","then":"The plan keeps her no alive in your head all week."},{"text":"Stay in and replay everything you did wrong","then":"By Sunday night you have a long list, and still no answers."},{"text":"Go to Sunday cricket with the lads, as planned","then":"You drop a catch, everyone laughs, and for an hour you forget her.","best":true},{"text":"Go, but keep checking if she viewed your story","then":"You're at the match, but your mind stays on your phone."}],"why":"Keeping your life moving, with friends and plans, is how the sting fades."}],"debrief":"A rejection isn't a verdict on your worth. Feel it, lean on a friend, respect her no, keep moving.","relearn":"A no stings but isn't a verdict; feel it, lean on a mate, respect it, keep your life going."},
  {"id":"rr-1297","cat":"tools-and-help","type":"branch","persona":"any","source":"low mood lingers","hook":"A month after your breakup with Aditya, you can barely get through a day and feel hopeless.","steps":[{"prompt":"Another morning, you can't face getting out of bed. What do you do?","options":[{"text":"Have a few drinks tonight to stop feeling it","then":"The evening blurs. The next morning feels even heavier."},{"text":"Call Tele-MANAS 14416 and say how it's been","then":"The counsellor listens without rushing and asks what your days have been like.","best":true},{"text":"Tell yourself to toughen up and push through alone","then":"You drag yourself to class, then cry in the washroom after."},{"text":"Wait a few more weeks. It should lift on its own","then":"Two more weeks pass. The heaviness hasn't moved."}],"why":"When low mood stops you functioning for weeks, real support like Tele-MANAS 14416 helps."},{"prompt":"Your friend Sneha asks how you're really doing. What do you say?","options":[{"text":"\"Fine. Just busy with college.\"","then":"Sneha nods, unconvinced, and lets it drop."},{"text":"\"It's been rough, but I've got it handled.\"","then":"Sneha backs off, and you're alone with it again."},{"text":"\"I'll be fine once Aditya regrets it.\"","then":"Sneha frowns. \"And if he doesn't?\" You don't have an answer."},{"text":"\"Honestly, it's been really hard. Can we talk?\"","then":"Sneha sits down. \"I'm glad you told me. I'm not going anywhere.\"","best":true}],"why":"Saying it out loud to a friend lets support in. You don't have to carry this alone."},{"prompt":"This week, you want to get through the days a little better. What do you try?","options":[{"text":"Keep busy every minute so there's no time to feel","then":"The days fill up. At night, it all comes crashing back."},{"text":"Small routines: meals, a walk, a call with Sneha","then":"It's slow, but by Friday the mornings feel a little less heavy.","best":true},{"text":"Scroll through old photos to feel close to him","then":"An hour disappears. You're right back at the day it ended."},{"text":"Find someone new fast to fill the gap","then":"The first chat is fun. The emptiness is still there after."}],"why":"Routine and people carry you through. Keep Tele-MANAS 14416 close if it gets heavy again."}],"debrief":"Heartbreak is survivable, but persistent heavy low mood is worth real help.","relearn":"If low mood after a breakup won't lift, reach for support: Tele-MANAS 14416 or a counsellor."},
  {"id":"rr-1298","cat":"tools-and-help","type":"branch","persona":"any","source":"the simple test","hook":"Three weeks in with Kabir, everything feels intense: daily calls, big plans, nonstop texts.","steps":[{"prompt":"You want a quick way to tell if this is good for you. What do you go by?","options":[{"text":"Whether it expands my world and respects me","then":"You notice he backs your exam plans but goes quiet whenever you see friends.","best":true},{"text":"How strong the feelings are, since this is rare","then":"The rush feels like an answer. You stop looking at anything else."},{"text":"Whether he's sweet to me when we're together","then":"He always is. You don't notice your week has shrunk to him and his calls."},{"text":"Whether my friends and cousins approve of him","then":"Your cousin says he looks nice in photos. It's her read, not yours."}],"why":"The test looks past the rush to whether your life is growing and you're respected."},{"prompt":"On Friday, Kabir asks you to skip a friend's birthday and spend the night with him. What do you do?","options":[{"text":"Go to the birthday and plan a separate night with him","then":"Kabir sulks a little, then asks about Saturday. You enjoy the party.","best":true},{"text":"Skip it. Wanting me all to himself shows how much he cares","then":"The evening is sweet. Your friend's message the next day is short and a bit hurt."},{"text":"Skip this one and see whether it becomes a pattern","then":"The night is fun. Two weeks later, he asks for the same thing again."},{"text":"Tell him he's being clingy and go without replying","then":"Kabir sends three hurt messages. You feel guilty all through the party."}],"why":"Keeping your friends and making time for him is love that expands your world."},{"prompt":"A month on, you catch yourself checking his mood before making any plan. What do you make of it?","options":[{"text":"My world's shrinking. I'll talk to him and a friend","then":"Your friend Nisha listens. Naming it makes the talk with Kabir feel possible.","best":true},{"text":"It's normal. Big love means always thinking of him first","then":"You keep adjusting. Slowly, your plans start to circle around his."},{"text":"I'm probably overthinking a small habit","then":"You let it go. The habit settles in without a word said."},{"text":"I'll keep an eye on it and see if it gets worse","then":"Weeks pass. You keep watching and keep adjusting, and nothing is said."}],"why":"Checking his mood before plans means your world is shrinking. That's not your fault, and naming it helps."}],"debrief":"Intensity isn't the test. Ask: does it expand my world and respect me?","relearn":"Quick check for any relationship: does it expand my world and respect me? Truer than intensity."},
  {"id":"rr-1299","cat":"tools-and-help","type":"reflect","persona":"any","source":"pocket toolkit","relearn":"'I' statements, breaks, apologies and naming needs are real skills for a hard talk.","hook":"Lensy: which tool do you most want in your pocket for the next hard talk?","prompt":"Pick one.","options":["An 'I felt...' line","A calming break","A genuine apology","Naming what I need"],"affirm":"Any of these is a real skill; carrying even one into a hard talk changes how it goes."},
  {"id":"rr-1300","cat":"tools-and-help","type":"reflect","persona":"any","source":"who i'd call","relearn":"Knowing one person you'd tell is a quiet kind of safety; you don't have to face it alone.","hook":"Lensy: if a relationship ever turned scary, who's the first person you'd tell?","prompt":"Picture them.","options":["A close friend","A family member","A counsellor","A neighbour I trust"],"affirm":"Knowing one person you'd tell is a quiet kind of safety; you don't have to face it alone."},
  {"id":"rr-1301","cat":"tools-and-help","type":"reflect","persona":"any","source":"my green flag","relearn":"Knowing what you most need names your standard; you get to hold out for it.","hook":"Lensy: which green flag matters most to you in a partner?","prompt":"Choose what lands.","options":["They respect my no","They keep their friends too","We repair after fights","They trust me freely"],"affirm":"Knowing what you most need names your standard; you get to hold out for it."},
  {"id":"rr-1302","cat":"tools-and-help","type":"reflect","persona":"Ananya, 19","source":"expand test","relearn":"Whatever you noticed, the question itself is the tool; love that's good for you tends to expand your world.","hook":"Lensy: does your relationship leave you bigger or smaller than before it?","prompt":"Sit with it.","options":["Bigger and bolder","About the same","Honestly, smaller","I'm still working it out"],"affirm":"Whatever you noticed, the question itself is the tool; love that's good for you tends to expand your world."},
  {"id":"rr-1303","cat":"tools-and-help","type":"reflect","persona":"any","source":"help is strength","relearn":"Asking for help is one of the strongest, wisest moves there is, and that includes asking for yourself.","hook":"Lensy: reaching for help when something's wrong, strength or weakness?","prompt":"What's true for you?","options":["Strength, clearly","I'm starting to see it","Still hard to ask","Strength for others, not me yet"],"affirm":"Asking for help is one of the strongest, wisest moves there is, and that includes asking for yourself."},
  {"id":"rr-1304","cat":"tools-and-help","type":"reflect","persona":"any","source":"one number","relearn":"Knowing even one real number means help is a moment away when you or a friend needs it.","hook":"Lensy: which India helpline feels worth memorising for you?","prompt":"Pick the one you'd keep.","options":["112 emergency","181 women's helpline","Tele-MANAS 14416","1091 in distress"],"affirm":"Knowing even one real number means help is a moment away when you or a friend needs it."},
  {"id":"rr-1305","cat":"tools-and-help","type":"reflect","persona":"any","source":"repair style","relearn":"However you reconnect, the willingness to repair is what makes a relationship last.","hook":"Lensy: after a fight, what helps you come back to repair?","prompt":"What works for you?","options":["A bit of space first","Saying sorry plainly","A small kind gesture","Just naming the hurt"],"affirm":"However you reconnect, the willingness to repair is what makes a relationship last."},
  {"id":"rr-1306","cat":"tools-and-help","type":"reflect","persona":"Zoya, 21","source":"breakup kindness","relearn":"Every one of these is true for you as well; offer yourself the kindness you'd give a friend.","hook":"Lensy: what would you tell a friend in the middle of a breakup?","prompt":"Say it to yourself too.","options":["'You're whole on your own'","'There's no timeline'","'Lean on us'","'Nothing's wrong with you'"],"affirm":"Every one of these is true for you as well; offer yourself the kindness you'd give a friend."},
  {"id":"rr-1307","cat":"tools-and-help","type":"reflect","persona":"Aarti, 21","source":"my non-negotiable","relearn":"Naming your non-negotiable makes it real; you deserve to feel safe, respected and free, no exceptions.","hook":"Lensy: what's one thing you won't settle below in a relationship?","prompt":"Name your line.","options":["Being respected","Having a say","Keeping my freedom","Feeling safe"],"affirm":"Naming your non-negotiable makes it real; you deserve to feel safe, respected and free, no exceptions."},
  {"id":"rr-1308","cat":"tools-and-help","type":"reflect","persona":"any","source":"carry the spine","relearn":"Hold that line and you've got a compass: the thing that grows you is closer to love than the thing that shrinks you.","hook":"Lensy: love expands your world, control shrinks it. Which half do you want to remember?","prompt":"Pick what you'll carry.","options":["Love expands","Control shrinks","Both, together","I'll watch for the shrink"],"affirm":"Hold that line and you've got a compass: the thing that grows you is closer to love than the thing that shrinks you."},
  {"id":"rr-1309","cat":"tools-and-help","type":"reflect","persona":"any","source":"not your fault","relearn":"Right: control is always the controller's doing, never the target's, no matter how long they stayed.","hook":"Lensy: if someone you love is being controlled, whose fault is the control?","prompt":"What do you believe?","options":["The controller's, fully","Never the target's","I'm learning that","100% on the one doing it"],"affirm":"Right: control is always the controller's doing, never the target's, no matter how long they stayed."},
  {"id":"rr-1310","cat":"tools-and-help","type":"reflect","persona":"any","source":"first warm move","relearn":"Small warmth, said out loud, is the antidote to contempt and the quiet glue of a healthy bond.","hook":"Lensy: what's a small warm thing you could do for a partner this week?","prompt":"Picture it.","options":["Say one real thank-you","Ask about their day","Plan something they'd love","Just listen fully"],"affirm":"Small warmth, said out loud, is the antidote to contempt and the quiet glue of a healthy bond."},
  {"id":"rr-1311","cat":"tools-and-help","type":"reflect","persona":"Meena, 20","source":"rebuild list","relearn":"Rebuilding your own life, friends, interests, plans, is the way through; you were whole before and still are.","hook":"Lensy: rebuilding after a hard relationship, what's one piece of your own life to grow back?","prompt":"Choose a start.","options":["My friendships","A skill or hobby","My savings","My own plans"],"affirm":"Rebuilding your own life, friends, interests, plans, is the way through; you were whole before and still are."},
  {"id":"rr-1312","cat":"tools-and-help","type":"reflect","persona":"Rohan, 20","source":"rohan's exit","relearn":"Leaving something that isn't right is brave, not a failure; it's the start of a better story, not the end of yours.","hook":"Lensy: leaving a relationship that isn't working, brave or a failure?","prompt":"Where do you land?","options":["Brave, honestly","Starting to think brave","Still feels like failing","Brave for others, hard for me"],"affirm":"Leaving something that isn't right is brave, not a failure; it's the start of a better story, not the end of yours."},
  {"id":"rr-1313","cat":"tools-and-help","type":"reflect","persona":"any","source":"trust check","relearn":"Trust is the absence of monitoring; whatever it feels like for you, it shouldn't need surveillance to exist.","hook":"Lensy: what does trust feel like to you in a relationship?","prompt":"What comes to mind?","options":["No need to check up","Space without guilt","Believing their word","Calm when apart"],"affirm":"Trust is the absence of monitoring; whatever it feels like for you, it shouldn't need surveillance to exist."},
  {"id":"rr-1314","cat":"tools-and-help","type":"reflect","persona":"any","source":"one truth forward","relearn":"Carry that one truth and you're better equipped to build healthy love and protect yourself if it isn't.","hook":"Lensy: of everything here, which relationship truth do you want to keep?","prompt":"Choose one.","options":["Built, not found","Repair beats no fights","Leaving can be brave","Help is strength"],"affirm":"Carry that one truth and you're better equipped to build healthy love and protect yourself if it isn't."},
  {"id":"rr-1315","cat":"tools-and-help","type":"reflect","persona":"any","source":"equipped","relearn":"Build, repair, read, leave, get help: that toolkit sets you up for real love and a safe exit if you ever need one.","hook":"Lensy: build, repair, read the flags, leave safely, get help. Feel more equipped?","prompt":"How's it sitting?","options":["Yes, equipped","Getting there","More than before","Ready to use it"],"affirm":"Build, repair, read, leave, get help: that toolkit sets you up for real love and a safe exit if you ever need one."},
  {"id":"rr-1316","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"asking myth","relearn":"Asking for help is strength; you don't have to handle a scary relationship alone.","hook":"\"Asking for help means you're weak.\"","myth":{"un":"Asking for help means you're weak.","re":"Reaching for help when something's wrong is strength, not weakness.","why":"Naming a problem and seeking support takes more courage than suffering in silence."}},
  {"id":"rr-1317","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"fix-them myth","relearn":"You can't love someone out of control; the change is theirs to make, not your job.","hook":"\"If you just love them enough, you can fix the controlling.\"","myth":{"un":"If you just love them enough, you can fix the controlling.","re":"You can't love someone out of controlling you; it isn't yours to fix.","why":"Control is a choice the other person makes, so only they can change it, not your love."}},
  {"id":"rr-1318","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"no-fights myth","relearn":"Good couples fight and repair; never fighting isn't the goal, repairing well is.","hook":"\"A good couple never fights.\"","myth":{"un":"A good couple never fights.","re":"Conflict is normal; what makes a couple strong is repairing well, not never fighting.","why":"Couples who repair after conflict last; it's contempt, not disagreement, that predicts breakdown."}},
  {"id":"rr-1319","cat":"tools-and-help","type":"strike-rewrite","persona":"Aarti, 21","source":"leaving myth","relearn":"Leaving an unhealthy relationship is brave, not a failure; it's the start of a safer story.","hook":"\"Leaving means you failed at the relationship.\"","myth":{"un":"Leaving means you failed at the relationship.","re":"Leaving an unhealthy relationship is brave and valid, never a failure.","why":"Walking away from harm protects you; it's the start of a safer story, not a verdict on you."}},
  {"id":"rr-1320","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"silence myth","relearn":"A real break is short, named and returns; the silent treatment is control, not taking space.","hook":"\"Giving the silent treatment is just taking space.\"","myth":{"un":"Giving the silent treatment is just taking space.","re":"A healthy break is brief, named and you return; the silent treatment is punishment.","why":"A break self-soothes then repairs; open-ended silence is used to control, not to cool down."}},
  {"id":"rr-1321","cat":"tools-and-help","type":"strike-rewrite","persona":"any","source":"stayed-too-long myth","relearn":"Staying long doesn't mean it wasn't bad; control traps people by design, and that's never their failing.","hook":"\"If they stayed so long, it can't be that bad.\"","myth":{"un":"If they stayed so long, it can't be that bad.","re":"Control traps capable people by design; staying as long as someone did is never a failing.","why":"Abuse isolates and erodes confidence on purpose, so leaving is hard for anyone, not a weakness."}},
  {"id":"rr-1322","cat":"tools-and-help","type":"strike-rewrite","persona":"Zoya, 21","source":"breakup-worth myth","relearn":"A breakup isn't proof something's wrong with you; you were whole before and you're whole after.","hook":"\"If they left you, something must be wrong with you.\"","myth":{"un":"If they left you, something must be wrong with you.","re":"A breakup is not a verdict on your worth; you were whole before and you're whole after.","why":"Two people not fitting says nothing is broken in you; your worth was never theirs to set."}},
  {"id":"rr-1323","cat":"tools-and-help","type":"strike-rewrite","persona":"Rohan, 20","source":"tough-it-out myth","relearn":"Toughing out heartbreak alone isn't strength; leaning on support is how you actually heal.","hook":"\"Real men just tough out a breakup alone.\"","myth":{"un":"Real men just tough out a breakup alone.","re":"Heartbreak is real grief; leaning on support beats toughing it out alone.","why":"Isolating slows healing, while a friend, routine or a counsellor actually moves you through it."}},
  {"id":"rr-1324","cat":"tools-and-help","type":"spot","persona":"any","source":"control hidden","relearn":"Care trusts and frees you; demanding location and issuing ultimatums is control wearing care's clothes.","hook":"Spot the two lines that are control dressed as care.","scene":[{"id":"a","text":"'Have fun with your friends tonight'","trick":false},{"id":"b","text":"'Send a photo so I know where you are'","trick":true},{"id":"c","text":"'Take your time deciding'","trick":false},{"id":"d","text":"'Delete him or we're finished'","trick":true},{"id":"e","text":"'I trust you completely'","trick":false}],"why":"Demanding location photos and ultimatums over your friends are control; trust and freedom are care."},
  {"id":"rr-1325","cat":"tools-and-help","type":"spot","persona":"any","source":"wreckers in talk","relearn":"Contempt and defensiveness wreck a fight; 'I' statements, owning it and asking to retry repair it.","hook":"Spot the two conflict wreckers in this argument.","scene":[{"id":"a","text":"'I felt hurt when you were late'","trick":false},{"id":"b","text":"'You're pathetic, as usual' (eye-roll)","trick":true},{"id":"c","text":"'Fair, that part was on me'","trick":false},{"id":"d","text":"'It's never my fault, always yours'","trick":true},{"id":"e","text":"'Can we take a breath and retry?'","trick":false}],"why":"Contempt ('pathetic', eye-roll) and defensiveness ('never my fault') are the wreckers; the rest repair."},
  {"id":"rr-1326","cat":"tools-and-help","type":"spot","persona":"any","source":"isolation moves","relearn":"Cutting you off from friends and family is isolation, not protection; healthy love welcomes your people.","hook":"Spot the two lines that are isolating you, not protecting you.","scene":[{"id":"a","text":"'Your sister can visit anytime'","trick":false},{"id":"b","text":"'Your friends are a bad influence, drop them'","trick":true},{"id":"c","text":"'Go to your reunion, enjoy'","trick":false},{"id":"d","text":"'You don't need anyone but me'","trick":true},{"id":"e","text":"'I'm glad you have your people'","trick":false}],"why":"'Drop your friends' and 'you need only me' cut you off; welcoming your people is the healthy sign."},
  {"id":"rr-1327","cat":"tools-and-help","type":"spot","persona":"any","source":"gaslight lines","relearn":"Gaslighting denies what happened and attacks your memory; a fair partner compares views and hears you.","hook":"Spot the two gaslighting lines that twist your reality.","scene":[{"id":"a","text":"'I remember it differently, let's compare'","trick":false},{"id":"b","text":"'That never happened, you're imagining it'","trick":true},{"id":"c","text":"'You're allowed to feel upset'","trick":false},{"id":"d","text":"'You're too crazy to trust your memory'","trick":true},{"id":"e","text":"'Tell me how you saw it'","trick":false}],"why":"'That never happened' and 'too crazy to trust your memory' make you doubt reality; that's gaslighting."},
  {"id":"rr-1328","cat":"tools-and-help","type":"spot","persona":"Meena, 20","source":"fake help","relearn":"Correct India lines: women 181 or 1091, emergency 112, Tele-MANAS 14416; ignore wrong numbers.","hook":"Spot the two wrong India helpline claims.","scene":[{"id":"a","text":"Women's helpline is 181","trick":false},{"id":"b","text":"Emergency is 999","trick":true},{"id":"c","text":"Tele-MANAS is 14416","trick":false},{"id":"d","text":"Women in distress is 1091","trick":false},{"id":"e","text":"Women's helpline is 100","trick":true}],"why":"India emergency is 112, not 999, and the women's helpline is 181 or 1091, not 100."},
  {"id":"rr-1329","cat":"tools-and-help","type":"spot","persona":"Zoya, 21","source":"breakup traps","relearn":"Numbing and isolating slow healing; talking, routine and letting yourself grieve are the way through.","hook":"Spot the two unhealthy coping moves after a breakup.","scene":[{"id":"a","text":"Calling a friend to talk it out","trick":false},{"id":"b","text":"Drinking nightly to feel nothing","trick":true},{"id":"c","text":"Sticking to your daily routine","trick":false},{"id":"d","text":"Refusing all help, alone is 'strong'","trick":true},{"id":"e","text":"Letting yourself grieve","trick":false}],"why":"Nightly numbing and refusing all help slow healing; talking, routine and grieving move you through."},
  {"id":"rr-1330","cat":"tools-and-help","type":"spot","persona":"any","source":"pressure dressed up","relearn":"Real love never says 'prove it' by giving up your goals or privacy; that's pressure, not love.","hook":"Spot the two pressure lines hiding behind 'love'.","scene":[{"id":"a","text":"'No rush, decide when you're ready'","trick":false},{"id":"b","text":"'If you loved me you'd skip your exam'","trick":true},{"id":"c","text":"'Your goals matter to me'","trick":false},{"id":"d","text":"'Prove your love: give me your passwords'","trick":true},{"id":"e","text":"'I support whatever you choose'","trick":false}],"why":"'If you loved me, skip your exam' and 'prove it with passwords' weaponise love to control you."},
  {"id":"rr-1331","cat":"tools-and-help","type":"spot","persona":"any","source":"victim-blame catch","relearn":"Never blame someone disclosing abuse; believe them, say it's not their fault, and help them find support.","hook":"Spot the two victim-blaming responses to someone disclosing abuse.","scene":[{"id":"a","text":"'I believe you'","trick":false},{"id":"b","text":"'What did you do to provoke it?'","trick":true},{"id":"c","text":"'It's not your fault'","trick":false},{"id":"d","text":"'You must like the drama if you stay'","trick":true},{"id":"e","text":"'Let's find help together'","trick":false}],"why":"'What did you do to provoke it' and 'you must like the drama' blame the victim; abuse is the abuser's fault."},
  {"id":"rr-1332","cat":"tools-and-help","type":"role-play","persona":"any","source":"name a need","hook":"Three weekends running, Tanvi planned everything with her flatmates and told you last.","setup":"Tonight she sits down beside you.","steps":[{"prompt":"Tanvi asks: \"You've been quiet all evening. Did I do something?\"","options":[{"text":"\"I felt sidelined this week. I'd love us to plan together.\"","then":"She turns to face you. \"Oh. I didn't see it that way. Tell me more.\"","best":true},{"text":"\"You always put me last. You never think about me.\"","then":"Tanvi's face hardens. \"That's not fair. I asked you twice last month.\""},{"text":"\"No, it's nothing. I'm just tired.\"","then":"\"Okay,\" she says slowly. She doesn't look convinced."},{"text":"\"Maybe I'll start making my own plans without you too.\"","then":"She blinks. \"Is that a threat? What's going on?\""}],"why":"\"I felt\" names the hurt without an attack, so Tanvi can actually hear it."},{"prompt":"Tanvi says: \"Is this about the weekend plans? My flatmates just move fast.\"","options":[{"text":"\"It is. Could we plan one weekend a month together first?\"","then":"Tanvi nods. \"That's fair. The first weekend of the month is ours.\"","best":true},{"text":"\"They move fast and you just follow them. That's the problem.\"","then":"She crosses her arms. \"So now my friends are the problem?\""},{"text":"\"It's fine. I know they matter to you.\"","then":"She smiles, relieved. \"Good. I was worried it was something big.\""},{"text":"\"It is. Just include me more from now on.\"","then":"\"More how?\" she asks. \"I honestly don't know what you want.\""}],"why":"A small, specific ask is easier to say yes to than blame or a vague request."},{"prompt":"Next week, Tanvi says: \"The group's doing a Lonavala trip on Saturday. I said we'd both come.\"","options":[{"text":"\"I'd have liked you to ask me first. Let's check next time.\"","then":"She pauses. \"You're right. I'll text you before I say yes for us.\"","best":true},{"text":"\"Great, whatever you decided is fine with me.\"","then":"\"Perfect!\" she says, and adds you to the trip group without asking."},{"text":"\"See? You've done it again. You never listen to anything I say.\"","then":"Tanvi sighs. \"I thought I was including you this time.\""},{"text":"\"Sure, I'll come along. We can talk about the planning part later.\"","then":"\"Cool,\" she says. The talk never comes, and next month it happens again."}],"why":"Naming it calmly, in the moment, with a simple ask gives her an easy change to make."}],"relearn":"An 'I felt...' line names your hurt without an attack, so it can be heard."},
  {"id":"rr-1333","cat":"tools-and-help","type":"role-play","persona":"any","source":"ask for a break","hook":"Varun lent his cousin money from your shared trip fund, and the argument is heating up fast.","setup":"Your heart is racing and you can't think straight.","steps":[{"prompt":"Varun says: \"So you're just going to stand there? Say something!\"","options":[{"text":"\"I'm flooded. Let's pause and come back to this in twenty.\"","then":"Varun stops pacing. \"Okay. Twenty minutes. I'll make tea.\"","best":true},{"text":"\"I'm done. Don't talk to me until you apologise.\"","then":"His jaw tightens. \"So I get the silent treatment now?\""},{"text":"\"Fine! You're always right, aren't you?\"","then":"\"Wow,\" he says flatly. \"That's really mature.\""},{"text":"\"I need a break from this. I'm going out.\"","then":"He calls after you. \"When are we finishing this?\""}],"why":"Saying you're flooded and when you'll return makes a break a pause, not a punishment."},{"prompt":"Later, Varun says: \"I'm calmer now. But I still don't get why you're this upset.\"","options":[{"text":"\"The trip fund was ours. I felt left out of the decision.\"","then":"He sits down. \"I didn't think of it as ours. That's fair.\"","best":true},{"text":"\"You never think before you do anything with our money.\"","then":"\"Never?\" He stiffens. \"I covered your rent share in March.\""},{"text":"\"Forget it. It's done now.\"","then":"\"Okay,\" he says, relieved. The trip fund stays a sore spot."},{"text":"\"Your cousin always takes advantage of you.\"","then":"His face shuts. \"Leave my family out of this.\""}],"why":"Coming back to name the hurt calmly is what turns a break into repair."},{"prompt":"A week later, another money talk starts heating up. Varun says: \"Here we go again.\"","options":[{"text":"\"I'm flooding again. Pause till after dinner, then finish?\"","then":"Varun exhales. \"After dinner. I'll hold you to it.\"","best":true},{"text":"\"Here we go again is right. You just never learn, do you?\"","then":"He goes cold. \"Then why do you even bother with me?\""},{"text":"\"Let's not do this. I'm going to bed.\"","then":"He throws up his hands. \"Great. Another thing we never finish.\""},{"text":"\"Fine, you win. Do whatever you want with the money.\"","then":"\"That's not what I want either,\" he says, frustrated."}],"why":"The same move works every time: name the flood, set a time, come back."}],"relearn":"A healthy break is named and you return; that's not the silent treatment."},
  {"id":"rr-1334","cat":"tools-and-help","type":"role-play","persona":"any","source":"hold the phone line","hook":"Your boyfriend Ishaan keeps asking for your phone password to prove you love him.","setup":"He holds out his hand for your phone.","steps":[{"prompt":"Ishaan says: \"If you really loved me, you'd have nothing to hide.\"","options":[{"text":"\"My phone stays private. Trust isn't proven by passwords.\"","then":"His hand drops. \"So you are hiding something.\"","best":true},{"text":"\"You're right. Couples shouldn't keep secrets from each other.\"","then":"He scrolls through your chats. \"Who's this Aditya?\""},{"text":"\"Sorry. I guess I've been a bit distant lately.\"","then":"\"You have,\" he says. \"So give it to me and I'll feel better.\""},{"text":"\"Only if I get to read all of yours too.\"","then":"\"Fine,\" he says. \"But I'm checking yours every night.\""}],"why":"Privacy isn't a secret. Love doesn't need a password as proof."},{"prompt":"Two days later, Ishaan says: \"I saw you were online at 1 a.m. Who were you talking to?\"","options":[{"text":"\"I don't have to account for every minute. That's not okay.\"","then":"He frowns. \"I'm only asking because I care about you.\"","best":true},{"text":"\"Just Riya. Sorry, I should have told you first.\"","then":"\"Next time, tell me before you go online,\" he says."},{"text":"\"Are you tracking me now? You're so insecure.\"","then":"His voice rises. \"Insecure? I'm the only one who cares here.\""},{"text":"\"I know you check because you care. It was just Riya.\"","then":"He nods, pleased. \"Good. Then you won't mind if I keep checking.\""}],"why":"Watching when you're online is monitoring, and monitoring is control, not care."},{"prompt":"Later, your friend Sana says: \"You seem tense lately. Is everything okay with Ishaan?\"","options":[{"text":"\"Not really. He keeps checking up on me and I feel watched.\"","then":"Sana squeezes your hand. \"That's not okay. I'm really glad you told me.\"","best":true},{"text":"\"All fine! He's just really protective of me.\"","then":"Sana smiles. \"Cute. I wish someone cared that much about me.\""},{"text":"\"It's my fault. I've been giving him reasons to worry.\"","then":"Sana frowns. \"Reasons? Like what?\" You can't actually name one."},{"text":"\"It's nothing I can't sort out with him myself.\"","then":"\"Okay,\" Sana says. \"But I'm here if that changes.\""}],"why":"Telling someone you trust breaks the isolation control needs. And it's never your fault."}],"relearn":"You can keep your phone private; trust isn't proven by handing over passwords."},
  {"id":"rr-1335","cat":"tools-and-help","type":"role-play","persona":"any","source":"own your part","hook":"In last night's argument about the dishes, you snapped at Aditya and called him useless.","setup":"This morning he's quiet over breakfast.","steps":[{"prompt":"Aditya says: \"You really hurt me last night.\"","options":[{"text":"\"That was on me. I was sharp and I'm sorry.\"","then":"His shoulders drop. \"Thank you. That means a lot.\"","best":true},{"text":"\"Well, you started it. It's not really my fault.\"","then":"\"So it's my fault you called me useless?\" he asks quietly."},{"text":"\"I'm sorry you felt hurt.\"","then":"He looks up. \"That's not really an apology, is it?\""},{"text":"\"I was tired. You know I didn't mean it.\"","then":"\"You're always tired,\" he says, and picks up his plate."}],"why":"Owning your part, with no excuses, is the antidote to defensiveness."},{"prompt":"Aditya says: \"It's not the first time you've said things like that.\"","options":[{"text":"\"You're right. I want to stop. Will you tell me when I do it?\"","then":"He nods slowly. \"Okay. I will. I just need it to change.\"","best":true},{"text":"\"I already said sorry. Why drag up all the old stuff now?\"","then":"\"Because it keeps happening,\" he says, and leaves for class."},{"text":"\"Fine. I'm a terrible partner. Happy now?\"","then":"He sighs. \"That's not what I said. Now I'm the one comforting you.\""},{"text":"\"Okay, I'll be nicer from now on. Can we please move on?\"","then":"\"Sure,\" he says. He doesn't sound like he believes it."}],"why":"Hearing the pattern, not just the one moment, shows you're taking it seriously."},{"prompt":"A week later, in another tense talk, Aditya says: \"You're doing that tone again.\"","options":[{"text":"\"You're right. Let me say that again, more gently.\"","then":"He relaxes. \"Thanks. Okay, go on.\"","best":true},{"text":"\"I'm not doing any tone. You're imagining it.\"","then":"\"I'm not imagining it,\" he says, hurt. \"It's the same tone as last week.\""},{"text":"\"Well, what you said was really annoying.\"","then":"His voice goes flat. \"So it's still my fault.\""},{"text":"\"Sorry, sorry. Let's just drop it then.\"","then":"\"We never finish anything,\" he says quietly."}],"why":"Catching yourself mid-argument and owning it is repair in real time."},{"prompt":"Later, Aditya asks: \"What do you think sets you off like that?\"","options":[{"text":"\"When I'm stressed I get sharp. I'm working on noticing it.\"","then":"He takes your hand. \"Thanks for telling me. Tell me if I can help.\"","best":true},{"text":"\"Honestly? It's when you don't listen to me properly.\"","then":"He pulls back. \"So we're back to it being me.\""},{"text":"\"I don't know. It's just how I am.\"","then":"\"Then how is it supposed to change?\" he asks."},{"text":"\"It's no big deal. Everyone snaps sometimes.\"","then":"\"It's a big deal to me,\" he says quietly."}],"why":"Knowing what sets you off helps you own it before it hurts someone."}],"relearn":"Owning your part is the antidote to defensiveness; it repairs faster than blame."},
  {"id":"rr-1336","cat":"tools-and-help","type":"role-play","persona":"any","source":"believe a friend","hook":"Your friend Rahul tells you his girlfriend threatens him when he goes out without her.","setup":"You're alone in the canteen after class.","steps":[{"prompt":"Rahul says: \"I don't know why I'm telling you. It's probably nothing.\"","options":[{"text":"\"I believe you. It's not your fault, and I'm here.\"","then":"Rahul looks up. \"You believe me? I thought you'd laugh.\"","best":true},{"text":"\"Are you sure you're not exaggerating it a bit?\"","then":"His face closes. \"Yeah. Forget I said anything.\""},{"text":"\"Her? She seems so sweet. What did you do to upset her?\"","then":"\"Nothing,\" he says quietly. \"Maybe I'm the problem.\""},{"text":"\"You need to dump her today. I'm serious.\"","then":"He shrinks back. \"It's not that simple. Forget it.\""}],"why":"Believing him and saying it's not his fault makes it safe for him to keep talking."},{"prompt":"Two days later, Rahul texts: \"She says she'll ruin me if I ever leave. Maybe I should just try harder.\"","options":[{"text":"\"You can't fix her threats. What would make you feel safer?\"","then":"He's slow to reply. \"Maybe not going to hers alone. I'll think about it.\"","best":true},{"text":"\"Yes, maybe if you're more careful she'll calm down.\"","then":"\"Okay,\" he replies. \"I'll stop seeing you all for a while.\""},{"text":"\"Leave her now. Pack a bag and come to mine tonight.\"","then":"He goes quiet for a day. \"I can't just leave like that.\""},{"text":"\"That's really between you two. I'd rather not get in the middle.\"","then":"\"Right. Sorry I brought it up,\" he replies, and goes offline."}],"why":"Her threats aren't his to fix. Asking what he needs respects his pace and his choices."},{"prompt":"A week later, Rahul says: \"She scared me last night. I don't know who to call.\"","options":[{"text":"\"Call 112 if you're in danger. Shall we find a counsellor too?\"","then":"Rahul breathes out. \"112. Okay. And yes. Can you help me look?\"","best":true},{"text":"\"Call her parents tonight. They'll know how to sort her out.\"","then":"\"Her parents think I'm the problem,\" he says. \"They'd tell her everything.\""},{"text":"\"Just stay at hers and keep her calm till it passes.\"","then":"\"I've been doing that for months,\" he says. \"It isn't working.\""},{"text":"\"I'll go over there myself and have it out with her tonight.\"","then":"\"Please don't,\" he says fast. \"She'll know I told you.\""}],"why":"Pointing him to real help, and staying beside him, supports him without taking over."},{"prompt":"A month later, Rahul says: \"I'm still with her. You must think I'm weak.\"","options":[{"text":"\"No. Control traps anyone. I'm here, whatever you decide.\"","then":"His eyes fill. \"Thanks. I think I needed to hear that.\"","best":true},{"text":"\"Honestly, I just don't get why you haven't left her yet.\"","then":"He looks away. \"Yeah. Neither do I.\""},{"text":"\"If you won't leave, I can't keep hearing about it.\"","then":"\"Okay,\" he says quietly. He stops telling you things."},{"text":"\"It's fine. Maybe she really will change.\"","then":"\"Maybe,\" he says, like he's said it to himself many times."}],"why":"Staying without judgement keeps the door open. Staying isn't weakness, and it's never his fault."}],"relearn":"To a friend disclosing abuse: believe them, say it's not their fault, stay with them."},
  {"id":"rr-1337","cat":"tools-and-help","type":"role-play","persona":"any","source":"keep your friends","hook":"Your friends' Rishikesh trip is this weekend. Your partner Nikhil wants you to skip it.","setup":"He brings it up over dinner.","steps":[{"prompt":"Nikhil says: \"I was hoping we'd get the weekend. Do you really have to go?\"","options":[{"text":"\"I'm going on the trip. I'll see you right after.\"","then":"He's quiet a moment. \"Okay. Send me a photo of the river?\"","best":true},{"text":"\"Okay, I'll cancel. A good partner puts you first.\"","then":"He grins. \"Really?\" Your friends' group chat goes quiet."},{"text":"\"Let me see if I can come back a day early for you.\"","then":"\"That'd be great,\" he says. Your friends sigh when you tell them."},{"text":"\"You can't stop me from seeing my friends.\"","then":"He looks stung. \"I wasn't trying to stop you. I just asked.\""}],"why":"Keeping your plans, and making time for him after, is healthy independence."},{"prompt":"The next month, your friends plan a dinner. Nikhil says: \"Again? We barely get time together.\"","options":[{"text":"\"Let's plan our own time too. Friday could be ours.\"","then":"He brightens. \"Friday. Okay, I'll plan something.\"","best":true},{"text":"\"You're right. I'll stop making plans with them.\"","then":"\"Really?\" he says, pleased. Over the next weeks, your friends' invites slow down."},{"text":"\"You're always busy too. Don't put this on me.\"","then":"He stiffens. \"I wasn't blaming you.\""},{"text":"\"Fine. I'll just bring you along to all of them.\"","then":"\"Great,\" he says. At dinner, your friends exchange a look."}],"why":"Making time for both keeps your friends and meets his need too."},{"prompt":"Weeks later, Meera invites you to her birthday dinner. Nikhil admits: \"Honestly, I get jealous when you're with your friends.\"","options":[{"text":"\"Thanks for telling me. You can trust me, and I'm still going.\"","then":"He nods. \"Okay. I'll work on it. Have fun.\"","best":true},{"text":"\"Aww, that's sweet. It shows how much you care.\"","then":"He smiles. \"So you get it. Stay home with me, then.\""},{"text":"\"Then I'll see them less often, so you never have to feel that.\"","then":"\"That would really help,\" he says, relieved."},{"text":"\"That's your problem to deal with, not mine.\"","then":"His face falls. \"I was trying to be honest with you.\""}],"why":"Jealousy isn't proof of love. You can be kind about it and still keep your plans."}],"relearn":"Keeping your own friends and plans is healthy independence, not a betrayal."},
  {"id":"rr-1338","cat":"tools-and-help","type":"role-play","persona":"Zoya, 21","source":"no-contact reply","hook":"It's been a week since you and Ira broke up, and you've kept no-contact to heal.","setup":"Your phone lights up with her name.","steps":[{"prompt":"Ira texts: \"Hey, just checking in. How are you doing?\"","options":[{"text":"\"I need space to heal, so I won't be replying for now.\"","then":"A minute later: \"Okay. I understand. Take care.\"","best":true},{"text":"\"Hey! Let's catch up soon. I've missed you so much.\"","then":"Ira replies fast: \"Me too! Coffee tomorrow?\""},{"text":"\"Oh, now you care? Bit late for that.\"","then":"She sends: \"Wow. I was just being nice.\""},{"text":"\"I'm doing amazing, honestly. Never been better!\"","then":"\"Glad to hear it!\" she sends, with three hearts. You stare at it for an hour."}],"why":"A short, clear line protects your healing without being cruel."},{"prompt":"Two weeks later, Ira messages: \"Can I come get my books? I could drop your hoodie too.\"","options":[{"text":"\"Please leave them with Meher. I'll pick mine up there.\"","then":"\"Sure,\" she replies. \"I'll drop them with Meher on Friday.\"","best":true},{"text":"\"Sure, come over and we can talk properly.\"","then":"\"Yes! I'll bring snacks,\" she replies. It already feels like a date."},{"text":"\"Just keep everything. I don't care anymore.\"","then":"\"That's harsh,\" she replies. \"They're my books.\""},{"text":"\"Come Saturday. It'll be quick and totally fine.\"","then":"\"Great! I'll stay for chai,\" she replies."}],"why":"Swapping things through a friend keeps the distance you need to heal."},{"prompt":"Late one night, Ira texts: \"I miss us. Was it really that bad?\"","options":[{"text":"\"I need space right now. Take care, Ira.\"","then":"A long pause. \"Okay. I'll stop texting. I'm sorry.\"","best":true},{"text":"\"Call me. I can't sleep either.\"","then":"Your phone rings at once. \"Hey. I knew you'd pick up.\""},{"text":"\"Yes. It was awful, and so were you.\"","then":"\"Wow,\" she sends. \"I guess I deserved that.\""},{"text":"\"Let's talk about it tomorrow when we're both awake.\"","then":"\"Yes! Call me at lunch?\" she replies. The space is gone again."}],"why":"Holding your space kindly, even when you miss her, is what lets you heal."},{"prompt":"A month on, your friend Meher asks: \"How are you really doing with the Ira stuff?\"","options":[{"text":"\"Some days are hard. Can we get dinner this week?\"","then":"Meher grins. \"Friday. My treat. You're not doing this alone.\"","best":true},{"text":"\"I'm totally over it. I don't even think about her.\"","then":"\"Okay,\" Meher says, not quite believing you."},{"text":"\"I keep checking her Instagram. Honestly, it helps.\"","then":"Meher winces. \"Does it, though? You look exhausted.\""},{"text":"\"I'll feel better once I'm dating someone new.\"","then":"\"Maybe,\" Meher says. \"But you don't need rescuing.\""}],"why":"Leaning on friends, not your ex's feed, is how healing takes hold."}],"relearn":"No-contact is a healthy tool. Protecting your space isn't rude: it's how you heal."},
  {"id":"rr-1339","cat":"tools-and-help","type":"role-play","persona":"Deepak, 20","source":"ask for support","hook":"Since your breakup with Kavya, you've skipped meals and lectures, and nights feel endless.","setup":"Your friend Arun catches you outside the library.","steps":[{"prompt":"Arun asks: \"Hey, haven't seen you in ages. How are you doing?\"","options":[{"text":"\"Honestly, I'm struggling. Could we talk this week?\"","then":"Arun stops walking. \"Of course. Chai after class tomorrow?\"","best":true},{"text":"\"I'm totally fine. Don't worry about me at all.\"","then":"\"Cool, cool,\" Arun says, and heads off. The evening feels longer."},{"text":"\"Busy with exams, yaar. You know how it is.\"","then":"\"Same,\" Arun laughs. \"Good luck, man.\" And he's gone."},{"text":"\"Not great. But it's my mess to handle alone.\"","then":"Arun hesitates. \"You sure? Okay, but call me if you need.\""}],"why":"Letting a friend in, even a little, beats toughing it out alone."},{"prompt":"A few days later, Arun asks: \"Since the breakup with Kavya, what's been hardest?\"","options":[{"text":"\"Not sleeping. And feeling like I wasn't good enough.\"","then":"Arun nods. \"That's grief, man. It doesn't mean something's wrong with you.\"","best":true},{"text":"\"Nothing really. I've moved on already.\"","then":"\"Okay,\" Arun says, but he keeps glancing at you."},{"text":"\"Everything. But gaming all night takes my mind off it.\"","then":"Arun frowns. \"All night? That doesn't sound like it's helping.\""},{"text":"\"Forget me. How's your semester going?\"","then":"Arun answers, then pauses. \"You changed the subject fast.\""}],"why":"Naming what you feel helps grief move. A breakup isn't a verdict on your worth."},{"prompt":"Weeks later, Arun says: \"You still seem really low. Have you thought about talking to someone?\"","options":[{"text":"\"Maybe I should. I'll call Tele-MANAS on 14416 tonight.\"","then":"Arun nods. \"Want me to sit with you while you call?\"","best":true},{"text":"\"Counselling is for people with real problems.\"","then":"\"This is a real problem,\" Arun says gently. \"You're allowed help.\""},{"text":"\"I can't afford a counsellor. I'll just push through.\"","then":"\"Tele-MANAS is free,\" Arun says. \"Think about it?\""},{"text":"\"I'll wait. It should pass on its own soon.\"","then":"\"It's been six weeks,\" Arun says quietly. \"I'm worried.\""}],"why":"Low mood that won't lift deserves real support, and Tele-MANAS 14416 is free."},{"prompt":"Later, Arun asks: \"What would help you on the bad evenings?\"","options":[{"text":"\"Maybe cricket on Sundays again. And texting you when it's bad.\"","then":"Arun grins. \"Sunday, 7 a.m. I'm holding you to it.\"","best":true},{"text":"\"Honestly? A couple of drinks every night to numb it out.\"","then":"Arun's face falls. \"That'll make the mornings worse, man.\""},{"text":"\"Nothing, really. I just need to stay alone until it's over.\"","then":"\"You don't have to be alone,\" Arun says. \"Seriously.\""},{"text":"\"Getting Kavya back. Then I'd be fine.\"","then":"Arun is quiet. \"You were you before her. You still are.\""}],"why":"Routine, friends and your own interests rebuild you. You were whole before, and you're whole now."}],"relearn":"Letting a friend in beats toughing it out alone; leaning on support is strength."},
  {"id":"rr-1350","type":"sort","hook":"Sort: respect, or disrespect?","items":[{"id":"a","text":"They listen when you speak"},{"id":"b","text":"They take your feelings seriously"},{"id":"c","text":"They speak well of you to others"},{"id":"d","text":"They talk over you"},{"id":"e","text":"They mock what matters to you"},{"id":"f","text":"They run you down to friends"}],"bins":[{"id":"respect","label":"Respect","valence":"pos"},{"id":"dis","label":"Disrespect","valence":"neg"}],"key":{"a":"respect","b":"respect","c":"respect","d":"dis","e":"dis","f":"dis"},"relearn":"Listening, taking your feelings seriously and speaking well of you is respect; talking over, mocking and running you down isn't.","source":"respect","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1351","type":"sort","hook":"Sort: honest transparency, or being monitored?","items":[{"id":"a","text":"You share your day because you want to"},{"id":"b","text":"You tell them where you are, freely"},{"id":"c","text":"You introduce them to your friends"},{"id":"d","text":"You must share your location always"},{"id":"e","text":"You hand over your passwords on demand"},{"id":"f","text":"Your phone is checked nightly"}],"bins":[{"id":"open","label":"Voluntary","valence":"pos"},{"id":"watch","label":"Monitored","valence":"neg"}],"key":{"a":"open","b":"open","c":"open","d":"watch","e":"watch","f":"watch"},"relearn":"Sharing freely because you want to is healthy transparency; mandatory location, passwords and phone-checks are monitoring.","source":"transparency","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1352","type":"sort","hook":"Sort: your own life, or your world shrinking?","items":[{"id":"a","text":"You still see your old friends"},{"id":"b","text":"You keep your own hobbies"},{"id":"c","text":"You have your own savings"},{"id":"d","text":"You've dropped everyone for them"},{"id":"e","text":"You quit things they dislike"},{"id":"f","text":"You ask before spending anything"}],"bins":[{"id":"whole","label":"Stays whole","valence":"pos"},{"id":"shrink","label":"Shrinking","valence":"neg"}],"key":{"a":"whole","b":"whole","c":"whole","d":"shrink","e":"shrink","f":"shrink"},"relearn":"Keeping friends, hobbies and your own money keeps you whole; dropping everyone and needing permission means your world is shrinking.","source":"keeping your world","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1353","type":"sort","hook":"Sort: kindness in the small things, or the opposite?","items":[{"id":"a","text":"A check-in text on a hard day"},{"id":"b","text":"Remembering what you care about"},{"id":"c","text":"Saying thank you for small things"},{"id":"d","text":"Silence when you're struggling"},{"id":"e","text":"Forgetting things on purpose"},{"id":"f","text":"Taking your effort for granted"}],"bins":[{"id":"kind","label":"Kindness","valence":"pos"},{"id":"cold","label":"Not","valence":"neg"}],"key":{"a":"kind","b":"kind","c":"kind","d":"cold","e":"cold","f":"cold"},"relearn":"Check-ins, remembering and thanks are everyday kindness; cold silence, deliberate forgetting and taking you for granted aren't.","source":"everyday kindness","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1354","type":"sort","hook":"Sort: healthy honesty, or harshness dressed as honesty?","items":[{"id":"a","text":"Naming a hurt gently"},{"id":"b","text":"Saying what you need clearly"},{"id":"c","text":"Telling a kind truth"},{"id":"d","text":"Cruel jabs called 'just honest'"},{"id":"e","text":"Insults framed as 'real talk'"},{"id":"f","text":"Tearing you down 'for your own good'"}],"bins":[{"id":"honest","label":"Honesty","valence":"pos"},{"id":"cruel","label":"Cruelty","valence":"neg"}],"key":{"a":"honest","b":"honest","c":"honest","d":"cruel","e":"cruel","f":"cruel"},"relearn":"Naming hurts gently and stating needs is honesty; cruel jabs and insults dressed as 'real talk' are just cruelty.","source":"honesty vs cruelty","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1355","type":"sort","hook":"Sort: a partner who lifts you, or one who keeps you small?","items":[{"id":"a","text":"Glad when you grow"},{"id":"b","text":"Backs your big plans"},{"id":"c","text":"Proud of your wins"},{"id":"d","text":"Threatened by your growth"},{"id":"e","text":"Talks you out of plans"},{"id":"f","text":"Sulks when you succeed"}],"bins":[{"id":"lift","label":"Lifts you","valence":"pos"},{"id":"small","label":"Keeps you small","valence":"neg"}],"key":{"a":"lift","b":"lift","c":"lift","d":"small","e":"small","f":"small"},"relearn":"Being glad you grow, backing your plans and pride in your wins lifts you; feeling threatened and sulking keeps you small.","source":"expands my world","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1356","type":"sort","hook":"Sort: shared effort, or one person carrying it all?","items":[{"id":"a","text":"Both plan the dates sometimes"},{"id":"b","text":"Chores split fairly"},{"id":"c","text":"Both reach out first sometimes"},{"id":"d","text":"You always do the chasing"},{"id":"e","text":"You handle every task"},{"id":"f","text":"You always smooth things over"}],"bins":[{"id":"shared","label":"Shared","valence":"pos"},{"id":"onesided","label":"One-sided","valence":"neg"}],"key":{"a":"shared","b":"shared","c":"shared","d":"onesided","e":"onesided","f":"onesided"},"relearn":"Taking turns planning, splitting chores and both reaching out is shared effort; always chasing and smoothing over is one-sided.","source":"shared effort","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1357","type":"sort","hook":"Sort: a green flag, or a red flag?","items":[{"id":"a","text":"They cheer your friendships"},{"id":"b","text":"They want you rested and well"},{"id":"c","text":"They give you room to breathe"},{"id":"d","text":"They time how long you're out"},{"id":"e","text":"They pick fights when you go out"},{"id":"f","text":"They need replies within minutes"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"green","c":"green","d":"red","e":"red","f":"red"},"relearn":"Cheering your friendships, wanting you well and giving room are green; timing you, fights over going out and instant replies are red.","source":"green vs red","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1358","type":"sort","hook":"Sort: support for your goals, or quiet sabotage?","items":[{"id":"a","text":"Quizzing you before your exam"},{"id":"b","text":"Covering chores in your busy week"},{"id":"c","text":"Asking how your project's going"},{"id":"d","text":"Picking a fight the night before"},{"id":"e","text":"Guilt-tripping you for studying"},{"id":"f","text":"Calling your dream a waste"}],"bins":[{"id":"support","label":"Support","valence":"pos"},{"id":"sabotage","label":"Sabotage","valence":"neg"}],"key":{"a":"support","b":"support","c":"support","d":"sabotage","e":"sabotage","f":"sabotage"},"relearn":"Helping you study, covering chores and showing interest is support; fights before exams, guilt and calling your dream a waste is sabotage.","source":"support goals","persona":"Deepak","cat":"what-healthy-looks-like"},
  {"id":"rr-1359","type":"sort","hook":"Sort: a healthy apology, or a fake one?","items":[{"id":"a","text":"'I was wrong, I'm sorry'"},{"id":"b","text":"Naming what they'll do differently"},{"id":"c","text":"Owning their part fully"},{"id":"d","text":"'Sorry you feel that way'"},{"id":"e","text":"Apology with a 'but you...'"},{"id":"f","text":"Sorry today, same thing tomorrow"}],"bins":[{"id":"real","label":"Real sorry","valence":"pos"},{"id":"fake","label":"Fake sorry","valence":"neg"}],"key":{"a":"real","b":"real","c":"real","d":"fake","e":"fake","f":"fake"},"relearn":"Owning it plainly and naming a change is a real apology; 'sorry you feel that way', a tacked-on 'but', and no change are fake.","source":"real apology","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1360","type":"sort","hook":"Sort: comfortable closeness, or being possessed?","items":[{"id":"a","text":"Happy to see your other people"},{"id":"b","text":"Trusts you out of sight"},{"id":"c","text":"Misses you, doesn't track you"},{"id":"d","text":"Wants you to itself only"},{"id":"e","text":"Panics when you're unreachable"},{"id":"f","text":"Calls your friends 'a threat'"}],"bins":[{"id":"close","label":"Closeness","valence":"pos"},{"id":"possess","label":"Possession","valence":"neg"}],"key":{"a":"close","b":"close","c":"close","d":"possess","e":"possess","f":"possess"},"relearn":"Welcoming your people and trusting you out of sight is closeness; wanting you to itself and treating friends as threats is possession.","source":"closeness vs possession","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1361","type":"sort","hook":"Sort: feeling free with them, or walking on eggshells?","items":[{"id":"a","text":"You relax around them"},{"id":"b","text":"You can say the wrong thing safely"},{"id":"c","text":"You bring up problems openly"},{"id":"d","text":"You rehearse before you speak"},{"id":"e","text":"You brace for their mood"},{"id":"f","text":"You hide small mistakes"}],"bins":[{"id":"free","label":"Free","valence":"pos"},{"id":"eggshells","label":"Eggshells","valence":"neg"}],"key":{"a":"free","b":"free","c":"free","d":"eggshells","e":"eggshells","f":"eggshells"},"relearn":"Relaxing, speaking freely and raising problems is feeling free; rehearsing, bracing and hiding mistakes is walking on eggshells.","source":"free vs eggshells","persona":"Ananya","cat":"what-healthy-looks-like"},
  {"id":"rr-1362","type":"sort","hook":"Sort: a fair split of money, or financial control?","items":[{"id":"a","text":"You both see the budget"},{"id":"b","text":"Each keeps some own money"},{"id":"c","text":"Big spends decided together"},{"id":"d","text":"One holds all the cash"},{"id":"e","text":"You account for every rupee"},{"id":"f","text":"You're given an 'allowance'"}],"bins":[{"id":"fair","label":"Fair","valence":"pos"},{"id":"control","label":"Control","valence":"neg"}],"key":{"a":"fair","b":"fair","c":"fair","d":"control","e":"control","f":"control"},"relearn":"A shared budget, your own money and joint big decisions is fair; one holding all cash and rationing you is financial control.","source":"money equality","persona":"Meena","cat":"what-healthy-looks-like"},
  {"id":"rr-1363","type":"sort","hook":"Sort: a queer relationship marker that's healthy, or not?","items":[{"id":"a","text":"They respect who's out to whom"},{"id":"b","text":"They follow your coming-out pace"},{"id":"c","text":"They love you as you are"},{"id":"d","text":"They out you to spite you"},{"id":"e","text":"They rush your timeline"},{"id":"f","text":"They use your secret as leverage"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"not","label":"Not","valence":"neg"}],"key":{"a":"healthy","b":"healthy","c":"healthy","d":"not","e":"not","f":"not"},"relearn":"Respecting who knows, following your pace and loving you as you are is healthy; outing you or using your secret as leverage isn't.","source":"queer-inclusive","persona":"Zoya","cat":"what-healthy-looks-like"},
  {"id":"rr-1364","type":"sort","hook":"Sort: real intimacy, or pressure dressed as closeness?","items":[{"id":"a","text":"Checking in on how you feel"},{"id":"b","text":"Slowing down when you hesitate"},{"id":"c","text":"Asking, not assuming"},{"id":"d","text":"'If you loved me you would'"},{"id":"e","text":"Sulking until you give in"},{"id":"f","text":"Treating a no as rejection of them"}],"bins":[{"id":"intimacy","label":"Intimacy","valence":"pos"},{"id":"pressure","label":"Pressure","valence":"neg"}],"key":{"a":"intimacy","b":"intimacy","c":"intimacy","d":"pressure","e":"pressure","f":"pressure"},"relearn":"Checking in, slowing down and asking is real intimacy; 'if you loved me', sulking and punishing a no is pressure.","source":"intimacy vs pressure","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1365","type":"sort","hook":"Sort: a sign you can be yourself, or a sign you can't?","items":[{"id":"a","text":"You laugh at your own jokes freely"},{"id":"b","text":"You wear what you like"},{"id":"c","text":"Your opinions come out easily"},{"id":"d","text":"You shrink to fit their mood"},{"id":"e","text":"You drop topics they dislike"},{"id":"f","text":"You copy their views to keep peace"}],"bins":[{"id":"self","label":"Yourself","valence":"pos"},{"id":"shrink","label":"Not","valence":"neg"}],"key":{"a":"self","b":"self","c":"self","d":"shrink","e":"shrink","f":"shrink"},"relearn":"Being able to joke, dress and speak freely means you can be yourself; shrinking, dropping topics and copying views means you can't.","source":"be yourself","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1366","type":"sort","hook":"Sort: a relationship that expands your world, or shrinks it?","items":[{"id":"a","text":"You've met new people through them"},{"id":"b","text":"You've tried things you now love"},{"id":"c","text":"Your circle has grown"},{"id":"d","text":"You've cut off your family"},{"id":"e","text":"You've quit what you enjoyed"},{"id":"f","text":"Your circle is only them"}],"bins":[{"id":"expand","label":"Expands","valence":"pos"},{"id":"shrink","label":"Shrinks","valence":"neg"}],"key":{"a":"expand","b":"expand","c":"expand","d":"shrink","e":"shrink","f":"shrink"},"relearn":"Meeting new people, new interests and a wider circle expands your world; cut-off family, dropped joys and only-them shrinks it.","source":"the spine test","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1367","type":"reflect","hook":"Lensy: the simplest test: does it expand your world and respect you?","prompt":"Does that test feel useful?","options":["Yes","I'll use it","Worth a check"],"affirm":"That one question, asked honestly, tells you more than any rush of intensity ever could.","relearn":"The portable test: does it expand my world and respect me?","source":"the simple test","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1368","type":"reflect","hook":"Lensy: independence inside love isn't betrayal. Your own friends and space are a good sign.","prompt":"Where do you sit with that?","options":["Agreed","Hadn't framed it so","Reassuring"],"affirm":"Keeping your own friends, interests and space isn't pulling away. It's part of a love that lasts.","relearn":"Your own friends, interests and space are a healthy sign, not a betrayal.","source":"independence","persona":"Ananya","cat":"what-healthy-looks-like"},
  {"id":"rr-1369","type":"reflect","hook":"Lensy: which healthy marker would you most like more of right now?","prompt":"No wrong pick, just notice.","options":["Respect","Trust","Equality","Honest talk"],"affirm":"Naming what you want more of is the first move toward asking for it, and toward building it.","relearn":"Respect, trust, equality and honest talk are markers you can name and grow.","source":"name a marker","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1370","type":"reflect","hook":"Lensy: 'love expands your world; control shrinks it.' Sit with that for a second.","prompt":"How does it land?","options":["True","I feel that","Stays with me"],"affirm":"Holding that line in mind makes the difference between caring and controlling easy to feel.","relearn":"Love expands your world; control shrinks it.","source":"the spine","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1371","type":"reflect","hook":"Lensy: think of a relationship that felt good: what made it feel safe?","prompt":"Just notice what comes up.","options":["I felt heard","I stayed myself","I could relax"],"affirm":"Whatever you noticed is a marker worth looking for again: your own felt sense is real data.","relearn":"Feeling heard, yourself and relaxed: that felt sense of safety is a real marker.","source":"felt safety","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1372","type":"reflect","hook":"Lensy: good ones are built, not found. What's one skill you could practise?","prompt":"Pick one, no pressure.","options":["Listening","Saying sorry","Asking clearly","Appreciating"],"affirm":"Treating love as a set of skills you can practise is exactly what makes the lasting kind possible.","relearn":"Relationships are built with practisable skills, not found by luck.","source":"built not found","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1373","type":"reflect","hook":"Lensy: who in your life models a healthy relationship you'd want?","prompt":"Bring someone to mind.","options":["A friend","Family","A mentor","Still looking"],"affirm":"Real models show you what 'good' actually looks like up close, far better than any fairy tale.","relearn":"Real-life models of healthy love teach more than fairy tales.","source":"models","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1374","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"considerate not controlled","hook":"You made weekend plans with your cousins without mentioning it, and your partner Rhea is hurt.","steps":[{"prompt":"Rhea says she felt left out when she heard. What do you do?","options":[{"text":"Hear her out, then agree how you'll keep each other posted","then":"Rhea says a heads-up would help. You agree to share plans early.","best":true},{"text":"Promise to clear every plan with her first from now on","then":"Rhea looks relieved. You feel a small weight settle on you."},{"text":"Tell her she's overreacting. It's just your cousins","then":"Rhea's hurt turns to anger. The weekend starts badly."},{"text":"Cancel the plans so she feels better","then":"Rhea says you didn't have to. Your cousins are disappointed."}],"why":"Listening and agreeing on check-ins respects her feelings and your freedom."},{"prompt":"A week later, Rhea asks you to send her your plan for each day. What do you say?","options":[{"text":"I'll tell you the big plans, not every hour of my day","then":"Rhea thinks, then nods. \"Fair. The big plans are enough.\"","best":true},{"text":"Sure, I'll send my full schedule each morning","then":"By Friday, you're explaining why lunch ran late."},{"text":"No way. That's a little creepy, honestly","then":"Rhea goes red. \"I was only trying to feel included.\""},{"text":"Agree, then quietly stop after a few days","then":"Rhea notices and asks why. The talk is harder now."}],"why":"Sharing plans is considerate. Reporting every hour hands over your independence."},{"prompt":"Your college friends plan a movie night for Friday. What do you do about Rhea?","options":[{"text":"Mention it early, and suggest a plan together Saturday","then":"Rhea says have fun, and picks a café for Saturday.","best":true},{"text":"Ask her if it's okay for you to go","then":"Rhea says yes, but you notice you're now asking for passes."},{"text":"Go without saying anything. You don't owe updates","then":"Rhea finds out from a story and feels hurt again."},{"text":"Skip it. It's easier than another talk","then":"Friday is quiet. Your friends stop asking as often."}],"why":"A heads-up is considerate. You don't need permission to live your own life."}],"debrief":"You can be considerate and still keep your own life.","relearn":"Be considerate without surrendering your independence."},
  {"id":"rr-1375","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"voluntary transparency","hook":"Your partner Aman asks for your phone passcode, \"to prove there's nothing to hide.\"","steps":[{"prompt":"He's waiting for an answer. What do you do?","options":[{"text":"Say checking doesn't build trust, and ask what's worrying him","then":"Aman admits his last partner cheated. He still wants the code.","best":true},{"text":"Agree, since real couples don't keep anything private","then":"He scrolls through your chats while you sit beside him, uneasy."},{"text":"Wonder what reason you've given him, and apologise for it","then":"Aman accepts the apology, and asks for the code again."},{"text":"Take it as sweet. He must really care about you","then":"You hand it over. That night he asks about a message from a classmate."}],"why":"Surveillance doesn't build trust. Asking about the worry gets to the real issue."},{"prompt":"Days later, Aman says you'd share your live location if you really loved him. What do you do?","options":[{"text":"Say no, and that love doesn't need tracking","then":"Aman sulks all evening and says you're making him feel unloved.","best":true},{"text":"Share it, since love means having nothing to hide","then":"By the weekend, he texts to ask why you stopped at the market."},{"text":"Share yours if he shares his, so it's fair","then":"Now you both watch the little dots. Neither of you feels calmer."},{"text":"Tell yourself it's normal. All couples fight like this","then":"You say nothing to anyone. The requests keep coming."}],"why":"Tracking is control, even when it's called love."},{"prompt":"Your friend Megha sees you checking your phone nervously and asks what's up. What do you do?","options":[{"text":"Tell her about the checking and how it's feeling","then":"Megha listens, then says calmly, \"That's control. It isn't on you.\"","best":true},{"text":"Say it's fine. Aman just cares a lot","then":"Megha smiles and drops it. You feel more alone than before."},{"text":"Say nothing. It's private between you two","then":"Megha nods, a little worried. You change the subject."},{"text":"Say it's your fault for being so bad at replying","then":"Megha frowns. \"Late replies aren't a crime,\" she says."}],"why":"Telling someone you trust breaks the isolation. Being watched is never your fault."},{"prompt":"That weekend, Aman says he'll check your phone whenever he likes from now on. What do you do?","options":[{"text":"Tell Megha, and plan together what you'll do next","then":"Megha helps you think it through. You're not working this out alone anymore.","best":true},{"text":"Try harder to be the kind of partner he trusts","then":"You reply faster and explain more. The checking doesn't stop."},{"text":"Decide it's your fault for not sharing sooner","then":"The guilt grows. Aman's checking grows with it."},{"text":"Ask his parents to talk some sense into him","then":"His mother says he's always been protective. Nothing changes."}],"why":"His control isn't yours to fix. Planning with someone you trust keeps you supported."}],"debrief":"Healthy transparency is voluntary. Demanded checking is control, and it's never your fault.","relearn":"Trust isn't proved by handing over surveillance."},
  {"id":"rr-1376","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"fairness","hook":"You and Kunal keep disagreeing about how to spend your free Sundays together.","steps":[{"prompt":"This Sunday, he wants a lazy day in. You want the old city food walk. What do you do?","options":[{"text":"Suggest turns: your plan this week, his the next","then":"Kunal laughs. \"Deal. But next Sunday I'm not leaving the sofa.\"","best":true},{"text":"Give in again. It's not worth a fuss","then":"The day is fine. You notice it's the third Sunday in a row."},{"text":"Insist on the food walk. You planned it first","then":"Kunal comes along, sulking, and checks his phone the whole walk."},{"text":"Let him pick this time, and hope he offers next time","then":"He enjoys his day in. He never does offer."}],"why":"Taking turns means you both count, not just the one who holds out."},{"prompt":"The next Sunday, Kunal wants to watch a cricket match you find boring. What do you do?","options":[{"text":"Join in, and ask for the food walk next time","then":"You end up cheering a wicket together. \"Food walk next week,\" Kunal says.","best":true},{"text":"Go, but sigh and scroll your phone all day","then":"Kunal notices. \"You could've just said no,\" he mutters."},{"text":"Say no. Cricket is a waste of a Sunday","then":"Kunal goes to watch at a friend's place. The day feels split."},{"text":"Say yes, but make sure he knows he owes you one","then":"Kunal agrees, but the day feels like a transaction."}],"why":"Giving his pick a real chance, and asking for your turn, keeps it fair both ways."},{"prompt":"Next month, Kunal says he's not sure your Sundays feel fair. What do you do?","options":[{"text":"Ask what feels off to him, and listen","then":"He says his picks feel rushed. You agree to give them a full day.","best":true},{"text":"Say it's fair. You've kept track","then":"Kunal frowns. \"You've been keeping score?\""},{"text":"Tell him to plan every Sunday, then","then":"Kunal sighs. \"That's not what I meant.\""},{"text":"Promise to give in more from now on","then":"Kunal looks uneasy. That isn't what he asked for."}],"why":"Fairness gets checked, not assumed. Asking keeps it real for both of you."}],"debrief":"Equality means turns and trade-offs, not one person always conceding.","relearn":"Fairness is taking turns, not always conceding."},
  {"id":"rr-1377","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"warm boundary","hook":"Your partner Sneha had a rough day at her internship and snapped at you over dinner plans.","steps":[{"prompt":"Her words stung. What do you do right now?","options":[{"text":"Give her a beat, then say it stung, but you're here","then":"Sneha exhales. \"Sorry. That wasn't about you. Work was awful.\"","best":true},{"text":"Snap back harder so she sees how it feels","then":"Voices rise. Dinner goes cold on the table."},{"text":"Say nothing and let it go. She's had a bad day","then":"The evening passes. The sting stays with you."},{"text":"Apologise, though you're not sure what for","then":"Sneha accepts it, a little confused. The real issue goes unsaid."}],"why":"Naming the sting while staying warm is support and a boundary at once."},{"prompt":"Later, Sneha starts telling you about her manager. What do you do?","options":[{"text":"Listen, and ask what would help tonight","then":"She says a hug and some quiet. The evening softens.","best":true},{"text":"Jump in with advice on handling her manager","then":"Sneha stops. \"I don't need a plan right now.\""},{"text":"Say your day was hard too, and tell her about it","then":"Sneha goes quiet. Now you're both tired and unheard."},{"text":"Tell her she's overreacting. It's just work","then":"She shuts down. \"Forget I said anything.\""}],"why":"Asking what helps meets her need without guessing or competing."},{"prompt":"A week later, after another long day, Sneha snaps at you again. What do you do?","options":[{"text":"Say calmly that it's twice now, and ask to talk","then":"Sneha nods. \"You're right. I'll tell you I'm fried instead.\"","best":true},{"text":"Let it go again. Stress makes everyone snap sometimes","then":"The snaps become normal. You start dreading her work days."},{"text":"Keep a list, to show her how often it happens","then":"The list grows. You never actually talk about it."},{"text":"Snap back. It's only fair this time","then":"The evening turns into a shouting match."}],"why":"Naming a pattern kindly keeps support and self-respect together."}],"debrief":"You can be supportive and still name what's not okay.","relearn":"Support and boundaries live together; you can do both."},
  {"id":"rr-1378","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"stay yourself","hook":"Lately you've been shrinking your opinions around your partner Yash to keep things smooth.","steps":[{"prompt":"At dinner with his friends, he says a film you loved was rubbish. What do you do?","options":[{"text":"Say lightly that you loved it, and why","then":"Yash raises an eyebrow, then asks what you saw in it.","best":true},{"text":"Nod along. It's easier than a debate","then":"The talk moves on. You feel a little smaller."},{"text":"Laugh and say you didn't really like it either","then":"Everyone agrees. You wonder why you said it."},{"text":"Argue until everyone at the table takes a side","then":"The table goes awkward. Yash changes the subject."}],"why":"A small honest opinion brings your real self back into the room."},{"prompt":"Later, Yash suggests a weekend trip to a place you'd rather skip. What do you do?","options":[{"text":"Say you'd rather not, and suggest another spot","then":"Yash thinks, then suggests a third place you both like.","best":true},{"text":"Agree. Your preference doesn't matter much","then":"The trip is fine. You spend it feeling half there."},{"text":"Agree now and quietly hope he changes his mind","then":"He doesn't change his mind. You pack, a little resentful."},{"text":"Say yes, then pick at the trip all weekend","then":"By Sunday, Yash snaps, \"Why did you even come?\""}],"why":"Saying what you want gives the relationship the real you to work with."},{"prompt":"A friend says you seem quieter around Yash than you used to be. What do you do?","options":[{"text":"Admit it, and decide to raise it with Yash","then":"When you tell Yash, he says he'd noticed and missed your opinions.","best":true},{"text":"Say that's just what being in love is like","then":"Your friend looks doubtful. You change the topic."},{"text":"Laugh it off. Everyone changes a bit","then":"The comment stays with you all week anyway."},{"text":"Snap that she's reading too much into it","then":"She holds up her hands and drops it. Things feel stiff between you."}],"why":"A healthy relationship has room for your whole voice."}],"debrief":"A healthy relationship has room for your real opinions.","relearn":"Keep your opinions; you shouldn't have to disappear to keep peace."},
  {"id":"rr-1379","cat":"what-healthy-looks-like","type":"branch","persona":"Deepak","source":"money autonomy","hook":"A month into dating, your partner Ritika suggests putting all your money into one shared account.","steps":[{"prompt":"She says it would show real commitment. What do you do?","options":[{"text":"Suggest keeping your own money while trust grows","then":"Ritika pauses, then asks how a shared fund could work instead.","best":true},{"text":"Pool everything. Holding back would look like doubt","then":"Within a week, she's deciding what your stipend goes on."},{"text":"Refuse outright and say she's after your money","then":"Ritika is stung. \"I was trying to be close to you.\""},{"text":"Agree for now, and bring up your doubts later","then":"The account opens. Your doubts get harder to raise each week."}],"why":"Some money of your own protects your freedom as the bond grows."},{"prompt":"Weeks later, Ritika asks how you'd like the two of you to handle money from here on. What do you suggest?","options":[{"text":"A shared fund we add to fairly and decide on together","then":"You agree amounts that fit both your budgets. It feels fair.","best":true},{"text":"Strictly fifty-fifty on every single rupee, always","then":"Some weeks, half is more than your stipend can take."},{"text":"Let her decide it all. She's better with money anyway","then":"She sets it all up. You stop knowing where the money goes."},{"text":"She pays, since she has more money","then":"Ritika agrees, but her face tightens."}],"why":"Fair shared money is decided together and fits both your means."},{"prompt":"You earn a little from weekend tutoring, and your mother asks if you can send some home. What do you do?","options":[{"text":"Send it, and tell Ritika. It's your call","then":"Your mother thanks you. When you tell Ritika, she nods.","best":true},{"text":"Ask Ritika for permission before you send it","then":"Ritika says fine, but you feel you needed a pass."},{"text":"Say no. Anything you earn should go to the couple","then":"Your mother says it's okay. You feel awful all evening."},{"text":"Send it quietly so Ritika doesn't ask questions","then":"Ritika finds out weeks later and asks why you hid it."}],"why":"Helping your family is your call. Telling her keeps it open, without needing a pass."},{"prompt":"Ritika later says couples who keep separate money don't trust each other. What do you say?","options":[{"text":"Trust isn't about one account. Shared and separate both work","then":"Ritika thinks it over. \"Okay. I just want us to feel like a team.\"","best":true},{"text":"Maybe you're right. Let's merge everything","then":"She's pleased. You quietly worry about next month's rent."},{"text":"Wow, that's a pretty childish way to see it","then":"Ritika's face closes. \"Forget I brought it up.\""},{"text":"Let's not talk about money. It always gets awkward","then":"The topic drops, and comes back sharper a week later."}],"why":"Some shared money and some of your own is healthy, and you're still a team."}],"debrief":"Equality with money means shared decisions and some independence.","relearn":"Keep some financial independence as a relationship grows."},
  {"id":"rr-1380","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"outside read","hook":"Your friend Tara says your partner Omkar seems great, but you've gone quiet lately.","steps":[{"prompt":"She says it gently over coffee. What do you do?","options":[{"text":"Take it seriously and ask her what she's noticed","then":"Tara says you cancel plans a lot and check your phone before answering.","best":true},{"text":"Brush it off. She doesn't get your relationship","then":"Tara drops it. The coffee ends a little stiffly."},{"text":"Get defensive and list everything Omkar does for you","then":"Tara holds up her hands. \"Okay. I just miss you.\""},{"text":"Thank her, and quickly change the subject","then":"Tara lets it go, but she looks worried."}],"why":"Friends often see your world shrinking before you do. It's worth a listen."},{"prompt":"That night, you think back over the last few months. What do you look at?","options":[{"text":"How free I feel to be myself and see people","then":"You realise you've stopped making plans before checking his mood.","best":true},{"text":"How many nice things Omkar has done for me","then":"The list is long. It doesn't explain the quiet."},{"text":"Whether we fight less than other couples","then":"You fight less than most. The heavy feeling stays."},{"text":"Whether Tara is just jealous of us","then":"It's an easier thought. It doesn't quite feel true."}],"why":"Whether you can still be yourself is a truer check than gifts or comparison."},{"prompt":"Omkar asks why you've been so distracted this week. What do you do?","options":[{"text":"Say you've gone quiet lately, and want to talk about it","then":"Omkar looks surprised, then sits down. \"Okay. Tell me.\"","best":true},{"text":"Say it's nothing. You're probably just overthinking it","then":"He nods and goes back to his phone. The quiet deepens."},{"text":"Tell him that Tara thinks he's been changing you","then":"Omkar bristles. \"Why is Tara in our business?\""},{"text":"Pick a fight about something small instead","then":"The fight is about the dishes. It isn't really about the dishes."}],"why":"Raising it directly lets you see how he responds, which is part of the read."},{"prompt":"A week later, Tara asks how things are going. What do you say?","options":[{"text":"Honestly, mixed. Can we catch up more often?","then":"Tara beams. \"Every Thursday, then. It's a date.\"","best":true},{"text":"Great! You were totally wrong about him","then":"Tara says she's glad, but she looks unsure."},{"text":"Fine. Let's not talk about Omkar anymore","then":"Tara nods. She stops asking after that."},{"text":"It's probably me. I've been too sensitive","then":"Tara looks at you for a long moment. \"I don't think it's you.\""}],"why":"Keeping trusted friends close keeps an honest mirror in your life."}],"debrief":"A trusted friend's read is useful, not interference. A world that shrinks around a partner's moods is never your fault.","relearn":"Outside eyes often spot your world shrinking first."},
  {"id":"rr-1381","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"maintenance","hook":"A year in with Riya, things are calm and good, and you're tempted to coast.","steps":[{"prompt":"You've both stopped saying thanks for the little things. What do you do?","options":[{"text":"Start thanking her again for the small things","then":"Riya notices your thanks for the chai, and smiles all morning.","best":true},{"text":"Leave it. You both know you're grateful","then":"Nothing changes. The quiet starts to feel a bit flat."},{"text":"Wait for her to start first. You did it last time","then":"Neither of you starts. A week goes by."},{"text":"Plan a huge romantic gesture to make up for it","then":"The gesture is lovely. By Tuesday, the little things are forgotten again."}],"why":"Small, steady appreciation keeps love alive more than grand gestures."},{"prompt":"Riya forgets to call when she said she would. It's minor. What do you do?","options":[{"text":"Mention it lightly and hear her side","then":"Riya winces. \"Sorry. The meeting ran over. I'll text next time.\"","best":true},{"text":"Let it slide. Why rock a good boat?","then":"It happens again next week. A small resentment starts."},{"text":"Go cold for the evening so she notices","then":"Riya asks what's wrong three times. The evening sours."},{"text":"Bring up three other times she forgot","then":"Riya gets defensive. The small thing becomes a big one."}],"why":"Small repairs, made early, stop little things piling up."},{"prompt":"You realise it's been months since you tried anything new together. What do you do?","options":[{"text":"Suggest something new you could try together","then":"Riya picks a pottery class. You both come home laughing, covered in clay.","best":true},{"text":"Leave it. Comfortable is the goal","then":"The weekends blur together. Neither of you minds, yet."},{"text":"Wonder if the spark is gone, and pull back","then":"Riya feels the distance and asks if something's wrong."},{"text":"Wait for Riya to suggest something","then":"Riya is waiting for you too. Nothing happens."}],"why":"Tending a good relationship keeps it good. Comfort needs care too."}],"debrief":"Even a good relationship is kept up with ongoing care, not assumed.","relearn":"Keep tending a good relationship; don't just coast."},
  {"id":"rr-1382","cat":"what-healthy-looks-like","type":"branch","persona":"Rohan","source":"clear asks","hook":"Three months with Anjali, and you've never said what you need from her. You hope she'll guess.","steps":[{"prompt":"She cancels your plans again, last minute. What do you do?","options":[{"text":"Tell her plainly that last-minute cancels hurt","then":"Anjali pauses. \"I didn't know it bugged you. I'll give more notice.\"","best":true},{"text":"Say \"cool, no worries\" and stew about it","then":"She thanks you. You spend the evening annoyed and alone."},{"text":"Act distant, so she figures out something's wrong","then":"She asks if you're okay. You say \"fine,\" and it gets weirder."},{"text":"Decide women just don't value guys like you","then":"The thought feels familiar. It also leaves you lonelier."}],"why":"Clear asks give her a real chance to meet them. Guessing games don't."},{"prompt":"A week later, Anjali asks what you'd like more of from her. What do you say?","options":[{"text":"More time just us, like one evening a week","then":"Anjali smiles. \"Wednesdays? I'd like that too.\"","best":true},{"text":"Nothing. I'm easy, whatever you want","then":"\"Okay,\" she says, a little sad that she can't read you."},{"text":"You should know that by now","then":"Her face falls. \"I'm trying. I'm not a mind reader.\""},{"text":"More attention, basically. You're always busy","then":"She stiffens. \"I'm always busy?\""}],"why":"A specific need is easy to understand and easy to say yes to."},{"prompt":"Your friend Kabir says asking for stuff makes guys look needy. What do you say?","options":[{"text":"Hoping she guesses is worse. I'd rather just ask","then":"Kabir shrugs. \"Huh. Maybe I should try that.\"","best":true},{"text":"True. Better to act like I don't care","then":"Kabir nods. You go home and wonder why it feels so lonely."},{"text":"Maybe. I'll only ask when it's really serious","then":"Small things pile up, unsaid, until they aren't small."},{"text":"Yeah. Strong guys handle things alone","then":"You feel tough for a minute. Then just tired."}],"why":"Saying what you need isn't weakness. It's how you get close to someone."}],"debrief":"Asking clearly for what you need is healthy, not needy.","relearn":"Say your needs clearly; hoping they guess breeds resentment."},
  {"id":"rr-1383","cat":"what-healthy-looks-like","type":"branch","persona":"Aarti","source":"check-in not curfew","hook":"Your partner Vikram wants you home by 8 every night, \"because he worries.\"","steps":[{"prompt":"He asks you to promise tonight. What do you do?","options":[{"text":"Offer a friendly check-in text, not a curfew","then":"Vikram frowns. \"A text isn't the same. I need you home.\"","best":true},{"text":"Tell yourself his worry shows how much he cares","then":"Vikram smiles. Soon you're watching the clock whenever you're out."},{"text":"Wonder if you've given him reason to worry","then":"You start apologising for things you haven't done."},{"text":"Follow your cousin's advice that good partners adjust","then":"Your cousin's words stay with you. A week later, Vikram asks about weekends too."}],"why":"Care looks like a check-in you choose. A curfew is control wearing a caring face."},{"prompt":"Days later, you're at a friend's birthday at 8:15, and Vikram calls, angry. What do you do?","options":[{"text":"Tell him calmly you're safe and will be home later","then":"Vikram hangs up, furious. Your friend asks quietly if you're okay.","best":true},{"text":"Believe he's right to be upset, since it's past 8","then":"You feel guilty all evening, though you did nothing wrong."},{"text":"Keep it from your friends so nobody judges him","then":"You smile through the cake, hoping nobody sees how tense you are."},{"text":"Stay out extra late on purpose to prove a point","then":"His messages get angrier by the minute. You dread going home."}],"why":"You're allowed to be out and safe. His anger is his to own, never your fault."},{"prompt":"Your friend Nidhi notices you're tense and asks about Vikram. What do you tell her?","options":[{"text":"The truth: the curfew, the calls, and how it feels","then":"Nidhi listens. \"That's not care. That's control. I'm with you.\"","best":true},{"text":"That he's just old-fashioned and really protective of me","then":"Nidhi nods slowly. She doesn't look convinced."},{"text":"Nothing. It would make him look bad","then":"Nidhi drops it. You feel a little lonelier."},{"text":"That it's my fault for upsetting him","then":"Nidhi frowns. \"You didn't do anything wrong.\""}],"why":"Telling someone you trust breaks the isolation that control relies on."},{"prompt":"Vikram says if you loved him, you'd stop seeing friends who \"fill your head.\" What do you do?","options":[{"text":"Keep your friends, and let Nidhi know what he said","then":"Vikram sulks for days. Nidhi checks in with you every evening.","best":true},{"text":"Tell yourself a partner should come before friends","then":"Vikram seems happier. You see your friends less, and feel smaller."},{"text":"Wonder if your friends really are a bad influence on you","then":"You start doubting Nidhi. A week later, he objects to your cousin too."},{"text":"Ask his mother to tell him to relax","then":"His mother says he's just protective. Nothing changes."}],"why":"Isolation is a control tactic. Your friends are your safety net, not a threat."},{"prompt":"One evening, Nidhi drops by to check on you. She asks what you want to do next, and says help is there. What do you do?","options":[{"text":"Plan with her, and save 181 / 1091 / 112 just in case","then":"Nidhi adds her own number under them. You feel less alone.","best":true},{"text":"Say you'll just love him more, and he'll relax","then":"You try harder for weeks. The rules only get tighter."},{"text":"Say it isn't serious enough to count as control","then":"Nidhi says gently that it doesn't have to be worse to count."},{"text":"Decide to handle it alone. It's your mess","then":"Nidhi squeezes your hand. \"It's not your mess. I'm here.\""}],"why":"Control isn't yours to fix. A plan, a trusted friend and 181 / 1091 / 112 keep you supported."}],"debrief":"A check-in is care. A curfew is control, and it's never your fault.","relearn":"A check-in is care; a curfew is control."},
  {"id":"rr-1384","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"drop the tally","hook":"Whenever you argue, your partner Sahil lists every time you've let him down, going back months.","steps":[{"prompt":"Tonight it starts again over a missed call. What do you do?","options":[{"text":"Say you'd rather repair than keep score, and ask to reset","then":"Sahil stops mid-sentence. \"Reset how?\" he asks, a little wary.","best":true},{"text":"Start listing all the times he's let you down too","then":"Two scoreboards go up. The missed call gets lost in the war."},{"text":"Apologise for every single thing on his list, one by one","then":"Sahil calms down. You feel like you're paying off a debt."},{"text":"Walk out mid-list and ignore him","then":"Sahil calls after you. The list gets one item longer."}],"why":"Asking to reset moves you from scoring points to fixing the actual problem."},{"prompt":"Later, Sahil says you keep doing the same things. What do you say?","options":[{"text":"Then let's pick the one that matters most and fix it","then":"Sahil thinks. \"The calls, honestly. I worry when you go silent.\"","best":true},{"text":"And you don't? Shall I get my list out?","then":"Sahil's jaw tightens. \"See? This is why I keep track.\""},{"text":"Fine. I'm clearly just hopeless at this whole thing","then":"Sahil sighs. Now he's comforting you instead of talking."},{"text":"Okay. I'll try to be better at all of it from now on","then":"Sahil nods, but he doesn't look convinced."}],"why":"One specific fix beats a vague promise or a counter-attack."},{"prompt":"A week later, you forget to call again. What do you do?","options":[{"text":"Own it straight away, and say what you'll do next time","then":"Sahil softens. \"Thanks for saying it first. Set a reminder?\"","best":true},{"text":"Hope he doesn't notice this time","then":"He notices. The old list comes out again, longer."},{"text":"Remind him he forgot something last week too","then":"The tally is back, and so is the old fight."},{"text":"Over-apologise, and promise it'll never happen again","then":"Sahil accepts, but a promise like that is hard to keep."}],"why":"Owning a slip quickly is repair. It stops a new tally from starting."},{"prompt":"Later, Sahil admits keeping score makes him feel safer. What do you say?","options":[{"text":"Thanks for telling me. What would help instead?","then":"Sahil thinks. \"Knowing you'll tell me when you'll be late.\"","best":true},{"text":"Okay. Keep the list, if it really helps you feel better","then":"Sahil nods. The list stays, and so does the tension."},{"text":"Honestly, that sounds a bit messed up to me","then":"Sahil goes red and shuts down."},{"text":"I'll keep one too, then we're even","then":"Sahil laughs, but it isn't a happy laugh."}],"why":"Getting to the worry under the tally is how repair replaces keeping score."}],"debrief":"Healthy couples repair rather than keep score.","relearn":"Repair beats score-keeping; drop the tally."},
  {"id":"rr-1385","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"own friends","hook":"You'd like more time with your school friends, without it turning into a fight with Kiran.","steps":[{"prompt":"Your friends plan a Saturday cricket match. What do you do?","options":[{"text":"Tell Kiran openly, and suggest she plan her own day","then":"Kiran shrugs. \"Sure. I'll see my sister.\" No drama at all.","best":true},{"text":"Go, but tell her you're studying at the library","then":"Kiran sees your photos on a friend's story that evening."},{"text":"Skip it. Explaining it just isn't worth the hassle","then":"Your friends play without you. You feel a little flat."},{"text":"Ask Kiran if she minds, and let her decide","then":"Kiran says \"go if you want,\" and you feel you needed a yes."}],"why":"Separate time with your own people is normal. There's nothing to hide."},{"prompt":"A few weeks later, Kiran says she feels left out of your friend group. What do you do?","options":[{"text":"Include her sometimes, and keep some plans your own","then":"Kiran joins the next dinner and likes your friends. She happily skips cricket.","best":true},{"text":"See them a lot less, so she doesn't feel upset","then":"Kiran relaxes. Your friends start leaving you off plans."},{"text":"Tell her that's her problem to sort out","then":"Kiran looks hurt. \"I was just being honest.\""},{"text":"Bring her along to every single plan from now on","then":"Kiran comes to everything. Your friends talk less freely."}],"why":"Sharing some of your world, and keeping some of it yours, is healthy."},{"prompt":"At a friends' dinner, someone jokes that Kiran must keep you on a short leash. What do you say?","options":[{"text":"No. She's fine with me having my own friends","then":"Your friend nods. \"Fair enough. Sounds nice, actually.\"","best":true},{"text":"Laugh along, even though it's not true","then":"The joke sticks, and you hear it again next week."},{"text":"Get angry and leave the table","then":"The table goes quiet. The joke becomes a thing."},{"text":"Maybe a bit, but that's just how couples are","then":"Your friend raises an eyebrow. You wonder why you said it."}],"why":"Having your own friends is normal. Say so plainly and move on."}],"debrief":"Time apart with your own people is healthy and nothing to hide.","relearn":"Separate friend-time is normal; you needn't hide it."},
  {"id":"rr-1386","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"appreciation","hook":"Your partner Irfan quietly fixed your cycle's flat tyre while you were at class.","steps":[{"prompt":"That evening, you realise you only mumbled thanks. What do you do?","options":[{"text":"Tell him you noticed, and that it meant something","then":"Irfan looks up, pleased. \"I wasn't sure you'd noticed.\"","best":true},{"text":"Leave it. He knows you're grateful","then":"Irfan says nothing. He seems a little flat tonight."},{"text":"Buy him something to make up for it","then":"He likes the gift, but you never actually say why."},{"text":"Joke that he should fix your laptop next","then":"Irfan laughs, but it lands as another chore."}],"why":"Saying thanks out loud lets him know his care was seen."},{"prompt":"Over the week, you notice other small things he does. What do you do?","options":[{"text":"Name one out loud when it happens","then":"Irfan grins each time. He starts noticing your small things too.","best":true},{"text":"Keep a mental note to thank him someday","then":"Someday doesn't come. The notes stay in your head."},{"text":"Expect them now. It's what partners do","then":"The small things slowly thin out."},{"text":"Save it all for a long thank-you on Sunday","then":"He's touched, and a little embarrassed. Midweek stays quiet."}],"why":"Small, real-time thanks feed the appreciation love runs on."},{"prompt":"A month later, back from a weekend at home, Irfan says nobody there notices what he does. What do you do?","options":[{"text":"Tell him the specific things you've noticed","then":"Irfan's shoulders drop. \"You really saw all that?\"","best":true},{"text":"Say he's being a bit dramatic","then":"He goes quiet and turns away."},{"text":"Tell him to just stop doing so much for them","then":"He sighs. \"That's not really the point.\""},{"text":"Give him a hug, and then change the subject","then":"He hugs back, but the feeling stays."}],"why":"Specific appreciation lands deeper than general comfort."}],"debrief":"Naming appreciation out loud is a quiet engine of healthy love.","relearn":"Say the thanks out loud; appreciation keeps love alive."},
  {"id":"rr-1387","cat":"what-healthy-looks-like","type":"branch","persona":"Rohan","source":"no games","hook":"You've caught yourself posting stories with other girls, just to see if Priya gets jealous.","steps":[{"prompt":"Priya doesn't react to your latest story. What do you do?","options":[{"text":"Stop, and ask her for the reassurance you want","then":"Priya is surprised. \"Of course I like you. I just don't do jealous.\"","best":true},{"text":"Post another, more obvious one","then":"Priya comments \"nice pic.\" You feel worse, not better."},{"text":"Assume she doesn't care, and go cold","then":"Priya asks what's wrong. You say \"nothing,\" and it grows."},{"text":"Ask her friends if she's said anything about it","then":"Word gets back to Priya. She feels tested, and she was."}],"why":"Asking for reassurance directly meets the real need, without games."},{"prompt":"Later, Priya asks if the stories were meant to get to her. What do you say?","options":[{"text":"Yes. I wanted proof you cared. That wasn't fair","then":"Priya is quiet, then nods. \"Thanks for saying it. Just ask me next time.\"","best":true},{"text":"No idea what you mean. They were just stories","then":"Priya doesn't believe you. Something small cracks."},{"text":"Maybe. You never show you care, so what else could I do","then":"Priya stiffens. \"So this is my fault?\""},{"text":"It was a joke. Relax","then":"Priya doesn't laugh. \"It didn't feel like one.\""}],"why":"Owning the test honestly starts to rebuild the trust it chipped."},{"prompt":"Your friend says jealousy is how you know a girl's really into you. What do you say?","options":[{"text":"I used to think that. Now it just seems like control","then":"Your friend thinks, then shrugs. \"Huh. Never saw it that way.\"","best":true},{"text":"Exactly. If she's not jealous, she doesn't really care","then":"Your friend nods. The old idea feels solid again, and lonelier."},{"text":"Maybe. I'll test it just one more time to make sure","then":"The next test goes badly. Priya stops replying for a day."},{"text":"Depends on the girl, I guess","then":"The talk drifts. The idea sits there, unexamined."}],"why":"Jealousy isn't proof of love. Secure care shows up as trust."},{"prompt":"A month later, you feel insecure again after Priya's night out. What do you do?","options":[{"text":"Tell her you felt a bit insecure, and ask for a call","then":"Priya calls right away. \"Thanks for telling me. I missed you too.\"","best":true},{"text":"Post something to make her wonder about you","then":"She sees it and sighs. The old pattern is back."},{"text":"Check who she was with on everyone's stories","then":"An hour of scrolling leaves you more anxious, not less."},{"text":"Pretend you're fine. Needing reassurance is weak","then":"The feeling festers. You snap at her over nothing."}],"why":"Naming insecurity and asking for what you need builds trust both ways."}],"debrief":"Ask for reassurance directly instead of testing for jealousy.","relearn":"Jealousy isn't proof of love; ask for what you need."},
  {"id":"rr-1388","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"decide together","hook":"You and Aryan plan to share a flat next year, and need to choose: near his campus or yours.","steps":[{"prompt":"Aryan says you care more about it, so you should just decide. What do you do?","options":[{"text":"Lay out both your needs first, then decide together","then":"Aryan lists his early labs. You list your late library nights.","best":true},{"text":"Great. Pick the flat near your own campus","then":"You start browsing near your campus. Aryan quietly mentions his early labs."},{"text":"Let him decide instead, to be fair","then":"Aryan starts browsing near his campus. You never mention your late nights."},{"text":"Pick the cheapest one, so there's nothing to argue about","then":"You filter by price. The cheap ones are far from both campuses."}],"why":"Laying out both needs first means the decision is really shared."},{"prompt":"A week into the search, two flats look good, and each suits one of you better. What do you do?","options":[{"text":"Compare both honestly against what each of you needs","then":"His labs start at 7, so the flat near his campus wins. You pick your room.","best":true},{"text":"Skip both and find a halfway one. Equal suffering is fair","then":"The halfway flat feels fair. By week two, you're both worn out by the commute."},{"text":"Go with his, and quietly resent the commute","then":"He's happy. You mention the commute every morning."},{"text":"Toss a coin to settle it","then":"The coin picks. Neither of you feels it was decided."}],"why":"Weighing both needs honestly beats splitting the pain or leaving it to luck."},{"prompt":"Your mother calls and asks you to pick an area near your aunt's place instead. What do you do?","options":[{"text":"Hear her out, and explain you two are deciding it","then":"Your mother sighs, then asks for the address so she can visit.","best":true},{"text":"Change the whole plan. Family always knows best","then":"Aryan is blindsided. The search starts over, without him."},{"text":"Agree on the phone, and not mention it to Aryan","then":"Aryan finds out when your aunt calls him. He feels left out."},{"text":"Snap at her to stay out of it","then":"Your mother goes quiet and hurt. The call ends badly."}],"why":"You can respect family and still keep a shared decision between the two of you."},{"prompt":"Aryan wants to pay less rent since his room is smaller. What do you say?","options":[{"text":"That's fair. Let's work out a split we both agree on","then":"You land on a split by room size. It takes ten minutes.","best":true},{"text":"No. Half is half","then":"Aryan goes quiet. He pays, but it bothers him."},{"text":"Fine, whatever. I don't want to fight about money","then":"The split feels off to you all month."},{"text":"Only if you do more of the chores to make up","then":"It turns into a trade. Every chore gets counted."}],"why":"Fair isn't always equal. Agreeing on the split together is what counts."},{"prompt":"A month after moving in, the commute turns out harder than you thought. What do you do?","options":[{"text":"Tell Aryan honestly and think it through together","then":"Aryan offers to swap cooking days so your mornings are easier.","best":true},{"text":"Say nothing. You agreed, so you'll live with it","then":"You grow tired and snappy, and Aryan doesn't know why."},{"text":"Blame Aryan for pushing this flat","then":"Aryan looks stung. \"We chose it together.\""},{"text":"Start looking for a new place on your own","then":"Aryan finds the listings on your laptop and feels shut out."}],"why":"Shared decisions stay shared. Revisiting them together is part of equality."}],"debrief":"Big choices made together, with both needs heard, is what equality looks like.","relearn":"Decide big things together; that's equality."},
  {"id":"rr-1389","cat":"what-healthy-looks-like","type":"branch","persona":"any","source":"real repair","hook":"After every disagreement, your partner Nisha showers you with gifts instead of talking about it.","steps":[{"prompt":"After last night's fight, a big bouquet arrives at your hostel. What do you do?","options":[{"text":"Thank her, and say you'd rather talk it through","then":"Nisha hesitates. \"Talk? I thought the flowers said sorry.\"","best":true},{"text":"Enjoy the flowers and skip the conversation","then":"The flowers are lovely. The fight sits unfinished between you."},{"text":"Send them back so she knows you're still upset","then":"Nisha is crushed. The fight gets bigger, not smaller."},{"text":"Thank her warmly, and hope the fight doesn't come back","then":"It comes back in a week, about the same thing."}],"why":"Thanks plus a request to talk keeps the kindness and the repair."},{"prompt":"Nisha says talking about fights makes her anxious, so she'd rather just move on. What do you say?","options":[{"text":"I get that. Can we try a short, calm talk together?","then":"Nisha nods slowly. \"Ten minutes? And you'll hold my hand?\"","best":true},{"text":"Fine. We'll just never bring up our fights again, then","then":"Nisha is relieved. The unfinished fights start to pile up."},{"text":"You're only avoiding responsibility, like you always do","then":"Nisha's eyes fill. \"This is why I don't talk.\""},{"text":"Okay, but next time I want a nicer gift","then":"Nisha laughs, unsure. Gifts become the repair plan."}],"why":"Meeting her anxiety gently, and still asking to talk, makes repair possible."},{"prompt":"One evening, Nisha mentions her parents never discussed fights, only bought gifts. What do you do?","options":[{"text":"Listen, and share what repair looked like in your home","then":"Nisha listens. You both realise you're learning this together.","best":true},{"text":"Say that's messed up and she needs to change","then":"Nisha shuts down. The talk ends early."},{"text":"Say it's fine, and that gifts work for you too","then":"Nisha relaxes, and the old habit gets your blessing."},{"text":"Offer advice on how she should handle her parents","then":"Nisha nods politely. The talk drifts away from you two."}],"why":"Understanding where a habit comes from, together, helps you build a new one."},{"prompt":"A week later, you have another disagreement. What do you suggest?","options":[{"text":"Let's talk it through tonight, then get chai after","then":"Nisha agrees. The talk is short, and the chai tastes like relief.","best":true},{"text":"Let's just skip it. Buy me something nice?","then":"Nisha looks relieved and orders a gift. The issue waits."},{"text":"We should cool off for a few days first","then":"Three days pass. By then, neither of you wants to bring it up."},{"text":"This time I'm right, so let's not argue","then":"Nisha bristles. The talk starts as a fight."}],"why":"Talk first, then treat: real repair keeps both."}],"debrief":"Real repair is a conversation, not a shower of gifts.","relearn":"Repair is a conversation, not gifts that paper over it."},
  {"id":"rr-1390","cat":"what-healthy-looks-like","type":"branch","persona":"Ananya","source":"markers over intensity","hook":"Your first relationship, with Rishi from your class, feels amazing. You're not sure it's the healthy kind.","steps":[{"prompt":"Your roommate asks how you can tell. What do you go by?","options":[{"text":"Respect, trust, equality, and space to be myself","then":"You see he respects your no, but grumbles about your study group.","best":true},{"text":"How intense it feels. Nothing has ever felt like this","then":"It feels like proof. You stop asking questions."},{"text":"How much he texts me. He literally never stops","then":"The texts feel like love. You don't notice how many you answer."},{"text":"Whether my parents would approve","then":"You picture their faces and panic. It doesn't answer much."}],"why":"The markers give a clearer read than the rush of a first relationship."},{"prompt":"Rishi says your study group takes you away from him. What do you do?","options":[{"text":"Keep going, and tell him it matters to you","then":"Rishi sulks, then says okay. You keep your Tuesday group.","best":true},{"text":"Drop the group. He's more important","then":"Rishi is thrilled. Your grades start to slip."},{"text":"Go less often, to keep him happy","then":"He's happy for now. Next, he asks about your dance class."},{"text":"Tell him he's being toxic, and block him for a day","then":"Rishi is confused and hurt. He didn't know it upset you."}],"why":"Space for your own life is a healthy marker, not a betrayal."},{"prompt":"A month on, a friend says your world seems smaller since you met Rishi. What do you do?","options":[{"text":"Check it against the markers honestly, with her","then":"Together you spot two things to raise with Rishi, and a lot that's good.","best":true},{"text":"Say she's just jealous you're dating","then":"Your friend backs off. You lose an honest mirror."},{"text":"Promise to see her more, and change nothing else","then":"You meet for chai once. Then the old pattern returns."},{"text":"Say it's worth it. The feeling is that strong","then":"Your friend drops it. Your world keeps shrinking quietly."}],"why":"An honest check with someone who knows you beats going by intensity."}],"debrief":"Measure by the markers, not the rush of intensity.","relearn":"Judge by respect, trust, equality and space, not intensity."},
  {"id":"rr-1391","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"keep your friends","hook":"Nakul keeps skipping plans with your friends. Saturday is Shruti's birthday.","setup":"You're walking back from class.","steps":[{"prompt":"Nakul says: \"Do we have to go to Shruti's thing?\"","options":[{"text":"\"My friends matter to me. Come if you can. I'm going anyway.\"","then":"Nakul slows down. \"Okay. It's not really about Shruti.\"","best":true},{"text":"\"Okay. Let's see how you feel on Saturday, and decide then.\"","then":"He smiles. \"Thanks. I'll probably be tired, though.\""},{"text":"\"You always do this. You clearly hate my friends.\"","then":"Nakul stiffens. \"I don't hate them. I'm just tired.\""},{"text":"\"Fine. I'll just go by myself, then.\"","then":"\"Cool,\" he says, relieved. Neither of you says what's really going on."}],"why":"Saying clearly that your friends matter, while still inviting him, keeps your world and your warmth."},{"prompt":"Later, Nakul admits: \"I feel like an outsider with your friends.\"","options":[{"text":"\"That sounds hard. What would help you feel less left out?\"","then":"He thinks. \"Maybe dinner with two of them first, not a big party.\"","best":true},{"text":"\"Then I'll see them less for now, till you feel settled.\"","then":"He relaxes. \"Thanks. That would really help.\""},{"text":"\"You're overthinking it. Honestly, they're totally fine with you.\"","then":"Nakul shrugs. \"If you say so.\" He changes the subject."},{"text":"\"Honestly, they do find you a bit quiet.\"","then":"He looks stung. \"Great. So I was right.\""}],"why":"Asking what would help respects his feeling without giving up your friends."},{"prompt":"On Saturday evening, Nakul says: \"I'm wiped out. Can you skip it just this once?\"","options":[{"text":"\"I'm still going. Rest, and I'll message you when I'm back.\"","then":"\"Okay,\" he says. \"Say happy birthday from me.\"","best":true},{"text":"\"Fine, I'll skip it. Shruti will understand.\"","then":"He smiles. \"Thank you.\" Soon party photos start arriving on your phone."},{"text":"\"Okay, I'll go. But honestly, I'm tired of making excuses for you.\"","then":"His face tightens. \"Then don't make any.\""},{"text":"\"You're always wiped out when it's my friends.\"","then":"\"That's not fair,\" he snaps. \"It's been a long week.\""}],"why":"Going warmly, without guilt or a dig, shows your friendships aren't up for trade."},{"prompt":"The next week, Nakul asks: \"My hostel friends are doing chai on Friday. Come with me?\"","options":[{"text":"\"I'd like that. And go even on days I can't.\"","then":"He grins. \"Deal. They've been asking about you.\"","best":true},{"text":"\"Only if you come to my friends' things too.\"","then":"His smile slips. \"So it's a trade now?\""},{"text":"\"Yes! Let's do all our plans together from now on.\"","then":"Nakul laughs. \"All of them? We'll get sick of each other.\""},{"text":"\"Maybe. I'm not sure I'll fit in with them.\"","then":"He nods slowly. \"Now you know how I feel.\""}],"why":"Backing each other's friendships, together and apart, is what healthy looks like."}],"relearn":"State your needs clearly and keep your own friendships."},
  {"id":"rr-1392","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"warm boundary","hook":"Simran calls the second you're home from work. You need an hour alone first.","setup":"Your head is still buzzing from the day.","steps":[{"prompt":"Simran says: \"Finally! I've waited all day to talk to you.\"","options":[{"text":"\"I need an hour to reset. It's not you. Call you at eight?\"","then":"A pause. \"Oh. Okay. Eight, then. Rest up.\"","best":true},{"text":"\"Simran, you're suffocating me. I just walked in.\"","then":"She goes quiet. \"Wow. Okay. Sorry for calling.\""},{"text":"\"Hi! I'm so tired, but tell me everything. How was your day?\"","then":"She laughs. \"Okay, so first, my professor...\" You're too drained to follow."},{"text":"\"Can't talk now. I'll explain later.\"","then":"\"Oh. Okay,\" she says, and hangs up sounding worried."}],"why":"A warm, clear boundary with a time to talk protects you without pushing her away."},{"prompt":"Later, Simran says: \"I just like hearing from you. I get anxious when you go quiet.\"","options":[{"text":"\"That makes sense. What if I text when I'm home, then call later?\"","then":"She brightens. \"A text would help a lot. Okay.\"","best":true},{"text":"\"Okay. Then I'll just pick up whenever you call, whatever time.\"","then":"\"Really? Thank you,\" she says. The tired knot in your chest stays."},{"text":"\"Your anxiety isn't my job to fix.\"","then":"She goes quiet. \"Right. Got it.\""},{"text":"\"There's no need to be anxious. I'm not going anywhere. I promise.\"","then":"\"I know,\" she says. \"I still feel it, though.\""}],"why":"Meeting her need with a small plan keeps your boundary and her trust."},{"prompt":"A week later, Simran asks: \"Tomorrow's my birthday eve. Video call right after work?\"","options":[{"text":"\"Yes, happily. I'll take my quiet hour after we hang up.\"","then":"\"Yay,\" she says. \"I'm wearing the silly hat.\"","best":true},{"text":"\"No. I need my time alone first, birthday or not.\"","then":"A pause. \"Wow. Okay. Later, then.\""},{"text":"\"Fine. But don't make this a habit.\"","then":"Her voice dims. \"I won't. Sorry I asked.\""},{"text":"\"Of course. Honestly, just call me anytime from now on.\"","then":"\"Really?\" she says, delighted. \"Every day?\""}],"why":"Saying yes warmly while keeping your quiet hour shows a boundary can be clear and kind."}],"relearn":"A warm, clear boundary protects you without attacking them."},
  {"id":"rr-1393","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"appreciation","hook":"Divya checks in on you before every exam. You've never told her what that means to you.","setup":"This morning she walks you to the exam hall.","steps":[{"prompt":"Divya says: \"Good luck! Tell me how it went, whenever you're free.\"","options":[{"text":"\"I will. I notice how you always check in. It means a lot.\"","then":"She blinks, then smiles. \"Oh. I didn't know you noticed.\"","best":true},{"text":"\"Yes, yes. You worry way too much, you know.\"","then":"She laughs, but it sounds thinner. \"Okay, fine.\""},{"text":"\"Thanks. Okay, I'd better go in now.\"","then":"\"Go, go,\" she says, and waves you in."},{"text":"\"You're the best, you know that? I'll buy you chai after this.\"","then":"She grins. \"Deal. Masala chai, not the sweet one.\""}],"why":"Naming exactly what you notice lets her know her care really lands."},{"prompt":"That evening, Divya asks: \"My ex called me clingy for checking in. Am I too much?\"","options":[{"text":"\"You're not. I love it. I should say that more often.\"","then":"Her shoulders drop. \"Okay. That's really nice to hear.\"","best":true},{"text":"\"A little, honestly. But I don't really mind.\"","then":"\"A little?\" she repeats, and goes quiet."},{"text":"\"Why would you even think that? Don't be silly.\"","then":"\"I don't know,\" she says. \"Forget I said it.\""},{"text":"\"Everyone checks in on their partner. It's normal.\"","then":"\"I guess,\" she says, not quite convinced."}],"why":"Telling her plainly that you value it answers the doubt behind her question."},{"prompt":"Next week, Divya says: \"I finished the slides for our group project last night.\"","options":[{"text":"\"Thank you. You stayed up for us. That saves my week.\"","then":"She beams. \"I was hoping someone would notice.\"","best":true},{"text":"\"Nice. Did you remember to add my part on the budget too?\"","then":"\"Yes,\" she says flatly. \"Your part too.\""},{"text":"\"Thanks! You're a total lifesaver, as always. What's next?\"","then":"She smiles. \"Anytime.\" She goes back to her laptop."},{"text":"\"You always take over these things, na?\"","then":"She frowns. \"Someone had to do it.\""}],"why":"Saying it out loud, often and specifically, makes appreciation a daily habit."}],"relearn":"Said-out-loud appreciation is a daily marker of healthy love."},
  {"id":"rr-1394","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"I felt","hook":"Manav cancelled dinner an hour before, again, to play cricket with his hostel mates.","setup":"Next day, he finds you at the canteen.","steps":[{"prompt":"Manav says: \"Hey. You didn't reply last night. All good?\"","options":[{"text":"\"I felt brushed off when you cancelled late. Can we talk?\"","then":"He pauses. \"Oh. Okay. I didn't think it was a big deal.\"","best":true},{"text":"\"You always ruin everything. Every single time, Manav.\"","then":"His face hardens. \"Wow. So I'm the villain now.\""},{"text":"\"All good. I was just busy with assignments.\"","then":"\"Cool,\" he says, relieved, and starts on the match."},{"text":"\"I was upset, but it's fine now. Don't worry about it.\"","then":"\"Oh, sorry,\" he says. \"Glad it's fine.\" The topic closes."}],"why":"An \"I felt\" line names the hurt without blame, so he can actually hear it."},{"prompt":"Later, Manav says: \"Sorry about dinner. The guys only had the ground that evening.\"","options":[{"text":"\"I get that. It's the last-minute part that stung.\"","then":"He nods slowly. \"Yeah. I should've told you earlier.\"","best":true},{"text":"\"Cricket always wins with you, doesn't it, Manav?\"","then":"\"That's not fair,\" he says, folding his arms."},{"text":"\"No worries. Cricket's important. I totally get it.\"","then":"\"Right?\" he grins. \"We won, by the way.\""},{"text":"\"Okay. Just don't let it happen again.\"","then":"\"Sure,\" he says, a little stiffly. He still isn't sure what bothered you."}],"why":"Naming the exact part that hurt gives him something he can change."},{"prompt":"A few days later, Manav says: \"Sunday dinner's on. Unless the guys book the ground again.\"","options":[{"text":"\"If that happens, tell me early and we'll pick another day.\"","then":"\"Fair,\" he says. \"By noon, latest. Promise.\"","best":true},{"text":"\"If you cancel again, we're done. I mean it this time.\"","then":"He goes still. \"Over cricket? Seriously?\""},{"text":"\"Sure, whatever works for you. I'm flexible.\"","then":"\"Great,\" he says, already checking the group chat."},{"text":"\"Then let's not plan things. Just call me whenever you're free.\"","then":"\"Easier for me,\" he says. \"But Sunday's still on, yeah?\""}],"why":"A small, clear ask about notice is easy for him to say yes to."},{"prompt":"On Sunday at noon, Manav texts: \"The guys got the ground tonight. Can we do Monday instead?\"","options":[{"text":"\"Thanks for telling me early. Monday works.\"","then":"\"Monday, then. I'll book the place,\" he replies. \"Promise.\"","best":true},{"text":"\"Seriously? I knew this would happen again.\"","then":"\"I'm trying here,\" he writes back. \"I texted as soon as I knew.\""},{"text":"\"Okay. But this is the last time I'm flexible.\"","then":"\"Noted,\" he replies. The warmth drains out of the chat."},{"text":"\"No. Sunday or nothing. We had a plan.\"","then":"\"Come on,\" he writes. \"I did tell you early this time.\""}],"why":"Thanking him for the early notice makes it more likely he'll do it again."}],"relearn":"An 'I felt' line raises a hurt without contempt or blame."},
  {"id":"rr-1395","cat":"what-healthy-looks-like","type":"role-play","persona":"Zoya","source":"no ultimatums","hook":"Your girlfriend Noor is upset that you're going home for the holidays.","setup":"She watches you pack.","steps":[{"prompt":"Noor says: \"Every break, you vanish to them. It's them or me.\"","options":[{"text":"\"I won't pick between you and my family. There's room for both.\"","then":"She sits on the bed. \"It doesn't feel like room. It feels like hiding.\"","best":true},{"text":"\"Okay. I'll cut the trip short and come back early for you.\"","then":"She brightens. \"Really? Come back by Tuesday, then.\""},{"text":"\"If you're making me choose, maybe we're done.\"","then":"Her eyes fill. \"That's not what I meant.\""},{"text":"\"I'll call you every night. Let's not fight about this now.\"","then":"\"Every night,\" she repeats flatly. She still looks hurt."}],"why":"Gently refusing the either-or keeps room for both the people you love."},{"prompt":"Noor says: \"I hate being a secret. Your family doesn't even know I exist.\"","options":[{"text":"\"That hurts. I get it. I'll tell them in my own time.\"","then":"She's quiet, then nods. \"Okay. I just needed to say it.\"","best":true},{"text":"\"Fine. I'll tell them on this trip, then. Happy now?\"","then":"Noor looks startled. \"Wait. Are you actually ready for that?\""},{"text":"\"I hear you. But you knew I wasn't out at home.\"","then":"\"I know,\" she says. \"It still hurts.\""},{"text":"\"It's easy for you. Your family's fine with it.\"","then":"\"Easy?\" she says. \"You don't know what it cost me.\""}],"why":"You can hear her hurt and still keep your own timeline for telling family."},{"prompt":"Two days into the trip, Noor texts: \"Miss you. Can you call tonight, or are they keeping you busy?\"","options":[{"text":"\"Miss you too. I'll call after dinner, around ten.\"","then":"\"Ten,\" she replies, with a heart. \"I'll wait up.\"","best":true},{"text":"\"Please don't start this again.\"","then":"\"I only asked,\" she writes. Then nothing for hours."},{"text":"\"Calling now. I'll sneak out of the family dinner.\"","then":"\"Now?\" she writes. \"Won't they wonder where you went?\""},{"text":"\"Can't. Family stuff all week. Talk when I'm back.\"","then":"\"All week?\" she writes. \"Okay. Sure.\""}],"why":"A clear, warm plan gives her a place without taking you from your family."},{"prompt":"Back on campus, Noor says: \"Sorry about the 'them or me' thing. I was scared of losing you.\"","options":[{"text":"\"Thank you. What would help you feel less hidden?\"","then":"She thinks. \"Maybe meeting your college friends properly. As us.\"","best":true},{"text":"\"It's fine. Let's just forget it ever happened.\"","then":"\"Okay,\" she says, but the worry stays in her face."},{"text":"\"You should be sorry. That was really unfair of you.\"","then":"Her apology falters. \"I know. That's why I said it.\""},{"text":"\"It's okay. I'll try to tell my family sooner, for you.\"","then":"She squeezes your hand. \"Only when you're ready. I mean that.\""}],"why":"Meeting her repair with a real question turns a fight into a plan for you both."}],"relearn":"Healthy love leaves room for your family and friends."},
  {"id":"rr-1396","cat":"what-healthy-looks-like","type":"role-play","persona":"any","source":"mutual asking","hook":"There's something you'd like to try in bed with Veer, your partner of a few months.","setup":"It's a lazy Sunday morning together.","steps":[{"prompt":"Veer says: \"You've gone quiet. What's on your mind?\"","options":[{"text":"\"I'd like to try something. I want to hear what you'd like too.\"","then":"He props himself up, curious. \"Okay. Tell me. I'm listening.\"","best":true},{"text":"\"Nothing. You'd never guess anyway, so forget it.\"","then":"He frowns. \"Guess what? Did I do something?\""},{"text":"\"Nothing, really. It's silly. Never mind.\"","then":"\"Okay,\" he says, then pauses. \"It's not silly. Tell me?\""},{"text":"\"I want us to try something new. You'll love it. I promise.\"","then":"He hesitates. \"Um. What is it, first?\""}],"why":"Asking plainly, and inviting his wishes too, makes it a shared talk, not a demand."},{"prompt":"Once you explain, Veer says: \"I'm not sure about that. It makes me a bit nervous.\"","options":[{"text":"\"That's okay. Your no counts. What would you enjoy?\"","then":"He relaxes. \"Thanks. Can I think about it?\"","best":true},{"text":"\"Come on, just try it once. For me? Please?\"","then":"He shifts away a little. \"I said I'm nervous.\""},{"text":"\"Forget it. I shouldn't have said anything.\"","then":"\"Hey, no,\" he says. \"I'm glad you told me.\""},{"text":"\"Okay. We'll go slowly, so you can get used to it.\"","then":"He hesitates. \"I didn't say yes, though.\""}],"why":"Treating his no as a real answer is what keeps asking free of pressure."},{"prompt":"A few days later, Veer says: \"Not that, but can I tell you something I'd like?\"","options":[{"text":"\"Yes, tell me. I'll be honest about whether I'm into it.\"","then":"He smiles, a little shy. \"Okay. Deal.\"","best":true},{"text":"\"Sure, anything you want. Honestly, I'm fine with whatever.\"","then":"\"Anything?\" he says. \"I'd rather know you actually want it.\""},{"text":"\"So you get your thing, but I don't get mine?\"","then":"His face drops. \"That's not what I meant.\""},{"text":"\"Of course. And then maybe you'll try mine.\"","then":"He pauses. \"Wait. Is this a trade?\""}],"why":"Mutual asking goes both ways: listen openly, and answer honestly."}],"relearn":"Mutual, pressure-free asking is what real intimacy looks like."},
  {"id":"rr-1397","cat":"what-healthy-looks-like","type":"role-play","persona":"Meena","source":"specific thanks","hook":"Sunil covered your shift at the garment unit today, without you asking.","setup":"Tonight he brings you dal.","steps":[{"prompt":"Sunil asks: \"How's the fever? I told the supervisor you'll be back Monday.\"","options":[{"text":"\"Better. You took my shift without asking. I felt cared for.\"","then":"He looks pleased. \"It was nothing. You'd do the same.\"","best":true},{"text":"\"Thanks. Is there some salt? The dal needs a little.\"","then":"\"A little,\" he says, and sits down quietly."},{"text":"\"You didn't have to do that. Now I owe you one.\"","then":"\"Owe me?\" he says. \"It's not like that.\""},{"text":"\"You're so good to me, Sunil. What would I do without you?\"","then":"He smiles and shrugs. \"You'd manage fine.\""}],"why":"Naming what he did, and how it felt, tells him his kindness landed."},{"prompt":"Sunil says: \"The supervisor grumbled, though. The double shift wore me out.\"","options":[{"text":"\"Sorry it cost you. Sit down. I'll make tea tonight.\"","then":"He sinks down, eyes closing. \"Tea sounds good.\"","best":true},{"text":"\"He always grumbles. Just ignore him.\"","then":"\"Easy to say,\" he mutters, rubbing his neck."},{"text":"\"I'll take your next two shifts. Then we're even.\"","then":"He laughs a little. \"Even? We're not keeping count.\""},{"text":"\"See? This is why I didn't ask you to do it.\"","then":"He looks hurt. \"I only wanted to help.\""}],"why":"Seeing what it cost him, and caring for him back, is thanks in action."},{"prompt":"A week later, Sunil says: \"I fixed the leaking tap in your room.\"","options":[{"text":"\"Thank you. No more buckets at night. That helps a lot.\"","then":"He grins. \"I saw it kept you up. No more drip-drip.\"","best":true},{"text":"\"Finally. It's been leaking for weeks.\"","then":"His grin fades. \"I came as soon as I could.\""},{"text":"\"Oh, nice. Thanks. Want some tea before you go?\"","then":"\"Sure,\" he says, and packs his tools away quietly."},{"text":"\"You didn't need to. I was going to call the landlord.\"","then":"\"Oh,\" he says. \"I thought it would help.\""}],"why":"A specific thank you, even for small things, keeps kindness flowing both ways."}],"relearn":"Specific appreciation lands deeper than a passing thanks."},
  {"id":"rr-1398","type":"spot","hook":"Spot the two controlling lines hiding in 'caring.'","scene":[{"id":"a","text":"\"Text me when you're home safe\"","trick":false},{"id":"b","text":"\"Share your location so I don't worry\"","trick":true},{"id":"c","text":"\"Have fun with your friends tonight\"","trick":false},{"id":"d","text":"\"Tell me everywhere you go, always\"","trick":true},{"id":"e","text":"\"Take the time you need\"","trick":false}],"why":"Demanding location and a full account of your movements is control; the rest is genuine care.","relearn":"Care sounds like 'text me safe'; control sounds like 'account for everywhere you go.'","source":"caring vs controlling","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1399","type":"spot","hook":"Spot the two red flags in this 'perfect' first month.","scene":[{"id":"a","text":"They remember what you care about","trick":false},{"id":"b","text":"They want you texting all day, every day","trick":true},{"id":"c","text":"They get on with your friends","trick":false},{"id":"d","text":"They sulk whenever you see others","trick":true},{"id":"e","text":"They give you space to study","trick":false}],"why":"Constant texting demands and sulking over your other people are red flags, not signs of deep love.","relearn":"Interest and space are green; round-the-clock demands and sulking are red.","source":"early red flags","persona":"Ananya","cat":"what-healthy-looks-like"},
  {"id":"rr-1400","type":"spot","hook":"Spot the two lines that are pressure, not love.","scene":[{"id":"a","text":"\"Only if you're comfortable\"","trick":false},{"id":"b","text":"\"If you loved me you'd say yes\"","trick":true},{"id":"c","text":"\"We can stop any time\"","trick":false},{"id":"d","text":"\"Everyone our age does this\"","trick":true},{"id":"e","text":"\"Tell me what feels good\"","trick":false}],"why":"'If you loved me' and 'everyone does it' are pressure tactics; the rest leave you free to choose.","relearn":"Real intimacy keeps your yes free; guilt and 'everyone does it' are pressure.","source":"pressure vs intimacy","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1401","type":"spot","hook":"Spot the two ways this 'apology' isn't one.","scene":[{"id":"a","text":"\"I was wrong, I'm sorry\"","trick":false},{"id":"b","text":"\"Sorry you took it that way\"","trick":true},{"id":"c","text":"\"I'll do it differently\"","trick":false},{"id":"d","text":"\"Sorry, but you started it\"","trick":true},{"id":"e","text":"\"That's on me\"","trick":false}],"why":"'Sorry you took it that way' and a blame-shifting 'but' dodge responsibility; a real apology owns it.","relearn":"A real apology owns the harm; deflecting and blame-shifting don't.","source":"real apology","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1402","type":"spot","hook":"Spot the two signs your world is shrinking.","scene":[{"id":"a","text":"You still have your own savings","trick":false},{"id":"b","text":"You've quietly dropped your old friends","trick":true},{"id":"c","text":"You keep up your weekend football","trick":false},{"id":"d","text":"You clear every plan with them first","trick":true},{"id":"e","text":"You text your best friend daily","trick":false}],"why":"Dropping your friends and clearing every plan are signs of shrinking; your money, hobbies and friends staying are healthy.","relearn":"Keeping your money, hobbies and friends is healthy; dropping them and seeking permission isn't.","source":"world shrinking","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1403","type":"spot","hook":"Spot the two disrespectful moves dressed as 'just joking.'","scene":[{"id":"a","text":"Gentle teasing you both enjoy","trick":false},{"id":"b","text":"Mocking you in front of friends","trick":true},{"id":"c","text":"A nickname you actually like","trick":false},{"id":"d","text":"'Jokes' about things you're insecure about","trick":true},{"id":"e","text":"Light banter that lifts you","trick":false}],"why":"Public mockery and 'jokes' aimed at your insecurities are contempt; shared, enjoyed banter isn't.","relearn":"Banter you both enjoy is fine; mockery and jabs at your insecurities are contempt.","source":"banter vs contempt","persona":"Rohan","cat":"what-healthy-looks-like"},
  {"id":"rr-1404","type":"spot","hook":"Spot the two signs of an unequal relationship.","scene":[{"id":"a","text":"Big choices made together","trick":false},{"id":"b","text":"One person decides everything","trick":true},{"id":"c","text":"Chores shared fairly","trick":false},{"id":"d","text":"You account for every rupee spent","trick":true},{"id":"e","text":"Both reach out first sometimes","trick":false}],"why":"One person deciding everything and rationing your money are inequality; shared choices, chores and effort aren't.","relearn":"Shared decisions, chores and effort are equality; one deciding all and rationing money isn't.","source":"equality check","persona":"Meena","cat":"what-healthy-looks-like"},
  {"id":"rr-1405","type":"strike-rewrite","hook":"\"Real love means losing yourself in someone.\"","myth":{"un":"Real love means losing yourself in someone.","re":"Real love keeps you whole: your friends, identity and independence stay intact.","why":"Healthy love expands who you are; it doesn't erase you."},"relearn":"Healthy love keeps you whole, not dissolved.","source":"keeps you whole","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1406","type":"strike-rewrite","hook":"\"If you really click, it should be effortless.\"","myth":{"un":"If you really click, it should be effortless.","re":"Good relationships are built with skills like listening, repair and appreciation, not found effortless.","why":"Effortless is a myth; the lasting ones are practised and tended."},"relearn":"Good relationships are built with skills, not found effortless.","source":"built not found","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1407","type":"strike-rewrite","hook":"\"A couple that truly loves each other never fights.\"","myth":{"un":"A couple that truly loves each other never fights.","re":"Healthy couples do disagree: what marks them is that they repair well afterwards.","why":"Conflict is normal; repair, not its absence, is the real marker."},"relearn":"Healthy couples fight sometimes and repair well.","source":"repair not no-conflict","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1408","type":"strike-rewrite","hook":"\"Wanting your own space means you're not that into them.\"","myth":{"un":"Wanting your own space means you're not that into them.","re":"Wanting your own space is healthy: independence and your own friends are a good sign, not a betrayal.","why":"Space keeps two people whole; needing none is the warning sign."},"relearn":"Your own space is a healthy sign, not a lack of love.","source":"space is healthy","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1409","type":"strike-rewrite","hook":"\"Once you're committed, your friends should come second.\"","myth":{"un":"Once you're committed, your friends should come second.","re":"A healthy relationship leaves room for your friends: keeping your world is a good sign.","why":"A partner who needs you cut off from everyone is the red flag, not your friends."},"relearn":"Keep your friends; a healthy bond leaves room for them.","source":"keep your world","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1410","type":"strike-rewrite","hook":"\"You should be your partner's whole world.\"","myth":{"un":"You should be your partner's whole world.","re":"Being someone's whole world is a burden, not a goal: healthy people keep their own full lives.","why":"Two whole people make a stronger bond than two who've shrunk to fit."},"relearn":"Healthy love is two whole lives, not one being everything.","source":"two whole people","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1411","type":"strike-rewrite","hook":"\"Compromise means whoever loves more gives in more.\"","myth":{"un":"Compromise means whoever loves more gives in more.","re":"Compromise is shared give-and-take; equality means turns and trade-offs, not one always yielding.","why":"When one always yields, that's not love. It's a slow imbalance."},"relearn":"Compromise is mutual give-and-take, not one person always yielding.","source":"fair compromise","persona":"Aarti","cat":"what-healthy-looks-like"},
  {"id":"rr-1412","type":"match","hook":"Match the healthy marker to a daily example.","pairs":[{"left":"Honest communication","right":"You can say a hard truth"},{"left":"Repair","right":"You make up after a row"},{"left":"Support","right":"They show up in a tough week"},{"left":"Equality","right":"Chores split fairly"},{"left":"Trust","right":"No need to check their phone"}],"relearn":"Honest talk, repair, support, equality and trust each show up in concrete daily moments.","source":"markers to examples","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1413","type":"match","hook":"Match the healthy ingredient to its opposite red flag.","pairs":[{"left":"Trust","right":"Snooping through your phone"},{"left":"Independence","right":"Cutting you off from friends"},{"left":"Respect","right":"Mocking what you care about"},{"left":"Equality","right":"One person decides all"},{"left":"Voluntary openness","right":"Demanding your passwords"}],"relearn":"Each green marker has a clear red opposite: trust vs snooping, independence vs isolation, and so on.","source":"marker vs red flag","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1414","type":"match","hook":"Match the loving move to what it gives you.","pairs":[{"left":"They cheer your goals","right":"You feel backed"},{"left":"They give you space","right":"You stay yourself"},{"left":"They keep their word","right":"You feel safe"},{"left":"They own their mistakes","right":"You can trust again"},{"left":"They appreciate you","right":"You feel valued"}],"relearn":"Backing, space, reliability, owning mistakes and appreciation are what healthy love feels like daily.","source":"moves to feelings","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1415","type":"match","hook":"Match the marker to the question that tests for it.","pairs":[{"left":"Independence","right":"Do I still have my own life?"},{"left":"Respect","right":"Is my no honoured?"},{"left":"Equality","right":"Do we decide together?"},{"left":"Trust","right":"Can we be apart, calmly?"},{"left":"Repair","right":"Do we recover after fights?"}],"relearn":"Each healthy marker comes with a simple question you can ask yourself to check for it.","source":"markers to tests","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1416","type":"match","hook":"Match the green flag to the red flag it replaces.","pairs":[{"left":"A friendly check-in","right":"A curfew you must obey"},{"left":"Sharing freely","right":"Mandatory location"},{"left":"A real apology","right":"A blame-shifting 'sorry, but'"},{"left":"Time with your friends","right":"Sulking when you go out"},{"left":"Deciding together","right":"Whoever's loudest wins"}],"relearn":"For every controlling move there's a healthy version: a check-in, free sharing, a real sorry, your own time, shared decisions.","source":"green replaces red","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1417","type":"match","hook":"Match the skill to the moment it's for.","pairs":[{"left":"'I felt' statement","right":"Raising a hurt"},{"left":"Take a break","right":"When you're flooded"},{"left":"Appreciation","right":"An ordinary good day"},{"left":"Owning your part","right":"After you messed up"},{"left":"Asking clearly","right":"When you need something"}],"relearn":"Healthy relationship skills each have a moment: 'I felt', a break, appreciation, owning your part, clear asks.","source":"skill to moment","persona":"any","cat":"what-healthy-looks-like"},
  {"id":"rr-1418","type":"match","hook":"Match the healthy sign to where you'd notice it.","pairs":[{"left":"You feel free","right":"In your own body, relaxed"},{"left":"You're respected","right":"In how they speak to you"},{"left":"You're trusted","right":"When you're out of sight"},{"left":"You're an equal","right":"In who decides"},{"left":"You're appreciated","right":"In the small thank-yous"}],"relearn":"Healthy signs show up in your body, their words, time apart, decisions and everyday thanks.","source":"signs to where","persona":"any","cat":"what-healthy-looks-like"},
];

